import { generateNarration, generateAtmosphereImage } from './services/geminiService';
import { decode, decodeAudioData } from './utils/audioUtils';

const DEFAULT_TEXT = `سکون کی نیند اور اللہ کی حفاظت۔ نبی کریم صلی اللہ علیہ وآلہ وسلم کا بتایا ہوا ایک ایسا عمل جو ہمیں رات بھر شیطان کے شر سے محفوظ رکھتا ہے۔ آج رات سونے سے پہلے آیت الکرسی پڑھنا نہ بھولیں۔
آپ صلی اللہ علیہ وآلہ وسلم نے فرمایا: جب تم رات کو اپنے بستر پر سونے کے لیے جاؤ تو آیت الکرسی پڑھ لیا کرو، پھر صبح تک اللہ تعالیٰ کی طرف سے تمہاری حفاظت کرنے والا ایک فرشتہ مقرر ہو جائے گا اور شیطان تمہارے پاس بھی نہ آ سکے گا۔ صحیح البخاری حدیث نمبر 5010۔
اللہ ہم سب کو اس پر عمل کرنے کی توفیق عطا فرمائے۔ آمین۔`;

