    setIsGenerating(true);
    setCurrentResult(null);

    try {
      // Step 1: Generate Audio
      const base64Audio = await generateNarration(settings.text, settings.voice);

      // We need to create a Blob for playback/download
      // Convert raw PCM to a format browser can handle? 
      // Actually, standard AudioContext can play the decoded PCM.
      // For persistent URL, we'll store the base64 or create an object URL from processed data
      const audioData = decode(base64Audio);
      const blob = new Blob([audioData], { type: 'audio/pcm' });
      const audioUrl = URL.createObjectURL(blob);

      // Step 2: Optional Image Generation
      let imageUrl;
      if (settings.generateImage) {
        imageUrl = await generateAtmosphereImage(settings.style);
      }

      const newHistoryItem: NarrationHistoryItem = {
        id: Date.now().toString(),
        text: settings.text,
        voice: settings.voice,
        timestamp: Date.now(),
        audioUrl,
        imageUrl: imageUrl || undefined
