    // If it's a blob URL, we need to fetch it or use the original decoded data
    // For simplicity, let's just re-decode if we have the base64 or fetch the blob
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

