import { drawVideoFrame } from './utils/videoUtils';

const DEFAULT_TEXT = `سکون کی نیند اور اللہ کی حفاظت۔ نبی کریم صلی اللہ علیہ وآلہ وسلم کا بتایا ہوا ایک ایسا عمل جو ہمیں رات بھر شیطان کے شر سے محفوظ رکھتا ہے۔ آج رات سونے سے پہلے آیت الکرسی پڑھنا نہ بھولیں۔
آپ صلی اللہ علیہ وآلہ وسلم نے فرمایا: جب تم رات کو اپنے بستر پر سونے کے لیے جاؤ تو آیت الکرسی پڑھ لیا کرو، پھر صبح تک اللہ تعالیٰ کی طرف سے تمہاری حفاظت کرنے والا ایک فرشتہ مقرر ہو جائے گا اور شیطان تمہارے پاس بھی نہ آ سکے گا۔ صحیح البخاری حدیث نمبر 5010۔`;

const App: React.FC = () => {
  const [settings, setSettings] = useState<GenerationSettings>({
    text: DEFAULT_TEXT,
    voice: VoiceName.CHARON,
    generateImage: true,
    style: "Starry night sky over a peaceful mosque silhouette"
  });

  const [isGenerating, setIsGenerating] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordProgress, setRecordProgress] = useState(0);
  const [currentResult, setCurrentResult] = useState<{ 
    audioUrl: string; 
    imageUrl?: string; 
    audioBuffer?: AudioBuffer;
    base64Audio: string;
  } | null>(null);
  const [history, setHistory] = useState<NarrationHistoryItem[]>([]);
  const [showHistory, setShowHistory] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const recordCanvasRef = useRef<HTMLCanvasElement>(null);

  // Load preview frame whenever result or text changes
  useEffect(() => {
    if (canvasRef.current && (currentResult?.imageUrl || settings.text)) {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => drawVideoFrame(canvasRef.current!, img, settings.text, 0);
      if (currentResult?.imageUrl) {
        img.src = currentResult.imageUrl;
      } else {
        drawVideoFrame(canvasRef.current!, null, settings.text, 0);
      }
    }
  }, [currentResult, settings.text]);

  const handleGenerate = async () => {
    if (!settings.text.trim()) return;
    setIsGenerating(true);
    setCurrentResult(null);

    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const base64Audio = await generateNarration(settings.text, settings.voice);
      const audioData = decode(base64Audio);
      const audioBuffer = await decodeAudioData(audioData, audioContextRef.current, 24000, 1);

      const audioBlob = new Blob([audioData], { type: 'audio/pcm' });
      const audioUrl = URL.createObjectURL(audioBlob);

      let imageUrl;
      if (settings.generateImage) {
        imageUrl = await generateAtmosphereImage(settings.style);
      }

      setCurrentResult({ audioUrl, imageUrl: imageUrl || undefined, audioBuffer, base64Audio });

      setHistory(prev => [{
        id: Date.now().toString(),
        text: settings.text,
        voice: settings.voice,
        timestamp: Date.now(),
        audioUrl,
        imageUrl: imageUrl || undefined
      }, ...prev]);

    } catch (error) {
      console.error("Generation failed", error);
      alert("Failed to generate assets. Please check your connection.");
    } finally {
      setIsGenerating(false);
    }
  };

  const startExport = async () => {
    if (!currentResult || !currentResult.audioBuffer) return;

    setIsRecording(true);
    setRecordProgress(0);

    const canvas = recordCanvasRef.current!;
    const ctx = canvas.getContext('2d')!;
    const stream = canvas.captureStream(30);

    const audioCtx = audioContextRef.current!;
    const dest = audioCtx.createMediaStreamDestination();

    // Create recorder
    const recorder = new MediaRecorder(new MediaStream([...stream.getTracks(), ...dest.stream.getTracks()]), {
      mimeType: 'video/webm;codecs=vp9'
    });

    const chunks: Blob[] = [];
    recorder.ondataavailable = (e) => chunks.push(e.data);
    recorder.onstop = () => {
      const blob = new Blob(chunks, { type: 'video/webm' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `noor-narrator-${Date.now()}.webm`;
      a.click();
      setIsRecording(false);
    };

    // Load Image
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = currentResult.imageUrl || '';
    await new Promise(r => img.onload = r);

    // Play Audio
    const source = audioCtx.createBufferSource();
    source.buffer = currentResult.audioBuffer;
    source.connect(dest);
    source.connect(audioCtx.destination);

    recorder.start();
    source.start();

    const duration = currentResult.audioBuffer.duration;
    const startTime = audioCtx.currentTime;

    const renderLoop = () => {
      const elapsed = audioCtx.currentTime - startTime;
      const progress = Math.min(elapsed / duration, 1);

      drawVideoFrame(canvas, img, settings.text, progress);
      setRecordProgress(progress * 100);

      if (progress < 1) {
        requestAnimationFrame(renderLoop);
      } else {
        setTimeout(() => recorder.stop(), 500);
      }
    };

    renderLoop();
  };

  const playPreview = async () => {
    if (!currentResult || !currentResult.audioBuffer || !audioContextRef.current) return;
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') await ctx.resume();
    const source = ctx.createBufferSource();
    source.buffer = currentResult.audioBuffer;
    source.connect(ctx.destination);
    source.start();
  };

  return (
    <div className="min-h-screen flex flex-col items-center bg-[#020617] p-4 md:p-8">
      {/* Recording Hidden Canvas */}
      <canvas ref={recordCanvasRef} width={1080} height={1920} className="hidden" />

      {/* Header */}
      <header className="w-full max-w-6xl flex justify-between items-center mb-10 relative z-20">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-emerald-800 rounded-2xl shadow-xl shadow-emerald-950/50">
            <Video className="w-8 h-8 text-yellow-400" />
          </div>
          <div>
            <h1 className="text-3xl font-bold text-white tracking-tight">Noor Narrator Studio</h1>
            <p className="text-sm text-emerald-500 font-semibold tracking-widest uppercase">AI Video Content for Social Media</p>
          </div>
        </div>

        <button 
          onClick={() => setShowHistory(!showHistory)}
          className="px-5 py-2.5 glass-card rounded-xl hover:bg-emerald-900/30 transition-all flex items-center gap-2 border border-emerald-900/50"
        >
          {showHistory ? <ArrowLeft className="w-5 h-5" /> : <History className="w-5 h-5" />}
          <span className="hidden sm:inline font-medium">{showHistory ? "Back to Editor" : "Archives"}</span>
        </button>
      </header>

      <main className="w-full max-w-6xl grid grid-cols-1 lg:grid-cols-12 gap-10 relative z-10">
        {!showHistory ? (
          <>
            {/* Editor Side */}
            <div className="lg:col-span-7 space-y-8">
              <section className="glass-card rounded-3xl p-8 shadow-2xl border-emerald-900/20">
                <div className="flex items-center justify-between mb-6">
                  <h2 className="text-xl font-bold flex items-center gap-3 text-yellow-500">
                    <Mic2 className="w-6 h-6" /> Script & Audio
                  </h2>
                  <span className="px-3 py-1 bg-emerald-950/50 rounded-full text-xs text-emerald-400 font-bold border border-emerald-900/30">Urdu Enabled</span>
                </div>

                <textarea
                  className="urdu-font w-full h-56 bg-black/40 border border-emerald-900/40 rounded-2xl p-6 text-2xl text-emerald-50 focus:outline-none focus:ring-4 focus:ring-emerald-600/20 transition-all resize-none shadow-inner"
                  placeholder="یہاں اپنا اردو متن لکھیں..."
                  value={settings.text}
                  onChange={(e) => setSettings({ ...settings, text: e.target.value })}
                  dir="rtl"
                />

                <div className="mt-8 grid grid-cols-1 sm:grid-cols-2 gap-6">
                  <div className="space-y-3">
                    <label className="text-xs font-bold text-emerald-600 uppercase tracking-widest flex items-center gap-2">
                       Narrator Voice
                    </label>
                    <select 
                      className="w-full bg-emerald-950/50 border border-emerald-900/40 rounded-xl p-4 text-sm text-emerald-100 focus:outline-none focus:ring-2 focus:ring-emerald-600 transition-all appearance-none cursor-pointer"
                      value={settings.voice}
                      onChange={(e) => setSettings({ ...settings, voice: e.target.value as VoiceName })}
                    >
                      <option value={VoiceName.CHARON}>Charon - Soulful & Deep</option>
                      <option value={VoiceName.KORE}>Kore - Clear & Classic</option>
                      <option value={VoiceName.PUCK}>Puck - Gentle & Kind</option>
                      <option value={VoiceName.FENRIR}>Fenrir - Authoritative</option>
                      <option value={VoiceName.ZEPHYR}>Zephyr - Elegant Female</option>
                    </select>
                  </div>

                  <div className="space-y-3">
                    <label className="text-xs font-bold text-emerald-600 uppercase tracking-widest flex items-center gap-2">
                      Visual Vibes
                    </label>
                    <button 
                      onClick={() => setSettings({...settings, generateImage: !settings.generateImage})}
                      className={`w-full flex items-center justify-between p-4 rounded-xl border transition-all ${settings.generateImage ? 'bg-emerald-600/10 border-emerald-600 text-emerald-200' : 'bg-slate-900/50 border-slate-800 text-slate-500'}`}
                    >
                      <span className="text-sm font-medium">Generate AI Background</span>
                      <ImageIcon className={`w-5 h-5 ${settings.generateImage ? 'text-emerald-400' : 'text-slate-600'}`} />
                    </button>
                  </div>
                </div>

                {settings.generateImage && (
                  <div className="mt-6 space-y-3 animate-in fade-in slide-in-from-top-2 duration-300">
                    <label className="text-xs font-bold text-emerald-600 uppercase tracking-widest">Atmosphere Description</label>
                    <input 
                      type="text"
                      className="w-full bg-emerald-950/50 border border-emerald-900/40 rounded-xl p-4 text-sm text-emerald-100 focus:outline-none focus:ring-2 focus:ring-emerald-600 transition-all"
                      placeholder="e.g. Mosque in moonlight, Islamic patterns, nature..."
                      value={settings.style}
                      onChange={(e) => setSettings({ ...settings, style: e.target.value })}
                    />
                  </div>
                )}

                <button
                  onClick={handleGenerate}
                  disabled={isGenerating || isRecording || !settings.text.trim()}
                  className="w-full mt-10 bg-gradient-to-r from-emerald-600 to-emerald-800 hover:from-emerald-500 hover:to-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed text-white font-black py-5 px-8 rounded-2xl shadow-2xl transition-all flex items-center justify-center gap-4 group uppercase tracking-widest text-sm"
                >
                  {isGenerating ? (
                    <>
                      <Loader2 className="w-6 h-6 animate-spin" />
                      Manifesting...
                    </>
                  ) : (
                    <>
                      <Sparkles className="w-6 h-6 group-hover:rotate-12 transition-transform" />
                      Generate Assets
                    </>
