                </div>

                <div className="relative group preview-container w-full max-w-[320px] mx-auto rounded-3xl overflow-hidden shadow-2xl border-4 border-emerald-900/30 bg-slate-900">
                  <canvas 
                    ref={canvasRef} 
                    width={1080} 
                    height={1920} 
                    className="w-full h-full object-contain"
                  />

                  {isRecording && (
                    <div className="absolute inset-0 bg-black/80 flex flex-col items-center justify-center p-8 text-center backdrop-blur-md">
