      </main>

      <footer className="mt-12 py-10 text-center text-slate-800 text-[10px] font-black uppercase tracking-[0.3em] relative z-20">
        &copy; {new Date().getFullYear()} Noor Narrator &bull; AI Powered Media Studio &bull; Built with Gemini 2.5
      </footer>
    </div>
  );
};

