import { GoogleGenAI } from "@google/genai";
import { VoiceName } from "../types";

export const generateNarration = async (text: string, voice: VoiceName) => {
  // Initialize inside the function to ensure process.env.API_KEY is available and fresh
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Custom prompt enhancement for tone and safety clearance
  const ttsPrompt = `Please narrate the following Urdu text with a calm, soulful, and respectful tone suitable for an Islamic educational reminder. Ensure clear pronunciation.

  Text: ${text}`;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: ttsPrompt }] }],
    config: {
      // Use string literal to avoid issues with Modality enum if problematic
      responseModalities: ["AUDIO"], 
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: voice },
        },
      },
    },
  });

  // More robust candidate and part extraction
  if (!response.candidates || response.candidates.length === 0) {
    throw new Error("The model did not return any candidates. This might be due to safety filters.");
  }

  const candidate = response.candidates[0];
  if (!candidate.content || !candidate.content.parts) {
    throw new Error("The response candidate is empty.");
  }

  // Iterate to find the audio part
  for (const part of candidate.content.parts) {
    if (part.inlineData && part.inlineData.data) {
      return part.inlineData.data;
    }
  }

  throw new Error("No audio content received in the model response.");
};

export const generateAtmosphereImage = async (prompt: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const imagePrompt = `A high-quality, atmospheric, and respectful background image for a spiritual Islamic reminder. 
    Subject: ${prompt}. 
    Style: Cinematic, professional photography, deep colors (emerald, navy, or gold), soft ambient lighting, no human figures, peaceful and dignified atmosphere. 4k resolution.`;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [{ text: imagePrompt }],
    },
    config: {
      imageConfig: {
        aspectRatio: "16:9"
      }
    }
  });

  if (!response.candidates || response.candidates.length === 0) {
    return null;
  }

  for (const part of response.candidates[0].content.parts || []) {
    if (part.inlineData && part.inlineData.data) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }
  return null;
};

