export const wrapText = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number
): string[] => {
  const words = text.split(/\s+/);
  const lines: string[] = [];
  let currentLine = '';

  for (let n = 0; n < words.length; n++) {
    const testLine = currentLine + words[n] + ' ';
    const metrics = ctx.measureText(testLine);
    const testWidth = metrics.width;
    if (testWidth > maxWidth && n > 0) {
      lines.push(currentLine.trim());
      currentLine = words[n] + ' ';
    } else {
      currentLine = testLine;
    }
  }
  lines.push(currentLine.trim());
  return lines;
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  image: HTMLImageElement | null,
  text: string,
  progress: number // 0 to 1
) => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;

  const width = canvas.width;
  const height = canvas.height;

  // Clear canvas
  ctx.clearRect(0, 0, width, height);

  // 1. Draw Background Image
  if (image) {
    const imgAspect = image.width / image.height;
    const canvasAspect = width / height;
    let renderWidth, renderHeight, x, y;

    if (imgAspect > canvasAspect) {
      renderHeight = height;
      renderWidth = height * imgAspect;
      x = (width - renderWidth) / 2;
      y = 0;
    } else {
      renderWidth = width;
      renderHeight = width / imgAspect;
      x = 0;
      y = (height - renderHeight) / 2;
    }
    ctx.drawImage(image, x, y, renderWidth, renderHeight);
  } else {
    // Fallback Gradient
    const grad = ctx.createLinearGradient(0, 0, 0, height);
    grad.addColorStop(0, '#042f2e');
    grad.addColorStop(1, '#020617');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, width, height);
  }

  // 2. Overlay Vignette / Darkener
  const overlay = ctx.createRadialGradient(width / 2, height / 2, 0, width / 2, height / 2, height);
  overlay.addColorStop(0, 'rgba(0,0,0,0.2)');
  overlay.addColorStop(1, 'rgba(0,0,0,0.7)');
  ctx.fillStyle = overlay;
  ctx.fillRect(0, 0, width, height);

  // 3. Setup Urdu Text Styling
  ctx.direction = 'rtl';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'white';

  // High-end drop shadow for legibility
  ctx.shadowColor = 'rgba(0,0,0,0.8)';
  ctx.shadowBlur = 15;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 5;

  const fontSize = width * 0.065;
  ctx.font = `bold ${fontSize}px "Noto Nastaliq Urdu"`;

  const maxWidth = width * 0.8;
  const lines = wrapText(ctx, text, maxWidth);
  const lineHeight = fontSize * 2.2;
  const totalHeight = lines.length * lineHeight;

  /**
   * SCROLLING LOGIC:
   * We want the text to start just below the screen and end just above the screen.
   * Total travel distance is the height of the screen + the total height of the text block.
   */
  const scrollPadding = 100; // Extra padding for start/end
  const scrollRange = height + totalHeight + (scrollPadding * 2);

  // Calculate startY based on progress (0 to 1)
  // At progress 0: first line is at height + scrollPadding
  // At progress 1: last line is at -scrollPadding
  let startY = (height + scrollPadding) - (scrollRange * progress) + (lineHeight / 2);

  // 4. Render each line
  lines.forEach((line) => {
    // Only draw if within reasonable bounds for performance
    if (startY > -lineHeight && startY < height + lineHeight) {
      ctx.fillText(line, width / 2, startY);
    }
    startY += lineHeight;
  });

  // Reset shadow for next frame
  ctx.shadowBlur = 0;
};

import React, { useState, useRef, useEffect } from 'react';
import { 
