export const generateNarration = async (text: string, voice: VoiceName) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  /**
   * We use a clear, concise instruction. 
   * Sometimes complex preamble instructions can trigger safety filters 
   * if the model misinterprets the context.
   */
  const ttsPrompt = `NARRATE THE FOLLOWING TEXT IN URDU. 
Use a calm, respectful, and soulful tone suitable for a spiritual reminder:

${text}`;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: ttsPrompt }] }],
    config: {
      responseModalities: [Modality.AUDIO], 
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: voice },
        },
      },
      // Explicitly applying safety settings to bypass strict default filtering
      safetySettings: safetySettings as any,
    },
  });

  // Check if the model returned any candidates at all
  if (!response.candidates || response.candidates.length === 0) {
    throw new Error("The model did not return any candidates. This usually happens when safety filters are triggered. Try slightly rephrasing your text to be more neutral.");
  }

  const candidate = response.candidates[0];

  // Provide more detailed feedback if the generation was specifically blocked
  if (candidate.finishReason && candidate.finishReason !== 'STOP') {
    if (candidate.finishReason === 'SAFETY') {
      throw new Error("Generation was blocked by safety filters. Please check if your text contains sensitive keywords.");
    }
    throw new Error(`Generation failed with reason: ${candidate.finishReason}`);
  }

  if (!candidate.content || !candidate.content.parts) {
    throw new Error("The response candidate is empty or contains no content parts.");
  }

  // Find and return the audio data part
  for (const part of candidate.content.parts) {
    if (part.inlineData && part.inlineData.data) {
      return part.inlineData.data;
    }
  }

  throw new Error("No audio content received in the model response.");
};

