export const wrapText = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number
): string[] => {
  // 1. Split by user's manual newlines to preserve formation
  const paragraphs = text.split('\n');
  const allLines: string[] = [];

  paragraphs.forEach((paragraph) => {
    // Handle empty lines (e.g., user pressed Enter twice)
    if (paragraph.trim() === '') {
      allLines.push('');
      return;
    }

    // 2. Wrap the text within this specific paragraph
    const words = paragraph.split(' ');
    let currentLine = '';

    for (let n = 0; n < words.length; n++) {
      const testLine = currentLine + (currentLine ? ' ' : '') + words[n];
      const metrics = ctx.measureText(testLine);
      const testWidth = metrics.width;

      if (testWidth > maxWidth && n > 0) {
        allLines.push(currentLine);
        currentLine = words[n];
      } else {
        currentLine = testLine;
      }
    }
    allLines.push(currentLine);
  });

  return allLines;
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  image: HTMLImageElement | null,
  text: string,
  progress: number // 0 to 1
) => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;

  const width = canvas.width;
  const height = canvas.height;

  // Clear canvas
  ctx.clearRect(0, 0, width, height);

  // 1. Draw Background Image
  if (image) {
    const imgAspect = image.width / image.height;
    const canvasAspect = width / height;
    let renderWidth, renderHeight, x, y;

    if (imgAspect > canvasAspect) {
      renderHeight = height;
      renderWidth = height * imgAspect;
      x = (width - renderWidth) / 2;
      y = 0;
    } else {
      renderWidth = width;
      renderHeight = width / imgAspect;
      x = 0;
      y = (height - renderHeight) / 2;
    }
    ctx.drawImage(image, x, y, renderWidth, renderHeight);
  } else {
    // Fallback Gradient
    const grad = ctx.createLinearGradient(0, 0, 0, height);
    grad.addColorStop(0, '#042f2e');
    grad.addColorStop(1, '#020617');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, width, height);
  }

  // 2. Overlay Vignette / Darkener
  const overlay = ctx.createRadialGradient(width / 2, height / 2, 0, width / 2, height / 2, height);
  overlay.addColorStop(0, 'rgba(0,0,0,0.1)');
  overlay.addColorStop(1, 'rgba(0,0,0,0.8)');
  ctx.fillStyle = overlay;
  ctx.fillRect(0, 0, width, height);

  // 3. Setup Urdu Text Styling
  ctx.direction = 'rtl';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'white';

  // High-end drop shadow for legibility
  ctx.shadowColor = 'rgba(0,0,0,0.9)';
  ctx.shadowBlur = 20;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 6;

  const fontSize = width * 0.065;
  ctx.font = `bold ${fontSize}px "Noto Nastaliq Urdu"`;

  const maxWidth = width * 0.85;
  const lines = wrapText(ctx, text, maxWidth);

  // Nastaliq is a tall script, so we use a generous line height
  const lineHeight = fontSize * 2.4;
  const totalHeight = lines.length * lineHeight;

  /**
   * ALIGNED SCROLLING LOGIC:
   * At progress 0: The first line is at 75% of the screen height.
   * At progress 1: The last line is at 25% of the screen height.
   * This keeps the text moving consistently with the audio duration.
   */
  const startPos = height * 0.75;
  const endPos = height * 0.25 - totalHeight + lineHeight;

  let currentY = startPos + (endPos - startPos) * progress;

  // 4. Render each line (including empty ones)
  lines.forEach((line) => {
    // Only draw if within bounds for performance
    if (currentY > -lineHeight && currentY < height + lineHeight) {
      if (line.trim()) {
        ctx.fillText(line, width / 2, currentY);
      }
    }
    currentY += lineHeight;
  });

  // Reset shadow for next frame
  ctx.shadowBlur = 0;
};

import React, { useState, useRef, useEffect } from 'react';
import { 
  Video, 
  Download, 
  Loader2, 
  Play, 
  Sparkles, 
  History, 
  Volume2, 
  Mic2, 
  ArrowLeft,
  Image as ImageIcon
} from 'lucide-react';
import { VoiceName, NarrationHistoryItem, GenerationSettings } from './types';
import { generateNarration, generateAtmosphereImage } from './services/geminiService';
import { decode, decodeAudioData } from './utils/audioUtils';
import { drawVideoFrame } from './utils/videoUtils';

const DEFAULT_TEXT = `سکون کی نیند اور اللہ کی حفاظت۔ نبی کریم صلی اللہ علیہ وآلہ وسلم کا بتایا ہوا ایک ایسا عمل جو ہمیں رات بھر شیطان کے شر سے محفوظ رکھتا ہے۔

آج رات سونے سے پہلے آیت الکرسی پڑھنا نہ بھولیں۔

آپ صلی اللہ علیہ وآلہ وسلم نے فرمایا: جب تم رات کو اپنے بستر پر سونے کے لیے جاؤ تو آیت الکرسی پڑھ لیا کرو، پھر صبح تک اللہ تعالیٰ کی طرف سے تمہاری حفاظت کرنے والا ایک فرشتہ مقرر ہو جائے گا اور شیطان تمہارے پاس بھی نہ آ سکے گا۔ 

صحیح البخاری حدیث نمبر 5010۔`;

const App: React.FC = () => {
  const [settings, setSettings] = useState<GenerationSettings>({
    text: DEFAULT_TEXT,
    voice: VoiceName.CHARON,
    generateImage: true,
    style: "Starry night sky over a peaceful mosque silhouette"
  });

  const [isGenerating, setIsGenerating] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordProgress, setRecordProgress] = useState(0);
  const [currentResult, setCurrentResult] = useState<{ 
    audioUrl: string; 
    imageUrl?: string; 
    audioBuffer?: AudioBuffer;
    base64Audio: string;
  } | null>(null);
  const [history, setHistory] = useState<NarrationHistoryItem[]>([]);
  const [showHistory, setShowHistory] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const recordCanvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (canvasRef.current && (currentResult?.imageUrl || settings.text)) {
      const img = new Image();
      img.crossOrigin = "anonymous";
      // Preview shows the starting state (progress 0)
      img.onload = () => drawVideoFrame(canvasRef.current!, img, settings.text, 0);
      if (currentResult?.imageUrl) {
        img.src = currentResult.imageUrl;
      } else {
        drawVideoFrame(canvasRef.current!, null, settings.text, 0);
      }
    }
  }, [currentResult, settings.text]);

  const handleGenerate = async () => {
    if (!settings.text.trim()) return;
    setIsGenerating(true);
    setCurrentResult(null);

    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const base64Audio = await generateNarration(settings.text, settings.voice);
      const audioData = decode(base64Audio);
      const audioBuffer = await decodeAudioData(audioData, audioContextRef.current, 24000, 1);

      const audioBlob = new Blob([audioData], { type: 'audio/pcm' });
      const audioUrl = URL.createObjectURL(audioBlob);

      let imageUrl;
      if (settings.generateImage) {
        imageUrl = await generateAtmosphereImage(settings.style);
      }

      setCurrentResult({ audioUrl, imageUrl: imageUrl || undefined, audioBuffer, base64Audio });

      setHistory(prev => [{
        id: Date.now().toString(),
        text: settings.text,
        voice: settings.voice,
        timestamp: Date.now(),
        audioUrl,
        imageUrl: imageUrl || undefined
      }, ...prev]);

    } catch (error: any) {
      console.error("Generation failed", error);
      alert(`Generation failed: ${error.message || "Unknown error"}`);
    } finally {
      setIsGenerating(false);
    }
  };

  const startExport = async () => {
    if (!currentResult || !currentResult.audioBuffer) return;

    setIsRecording(true);
    setRecordProgress(0);

    const canvas = recordCanvasRef.current!;
    const stream = canvas.captureStream(30);

    const audioCtx = audioContextRef.current!;
    const dest = audioCtx.createMediaStreamDestination();

    const recorder = new MediaRecorder(new MediaStream([...stream.getTracks(), ...dest.stream.getTracks()]), {
      mimeType: 'video/webm;codecs=vp9'
    });

    const chunks: Blob[] = [];
    recorder.ondataavailable = (e) => chunks.push(e.data);
    recorder.onstop = () => {
      const blob = new Blob(chunks, { type: 'video/webm' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `noor-narrator-${Date.now()}.webm`;
      a.click();
      setIsRecording(false);
    };

    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = currentResult.imageUrl || '';
    await new Promise(r => img.onload = r);

    const source = audioCtx.createBufferSource();
    source.buffer = currentResult.audioBuffer;
    source.connect(dest);
    source.connect(audioCtx.destination);

    recorder.start();
    source.start();

    const duration = currentResult.audioBuffer.duration;
    const startTime = audioCtx.currentTime;

    const renderLoop = () => {
      const elapsed = audioCtx.currentTime - startTime;
      const progress = Math.min(elapsed / duration, 1);

      drawVideoFrame(canvas, img, settings.text, progress);
      setRecordProgress(progress * 100);

      if (progress < 1) {
        requestAnimationFrame(renderLoop);
      } else {
        setTimeout(() => recorder.stop(), 500);
      }
    };

    renderLoop();
  };

