import { GoogleGenAI, Modality } from "@google/genai";
import { VoiceName } from "../types";

/**
 * Optimized safety settings. 
 * Removing 'CIVIC_INTEGRITY' as it can sometimes cause 'OTHER' errors 
 * in specific regions or model versions if not fully supported.
 */
const safetySettings = [
  {
    category: "HARM_CATEGORY_HARASSMENT",
    threshold: "BLOCK_NONE",
  },
  {
    category: "HARM_CATEGORY_HATE_SPEECH",
    threshold: "BLOCK_NONE",
  },
  {
    category: "HARM_CATEGORY_SEXUALLY_EXPLICIT",
    threshold: "BLOCK_NONE",
  },
  {
    category: "HARM_CATEGORY_DANGEROUS_CONTENT",
    threshold: "BLOCK_NONE",
  },
];

export const generateNarration = async (text: string, voice: VoiceName) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  /**
   * Extremely simplified prompt. 
   * For the TTS model, a direct instruction often prevents the 'OTHER' 
   * finish reason which can be triggered by the model trying to 
   * generate a text response alongside the audio.
   */
  const ttsPrompt = `Narrate this Urdu text with a calm and respectful tone: ${text}`;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: ttsPrompt }] }],
    config: {
      responseModalities: [Modality.AUDIO], 
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: voice },
        },
      },
      // Simplified safety settings
      safetySettings: safetySettings as any,
    },
  });

  if (!response.candidates || response.candidates.length === 0) {
    throw new Error("No candidates returned. Safety filters might be blocking this content.");
  }

  const candidate = response.candidates[0];

  // Handle finish reasons more gracefully
  if (candidate.finishReason && candidate.finishReason !== 'STOP') {
    if (candidate.finishReason === 'SAFETY') {
      throw new Error("Generation blocked by Safety Filters.");
    }
    // If reason is 'OTHER', it's often a transient model error or modality conflict
    console.warn(`Model finished with reason: ${candidate.finishReason}`);
  }

  if (!candidate.content || !candidate.content.parts) {
    throw new Error("Empty candidate content received.");
  }

  // Find the audio data part
  for (const part of candidate.content.parts) {
    if (part.inlineData && part.inlineData.data) {
      return part.inlineData.data;
    }
  }

  throw new Error("No audio data found in the response parts.");
};

export const generateAtmosphereImage = async (prompt: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const imagePrompt = `Atmospheric background for a spiritual quote: ${prompt}. Cinematic photography, soft lighting, peaceful, no people, high quality.`;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [{ text: imagePrompt }],
    },
    config: {
      imageConfig: {
        aspectRatio: "16:9"
      },
      safetySettings: safetySettings as any,
    }
  });

  if (!response.candidates || response.candidates.length === 0) return null;

  const candidate = response.candidates[0];
  if (candidate.content && candidate.content.parts) {
    for (const part of candidate.content.parts) {
      if (part.inlineData && part.inlineData.data) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
  }

  return null;
};

