export const wrapText = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number
): string[] => {
  const paragraphs = text.split('\n');
  const allLines: string[] = [];

  paragraphs.forEach((paragraph) => {
    if (paragraph.trim() === '') {
      allLines.push('');
      return;
    }

    const words = paragraph.split(' ');
    let currentLine = '';

    for (let n = 0; n < words.length; n++) {
      const testLine = currentLine + (currentLine ? ' ' : '') + words[n];
      const metrics = ctx.measureText(testLine);
      const testWidth = metrics.width;

      if (testWidth > maxWidth && n > 0) {
        allLines.push(currentLine);
        currentLine = words[n];
      } else {
        currentLine = testLine;
      }
    }
    allLines.push(currentLine);
  });

  return allLines;
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  background: HTMLImageElement | HTMLVideoElement | null,
  text: string,
  progress: number,
  animationType: AnimationType = AnimationType.VERTICAL_SCROLL
) => {
  const ctx = canvas.getContext('2d', { alpha: false });
  if (!ctx) return;

  const width = canvas.width;
  const height = canvas.height;

  // 1. Draw Background
  if (background) {
    const bgWidth = background instanceof HTMLVideoElement ? background.videoWidth : background.width;
    const bgHeight = background instanceof HTMLVideoElement ? background.videoHeight : background.height;

    const bgAspect = bgWidth / bgHeight;
    const canvasAspect = width / height;
    let renderWidth, renderHeight, x, y;

    if (bgAspect > canvasAspect) {
      renderHeight = height;
      renderWidth = height * bgAspect;
      x = (width - renderWidth) / 2;
      y = 0;
    } else {
      renderWidth = width;
      renderHeight = width / bgAspect;
      x = 0;
      y = (height - renderHeight) / 2;
    }

    // If it's a video, ensure we draw the current frame
    ctx.drawImage(background, x, y, renderWidth, renderHeight);
  } else {
    const grad = ctx.createLinearGradient(0, 0, 0, height);
    grad.addColorStop(0, '#042f2e');
    grad.addColorStop(1, '#020617');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, width, height);
  }

  // 2. Dark Overlay
  ctx.fillStyle = 'rgba(0, 0, 0, 0.4)';
  ctx.fillRect(0, 0, width, height);

  // 3. Text Setup
  ctx.direction = 'rtl';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'white';

  ctx.shadowColor = 'rgba(0,0,0,0.8)';
  ctx.shadowBlur = 15;
  ctx.shadowOffsetY = 5;

  const fontSize = width * 0.07;
  // Fallback fonts for Emojis
  ctx.font = `bold ${fontSize}px "Noto Nastaliq Urdu", "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", sans-serif`;

  const maxWidth = width * 0.85;
  const lines = wrapText(ctx, text, maxWidth);
  const lineHeight = fontSize * 2.5;
  const totalHeight = lines.length * lineHeight;

  ctx.save();

  if (animationType === AnimationType.VERTICAL_SCROLL) {
    const startPos = height * 0.8;
    const endPos = height * 0.2 - totalHeight + lineHeight;
    let currentY = startPos + (endPos - startPos) * progress;

    lines.forEach((line) => {
      if (currentY > -lineHeight && currentY < height + lineHeight) {
        if (line.trim()) ctx.fillText(line, width / 2, currentY);
      }
      currentY += lineHeight;
    });
  } else if (animationType === AnimationType.LEFT_TO_RIGHT || animationType === AnimationType.RIGHT_TO_LEFT) {
    // Single-block horizontal movement
    // Calculate vertical center
    const blockStartY = (height - totalHeight) / 2 + lineHeight / 2;

    // Horizontal range: from offscreen left to offscreen right (or vice versa)
    const padding = width * 0.6;
    const startX = animationType === AnimationType.LEFT_TO_RIGHT ? -padding : width + padding;
    const endX = animationType === AnimationType.LEFT_TO_RIGHT ? width + padding : -padding;

    const currentX = startX + (endX - startX) * progress;

    lines.forEach((line, i) => {
      const y = blockStartY + (i * lineHeight);
      if (line.trim()) ctx.fillText(line, currentX, y);
    });
  }

  ctx.restore();
  ctx.shadowBlur = 0;
};

