  // Handle preview rendering
  useEffect(() => {
    if (canvasRef.current && (currentResult?.imageUrl || settings.customBackgroundUrl || settings.text)) {
      const isVideo = settings.customBackgroundType === 'video' && settings.backgroundSource === BackgroundSource.CUSTOM;

      if (isVideo && settings.customBackgroundUrl) {
        if (!backgroundVideoRef.current) {
          const video = document.createElement('video');
          video.src = settings.customBackgroundUrl;
          video.muted = true;
          video.loop = true;
          video.crossOrigin = "anonymous";
          video.onloadeddata = () => {
             drawVideoFrame(canvasRef.current!, video, settings.text, 0, settings.animationType);
          };
          backgroundVideoRef.current = video;
        } else {
           drawVideoFrame(canvasRef.current!, backgroundVideoRef.current, settings.text, 0, settings.animationType);
        }
      } else {
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => drawVideoFrame(canvasRef.current!, img, settings.text, 0, settings.animationType);

        const src = (settings.backgroundSource === BackgroundSource.CUSTOM) 
          ? settings.customBackgroundUrl 
          : currentResult?.imageUrl;

        if (src) {
          img.src = src;
        } else {
          drawVideoFrame(canvasRef.current!, null, settings.text, 0, settings.animationType);
        }
      }
    }
  }, [currentResult, settings.text, settings.animationType, settings.backgroundSource, settings.customBackgroundUrl]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const url = URL.createObjectURL(file);
    const type = file.type.startsWith('video') ? 'video' : 'image';

    setSettings(prev => ({
      ...prev,
      backgroundSource: BackgroundSource.CUSTOM,
      customBackgroundUrl: url,
      customBackgroundType: type as any
    }));

    // Reset video ref if source changes
    backgroundVideoRef.current = null;
  };

  const stopGeneration = () => {
    stopSignalRef.current = true;
    setIsGenerating(false);
  };

  const handleGenerate = async () => {
    if (!settings.text.trim()) return;
    setIsGenerating(true);
    stopSignalRef.current = false;
    setCurrentResult(null);

    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const base64Audio = await generateNarration(settings.text, settings.voice);
      if (stopSignalRef.current) return;

      const audioData = decode(base64Audio);
      const audioBuffer = await decodeAudioData(audioData, audioContextRef.current, 24000, 1);
      const audioBlob = new Blob([audioData], { type: 'audio/pcm' });
      const audioUrl = URL.createObjectURL(audioBlob);

      let imageUrl;
      if (settings.backgroundSource === BackgroundSource.AI && settings.generateImage) {
        imageUrl = await generateAtmosphereImage(settings.style);
        if (stopSignalRef.current) return;
      }

      setCurrentResult({ audioUrl, imageUrl: imageUrl || undefined, audioBuffer, base64Audio });

      setHistory(prev => [{
        id: Date.now().toString(),
        text: settings.text,
        voice: settings.voice,
        timestamp: Date.now(),
        audioUrl,
        imageUrl: imageUrl || undefined
      }, ...prev]);

    } catch (error: any) {
      if (!stopSignalRef.current) {
        console.error("Generation failed", error);
        alert(`Generation failed: ${error.message || "Unknown error"}`);
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const startExport = async () => {
    if (!currentResult || !currentResult.audioBuffer) return;

    setIsRecording(true);
    setRecordProgress(0);

    const canvas = recordCanvasRef.current!;
    const stream = canvas.captureStream(60);
    const audioCtx = audioContextRef.current!;
    const dest = audioCtx.createMediaStreamDestination();

    const recorder = new MediaRecorder(new MediaStream([...stream.getTracks(), ...dest.stream.getTracks()]), {
      mimeType: 'video/webm;codecs=vp9'
    });

    const chunks: Blob[] = [];
    recorder.ondataavailable = (e) => chunks.push(e.data);
    recorder.onstop = () => {
      const blob = new Blob(chunks, { type: 'video/webm' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `noor-${Date.now()}.webm`;
      a.click();
      setIsRecording(false);
    };

    let bgSource: HTMLImageElement | HTMLVideoElement | null = null;
    const isVideo = settings.customBackgroundType === 'video' && settings.backgroundSource === BackgroundSource.CUSTOM;

    if (isVideo && settings.customBackgroundUrl) {
      bgSource = document.createElement('video');
      bgSource.src = settings.customBackgroundUrl;
      bgSource.muted = true;
      bgSource.crossOrigin = "anonymous";
      await new Promise(r => bgSource!.onloadeddata = r);
    } else {
      const src = (settings.backgroundSource === BackgroundSource.CUSTOM) 
        ? settings.customBackgroundUrl 
        : currentResult.imageUrl;
      if (src) {
        bgSource = new Image();
        bgSource.crossOrigin = "anonymous";
        bgSource.src = src;
        await new Promise(r => (bgSource as HTMLImageElement).onload = r);
      }
    }

    const sourceNode = audioCtx.createBufferSource();
    sourceNode.buffer = currentResult.audioBuffer;
    sourceNode.connect(dest);
    sourceNode.connect(audioCtx.destination);

    recorder.start();
    sourceNode.start();

    const duration = currentResult.audioBuffer.duration;
    const startTime = audioCtx.currentTime;

    const renderLoop = () => {
      const elapsed = audioCtx.currentTime - startTime;
      const progress = Math.min(elapsed / duration, 1);

      if (bgSource instanceof HTMLVideoElement) {
        bgSource.currentTime = elapsed % bgSource.duration;
      }

      drawVideoFrame(canvas, bgSource, settings.text, progress, settings.animationType);
      setRecordProgress(progress * 100);

      if (progress < 1) {
        requestAnimationFrame(renderLoop);
      } else {
        setTimeout(() => recorder.stop(), 500);
      }
    };

    renderLoop();
  };

  const playPreview = async () => {
    if (!currentResult || !currentResult.audioBuffer || !audioContextRef.current) return;
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') await ctx.resume();
    const source = ctx.createBufferSource();
    source.buffer = currentResult.audioBuffer;
    source.connect(ctx.destination);
    source.start();
  };

  return (
    <div className="min-h-screen flex flex-col items-center bg-[#020617] p-4 md:p-8">
