            <Video className="w-8 h-8 text-yellow-400" />
          </div>
          <div>
            <h1 className="text-3xl font-bold text-white tracking-tight">Noor Narrator Studio</h1>
            <p className="text-sm text-emerald-500 font-semibold tracking-widest uppercase">AI Video Content Creator</p>
          </div>
        </div>

        <button 
          onClick={() => setShowHistory(!showHistory)}
          className="px-5 py-2.5 glass-card rounded-xl hover:bg-emerald-900/30 transition-all flex items-center gap-2 border border-emerald-900/50"
        >
          {showHistory ? <ArrowLeft className="w-5 h-5" /> : <History className="w-5 h-5" />}
          <span className="hidden sm:inline font-medium">{showHistory ? "Back" : "Archives"}</span>
