export const wrapText = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number
): string[] => {
  // Split by manual newlines to respect user-intended pauses and formatting
  const paragraphs = text.split('\n');
  const allLines: string[] = [];

  paragraphs.forEach((paragraph) => {
    const trimmed = paragraph.trim();
    if (trimmed === '') {
      allLines.push('');
      return;
    }

    const words = trimmed.split(' ');
    let currentLine = '';

    for (let n = 0; n < words.length; n++) {
      const testLine = currentLine + (currentLine ? ' ' : '') + words[n];
      const metrics = ctx.measureText(testLine);
      const testWidth = metrics.width;

      if (testWidth > maxWidth && n > 0) {
        allLines.push(currentLine);
        currentLine = words[n];
      } else {
        currentLine = testLine;
      }
    }
    allLines.push(currentLine);
  });

  return allLines;
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  background: HTMLImageElement | HTMLVideoElement | null,
  text: string,
  progress: number,
  animationType: AnimationType = AnimationType.VERTICAL_SCROLL
) => {
  const ctx = canvas.getContext('2d', { alpha: false });
  if (!ctx) return;

  const width = canvas.width;
  const height = canvas.height;

  // 1. Draw Background
  if (background) {
    const bgWidth = background instanceof HTMLVideoElement ? background.videoWidth : background.width;
    const bgHeight = background instanceof HTMLVideoElement ? background.videoHeight : background.height;

    const bgAspect = bgWidth / bgHeight;
    const canvasAspect = width / height;
    let renderWidth, renderHeight, x, y;

    if (bgAspect > canvasAspect) {
      renderHeight = height;
      renderWidth = height * bgAspect;
      x = (width - renderWidth) / 2;
      y = 0;
    } else {
      renderWidth = width;
      renderHeight = width / bgAspect;
      x = 0;
      y = (height - renderHeight) / 2;
    }
    ctx.drawImage(background, x, y, renderWidth, renderHeight);
  } else {
    // Elegant fallback gradient
    const grad = ctx.createLinearGradient(0, 0, 0, height);
    grad.addColorStop(0, '#042f2e');
    grad.addColorStop(1, '#020617');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, width, height);
  }

  // 2. High-quality Vignette Overlay
  const vignette = ctx.createRadialGradient(width / 2, height / 2, 0, width / 2, height / 2, height);
  vignette.addColorStop(0, 'rgba(0, 0, 0, 0.2)');
  vignette.addColorStop(1, 'rgba(0, 0, 0, 0.7)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  // 3. Text Configuration
  ctx.direction = 'rtl';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'white';

  // Glowing text effect for high-end aesthetic
  ctx.shadowColor = 'rgba(0, 0, 0, 1)';
  ctx.shadowBlur = 25;
  ctx.shadowOffsetY = 8;

  const fontSize = width * 0.08;
  // Comprehensive font stack for Urdu (Nastaliq), Emojis, and Quotes
  ctx.font = `bold ${fontSize}px "Noto Nastaliq Urdu", "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", "Inter", sans-serif`;

  const maxWidth = width * 0.88;
  const lineHeight = fontSize * 2.4;

  ctx.save();

  if (animationType === AnimationType.VERTICAL_SCROLL) {
    // Traditional full-text vertical scroll
    const lines = wrapText(ctx, text, maxWidth);
    const totalHeight = lines.length * lineHeight;
    const startPos = height * 0.85;
    const endPos = height * 0.15 - totalHeight + lineHeight;
    let currentY = startPos + (endPos - startPos) * progress;

    lines.forEach((line) => {
      if (currentY > -lineHeight && currentY < height + lineHeight) {
        if (line.trim()) ctx.fillText(line, width / 2, currentY);
      }
      currentY += lineHeight;
    });
  } else {
    // "Noor Studio" Sequential Horizontal Animation
    // We split by newline and filter out empty paragraphs to maintain smooth flow
    const paragraphs = text.split('\n').filter(p => p.trim() !== '');
    const totalParagraphs = paragraphs.length;

    if (totalParagraphs > 0) {
      // Calculate which paragraph should be visible based on overall progress
      const pIndex = Math.min(Math.floor(progress * totalParagraphs), totalParagraphs - 1);
      const pProgress = (progress * totalParagraphs) % 1;
      const currentParagraph = paragraphs[pIndex];

      const blockLines = wrapText(ctx, currentParagraph, maxWidth);
      const blockTotalHeight = blockLines.length * lineHeight;

      // Keep text centered vertically
      const blockStartY = (height - blockTotalHeight) / 2 + (lineHeight / 2);

      /**
       * Right-to-Left (RTL) Movement Logic:
       * For Urdu, we usually want text to enter from the RIGHT and exit to the LEFT.
       * If animationType is RIGHT_TO_LEFT, text starts at X > width and ends at X < 0.
       */
      const padding = width * 0.8; // Distance offscreen to ensure smooth entrance/exit
      let startX, endX;

      if (animationType === AnimationType.RIGHT_TO_LEFT) {
        startX = width + padding;
        endX = -padding;
      } else {
        startX = -padding;
        endX = width + padding;
      }

      const currentX = startX + (endX - startX) * pProgress;

      blockLines.forEach((line, i) => {
        const y = blockStartY + (i * lineHeight);
        if (line.trim()) {
          ctx.fillText(line, currentX, y);
        }
      });
    }
  }

  ctx.restore();
  ctx.shadowBlur = 0;
};

