                </div>

                <div className="flex gap-4 mt-10">
                  <button
                    onClick={handleGenerate}
                    disabled={isGenerating || isRecording || !settings.text.trim()}
                    className="flex-1 bg-gradient-to-r from-emerald-600 to-emerald-800 hover:from-emerald-500 hover:to-emerald-700 disabled:opacity-50 text-white font-black py-5 px-8 rounded-2xl shadow-2xl transition-all flex items-center justify-center gap-4 group uppercase tracking-widest text-sm"
                  >
                    {isGenerating ? (
                      <>
                        <Loader2 className="w-6 h-6 animate-spin" />
                        Crafting Cinematic Content...
                      </>
                    ) : (
                      <>
                        <Sparkles className="w-6 h-6" />
                        Generate AI Assets
                      </>
                    )}
                  </button>

                  {isGenerating && (
                    <button
                      onClick={stopGeneration}
                      className="bg-red-900/30 hover:bg-red-900/50 text-red-500 border border-red-900/40 font-black px-6 rounded-2xl transition-all flex items-center justify-center gap-2 uppercase tracking-widest text-xs"
                    >
                      <Square className="w-5 h-5 fill-current" />
                      Abort
                    </button>
                  )}
                </div>
              </section>
            </div>

            <div className="lg:col-span-5 space-y-8">
              <section className="glass-card rounded-3xl p-6 shadow-2xl sticky top-8">
                <div className="flex items-center justify-between mb-6">
                  <h2 className="text-lg font-bold flex items-center gap-3 text-emerald-400">
                    <Play className="w-5 h-5" /> Live Preview
                  </h2>
                </div>

                <div className="relative group preview-container w-full max-w-[320px] mx-auto rounded-3xl overflow-hidden shadow-2xl border-4 border-emerald-900/30 bg-slate-900">
                  <canvas 
                    ref={canvasRef} 
                    width={1080} 
                    height={1920} 
                    className="w-full h-full object-contain"
                  />

                  {isRecording && (
                    <div className="absolute inset-0 bg-black/80 flex flex-col items-center justify-center p-8 text-center backdrop-blur-md">
                      <div className="w-16 h-16 relative mb-6">
                        <div className="absolute inset-0 border-4 border-emerald-900 rounded-full"></div>
                        <div className="absolute inset-0 border-4 border-yellow-500 rounded-full border-t-transparent animate-spin"></div>
                      </div>
                      <h3 className="text-lg font-bold text-white mb-2">Exporting MP4</h3>
                      <p className="text-emerald-500 text-sm font-bold tracking-widest">{Math.round(recordProgress)}%</p>
                    </div>
                  )}

                  {!currentResult && !isGenerating && settings.backgroundSource === BackgroundSource.AI && (
                    <div className="absolute inset-0 flex flex-col items-center justify-center p-10 text-center text-slate-800">
                      <ImageIcon className="w-12 h-12 mb-4 opacity-10" />
                      <p className="text-xs font-medium italic">Generate to see preview</p>
                    </div>
                  )}
                </div>

                <div className="mt-8 space-y-4">
                  <button
                    onClick={playPreview}
                    disabled={!currentResult || isRecording}
                    className="w-full flex items-center justify-center gap-3 p-4 bg-emerald-900/30 text-emerald-400 rounded-2xl hover:bg-emerald-800/40 transition-all font-bold disabled:opacity-30 border border-emerald-800/30"
                  >
                    <Volume2 className="w-5 h-5" /> Hear Narration
                  </button>

                  <button
                    onClick={startExport}
                    disabled={!currentResult || isRecording}
                    className="w-full flex items-center justify-center gap-4 p-5 bg-yellow-500 text-slate-950 rounded-2xl hover:bg-yellow-400 transition-all font-black shadow-xl shadow-yellow-500/20 disabled:opacity-50 group"
                  >
                    <Download className="w-6 h-6 group-hover:-translate-y-1 transition-transform" />
                    DOWNLOAD SOCIAL VIDEO
                  </button>
                </div>
              </section>
            </div>
          </>
        ) : (
          <div className="col-span-12 space-y-10 animate-in fade-in slide-in-from-bottom-6 duration-500">
            <section className="glass-card rounded-[3rem] p-12 min-h-[70vh]">
               <div className="flex flex-col items-center mb-12">
                  <History className="w-16 h-16 text-emerald-800 mb-4 opacity-30" />
                  <h2 className="text-3xl font-black text-white">Creation Archives</h2>
                  <div className="w-20 h-1 bg-yellow-500 mt-4 rounded-full"></div>
                </div>
                {history.length > 0 ? (
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                    {history.map((item) => (
                      <div key={item.id} className="glass-card bg-slate-950/40 border border-emerald-900/20 rounded-3xl overflow-hidden hover:border-emerald-600/40 transition-all group cursor-pointer" onClick={() => {
                        setSettings({...settings, text: item.text, voice: item.voice});
                        setShowHistory(false);
                      }}>
                        {item.imageUrl && (
                          <div className="h-44 overflow-hidden relative">
                            <img src={item.imageUrl} alt="Memory" className="w-full h-full object-cover opacity-60" />
                            <div className="absolute inset-0 bg-gradient-to-t from-slate-950 to-transparent"></div>
                          </div>
                        )}
                        <div className="p-6">
                          <p className="urdu-font text-xl text-emerald-100 line-clamp-2" dir="rtl">{item.text}</p>
                          <div className="flex justify-between items-center mt-6">
                             <span className="text-[10px] text-emerald-800 font-bold uppercase">{new Date(item.timestamp).toLocaleDateString()}</span>
                             <span className="text-[10px] text-yellow-500 font-bold uppercase">{item.voice}</span>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-20 text-slate-700 font-bold">No history available yet.</div>
                )}
            </section>
          </div>
        )}
      </main>

      <footer className="mt-12 py-10 text-center text-slate-800 text-[10px] font-black uppercase tracking-[0.3em]">
        &copy; {new Date().getFullYear()} Noor Narrator Studio &bull; Premium AI Video Solutions
      </footer>
    </div>
  );
};

export default App;

import { AnimationType } from "../types";

export const wrapText = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number
): string[] => {
  const paragraphs = text.split('\n');
  const allLines: string[] = [];

  paragraphs.forEach((paragraph) => {
    const trimmed = paragraph.trim();
    if (trimmed === '') {
      allLines.push('');
      return;
    }

    const words = trimmed.split(' ');
    let currentLine = '';

    for (let n = 0; n < words.length; n++) {
      const testLine = currentLine + (currentLine ? ' ' : '') + words[n];
      const metrics = ctx.measureText(testLine);
      const testWidth = metrics.width;

      if (testWidth > maxWidth && n > 0) {
        allLines.push(currentLine);
        currentLine = words[n];
      } else {
        currentLine = testLine;
      }
    }
    allLines.push(currentLine);
  });

  return allLines;
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  background: HTMLImageElement | HTMLVideoElement | null,
  text: string,
  progress: number,
  animationType: AnimationType = AnimationType.VERTICAL_SCROLL
) => {
  const ctx = canvas.getContext('2d', { alpha: false });
  if (!ctx) return;

  const width = canvas.width;
  const height = canvas.height;

  // 1. Draw Background
  if (background) {
    const bgWidth = background instanceof HTMLVideoElement ? background.videoWidth : background.width;
    const bgHeight = background instanceof HTMLVideoElement ? background.videoHeight : background.height;

    // Avoid drawing if video dimensions aren't ready
    if (bgWidth === 0 || bgHeight === 0) return;

    const bgAspect = bgWidth / bgHeight;
    const canvasAspect = width / height;
    let renderWidth, renderHeight, x, y;

    if (bgAspect > canvasAspect) {
      renderHeight = height;
      renderWidth = height * bgAspect;
      x = (width - renderWidth) / 2;
      y = 0;
    } else {
      renderWidth = width;
      renderHeight = width / bgAspect;
      x = 0;
      y = (height - renderHeight) / 2;
    }
    ctx.drawImage(background, x, y, renderWidth, renderHeight);
  } else {
    const grad = ctx.createLinearGradient(0, 0, 0, height);
    grad.addColorStop(0, '#042f2e');
    grad.addColorStop(1, '#020617');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, width, height);
  }

  // 2. High-quality Overlay
  const vignette = ctx.createRadialGradient(width / 2, height / 2, 0, width / 2, height / 2, height);
  vignette.addColorStop(0, 'rgba(0, 0, 0, 0.3)');
  vignette.addColorStop(1, 'rgba(0, 0, 0, 0.75)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  // 3. Text Setup
  ctx.direction = 'rtl';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'white';

  ctx.shadowColor = 'rgba(0, 0, 0, 1)';
  ctx.shadowBlur = 30;
  ctx.shadowOffsetY = 10;

  const fontSize = width * 0.085;
  ctx.font = `bold ${fontSize}px "Noto Nastaliq Urdu", "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", "Inter", sans-serif`;

  const maxWidth = width * 0.88;
  const lineHeight = fontSize * 2.5;

  ctx.save();

  if (animationType === AnimationType.VERTICAL_SCROLL) {
    const lines = wrapText(ctx, text, maxWidth);
    const totalHeight = lines.length * lineHeight;
    const startPos = height * 0.85;
    const endPos = height * 0.15 - totalHeight + lineHeight;
    let currentY = startPos + (endPos - startPos) * progress;

    lines.forEach((line) => {
      if (currentY > -lineHeight && currentY < height + lineHeight) {
        if (line.trim()) ctx.fillText(line, width / 2, currentY);
      }
      currentY += lineHeight;
    });
  } else {
    // Sequential "Slide and Stay" Logic
    const paragraphs = text.split('\n').filter(p => p.trim() !== '');
    const totalParagraphs = paragraphs.length;

    if (totalParagraphs > 0) {
      const pIndex = Math.min(Math.floor(progress * totalParagraphs), totalParagraphs - 1);
      const pProgress = (progress * totalParagraphs) % 1;
      const currentParagraph = paragraphs[pIndex];

      const blockLines = wrapText(ctx, currentParagraph, maxWidth);
      const blockTotalHeight = blockLines.length * lineHeight;
      const blockStartY = (height - blockTotalHeight) / 2 + (lineHeight / 2);

      const padding = width * 1.0; 
      const slideDuration = 0.25; // 25% of the time slice spent sliding

      let startX, targetX = width / 2;

      if (animationType === AnimationType.RIGHT_TO_LEFT) {
        startX = width + padding;
      } else {
        startX = -padding;
      }

      // If within sliding duration, interpolate. Otherwise, stay at target.
      const currentX = pProgress < slideDuration 
        ? startX + (targetX - startX) * (pProgress / slideDuration)
        : targetX;

      blockLines.forEach((line, i) => {
        const y = blockStartY + (i * lineHeight);
        if (line.trim()) {
          ctx.fillText(line, currentX, y);
        }
      });
    }
  }

  ctx.restore();
  ctx.shadowBlur = 0;
};

import React, { useState, useRef, useEffect } from 'react';
import { 
  Video, 
  Download, 
  Loader2, 
  Play, 
  Sparkles, 
  History, 
  Volume2, 
  Mic2, 
  ArrowLeft,
  Image as ImageIcon,
  Square,
  Upload
} from 'lucide-react';
import { VoiceName, NarrationHistoryItem, GenerationSettings, AnimationType, BackgroundSource } from './types';
import { generateNarration, generateAtmosphereImage } from './services/geminiService';
import { decode, decodeAudioData } from './utils/audioUtils';
import { drawVideoFrame } from './utils/videoUtils';

const DEFAULT_TEXT = `سکون کی نیند اور اللہ کی حفاظت۔ ✨

نبی کریم صلی اللہ علیہ وآلہ وسلم کا بتایا ہوا ایک ایسا عمل جو ہمیں رات بھر شیطان کے شر سے محفوظ رکھتا ہے۔ 🌙

آپ صلی اللہ علیہ وآلہ وسلم نے فرمایا: "جب تم رات کو اپنے بستر پر سونے کے لیے جاؤ تو آیت الکرسی پڑھ لیا کرو۔" 📖

صحیح البخاری حدیث نمبر 5010۔`;

const App: React.FC = () => {
  const [settings, setSettings] = useState<GenerationSettings>({
    text: DEFAULT_TEXT,
    voice: VoiceName.CHARON,
    generateImage: true,
    style: "Starry night sky over a peaceful mosque silhouette",
    animationType: AnimationType.VERTICAL_SCROLL,
    backgroundSource: BackgroundSource.AI
  });

  const [isGenerating, setIsGenerating] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordProgress, setRecordProgress] = useState(0);
  const [currentResult, setCurrentResult] = useState<{ 
    audioUrl: string; 
    imageUrl?: string; 
    audioBuffer?: AudioBuffer;
    base64Audio: string;
  } | null>(null);
  const [history, setHistory] = useState<NarrationHistoryItem[]>([]);
  const [showHistory, setShowHistory] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const recordCanvasRef = useRef<HTMLCanvasElement>(null);
  const backgroundVideoRef = useRef<HTMLVideoElement | null>(null);
  const stopSignalRef = useRef<boolean>(false);
  const previewRequestRef = useRef<number>(0);

  // Handle preview rendering and animation loop
  useEffect(() => {
    const isVideo = settings.customBackgroundType === 'video' && settings.backgroundSource === BackgroundSource.CUSTOM;
    const paragraphs = settings.text.split('\n').filter(p => p.trim() !== '');
    // Preview at 30% of the first paragraph to show it in its "stay" phase
    const previewProgress = (settings.animationType === AnimationType.VERTICAL_SCROLL) 
      ? 0 
      : (0.3 / (paragraphs.length || 1));

    const draw = () => {
      if (!canvasRef.current) return;

      let bg: HTMLImageElement | HTMLVideoElement | null = null;
      if (isVideo && settings.customBackgroundUrl) {
        if (!backgroundVideoRef.current || backgroundVideoRef.current.src !== settings.customBackgroundUrl) {
          const v = document.createElement('video');
          v.src = settings.customBackgroundUrl;
          v.muted = true;
          v.loop = true;
          v.crossOrigin = "anonymous";
          v.play().catch(() => {});
          backgroundVideoRef.current = v;
        }
        bg = backgroundVideoRef.current;
      } else {
        const src = (settings.backgroundSource === BackgroundSource.CUSTOM) 
          ? settings.customBackgroundUrl 
          : currentResult?.imageUrl;

        if (src) {
          const img = new Image();
          img.crossOrigin = "anonymous";
          img.src = src;
          bg = img;
        }
      }

      drawVideoFrame(canvasRef.current, bg, settings.text, previewProgress, settings.animationType);

      // If it's a video, we need to keep drawing to see motion
      if (isVideo) {
        previewRequestRef.current = requestAnimationFrame(draw);
      }
    };

    // Initial draw
    draw();

    return () => {
      if (previewRequestRef.current) {
        cancelAnimationFrame(previewRequestRef.current);
      }
    };
  }, [currentResult, settings.text, settings.animationType, settings.backgroundSource, settings.customBackgroundUrl, settings.customBackgroundType]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const url = URL.createObjectURL(file);
    const type = file.type.startsWith('video') ? 'video' : 'image';

    setSettings(prev => ({
      ...prev,
      backgroundSource: BackgroundSource.CUSTOM,
      customBackgroundUrl: url,
      customBackgroundType: type as any
    }));

    backgroundVideoRef.current = null;
  };

  const stopGeneration = () => {
    stopSignalRef.current = true;
    setIsGenerating(false);
  };

  const handleGenerate = async () => {
    if (!settings.text.trim()) return;
    setIsGenerating(true);
    stopSignalRef.current = false;
    setCurrentResult(null);

    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const base64Audio = await generateNarration(settings.text, settings.voice);
      if (stopSignalRef.current) return;

      const audioData = decode(base64Audio);
      const audioBuffer = await decodeAudioData(audioData, audioContextRef.current, 24000, 1);
      const audioBlob = new Blob([audioData], { type: 'audio/pcm' });
      const audioUrl = URL.createObjectURL(audioBlob);

      let imageUrl;
      if (settings.backgroundSource === BackgroundSource.AI && settings.generateImage) {
        imageUrl = await generateAtmosphereImage(settings.style);
        if (stopSignalRef.current) return;
      }

      setCurrentResult({ audioUrl, imageUrl: imageUrl || undefined, audioBuffer, base64Audio });

      setHistory(prev => [{
        id: Date.now().toString(),
        text: settings.text,
        voice: settings.voice,
        timestamp: Date.now(),
        audioUrl,
        imageUrl: imageUrl || undefined
      }, ...prev]);

    } catch (error: any) {
      if (!stopSignalRef.current) {
        console.error("Generation failed", error);
        alert(`Generation failed: ${error.message || "Unknown error"}`);
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const startExport = async () => {
    if (!currentResult || !currentResult.audioBuffer) return;

    setIsRecording(true);
    setRecordProgress(0);

    const canvas = recordCanvasRef.current!;
    const stream = canvas.captureStream(60);
    const audioCtx = audioContextRef.current!;
    const dest = audioCtx.createMediaStreamDestination();

    const recorder = new MediaRecorder(new MediaStream([...stream.getTracks(), ...dest.stream.getTracks()]), {
      mimeType: 'video/webm;codecs=vp9'
    });

    const chunks: Blob[] = [];
    recorder.ondataavailable = (e) => chunks.push(e.data);
    recorder.onstop = () => {
      const blob = new Blob(chunks, { type: 'video/webm' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `noor-${Date.now()}.webm`;
      a.click();
      setIsRecording(false);
    };

    let bgSource: HTMLImageElement | HTMLVideoElement | null = null;
    const isVideo = settings.customBackgroundType === 'video' && settings.backgroundSource === BackgroundSource.CUSTOM;

    if (isVideo && settings.customBackgroundUrl) {
      bgSource = document.createElement('video');
      bgSource.src = settings.customBackgroundUrl;
      bgSource.muted = true;
      bgSource.crossOrigin = "anonymous";
      await new Promise(r => bgSource!.onloadeddata = r);
      (bgSource as HTMLVideoElement).play();
    } else {
      const src = (settings.backgroundSource === BackgroundSource.CUSTOM) 
        ? settings.customBackgroundUrl 
        : currentResult.imageUrl;
      if (src) {
        bgSource = new Image();
        bgSource.crossOrigin = "anonymous";
        bgSource.src = src;
        await new Promise(r => (bgSource as HTMLImageElement).onload = r);
      }
    }

    const sourceNode = audioCtx.createBufferSource();
    sourceNode.buffer = currentResult.audioBuffer;
    sourceNode.connect(dest);
    sourceNode.connect(audioCtx.destination);

    recorder.start();
    sourceNode.start();

    const duration = currentResult.audioBuffer.duration;
    const startTime = audioCtx.currentTime;

    const renderLoop = () => {
      const elapsed = audioCtx.currentTime - startTime;
      const progress = Math.min(elapsed / duration, 1);

      if (bgSource instanceof HTMLVideoElement) {
        bgSource.currentTime = elapsed % bgSource.duration;
      }

      drawVideoFrame(canvas, bgSource, settings.text, progress, settings.animationType);
      setRecordProgress(progress * 100);

      if (progress < 1) {
        requestAnimationFrame(renderLoop);
      } else {
        setTimeout(() => recorder.stop(), 500);
      }
    };

    renderLoop();
  };

  const playPreview = async () => {
    if (!currentResult || !currentResult.audioBuffer || !audioContextRef.current) return;
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') await ctx.resume();
    const source = ctx.createBufferSource();
    source.buffer = currentResult.audioBuffer;
    source.connect(ctx.destination);
    source.start();
  };

  return (
