import { GoogleGenAI, Modality } from "@google/genai";
import { VoiceName } from "../types";

const safetySettings = [
  {
    category: "HARM_CATEGORY_HARASSMENT",
    threshold: "BLOCK_NONE",
  },
  {
    category: "HARM_CATEGORY_HATE_SPEECH",
    threshold: "BLOCK_NONE",
  },
  {
    category: "HARM_CATEGORY_SEXUALLY_EXPLICIT",
    threshold: "BLOCK_NONE",
  },
  {
    category: "HARM_CATEGORY_DANGEROUS_CONTENT",
    threshold: "BLOCK_NONE",
  },
];

export const generateNarration = async (text: string, voice: VoiceName) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Use systemInstruction for tone and style to prevent interference with the main content text
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text }] }],
    config: {
      systemInstruction: "Narrate the following text in a calm, soulful, and respectful manner. Speak clearly and with appropriate spiritual gravity.",
      responseModalities: [Modality.AUDIO], 
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: voice },
        },
      },
      safetySettings: safetySettings as any,
    },
  });

  if (!response.candidates || response.candidates.length === 0) {
    throw new Error("The AI was unable to generate a response. This might be due to safety filters or a temporary service issue.");
  }

  const candidate = response.candidates[0];

  // Robust finish reason checking
  if (candidate.finishReason && candidate.finishReason !== 'STOP') {
    if (candidate.finishReason === 'SAFETY') {
      throw new Error("This content was flagged by safety filters. Please try rephrasing the text.");
    }
    throw new Error(`Narration failed with reason: ${candidate.finishReason}. Please try again with shorter text.`);
  }

  if (!candidate.content || !candidate.content.parts) {
    throw new Error("The model returned a response without audio data. Try slightly modifying your text.");
  }

  // Find the audio data part
  for (const part of candidate.content.parts) {
    if (part.inlineData && part.inlineData.data) {
      return part.inlineData.data;
    }
  }

  throw new Error("Audio data was not found in the AI response. Please try again.");
};

export const generateAtmosphereImage = async (prompt: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const imagePrompt = `Atmospheric spiritual background: ${prompt}. Cinematic photography, soft ethereal lighting, peaceful, no human faces, high quality 4k.`;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [{ text: imagePrompt }],
    },
    config: {
      imageConfig: {
        aspectRatio: "16:9"
      },
      safetySettings: safetySettings as any,
    }
  });

  if (!response.candidates || response.candidates.length === 0) return null;

  const candidate = response.candidates[0];
  if (candidate.content && candidate.content.parts) {
    for (const part of candidate.content.parts) {
      if (part.inlineData && part.inlineData.data) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
  }

  return null;
};

