          : currentResult?.imageUrl;

        if (src) {
          const img = new Image();
          img.crossOrigin = "anonymous";
          img.src = src;
          bg = img;
        }
      }

      drawVideoFrame(canvasRef.current, bg, settings.text, previewProgress, settings.animationType);

      // Keep animating if we have a video background
      if (isVideo) {
        previewRequestRef.current = requestAnimationFrame(draw);
      }
    };

    draw();

    return () => {
      if (previewRequestRef.current) {
        cancelAnimationFrame(previewRequestRef.current);
      }
    };
  }, [currentResult, settings.text, settings.animationType, settings.backgroundSource, settings.customBackgroundUrl, settings.customBackgroundType]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
