    category: "HARM_CATEGORY_DANGEROUS_CONTENT",
    threshold: "BLOCK_NONE",
  },
];

/**
 * Sanitizes text for TTS by removing emojis and characters that aren't spoken.
 * This prevents processing errors in the model's tokenizer/audio generator.
 */
const sanitizeForTTS = (text: string): string => {
  return text
    .replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu, '')
    .replace(/[✨🌙📖]/g, '') // Remove specific symbols often used in this app
    .trim();
};

export const generateNarration = async (text: string, voice: VoiceName) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const cleanText = sanitizeForTTS(text);

  if (!cleanText) {
    throw new Error("The script is empty or contains only non-speakable symbols.");
  }

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: cleanText }] }],
      config: {
        systemInstruction: "You are a professional narrator. Narrate the provided text with a calm, soulful, and respectful tone. Maintain spiritual gravity and clear pronunciation.",
        responseModalities: [Modality.AUDIO], 
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voice },
          },
        },
        safetySettings: safetySettings as any,
      },
    });

    if (!response.candidates || response.candidates.length === 0) {
      throw new Error("No candidates returned from AI. This may be due to safety filters.");
    }

    const candidate = response.candidates[0];

    if (candidate.finishReason && candidate.finishReason !== 'STOP') {
      const reasonMap: Record<string, string> = {
        SAFETY: "Content was flagged by safety filters.",
        RECITATION: "The content was flagged as potentially copyrighted recitation.",
        OTHER: "An internal processing error occurred."
      };
      throw new Error(reasonMap[candidate.finishReason] || `Narration failed: ${candidate.finishReason}`);
    }

    if (!candidate.content?.parts) {
      throw new Error("The model response is missing content parts.");
    }

    // Find the audio data part
    for (const part of candidate.content.parts) {
      if (part.inlineData && part.inlineData.data) {
        return part.inlineData.data;
      }
    }

    throw new Error("Audio data was missing from the generated response.");

  } catch (error: any) {
    console.error("Narration API Error:", error);
    // Specifically handle the 500 error if it's stringified in the message
    if (error.message?.includes("500") || error.message?.includes("Internal error")) {
      throw new Error("The AI service encountered a temporary internal glitch. Try again in a few seconds or simplify your script.");
    }
    throw error;
  }
};

