/**
 * Strips text of characters that might cause the TTS engine to crash or fail.
 * High-precision sanitization for Urdu characters.
 */
const sanitizeForTTS = (text: string, strict = false): string => {
  let sanitized = text
    // Replace ligatures like ﷺ (U+FDFA) with phonetic equivalent
    .replace(/\uFDFA/g, 'صلی اللہ علیہ وسلم')
    // Remove all emojis and miscellaneous symbols
    .replace(/[\u{1F000}-\u{1F9FF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B50}\u{2B55}]/gu, '');

  if (strict) {
    // Ultra-strict: Only Urdu letters and basic spaces. No digits, no punctuation.
    sanitized = sanitized.replace(/[^\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\s]/g, ' ');
  } else {
    // Normal Urdu sanitization: Keep letters, digits, and very safe punctuation.
    sanitized = sanitized.replace(/[^\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\s\d.,?!]/g, ' ');
  }

  return sanitized.replace(/\s+/g, ' ').trim();
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const generateNarration = async (text: string, voice: VoiceName, retryCount = 0): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const isStrict = retryCount > 0;
  const cleanText = sanitizeForTTS(text, isStrict);

  if (!cleanText) {
    throw new Error("The script is empty or contains no valid Urdu text.");
  }

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ 
        parts: [{ text: cleanText }] 
      }],
      config: {
        responseModalities: [Modality.AUDIO], 
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voice },
          },
        },
        safetySettings: safetySettings as any,
      },
    });

    if (!response.candidates || response.candidates.length === 0) {
      throw new Error("The narration service returned no results.");
    }

    const candidate = response.candidates[0];

    if ((candidate.finishReason === 'OTHER' || candidate.finishReason === 'RECITATION') && retryCount < 2) {
      console.warn(`Narration failed with ${candidate.finishReason}. Retrying with strict text filtering...`);
      await delay(1000);
      return generateNarration(text, voice, retryCount + 1);
    }

    if (candidate.finishReason && candidate.finishReason !== 'STOP') {
      throw new Error(`Speech synthesis stopped: ${candidate.finishReason}`);
    }

    if (!candidate.content?.parts) {
      throw new Error("Model response content is empty.");
    }

    for (const part of candidate.content.parts) {
      if (part.inlineData && part.inlineData.data) {
        return part.inlineData.data;
      }
    }

    throw new Error("Audio data part not found in model response.");

  } catch (error: any) {
    console.error(`Narration Error (Attempt ${retryCount + 1}):`, error);
    if ((error.message?.includes("500") || error.message?.includes("INTERNAL")) && retryCount < 1) {
      await delay(2500);
      return generateNarration(text, voice, retryCount + 1);
    }
    if (error.message?.includes("500") || error.message?.includes("INTERNAL") || error.message?.includes("OTHER")) {
      throw new Error("The Narration AI is having trouble processing this specific script. Try removing punctuation or using a different voice.");
    }
    throw error;
  }
};

export const generateSEOMetadata = async (script: string): Promise<SEOMetadata> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Analyze this Urdu script and generate SEO optimized social media metadata (YouTube/TikTok/Instagram). 
    Provide an engaging title, a detailed description with hashtags, and a list of keywords. 
    Script: ${script}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          description: { type: Type.STRING },
          keywords: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["title", "description", "keywords"]
      }
    }
  });

  return JSON.parse(response.text || '{}') as SEOMetadata;
};

export const generateAtmosphereImage = async (prompt: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const imagePrompt = `Peaceful atmosphere: ${prompt}. Cinematic Islamic aesthetics, mosque architecture, soft evening light, high quality.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: imagePrompt }],
      },
      config: {
        imageConfig: {
          aspectRatio: "16:9"
        },
        safetySettings: safetySettings as any,
      }
    });

    if (!response.candidates || response.candidates.length === 0) return null;

    const candidate = response.candidates[0];
    if (candidate.content && candidate.content.parts) {
      for (const part of candidate.content.parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
    }
  } catch (err) {
    console.warn("Image generation failed silently.", err);
  }
  return null;
};

