import { GoogleGenAI, Modality, Type } from "@google/genai";
import { VoiceName, SEOMetadata } from "../types";

const safetySettings = [
  { category: "HARM_CATEGORY_HARASSMENT", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_HATE_SPEECH", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_SEXUALLY_EXPLICIT", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_DANGEROUS_CONTENT", threshold: "BLOCK_NONE" },
];

/**
 * Strips text of characters that might cause the TTS engine to crash or trigger 'OTHER' errors.
 * Improved to handle Urdu-specific punctuation that often causes synthesis failures.
 */
const sanitizeForTTS = (text: string, strict = false): string => {
  let sanitized = text
    .replace(/\uFDFA/g, 'صلی اللہ علیہ وسلم') // ﷺ
    .replace(/[\u{1F000}-\u{1F9FF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B50}\u{2B55}]/gu, ''); // Emojis

  if (strict) {
    // Last resort: Only Urdu alphabet characters and spaces.
    sanitized = sanitized.replace(/[^\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\s]/g, ' ');
  } else {
    // Balanced: Keep Urdu, common digits, and very standard punctuation.
    // Avoided complex Urdu marks like tatweel or exotic diacritics that confuse the preview model.
    sanitized = sanitized.replace(/[^\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\s\d.,?!:;]/g, ' ');
  }

  return sanitized.replace(/\s+/g, ' ').trim();
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const generateNarration = async (text: string, voice: VoiceName, retryCount = 0): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const isStrict = retryCount > 0;
  const cleanText = sanitizeForTTS(text, isStrict);

  if (!cleanText) {
    throw new Error("No valid Urdu text found in script.");
  }

  try {
    // The preview TTS model often returns 'OTHER' if the prompt is too complex.
    // We combine the persona and content into a single part to ensure the model understands the context immediately.
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ 
        parts: [{ 
          text: `Narrate the following text in a professional, calm Urdu voice: ${cleanText}` 
        }] 
      }],
      config: {
        responseModalities: [Modality.AUDIO], 
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voice },
          },
        },
        safetySettings: safetySettings as any,
        // Removed systemInstruction as it can cause 'OTHER' errors in audio-only modality sessions
      },
    });

    if (!response.candidates || response.candidates.length === 0) {
      throw new Error("Empty response from AI.");
    }

    const candidate = response.candidates[0];

    // 'OTHER' and 'RECITATION' are common hurdles for Islamic content.
    // RECITATION triggers if the model thinks it's reciting scripture. 
    // We try to recover by using 'strict' text which usually bypasses heuristic filters.
    if ((candidate.finishReason === 'OTHER' || candidate.finishReason === 'RECITATION') && retryCount < 2) {
      console.warn(`Narration attempt ${retryCount + 1} stopped with ${candidate.finishReason}. Retrying with strict sanitization...`);
      await delay(1500);
      return generateNarration(text, voice, retryCount + 1);
    }

    if (candidate.finishReason && candidate.finishReason !== 'STOP') {
      throw new Error(`Synthesis failed: ${candidate.finishReason}`);
    }

    const audioPart = candidate.content?.parts?.find(p => p.inlineData?.data);
    if (audioPart?.inlineData?.data) {
      return audioPart.inlineData.data;
    }

    throw new Error("No audio data returned.");

  } catch (error: any) {
    console.error(`Narration Error (Attempt ${retryCount + 1}):`, error);

    // Retry on 500/Internal
    if ((error.message?.includes("500") || error.message?.includes("INTERNAL")) && retryCount < 1) {
      await delay(3000);
      return generateNarration(text, voice, retryCount + 1);
    }

    throw new Error("The narration service is currently sensitive to this script. Try changing a few words or reducing punctuation.");
  }
};

export const generateSEOMetadata = async (script: string): Promise<SEOMetadata> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const response = await ai.models.generateContent({
