import { AnimationType } from "../types";

export const wrapText = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number
): string[] => {
  const paragraphs = text.split('\n');
  const allLines: string[] = [];

  paragraphs.forEach((paragraph) => {
    const trimmed = paragraph.trim();
    if (trimmed === '') {
      allLines.push('');
      return;
    }

    const words = trimmed.split(' ');
    let currentLine = '';

    for (let n = 0; n < words.length; n++) {
      const testLine = currentLine + (currentLine ? ' ' : '') + words[n];
      const metrics = ctx.measureText(testLine);
      const testWidth = metrics.width;

      if (testWidth > maxWidth && n > 0) {
        allLines.push(currentLine);
        currentLine = words[n];
      } else {
        currentLine = testLine;
      }
    }
    allLines.push(currentLine);
  });

  return allLines;
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  background: HTMLImageElement | HTMLVideoElement | null,
  text: string,
  progress: number,
  animationType: AnimationType = AnimationType.VERTICAL_SCROLL
) => {
  const ctx = canvas.getContext('2d', { alpha: false });
  if (!ctx) return;

  const width = canvas.width;
  const height = canvas.height;

  // 1. Background Rendering
  if (background) {
    const bgWidth = background instanceof HTMLVideoElement ? background.videoWidth : background.width;
    const bgHeight = background instanceof HTMLVideoElement ? background.videoHeight : background.height;

    if (bgWidth > 0 && bgHeight > 0) {
      const bgAspect = bgWidth / bgHeight;
      const canvasAspect = width / height;
      let renderWidth, renderHeight, x, y;

      if (bgAspect > canvasAspect) {
        renderHeight = height;
        renderWidth = height * bgAspect;
        x = (width - renderWidth) / 2;
        y = 0;
      } else {
        renderWidth = width;
        renderHeight = width / bgAspect;
        x = 0;
        y = (height - renderHeight) / 2;
      }
      ctx.drawImage(background, x, y, renderWidth, renderHeight);
    }
  } else {
    const grad = ctx.createLinearGradient(0, 0, 0, height);
    grad.addColorStop(0, '#042f2e');
    grad.addColorStop(1, '#020617');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, width, height);
  }

  // 2. Cinematic Vignette
  const vignette = ctx.createRadialGradient(width / 2, height / 2, 0, width / 2, height / 2, height);
  vignette.addColorStop(0, 'rgba(0, 0, 0, 0.3)');
  vignette.addColorStop(1, 'rgba(0, 0, 0, 0.85)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  // 3. Typography Configuration
  ctx.direction = 'rtl';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'white';

  ctx.shadowColor = 'rgba(0, 0, 0, 1)';
  ctx.shadowBlur = 30;
  ctx.shadowOffsetY = 10;

  const fontSize = width * 0.082;
  ctx.font = `bold ${fontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  const maxWidth = width * 0.88;
  const lineHeight = fontSize * 2.5;

  ctx.save();

  if (animationType === AnimationType.VERTICAL_SCROLL) {
    const lines = wrapText(ctx, text, maxWidth);
    const totalContentHeight = lines.length * lineHeight;

    // To ensure text doesn't move too fast, we ensure the total scroll distance 
    // is limited based on content length. 
    // We introduce a 'dead zone' at start and end for readability (0.1 to 0.9 progress).
    const scrollEase = (p: number) => {
      if (p < 0.1) return 0;
      if (p > 0.9) return 1;
      return (p - 0.1) / 0.8;
    };

    const activeProgress = scrollEase(progress);

    // The text starts near the bottom and moves up. 
    // We cap the speed by only scrolling what is necessary plus some padding.
    const startY = height * 0.85;
    const endY = height * 0.15 - totalContentHeight;

    let currentY = startY + (endY - startY) * activeProgress;

    lines.forEach((line) => {
      // Cull invisible lines to improve rendering performance
      if (currentY > -lineHeight && currentY < height + lineHeight) {
        if (line.trim()) {
          ctx.fillText(line, width / 2, currentY);
        }
      }
      currentY += lineHeight;
    });
  } else {
    // Left-to-Right / Right-to-Left Slide Logic
    const paragraphs = text.split('\n').filter(p => p.trim() !== '');
    const totalParagraphs = paragraphs.length;

    if (totalParagraphs > 0) {
      const pIndex = Math.min(Math.floor(progress * totalParagraphs), totalParagraphs - 1);
      const pProgress = (progress * totalParagraphs) % 1; 
      const currentParagraph = paragraphs[pIndex];

      const blockLines = wrapText(ctx, currentParagraph, maxWidth);
      const blockCenterY = height / 2;
      const blockStartY = blockCenterY - ((blockLines.length - 1) * lineHeight) / 2;

      // Phase control: 25% Slide In, 50% Stay, 25% Slide Out
      const slideInEnd = 0.25;
      const slideOutStart = 0.75;

      let currentX = width / 2;
      let opacity = 1;
      const offscreenOffset = width * 1.1;

      if (animationType === AnimationType.RIGHT_TO_LEFT) {
        if (pProgress < slideInEnd) {
          const t = pProgress / slideInEnd;
          currentX = (width + offscreenOffset) - (offscreenOffset + width/2) * t;
          opacity = t;
        } else if (pProgress > slideOutStart) {
          const t = (pProgress - slideOutStart) / (1 - slideOutStart);
          currentX = (width / 2) - (width/2 + offscreenOffset) * t;
          opacity = 1 - t;
        }
      } else {
        // LEFT_TO_RIGHT
        if (pProgress < slideInEnd) {
          const t = pProgress / slideInEnd;
          currentX = -offscreenOffset + (offscreenOffset + width/2) * t;
          opacity = t;
        } else if (pProgress > slideOutStart) {
          const t = (pProgress - slideOutStart) / (1 - slideOutStart);
          currentX = (width / 2) + (width/2 + offscreenOffset) * t;
          opacity = 1 - t;
        }
      }

      ctx.globalAlpha = Math.max(0, Math.min(1, opacity));
      blockLines.forEach((line, i) => {
        const y = blockStartY + (i * lineHeight);
        if (line.trim()) {
          ctx.fillText(line, currentX, y);
        }
      });
    }
  }

  ctx.restore();
  ctx.shadowBlur = 0;
};

export enum VoiceName {
  KORE = 'Kore',
  PUCK = 'Puck',
  CHARON = 'Charon',
  FENRIR = 'Fenrir',
  ZEPHYR = 'Zephyr'
}

export enum AnimationType {
  VERTICAL_SCROLL = 'Vertical Scroll',
  LEFT_TO_RIGHT = 'Left to Right',
  RIGHT_TO_LEFT = 'Right to Left',
}

export enum AspectRatio {
  VERTICAL = '9:16',
  LANDSCAPE = '16:9',
  SQUARE = '1:1',
  FEED = '4:5'
}

export enum BackgroundSource {
  AI = 'AI Generated',
  CUSTOM = 'Custom Upload'
}

export interface SEOMetadata {
  title: string;
  description: string;
  keywords: string[];
}

export interface NarrationHistoryItem {
  id: string;
  text: string;
  voice: VoiceName;
  timestamp: number;
  audioUrl?: string;
  imageUrl?: string;
  seo?: SEOMetadata;
  aspectRatio?: AspectRatio;
}

export interface GenerationSettings {
  text: string;
  voice: VoiceName;
  generateImage: boolean;
  style: string;
  animationType: AnimationType;
  aspectRatio: AspectRatio;
  backgroundSource: BackgroundSource;
  customBackgroundUrl?: string;
  customBackgroundType?: 'image' | 'video';
}

import React, { useState, useRef, useEffect } from 'react';
import { 
  Video, 
  Download, 
  Loader2, 
  Play, 
  Sparkles, 
  History, 
  Volume2, 
  Mic2, 
  ArrowLeft,
  Image as ImageIcon,
  Square,
  Upload,
  Copy,
  Hash,
  Check,
  Monitor,
  Smartphone,
  Instagram,
  Facebook
} from 'lucide-react';
import { VoiceName, NarrationHistoryItem, GenerationSettings, AnimationType, BackgroundSource, SEOMetadata, AspectRatio } from './types';
import { generateNarration, generateAtmosphereImage, generateSEOMetadata } from './services/geminiService';
import { decode, decodeAudioData } from './utils/audioUtils';
import { drawVideoFrame } from './utils/videoUtils';

const DEFAULT_TEXT = `سکون کی نیند اور اللہ کی حفاظت۔ ✨

نبی کریم صلی اللہ علیہ وآلہ وسلم کا بتایا ہوا ایک ایسا عمل جو ہمیں رات بھر شیطان کے شر سے محفوظ رکھتا ہے۔ 🌙

آپ صلی اللہ علیہ وآلہ وسلم نے فرمایا: "جب تم رات کو اپنے بستر پر سونے کے لیے جاؤ تو آیت الکرسی پڑھ لیا کرو۔" 📖

صحیح البخاری حدیث نمبر 5010۔`;

const ASPECT_RATIO_CONFIG = {
  [AspectRatio.VERTICAL]: { width: 1080, height: 1920, label: "Reels / TikTok", icon: Smartphone },
  [AspectRatio.LANDSCAPE]: { width: 1920, height: 1080, label: "YouTube / Desktop", icon: Monitor },
  [AspectRatio.SQUARE]: { width: 1080, height: 1080, label: "Instagram Feed", icon: Instagram },
  [AspectRatio.FEED]: { width: 1080, height: 1350, label: "Facebook / Portrait", icon: Facebook },
};

const App: React.FC = () => {
  const [settings, setSettings] = useState<GenerationSettings>({
    text: DEFAULT_TEXT,
    voice: VoiceName.CHARON,
    generateImage: true,
    style: "Starry night sky over a peaceful mosque silhouette",
    animationType: AnimationType.VERTICAL_SCROLL,
    aspectRatio: AspectRatio.VERTICAL,
    backgroundSource: BackgroundSource.AI
  });

  const [isGenerating, setIsGenerating] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordProgress, setRecordProgress] = useState(0);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  const [currentResult, setCurrentResult] = useState<{ 
    audioUrl: string; 
    imageUrl?: string; 
    audioBuffer?: AudioBuffer;
    base64Audio: string;
    seo?: SEOMetadata;
  } | null>(null);

  const [history, setHistory] = useState<NarrationHistoryItem[]>([]);
  const [showHistory, setShowHistory] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const recordCanvasRef = useRef<HTMLCanvasElement>(null);
  const backgroundVideoRef = useRef<HTMLVideoElement | null>(null);
  const stopSignalRef = useRef<boolean>(false);
  const previewRequestRef = useRef<number>(0);
  const previewStartTimeRef = useRef<number>(Date.now());

  useEffect(() => {
    const isVideo = settings.customBackgroundType === 'video' && settings.backgroundSource === BackgroundSource.CUSTOM;
    previewStartTimeRef.current = Date.now();

    const draw = () => {
      if (!canvasRef.current) return;

      const config = ASPECT_RATIO_CONFIG[settings.aspectRatio];
      if (canvasRef.current.width !== config.width || canvasRef.current.height !== config.height) {
        canvasRef.current.width = config.width;
        canvasRef.current.height = config.height;
      }

      let bg: HTMLImageElement | HTMLVideoElement | null = null;
      if (isVideo && settings.customBackgroundUrl) {
        if (!backgroundVideoRef.current || backgroundVideoRef.current.src !== settings.customBackgroundUrl) {
          const v = document.createElement('video');
          v.src = settings.customBackgroundUrl;
          v.muted = true;
          v.loop = true;
          v.setAttribute('playsinline', 'true');
          v.crossOrigin = "anonymous";
          v.play().catch(err => console.warn("Video preview play failed:", err));
          backgroundVideoRef.current = v;
        }
        bg = backgroundVideoRef.current;
      } else {
        const src = (settings.backgroundSource === BackgroundSource.CUSTOM) 
          ? settings.customBackgroundUrl 
          : currentResult?.imageUrl;

        if (src) {
          const img = new Image();
          img.crossOrigin = "anonymous";
          img.src = src;
          bg = img;
        }
      }

      const duration = currentResult?.audioBuffer?.duration || 10;
      const elapsed = (Date.now() - previewStartTimeRef.current) / 1000;
      const progress = (elapsed % duration) / duration;

      drawVideoFrame(canvasRef.current, bg, settings.text, progress, settings.animationType);

      if (currentResult || isVideo || settings.customBackgroundUrl) {
        previewRequestRef.current = requestAnimationFrame(draw);
      } else {
        drawVideoFrame(canvasRef.current, bg, settings.text, 0, settings.animationType);
      }
    };

    draw();

    return () => {
      if (previewRequestRef.current) {
        cancelAnimationFrame(previewRequestRef.current);
      }
    };
  }, [currentResult, settings.text, settings.animationType, settings.aspectRatio, settings.backgroundSource, settings.customBackgroundUrl, settings.customBackgroundType]);

  const copyToClipboard = (text: string, field: string) => {
    navigator.clipboard.writeText(text);
    setCopiedField(field);
    setTimeout(() => setCopiedField(null), 2000);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const url = URL.createObjectURL(file);
    const type = file.type.startsWith('video') ? 'video' : 'image';

    setSettings(prev => ({
      ...prev,
      backgroundSource: BackgroundSource.CUSTOM,
      customBackgroundUrl: url,
      customBackgroundType: type as any
    }));

    if (backgroundVideoRef.current) {
      backgroundVideoRef.current.pause();
      backgroundVideoRef.current = null;
    }
  };

  const stopGeneration = () => {
    stopSignalRef.current = true;
    setIsGenerating(false);
  };

  const handleGenerate = async () => {
    if (!settings.text.trim()) return;
    setIsGenerating(true);
    stopSignalRef.current = false;
    setCurrentResult(null);

    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const base64Audio = await generateNarration(settings.text, settings.voice);
      if (stopSignalRef.current) return;

      const audioData = decode(base64Audio);
      const audioBuffer = await decodeAudioData(audioData, audioContextRef.current, 24000, 1);
      const audioBlob = new Blob([audioData], { type: 'audio/pcm' });
      const audioUrl = URL.createObjectURL(audioBlob);

      const seoPromise = generateSEOMetadata(settings.text);
      let imageUrlPromise = Promise.resolve<string | null>(null);

      if (settings.backgroundSource === BackgroundSource.AI && settings.generateImage) {
        imageUrlPromise = generateAtmosphereImage(settings.style);
      }

      const [seo, imageUrl] = await Promise.all([seoPromise, imageUrlPromise]);

      if (stopSignalRef.current) return;

      setCurrentResult({ 
        audioUrl, 
        imageUrl: imageUrl || undefined, 
        audioBuffer, 
        base64Audio,
        seo 
      });

      setHistory(prev => [{
        id: Date.now().toString(),
        text: settings.text,
        voice: settings.voice,
        timestamp: Date.now(),
        audioUrl,
        imageUrl: imageUrl || undefined,
        seo,
        aspectRatio: settings.aspectRatio
      }, ...prev]);

    } catch (error: any) {
      if (!stopSignalRef.current) {
        console.error("Generation failed:", error);
        alert(error.message || "An unexpected error occurred during generation.");
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const startExport = async () => {
    if (!currentResult || !currentResult.audioBuffer) return;

    setIsRecording(true);
    setRecordProgress(0);

    const config = ASPECT_RATIO_CONFIG[settings.aspectRatio];
    const canvas = recordCanvasRef.current!;
    canvas.width = config.width;
    canvas.height = config.height;

    const stream = canvas.captureStream(60);
    const audioCtx = audioContextRef.current!;
    const dest = audioCtx.createMediaStreamDestination();

    const recorder = new MediaRecorder(new MediaStream([...stream.getTracks(), ...dest.stream.getTracks()]), {
      mimeType: 'video/webm;codecs=vp9'
    });

    const chunks: Blob[] = [];
    recorder.ondataavailable = (e) => chunks.push(e.data);
    recorder.onstop = () => {
      const blob = new Blob(chunks, { type: 'video/webm' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `noor-studio-${Date.now()}.webm`;
      a.click();
      setIsRecording(false);
    };

    let bgSource: HTMLImageElement | HTMLVideoElement | null = null;
    const isVideo = settings.customBackgroundType === 'video' && settings.backgroundSource === BackgroundSource.CUSTOM;

    if (isVideo && settings.customBackgroundUrl) {
      bgSource = document.createElement('video');
      bgSource.src = settings.customBackgroundUrl;
      bgSource.muted = true;
      bgSource.setAttribute('playsinline', 'true');
      bgSource.crossOrigin = "anonymous";
      await new Promise(r => bgSource!.onloadeddata = r);
      (bgSource as HTMLVideoElement).play();
    } else {
      const src = (settings.backgroundSource === BackgroundSource.CUSTOM) 
        ? settings.customBackgroundUrl 
        : currentResult.imageUrl;
      if (src) {
        bgSource = new Image();
        bgSource.crossOrigin = "anonymous";
        bgSource.src = src;
        await new Promise(r => (bgSource as HTMLImageElement).onload = r);
      }
    }

    const sourceNode = audioCtx.createBufferSource();
    sourceNode.buffer = currentResult.audioBuffer;
    sourceNode.connect(dest);
    sourceNode.connect(audioCtx.destination);

    recorder.start();
    sourceNode.start();

    const duration = currentResult.audioBuffer.duration;
    const startTime = audioCtx.currentTime;

    const renderLoop = () => {
      const elapsed = audioCtx.currentTime - startTime;
      const progress = Math.min(elapsed / duration, 1);

      if (bgSource instanceof HTMLVideoElement) {
        bgSource.currentTime = elapsed % bgSource.duration;
      }

      drawVideoFrame(canvas, bgSource, settings.text, progress, settings.animationType);
      setRecordProgress(progress * 100);

      if (progress < 1) {
        requestAnimationFrame(renderLoop);
      } else {
        setTimeout(() => recorder.stop(), 500);
      }
    };

    renderLoop();
  };

  const playPreview = async () => {
    if (!currentResult || !currentResult.audioBuffer || !audioContextRef.current) return;
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') await ctx.resume();
    const source = ctx.createBufferSource();
    source.buffer = currentResult.audioBuffer;
    source.connect(ctx.destination);
    source.start();
    previewStartTimeRef.current = Date.now();
  };

  return (
    <div className="min-h-screen flex flex-col items-center bg-[#020617] p-4 md:p-8">
      <canvas ref={recordCanvasRef} className="hidden" />

      <header className="w-full max-w-6xl flex justify-between items-center mb-10 relative z-20">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-emerald-800 rounded-2xl shadow-xl shadow-emerald-950/50">
            <Video className="w-8 h-8 text-yellow-400" />
          </div>
          <div>
            <h1 className="text-3xl font-bold text-white tracking-tight">Noor Narrator Studio</h1>
            <p className="text-sm text-emerald-500 font-semibold tracking-widest uppercase">AI Voice & Video Optimizer</p>
          </div>
        </div>

        <button 
          onClick={() => setShowHistory(!showHistory)}
          className="px-5 py-2.5 glass-card rounded-xl hover:bg-emerald-900/30 transition-all flex items-center gap-2 border border-emerald-900/50"
        >
          {showHistory ? <ArrowLeft className="w-5 h-5" /> : <History className="w-5 h-5" />}
          <span className="hidden sm:inline font-medium">{showHistory ? "Studio" : "Archive"}</span>
        </button>
      </header>

      <main className="w-full max-w-6xl grid grid-cols-1 lg:grid-cols-12 gap-10 relative z-10">
        {!showHistory ? (
          <>
            <div className="lg:col-span-7 space-y-6">
              <section className="glass-card rounded-3xl p-8 shadow-2xl border-emerald-900/20">
                <div className="flex items-center justify-between mb-6">
                  <h2 className="text-xl font-bold flex items-center gap-3 text-yellow-500">
                    <Mic2 className="w-6 h-6" /> Script Editor
                  </h2>
                </div>

                <textarea
                  className="urdu-font w-full h-56 bg-black/40 border border-emerald-900/40 rounded-2xl p-6 text-2xl text-emerald-50 focus:outline-none focus:ring-4 focus:ring-emerald-600/20 transition-all resize-none shadow-inner"
                  placeholder="یہاں اپنا اردو متن لکھیں..."
                  value={settings.text}
                  onChange={(e) => setSettings({ ...settings, text: e.target.value })}
                  dir="rtl"
                />

                <div className="mt-8 grid grid-cols-1 sm:grid-cols-2 gap-6">
                  <div className="space-y-3">
                    <label className="text-xs font-bold text-emerald-600 uppercase tracking-widest flex items-center gap-2">
                       Voice
                    </label>
                    <select 
                      className="w-full bg-emerald-950/50 border border-emerald-900/40 rounded-xl p-4 text-sm text-emerald-100 focus:outline-none focus:ring-2 focus:ring-emerald-600 transition-all cursor-pointer"
                      value={settings.voice}
                      onChange={(e) => setSettings({ ...settings, voice: e.target.value as VoiceName })}
                    >
                      <option value={VoiceName.CHARON}>Charon - Soulful & Deep</option>
                      <option value={VoiceName.KORE}>Kore - Clear & Classic</option>
                      <option value={VoiceName.PUCK}>Puck - Gentle & Kind</option>
                      <option value={VoiceName.FENRIR}>Fenrir - Authoritative</option>
                      <option value={VoiceName.ZEPHYR}>Zephyr - Elegant Female</option>
                    </select>
                  </div>

                  <div className="space-y-3">
                    <label className="text-xs font-bold text-emerald-600 uppercase tracking-widest flex items-center gap-2">
                       Text Motion
                    </label>
                    <select 
                      className="w-full bg-emerald-950/50 border border-emerald-900/40 rounded-xl p-4 text-sm text-emerald-100 focus:outline-none focus:ring-2 focus:ring-emerald-600 transition-all cursor-pointer"
                      value={settings.animationType}
                      onChange={(e) => setSettings({ ...settings, animationType: e.target.value as AnimationType })}
                    >
                      <option value={AnimationType.VERTICAL_SCROLL}>Slow Vertical Scroll</option>
                      <option value={AnimationType.RIGHT_TO_LEFT}>Slide Right to Left</option>
                      <option value={AnimationType.LEFT_TO_RIGHT}>Slide Left to Right</option>
                    </select>
                  </div>
                </div>

                <div className="mt-8 space-y-4">
                  <label className="text-xs font-bold text-emerald-600 uppercase tracking-widest block mb-4">Target Platform / Size</label>
                  <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                    {Object.entries(ASPECT_RATIO_CONFIG).map(([key, config]) => {
                      const Icon = config.icon;
                      const isActive = settings.aspectRatio === key;
                      return (
                        <button
                          key={key}
                          onClick={() => setSettings({ ...settings, aspectRatio: key as AspectRatio })}
                          className={`flex flex-col items-center gap-2 p-3 rounded-xl border transition-all ${
                            isActive 
                              ? 'bg-emerald-600/20 border-emerald-500 text-emerald-200' 
                              : 'bg-black/20 border-emerald-900/20 text-slate-500 hover:border-emerald-900/50'
                          }`}
                        >
                          <Icon className={`w-5 h-5 ${isActive ? 'text-yellow-400' : ''}`} />
                          <span className="text-[10px] font-black uppercase text-center">{config.label}</span>
                          <span className="text-[9px] opacity-50">{key}</span>
                        </button>
                      );
                    })}
                  </div>
                </div>

                <div className="mt-8 space-y-4">
                   <div className="flex gap-4">
                     <button 
                        onClick={() => setSettings({...settings, backgroundSource: BackgroundSource.AI})}
                        className={`flex-1 flex flex-col items-center gap-2 p-4 rounded-2xl border transition-all ${settings.backgroundSource === BackgroundSource.AI ? 'bg-emerald-600/10 border-emerald-600 text-emerald-200' : 'bg-slate-900/50 border-slate-800 text-slate-500'}`}
                      >
                        <Sparkles className="w-5 h-5" />
                        <span className="text-xs font-bold uppercase tracking-tight">AI Generated</span>
                      </button>
                      <button 
                        onClick={() => document.getElementById('bg-upload')?.click()}
                        className={`flex-1 flex flex-col items-center gap-2 p-4 rounded-2xl border transition-all ${settings.backgroundSource === BackgroundSource.CUSTOM ? 'bg-emerald-600/10 border-emerald-600 text-emerald-200' : 'bg-slate-900/50 border-slate-800 text-slate-500'}`}
                      >
                        <Upload className="w-5 h-5" />
                        <span className="text-xs font-bold uppercase tracking-tight">Upload Asset</span>
                      </button>
                      <input id="bg-upload" type="file" accept="image/*,video/*" className="hidden" onChange={handleFileUpload} />
                   </div>

                  {settings.backgroundSource === BackgroundSource.AI && (
                    <div className="animate-in fade-in slide-in-from-top-2">
                       <label className="text-xs font-bold text-emerald-600 uppercase tracking-widest mb-2 block">Visual Atmosphere</label>
                        <input 
                          type="text"
                          className="w-full bg-emerald-950/50 border border-emerald-900/40 rounded-xl p-4 text-sm text-emerald-100 focus:outline-none focus:ring-2 focus:ring-emerald-600 transition-all"
                          placeholder="e.g. Starry sky over a peaceful mosque..."
                          value={settings.style}
                          onChange={(e) => setSettings({ ...settings, style: e.target.value })}
                        />
                    </div>
                  )}
                </div>

                <div className="flex gap-4 mt-10">
                  <button
                    onClick={handleGenerate}
                    disabled={isGenerating || isRecording || !settings.text.trim()}
                    className="flex-1 bg-gradient-to-r from-emerald-600 to-emerald-800 hover:from-emerald-500 hover:to-emerald-700 disabled:opacity-50 text-white font-black py-5 px-8 rounded-2xl shadow-2xl transition-all flex items-center justify-center gap-4 group uppercase tracking-widest text-sm"
                  >
                    {isGenerating ? (
                      <>
                        <Loader2 className="w-6 h-6 animate-spin" />
                        Creating...
                      </>
                    ) : (
                      <>
                        <Sparkles className="w-6 h-6" />
                        Generate & Optimize
                      </>
                    )}
                  </button>

                  {isGenerating && (
                    <button
                      onClick={stopGeneration}
                      className="bg-red-900/30 hover:bg-red-900/50 text-red-500 border border-red-900/40 font-black px-6 rounded-2xl transition-all flex items-center justify-center gap-2 uppercase tracking-widest text-xs"
                    >
                      <Square className="w-5 h-5 fill-current" />
                      Stop
                    </button>
                  )}
                </div>
              </section>

              {currentResult?.seo && (
                <section className="glass-card rounded-3xl p-8 shadow-2xl border-emerald-900/20 animate-in fade-in slide-in-from-bottom-6 duration-700">
                  <div className="flex items-center gap-3 mb-8">
                    <div className="p-2 bg-yellow-500/20 rounded-lg">
                      <Sparkles className="w-5 h-5 text-yellow-500" />
                    </div>
                    <h2 className="text-xl font-bold text-white">SEO & Social Optimization</h2>
                  </div>

                  <div className="space-y-6">
                    <div className="space-y-2">
                      <div className="flex justify-between items-center">
                        <label className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest">Optimized Title</label>
                        <button 
                          onClick={() => copyToClipboard(currentResult.seo!.title, 'title')}
                          className="text-emerald-400 hover:text-white flex items-center gap-1 text-[10px] font-bold uppercase transition-colors"
                        >
                          {copiedField === 'title' ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
                          {copiedField === 'title' ? 'Copied' : 'Copy'}
                        </button>
                      </div>
                      <div className="p-4 bg-black/40 border border-emerald-900/30 rounded-xl text-emerald-50 text-sm font-semibold">
                        {currentResult.seo.title}
                      </div>
                    </div>

                    <div className="space-y-2">
                      <div className="flex justify-between items-center">
                        <label className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest">Description & Tags</label>
                        <button 
                          onClick={() => copyToClipboard(currentResult.seo!.description, 'desc')}
                          className="text-emerald-400 hover:text-white flex items-center gap-1 text-[10px] font-bold uppercase transition-colors"
                        >
