import { AnimationType } from "../types";

export const wrapText = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number
): string[] => {
  const paragraphs = text.split('\n');
  const allLines: string[] = [];

  paragraphs.forEach((paragraph) => {
    const trimmed = paragraph.trim();
    if (trimmed === '') {
      allLines.push('');
      return;
    }

    const words = trimmed.split(' ');
    let currentLine = '';

    for (let n = 0; n < words.length; n++) {
      const testLine = currentLine + (currentLine ? ' ' : '') + words[n];
      const metrics = ctx.measureText(testLine);
      const testWidth = metrics.width;

      if (testWidth > maxWidth && n > 0) {
        allLines.push(currentLine);
        currentLine = words[n];
      } else {
        currentLine = testLine;
      }
    }
    allLines.push(currentLine);
  });

  return allLines;
};

/**
 * Calculates weighted timing for paragraphs based on character counts.
 * This provides a much better "sync" with voice than equal division.
 */
const getParagraphTimings = (paragraphs: string[]) => {
  const lengths = paragraphs.map(p => Math.max(p.trim().length, 1));
  const totalLength = lengths.reduce((a, b) => a + b, 0);

  const segments: { start: number; end: number }[] = [];
  let current = 0;

  lengths.forEach(len => {
    const share = len / totalLength;
    segments.push({ start: current, end: current + share });
    current += share;
  });

  return segments;
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  background: HTMLImageElement | HTMLVideoElement | null,
  text: string,
  progress: number,
  animationType: AnimationType = AnimationType.VERTICAL_SCROLL
) => {
  const ctx = canvas.getContext('2d', { alpha: false });
  if (!ctx) return;

  const width = canvas.width;
  const height = canvas.height;

  // 1. Background
  if (background) {
    const bgWidth = background instanceof HTMLVideoElement ? background.videoWidth : background.width;
    const bgHeight = background instanceof HTMLVideoElement ? background.videoHeight : background.height;

    if (bgWidth > 0 && bgHeight > 0) {
      const bgAspect = bgWidth / bgHeight;
      const canvasAspect = width / height;
      let renderWidth, renderHeight, x, y;

      if (bgAspect > canvasAspect) {
        renderHeight = height;
        renderWidth = height * bgAspect;
        x = (width - renderWidth) / 2;
        y = 0;
      } else {
        renderWidth = width;
        renderHeight = width / bgAspect;
        x = 0;
        y = (height - renderHeight) / 2;
      }
      ctx.drawImage(background, x, y, renderWidth, renderHeight);
    }
  } else {
    const grad = ctx.createLinearGradient(0, 0, 0, height);
    grad.addColorStop(0, '#042f2e');
    grad.addColorStop(1, '#020617');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, width, height);
  }

  // 2. Cinematic Overlays
  const vignette = ctx.createRadialGradient(width / 2, height / 2, 0, width / 2, height / 2, height);
  vignette.addColorStop(0, 'rgba(0, 0, 0, 0.2)');
  vignette.addColorStop(0.6, 'rgba(0, 0, 0, 0.5)');
  vignette.addColorStop(1, 'rgba(0, 0, 0, 0.85)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  // 3. Text Styling
  ctx.direction = 'rtl';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'white';

  ctx.shadowColor = 'rgba(0, 0, 0, 1)';
  ctx.shadowBlur = 35;
  ctx.shadowOffsetY = 12;

  const baseFontSize = width * 0.082;
  const maxWidth = width * 0.88;
  const lineHeight = baseFontSize * 2.5;

  ctx.save();

  if (animationType === AnimationType.VERTICAL_SCROLL) {
    const lines = wrapText(ctx, text, maxWidth);
    const totalContentHeight = lines.length * lineHeight;

    // Smooth readable scroll mapping
    const startY = height * 0.9;
    const endY = height * 0.1 - totalContentHeight;

    // We slow down the scroll by adding padding to the progress range
    const scrollEase = (p: number) => {
      const pad = 0.05;
      if (p < pad) return 0;
      if (p > 1 - pad) return 1;
      return (p - pad) / (1 - 2 * pad);
    };

    let currentY = startY + (endY - startY) * scrollEase(progress);

    ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;
    lines.forEach((line) => {
      if (currentY > -lineHeight && currentY < height + lineHeight) {
        if (line.trim()) {
          ctx.fillText(line, width / 2, currentY);
        }
      }
      currentY += lineHeight;
    });
  } else {
    const paragraphs = text.split('\n').filter(p => p.trim() !== '');
    if (paragraphs.length > 0) {
      const timings = getParagraphTimings(paragraphs);

      // Find current active paragraph based on weighted progress
      let pIndex = timings.findIndex(t => progress >= t.start && progress <= t.end);
      if (pIndex === -1) pIndex = progress < 0.5 ? 0 : paragraphs.length - 1;

      const timing = timings[pIndex];
      const pProgress = (progress - timing.start) / (timing.end - timing.start);
      const currentParagraph = paragraphs[pIndex];

      const blockLines = wrapText(ctx, currentParagraph, maxWidth);
      const blockCenterY = height / 2;
      const blockStartY = blockCenterY - ((blockLines.length - 1) * lineHeight) / 2;

      // Phase control for transition within paragraph
      const inT = 0.15;
      const outT = 0.85;

      let currentX = width / 2;
      let opacity = 1;
      let scale = 1.0;
      const offscreenOffset = width * 1.2;

      // Subtle pulse/breath animation
      scale = 1.0 + Math.sin(pProgress * Math.PI) * 0.03;

      if (animationType === AnimationType.RIGHT_TO_LEFT) {
        if (pProgress < inT) {
          const t = pProgress / inT;
          currentX = (width + offscreenOffset) - (offscreenOffset + width/2) * t;
          opacity = t;
        } else if (pProgress > outT) {
          const t = (pProgress - outT) / (1 - outT);
          currentX = (width / 2) - (width/2 + offscreenOffset) * t;
          opacity = 1 - t;
        }
      } else {
        // LEFT_TO_RIGHT
        if (pProgress < inT) {
          const t = pProgress / inT;
          currentX = -offscreenOffset + (offscreenOffset + width/2) * t;
          opacity = t;
        } else if (pProgress > outT) {
          const t = (pProgress - outT) / (1 - outT);
          currentX = (width / 2) + (width/2 + offscreenOffset) * t;
          opacity = 1 - t;
        }
      }

      ctx.globalAlpha = Math.max(0, Math.min(1, opacity));
      const fontSize = baseFontSize * scale;
      ctx.font = `bold ${fontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

      blockLines.forEach((line, i) => {
        const y = blockStartY + (i * lineHeight * scale);
        if (line.trim()) {
          ctx.fillText(line, currentX, y);
        }
      });
    }
  }

  ctx.restore();
  ctx.shadowBlur = 0;
};

import React, { useState, useRef, useEffect } from 'react';
import { 
  Video, 
  Download, 
  Loader2, 
  Play, 
  Sparkles, 
  History, 
  Volume2, 
  Mic2, 
  ArrowLeft,
  Image as ImageIcon,
  Square,
  Upload,
  Copy,
  Hash,
  Check,
  Monitor,
  Smartphone,
  Instagram,
  Facebook
} from 'lucide-react';
import { VoiceName, NarrationHistoryItem, GenerationSettings, AnimationType, BackgroundSource, SEOMetadata, AspectRatio } from './types';
import { generateNarration, generateAtmosphereImage, generateSEOMetadata } from './services/geminiService';
import { decode, decodeAudioData } from './utils/audioUtils';
import { drawVideoFrame } from './utils/videoUtils';

const DEFAULT_TEXT = `سکون کی نیند اور اللہ کی حفاظت۔ ✨

نبی کریم صلی اللہ علیہ وآلہ وسلم کا بتایا ہوا ایک ایسا عمل جو ہمیں رات بھر شیطان کے شر سے محفوظ رکھتا ہے۔ 🌙

آپ صلی اللہ علیہ وآلہ وسلم نے فرمایا: "جب تم رات کو اپنے بستر پر سونے کے لیے جاؤ تو آیت الکرسی پڑھ لیا کرو۔" 📖

صحیح البخاری حدیث نمبر 5010۔`;

const ASPECT_RATIO_CONFIG = {
  [AspectRatio.VERTICAL]: { width: 1080, height: 1920, label: "Reels / TikTok", icon: Smartphone },
  [AspectRatio.LANDSCAPE]: { width: 1920, height: 1080, label: "YouTube / Desktop", icon: Monitor },
  [AspectRatio.SQUARE]: { width: 1080, height: 1080, label: "Instagram Feed", icon: Instagram },
  [AspectRatio.FEED]: { width: 1080, height: 1350, label: "Facebook / Portrait", icon: Facebook },
};

const App: React.FC = () => {
  const [settings, setSettings] = useState<GenerationSettings>({
    text: DEFAULT_TEXT,
    voice: VoiceName.CHARON,
    generateImage: true,
    style: "Starry night sky over a peaceful mosque silhouette",
    animationType: AnimationType.VERTICAL_SCROLL,
    aspectRatio: AspectRatio.VERTICAL,
    backgroundSource: BackgroundSource.AI
  });

  const [isGenerating, setIsGenerating] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordProgress, setRecordProgress] = useState(0);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  const [currentResult, setCurrentResult] = useState<{ 
    audioUrl: string; 
    imageUrl?: string; 
    audioBuffer?: AudioBuffer;
    base64Audio: string;
    seo?: SEOMetadata;
  } | null>(null);

  const [history, setHistory] = useState<NarrationHistoryItem[]>([]);
  const [showHistory, setShowHistory] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const recordCanvasRef = useRef<HTMLCanvasElement>(null);
  const backgroundVideoRef = useRef<HTMLVideoElement | null>(null);
  const stopSignalRef = useRef<boolean>(false);
  const previewRequestRef = useRef<number>(0);
  const previewStartTimeRef = useRef<number>(Date.now());

  useEffect(() => {
    const isVideo = settings.customBackgroundType === 'video' && settings.backgroundSource === BackgroundSource.CUSTOM;
    previewStartTimeRef.current = Date.now();

    const draw = () => {
      if (!canvasRef.current) return;

      const config = ASPECT_RATIO_CONFIG[settings.aspectRatio];
      if (canvasRef.current.width !== config.width || canvasRef.current.height !== config.height) {
        canvasRef.current.width = config.width;
        canvasRef.current.height = config.height;
      }

      let bg: HTMLImageElement | HTMLVideoElement | null = null;
      if (isVideo && settings.customBackgroundUrl) {
        if (!backgroundVideoRef.current || backgroundVideoRef.current.src !== settings.customBackgroundUrl) {
          const v = document.createElement('video');
          v.src = settings.customBackgroundUrl;
          v.muted = true;
          v.loop = true;
          v.setAttribute('playsinline', 'true');
          v.crossOrigin = "anonymous";
          v.play().catch(err => console.warn("Video preview play failed:", err));
          backgroundVideoRef.current = v;
        }
        bg = backgroundVideoRef.current;
      } else {
        const src = (settings.backgroundSource === BackgroundSource.CUSTOM) 
          ? settings.customBackgroundUrl 
          : currentResult?.imageUrl;

        if (src) {
          const img = new Image();
          img.crossOrigin = "anonymous";
          img.src = src;
          bg = img;
        }
      }

      const duration = currentResult?.audioBuffer?.duration || 10;
      const elapsed = (Date.now() - previewStartTimeRef.current) / 1000;
      const progress = (elapsed % duration) / duration;

      drawVideoFrame(canvasRef.current, bg, settings.text, progress, settings.animationType);

      if (currentResult || isVideo || settings.customBackgroundUrl) {
        previewRequestRef.current = requestAnimationFrame(draw);
      } else {
        drawVideoFrame(canvasRef.current, bg, settings.text, 0, settings.animationType);
      }
    };

    draw();

    return () => {
      if (previewRequestRef.current) {
        cancelAnimationFrame(previewRequestRef.current);
      }
    };
  }, [currentResult, settings.text, settings.animationType, settings.aspectRatio, settings.backgroundSource, settings.customBackgroundUrl, settings.customBackgroundType]);

  const copyToClipboard = (text: string, field: string) => {
    navigator.clipboard.writeText(text);
    setCopiedField(field);
    setTimeout(() => setCopiedField(null), 2000);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const url = URL.createObjectURL(file);
    const type = file.type.startsWith('video') ? 'video' : 'image';

    setSettings(prev => ({
      ...prev,
      backgroundSource: BackgroundSource.CUSTOM,
      customBackgroundUrl: url,
      customBackgroundType: type as any
    }));

    if (backgroundVideoRef.current) {
      backgroundVideoRef.current.pause();
      backgroundVideoRef.current = null;
    }
  };

  const stopGeneration = () => {
    stopSignalRef.current = true;
    setIsGenerating(false);
  };

  const handleGenerate = async () => {
    if (!settings.text.trim()) return;
    setIsGenerating(true);
    stopSignalRef.current = false;
    setCurrentResult(null);

    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const base64Audio = await generateNarration(settings.text, settings.voice);
      if (stopSignalRef.current) return;

      const audioData = decode(base64Audio);
      const audioBuffer = await decodeAudioData(audioData, audioContextRef.current, 24000, 1);
      const audioUrl = URL.createObjectURL(new Blob([audioData], { type: 'audio/pcm' }));

      const seoPromise = generateSEOMetadata(settings.text);
      let imageUrlPromise = Promise.resolve<string | null>(null);

      if (settings.backgroundSource === BackgroundSource.AI && settings.generateImage) {
        imageUrlPromise = generateAtmosphereImage(settings.style);
      }

      const [seo, imageUrl] = await Promise.all([seoPromise, imageUrlPromise]);

      if (stopSignalRef.current) return;

      setCurrentResult({ 
        audioUrl, 
        imageUrl: imageUrl || undefined, 
        audioBuffer, 
        base64Audio,
        seo 
      });

      setHistory(prev => [{
        id: Date.now().toString(),
        text: settings.text,
        voice: settings.voice,
        timestamp: Date.now(),
        audioUrl,
        imageUrl: imageUrl || undefined,
        seo,
        aspectRatio: settings.aspectRatio
      }, ...prev]);

    } catch (error: any) {
      if (!stopSignalRef.current) {
        console.error("Generation failed:", error);
        alert(error.message || "An unexpected error occurred during generation.");
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const startExport = async () => {
    if (!currentResult || !currentResult.audioBuffer) return;

    setIsRecording(true);
    setRecordProgress(0);

    const config = ASPECT_RATIO_CONFIG[settings.aspectRatio];
    const canvas = recordCanvasRef.current!;
    canvas.width = config.width;
    canvas.height = config.height;

    const stream = canvas.captureStream(60);
    const audioCtx = audioContextRef.current!;
    const dest = audioCtx.createMediaStreamDestination();

    const recorder = new MediaRecorder(new MediaStream([...stream.getTracks(), ...dest.stream.getTracks()]), {
      mimeType: 'video/webm;codecs=vp9'
    });

    const chunks: Blob[] = [];
    recorder.ondataavailable = (e) => chunks.push(e.data);
    recorder.onstop = () => {
      const blob = new Blob(chunks, { type: 'video/webm' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `noor-studio-${Date.now()}.webm`;
      a.click();
      setIsRecording(false);
    };

    let bgSource: HTMLImageElement | HTMLVideoElement | null = null;
    const isVideo = settings.customBackgroundType === 'video' && settings.backgroundSource === BackgroundSource.CUSTOM;

    if (isVideo && settings.customBackgroundUrl) {
      bgSource = document.createElement('video');
      bgSource.src = settings.customBackgroundUrl;
      bgSource.muted = true;
      bgSource.setAttribute('playsinline', 'true');
      bgSource.crossOrigin = "anonymous";
      await new Promise(r => bgSource!.onloadeddata = r);
      (bgSource as HTMLVideoElement).play();
    } else {
      const src = (settings.backgroundSource === BackgroundSource.CUSTOM) 
        ? settings.customBackgroundUrl 
        : currentResult.imageUrl;
      if (src) {
        bgSource = new Image();
        bgSource.crossOrigin = "anonymous";
        bgSource.src = src;
        await new Promise(r => (bgSource as HTMLImageElement).onload = r);
      }
    }

    const sourceNode = audioCtx.createBufferSource();
    sourceNode.buffer = currentResult.audioBuffer;
    sourceNode.connect(dest);
    sourceNode.connect(audioCtx.destination);

    recorder.start();
    sourceNode.start();

    const duration = currentResult.audioBuffer.duration;
    const startTime = audioCtx.currentTime;

    const renderLoop = () => {
      const elapsed = audioCtx.currentTime - startTime;
      const progress = Math.min(elapsed / duration, 1);

      if (bgSource instanceof HTMLVideoElement) {
        bgSource.currentTime = elapsed % bgSource.duration;
      }

      drawVideoFrame(canvas, bgSource, settings.text, progress, settings.animationType);
      setRecordProgress(progress * 100);

      if (progress < 1) {
        requestAnimationFrame(renderLoop);
      } else {
        setTimeout(() => recorder.stop(), 500);
      }
    };

    renderLoop();
  };

  const playPreview = async () => {
    if (!currentResult || !currentResult.audioBuffer || !audioContextRef.current) return;
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') await ctx.resume();
    const source = ctx.createBufferSource();
    source.buffer = currentResult.audioBuffer;
    source.connect(ctx.destination);
    source.start();
    previewStartTimeRef.current = Date.now();
  };

  return (
    <div className="min-h-screen flex flex-col items-center bg-[#020617] p-4 md:p-8">
      <canvas ref={recordCanvasRef} className="hidden" />

      <header className="w-full max-w-6xl flex justify-between items-center mb-10 relative z-20 animate-fade-in" style={{ animationDelay: '0s' }}>
        <div className="flex items-center gap-4">
          <div className="p-3 bg-emerald-800 rounded-2xl shadow-xl shadow-emerald-950/50">
            <Video className="w-8 h-8 text-yellow-400" />
          </div>
          <div>
            <h1 className="text-3xl font-bold text-white tracking-tight">Noor Narrator Studio</h1>
