const App: React.FC = () => {
  const [settings, setSettings] = useState<GenerationSettings>(() => {
    const savedText = localStorage.getItem(STORAGE_KEY);
    return {
      text: savedText || DEFAULT_TEXT,
      voice: VoiceName.CHARON,
      generateImage: true,
      style: "Starry night sky over a peaceful mosque silhouette",
      animationType: AnimationType.VERTICAL_SCROLL,
      aspectRatio: AspectRatio.VERTICAL,
      backgroundSource: BackgroundSource.AI
    };
  });

  const [isGenerating, setIsGenerating] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordProgress, setRecordProgress] = useState(0);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const [currentResult, setCurrentResult] = useState<{ 
    audioUrl: string; 
    imageUrl?: string; 
    audioBuffer?: AudioBuffer;
    base64Audio: string;
    seo?: SEOMetadata;
  } | null>(null);

  const [history, setHistory] = useState<NarrationHistoryItem[]>([]);
  const [showHistory, setShowHistory] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const recordCanvasRef = useRef<HTMLCanvasElement>(null);
  const backgroundVideoRef = useRef<HTMLVideoElement | null>(null);
  const stopSignalRef = useRef<boolean>(false);
  const previewRequestRef = useRef<number>(0);
  const previewStartTimeRef = useRef<number>(Date.now());
  const currentPreviewSourceRef = useRef<AudioBufferSourceNode | null>(null);

  // Persist text to local storage whenever it changes
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, settings.text);
  }, [settings.text]);

  useEffect(() => {
    const isVideo = settings.customBackgroundType === 'video' && settings.backgroundSource === BackgroundSource.CUSTOM;

    const draw = () => {
      if (!canvasRef.current) return;

      const config = ASPECT_RATIO_CONFIG[settings.aspectRatio];
      if (canvasRef.current.width !== config.width || canvasRef.current.height !== config.height) {
        canvasRef.current.width = config.width;
        canvasRef.current.height = config.height;
      }

      let bg: HTMLImageElement | HTMLVideoElement | null = null;
      if (isVideo && settings.customBackgroundUrl) {
        if (!backgroundVideoRef.current || backgroundVideoRef.current.src !== settings.customBackgroundUrl) {
          const v = document.createElement('video');
          v.src = settings.customBackgroundUrl;
          v.muted = true;
          v.loop = true;
          v.setAttribute('playsinline', 'true');
          v.crossOrigin = "anonymous";
          v.play().catch(err => console.warn("Video preview play failed:", err));
          backgroundVideoRef.current = v;
        }
        bg = backgroundVideoRef.current;
      } else {
        const src = (settings.backgroundSource === BackgroundSource.CUSTOM) 
          ? settings.customBackgroundUrl 
          : currentResult?.imageUrl;

        if (src) {
          const img = new Image();
          img.crossOrigin = "anonymous";
          img.src = src;
          bg = img;
        }
      }

      const duration = currentResult?.audioBuffer?.duration || 10;
      const elapsed = (Date.now() - previewStartTimeRef.current) / 1000;
      const progress = (elapsed % duration) / duration;

      drawVideoFrame(canvasRef.current, bg, settings.text, progress, settings.animationType);

      if (currentResult || isVideo || settings.customBackgroundUrl) {
        previewRequestRef.current = requestAnimationFrame(draw);
      } else {
        drawVideoFrame(canvasRef.current, bg, settings.text, 0, settings.animationType);
      }
    };

    draw();

    return () => {
      if (previewRequestRef.current) {
        cancelAnimationFrame(previewRequestRef.current);
      }
    };
  }, [currentResult, settings.text, settings.animationType, settings.aspectRatio, settings.backgroundSource, settings.customBackgroundUrl, settings.customBackgroundType]);

  const copyToClipboard = (text: string, field: string) => {
    navigator.clipboard.writeText(text);
    setCopiedField(field);
    setTimeout(() => setCopiedField(null), 2000);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const url = URL.createObjectURL(file);
    const type = file.type.startsWith('video') ? 'video' : 'image';

    setSettings(prev => ({
      ...prev,
      backgroundSource: BackgroundSource.CUSTOM,
      customBackgroundUrl: url,
      customBackgroundType: type as any
    }));

    if (backgroundVideoRef.current) {
      backgroundVideoRef.current.pause();
      backgroundVideoRef.current = null;
    }
  };

  const stopGeneration = () => {
    stopSignalRef.current = true;
    setIsGenerating(false);
  };

  const handleGenerate = async () => {
    if (!settings.text.trim()) return;
    setIsGenerating(true);
    setErrorMsg(null);
    stopSignalRef.current = false;
    setCurrentResult(null);

    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const base64Audio = await generateNarration(settings.text, settings.voice);
      if (stopSignalRef.current) return;

      const audioData = decode(base64Audio);
      const audioBuffer = await decodeAudioData(audioData, audioContextRef.current, 24000, 1);
      const audioUrl = URL.createObjectURL(new Blob([audioData], { type: 'audio/pcm' }));

      const seoPromise = generateSEOMetadata(settings.text);
      let imageUrlPromise = Promise.resolve<string | null>(null);

      if (settings.backgroundSource === BackgroundSource.AI && settings.generateImage) {
        imageUrlPromise = generateAtmosphereImage(settings.style);
      }

      const [seo, imageUrl] = await Promise.all([seoPromise, imageUrlPromise]);

      if (stopSignalRef.current) return;

      setCurrentResult({ 
        audioUrl, 
        imageUrl: imageUrl || undefined, 
        audioBuffer, 
        base64Audio,
        seo 
      });

      setHistory(prev => [{
        id: Date.now().toString(),
        text: settings.text,
        voice: settings.voice,
        timestamp: Date.now(),
        audioUrl,
        imageUrl: imageUrl || undefined,
        seo,
        aspectRatio: settings.aspectRatio
      }, ...prev]);

    } catch (error: any) {
      if (!stopSignalRef.current) {
        console.error("Generation failed:", error);
        setErrorMsg(error.message || "An unexpected error occurred.");
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const startExport = async () => {
    if (!currentResult || !currentResult.audioBuffer) return;

    // Stop any existing preview before export starts
    if (currentPreviewSourceRef.current) {
      currentPreviewSourceRef.current.stop();
      currentPreviewSourceRef.current = null;
    }

    setIsRecording(true);
    setRecordProgress(0);

    const config = ASPECT_RATIO_CONFIG[settings.aspectRatio];
    const canvas = recordCanvasRef.current!;
    canvas.width = config.width;
    canvas.height = config.height;

    const stream = canvas.captureStream(60);
    const audioCtx = audioContextRef.current!;
    const dest = audioCtx.createMediaStreamDestination();

    const recorder = new MediaRecorder(new MediaStream([...stream.getTracks(), ...dest.stream.getTracks()]), {
      mimeType: 'video/webm;codecs=vp9'
    });

    const chunks: Blob[] = [];
    recorder.ondataavailable = (e) => chunks.push(e.data);
    recorder.onstop = () => {
      const blob = new Blob(chunks, { type: 'video/webm' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `noor-studio-${Date.now()}.webm`;
      a.click();
      setIsRecording(false);
    };

    let bgSource: HTMLImageElement | HTMLVideoElement | null = null;
    const isVideo = settings.customBackgroundType === 'video' && settings.backgroundSource === BackgroundSource.CUSTOM;

    if (isVideo && settings.customBackgroundUrl) {
      bgSource = document.createElement('video');
      bgSource.src = settings.customBackgroundUrl;
      bgSource.muted = true;
      bgSource.setAttribute('playsinline', 'true');
      bgSource.crossOrigin = "anonymous";
      await new Promise(r => bgSource!.onloadeddata = r);
      (bgSource as HTMLVideoElement).play();
    } else {
      const src = (settings.backgroundSource === BackgroundSource.CUSTOM) 
        ? settings.customBackgroundUrl 
        : currentResult.imageUrl;
      if (src) {
        bgSource = new Image();
        bgSource.crossOrigin = "anonymous";
        bgSource.src = src;
        await new Promise(r => (bgSource as HTMLImageElement).onload = r);
      }
    }

    const sourceNode = audioCtx.createBufferSource();
    sourceNode.buffer = currentResult.audioBuffer;
    sourceNode.connect(dest);

    recorder.start();
    sourceNode.start();

    const duration = currentResult.audioBuffer.duration;
    const startTime = audioCtx.currentTime;

    const renderLoop = () => {
      const elapsed = audioCtx.currentTime - startTime;
      const progress = Math.min(elapsed / duration, 1);

      if (bgSource instanceof HTMLVideoElement) {
        bgSource.currentTime = elapsed % bgSource.duration;
      }

      drawVideoFrame(canvas, bgSource, settings.text, progress, settings.animationType);
      setRecordProgress(progress * 100);

      if (progress < 1) {
        requestAnimationFrame(renderLoop);
      } else {
        setTimeout(() => recorder.stop(), 500);
      }
    };

    renderLoop();
  };

  const playPreview = async () => {
    if (!currentResult || !currentResult.audioBuffer || !audioContextRef.current) return;
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') await ctx.resume();

    // Stop previous preview if it's still running
    if (currentPreviewSourceRef.current) {
      try {
        currentPreviewSourceRef.current.stop();
      } catch (e) {
        // Already stopped
      }
    }

    const source = ctx.createBufferSource();
    source.buffer = currentResult.audioBuffer;
    source.connect(ctx.destination);

    currentPreviewSourceRef.current = source;
    source.onended = () => {
      if (currentPreviewSourceRef.current === source) {
        currentPreviewSourceRef.current = null;
      }
    };

    source.start();
    // Sync visual start with actual audio start
    previewStartTimeRef.current = Date.now();
  };

  return (
    <div className="min-h-screen flex flex-col items-center bg-[#020617] p-4 md:p-8">
      <canvas ref={recordCanvasRef} className="hidden" />

      <header className="w-full max-w-6xl flex justify-between items-center mb-10 relative z-20 animate-fade-in" style={{ animationDelay: '0s' }}>
        <div className="flex items-center gap-4">
          <div className="p-3 bg-emerald-800 rounded-2xl shadow-xl shadow-emerald-950/50">
            <Video className="w-8 h-8 text-yellow-400" />
          </div>
          <div>
            <h1 className="text-3xl font-bold text-white tracking-tight">Noor Narrator Studio</h1>
            <p className="text-sm text-emerald-500 font-semibold tracking-widest uppercase">AI Voice & Video Sync</p>
          </div>
        </div>

        <button 
          onClick={() => setShowHistory(!showHistory)}
          className="px-5 py-2.5 glass-card rounded-xl hover:bg-emerald-900/40 transition-all flex items-center gap-2 border border-emerald-900/50"
        >
          {showHistory ? <ArrowLeft className="w-5 h-5" /> : <History className="w-5 h-5" />}
          <span className="hidden sm:inline font-bold">{showHistory ? "Studio" : "Archive"}</span>
        </button>
      </header>

      <main className="w-full max-w-6xl grid grid-cols-1 lg:grid-cols-12 gap-10 relative z-10">
        {!showHistory ? (
          <>
            <div className="lg:col-span-7 space-y-6 animate-fade-in" style={{ animationDelay: '0.1s' }}>
              <section className="glass-card rounded-3xl p-8 shadow-2xl border-emerald-900/20">
                <div className="flex items-center justify-between mb-6">
                  <h2 className="text-xl font-bold flex items-center gap-3 text-yellow-500">
                    <Mic2 className="w-6 h-6" /> Script Editor
                  </h2>
                </div>

                {errorMsg && (
                  <div className="mb-6 p-4 bg-red-900/20 border border-red-500/30 rounded-2xl flex items-start gap-3 animate-in fade-in slide-in-from-top-2">
                    <AlertCircle className="w-5 h-5 text-red-500 mt-0.5 shrink-0" />
                    <div className="text-sm text-red-200">
                      <p className="font-bold mb-1">Attention</p>
                      <p>{errorMsg}</p>
                    </div>
                  </div>
                )}

                <textarea
                  className="urdu-font w-full h-56 bg-black/40 border border-emerald-900/40 rounded-2xl p-6 text-2xl text-emerald-50 focus:outline-none focus:ring-4 focus:ring-emerald-600/20 transition-all resize-none shadow-inner"
                  placeholder="یہاں اپنا اردو متن لکھیں..."
                  value={settings.text}
                  onChange={(e) => setSettings({ ...settings, text: e.target.value })}
                  dir="rtl"
                />

                <div className="mt-8 grid grid-cols-1 sm:grid-cols-2 gap-6">
                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest flex items-center gap-2">
                       Narrator Voice
                    </label>
                    <select 
                      className="w-full bg-emerald-950/50 border border-emerald-900/40 rounded-xl p-4 text-sm text-emerald-100 focus:outline-none focus:ring-2 focus:ring-emerald-600 transition-all cursor-pointer"
                      value={settings.voice}
                      onChange={(e) => setSettings({ ...settings, voice: e.target.value as VoiceName })}
                    >
                      <option value={VoiceName.CHARON}>Charon - Deep & Spiritual</option>
                      <option value={VoiceName.KORE}>Kore - Clear Classic</option>
                      <option value={VoiceName.PUCK}>Puck - Gentle Narrative</option>
                      <option value={VoiceName.FENRIR}>Fenrir - Strong Male</option>
                      <option value={VoiceName.ZEPHYR}>Zephyr - Elegant Female</option>
                    </select>
                  </div>

                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest flex items-center gap-2">
                       Animation Type
                    </label>
                    <select 
                      className="w-full bg-emerald-950/50 border border-emerald-900/40 rounded-xl p-4 text-sm text-emerald-100 focus:outline-none focus:ring-2 focus:ring-emerald-600 transition-all cursor-pointer"
                      value={settings.animationType}
                      onChange={(e) => setSettings({ ...settings, animationType: e.target.value as AnimationType })}
                    >
                      <option value={AnimationType.VERTICAL_SCROLL}>Vertical Read</option>
                      <option value={AnimationType.RIGHT_TO_LEFT}>Slide Right to Left</option>
                      <option value={AnimationType.LEFT_TO_RIGHT}>Slide Left to Right</option>
                    </select>
                  </div>
                </div>

                <div className="mt-8 space-y-4">
                  <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest block mb-4">Export Dimension</label>
                  <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                    {Object.entries(ASPECT_RATIO_CONFIG).map(([key, config]) => {
                      const Icon = config.icon;
                      const isActive = settings.aspectRatio === key;
                      return (
                        <button
                          key={key}
                          onClick={() => setSettings({ ...settings, aspectRatio: key as AspectRatio })}
                          className={`flex flex-col items-center gap-2 p-3 rounded-xl border transition-all ${
                            isActive 
                              ? 'bg-emerald-600/30 border-emerald-500 text-emerald-200 shadow-[0_0_15px_-5px_rgba(16,185,129,0.5)]' 
                              : 'bg-black/20 border-emerald-900/20 text-slate-500 hover:border-emerald-900/50'
                          }`}
                        >
                          <Icon className={`w-5 h-5 ${isActive ? 'text-yellow-400' : ''}`} />
                          <span className="text-[10px] font-black uppercase text-center">{config.label}</span>
                          <span className="text-[8px] opacity-40 font-bold">{key}</span>
                        </button>
                      );
                    })}
                  </div>
                </div>

                <div className="mt-8 space-y-4">
                   <div className="flex gap-4">
                     <button 
                        onClick={() => setSettings({...settings, backgroundSource: BackgroundSource.AI})}
                        className={`flex-1 flex flex-col items-center gap-2 p-4 rounded-2xl border transition-all ${settings.backgroundSource === BackgroundSource.AI ? 'bg-emerald-600/10 border-emerald-600 text-emerald-200 shadow-inner' : 'bg-slate-900/50 border-slate-800 text-slate-500'}`}
                      >
                        <Sparkles className="w-5 h-5" />
                        <span className="text-xs font-black uppercase tracking-tight">AI Generated</span>
                      </button>
                      <button 
                        onClick={() => document.getElementById('bg-upload')?.click()}
                        className={`flex-1 flex flex-col items-center gap-2 p-4 rounded-2xl border transition-all ${settings.backgroundSource === BackgroundSource.CUSTOM ? 'bg-emerald-600/10 border-emerald-600 text-emerald-200 shadow-inner' : 'bg-slate-900/50 border-slate-800 text-slate-500'}`}
                      >
                        <Upload className="w-5 h-5" />
                        <span className="text-xs font-black uppercase tracking-tight">Custom Upload</span>
                      </button>
                      <input id="bg-upload" type="file" accept="image/*,video/*" className="hidden" onChange={handleFileUpload} />
                   </div>

                  {settings.backgroundSource === BackgroundSource.AI && (
                    <div className="animate-in fade-in slide-in-from-top-2">
                       <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest mb-2 block">Atmosphere Prompt</label>
                        <input 
                          type="text"
                          className="w-full bg-emerald-950/50 border border-emerald-900/40 rounded-xl p-4 text-sm text-emerald-100 focus:outline-none focus:ring-2 focus:ring-emerald-600 transition-all"
                          placeholder="e.g. Dreamy mosque at sunset, high quality..."
                          value={settings.style}
                          onChange={(e) => setSettings({ ...settings, style: e.target.value })}
                        />
                    </div>
                  )}
                </div>

                <div className="flex gap-4 mt-10">
                  <button
                    onClick={handleGenerate}
                    disabled={isGenerating || isRecording || !settings.text.trim()}
                    className="flex-1 bg-gradient-to-br from-emerald-500 to-emerald-800 hover:from-emerald-400 hover:to-emerald-700 disabled:opacity-50 text-white font-black py-5 px-8 rounded-2xl shadow-2xl transition-all flex items-center justify-center gap-4 group uppercase tracking-[0.2em] text-sm relative overflow-hidden"
                  >
                    {isGenerating ? (
                      <>
                        <Loader2 className="w-6 h-6 animate-spin" />
                        Processing Assets...
                      </>
                    ) : (
                      <>
                        <Sparkles className="w-6 h-6 group-hover:scale-110 transition-transform" />
                        Generate & Sync
                      </>
                    )}
                  </button>

                  {isGenerating && (
                    <button
                      onClick={stopGeneration}
                      className="bg-red-900/30 hover:bg-red-900/50 text-red-500 border border-red-900/40 font-black px-6 rounded-2xl transition-all flex items-center justify-center gap-2 uppercase tracking-widest text-xs"
                    >
                      <Square className="w-5 h-5 fill-current" />
                      Abort
                    </button>
                  )}
                </div>
              </section>

              {currentResult?.seo && (
                <section className="glass-card rounded-3xl p-8 shadow-2xl border-emerald-900/20 animate-fade-in" style={{ animationDelay: '0.2s' }}>
                  <div className="flex items-center gap-3 mb-8">
                    <div className="p-2 bg-yellow-500/20 rounded-lg">
                      <Sparkles className="w-5 h-5 text-yellow-500" />
                    </div>
                    <h2 className="text-xl font-black text-white uppercase tracking-tight">Social Post Optimizer</h2>
                  </div>

                  <div className="space-y-6">
                    <div className="space-y-2">
                      <div className="flex justify-between items-center">
                        <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Viral Title</label>
                        <button 
                          onClick={() => copyToClipboard(currentResult.seo!.title, 'title')}
                          className="text-emerald-400 hover:text-white flex items-center gap-1 text-[10px] font-black uppercase transition-colors"
                        >
                          {copiedField === 'title' ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
                          {copiedField === 'title' ? 'Done' : 'Copy'}
                        </button>
                      </div>
                      <div className="p-4 bg-black/40 border border-emerald-900/30 rounded-xl text-emerald-50 text-sm font-bold shadow-inner">
                        {currentResult.seo.title}
                      </div>
                    </div>

                    <div className="space-y-2">
                      <div className="flex justify-between items-center">
                        <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Description & Tags</label>
                        <button 
                          onClick={() => copyToClipboard(currentResult.seo!.description, 'desc')}
                          className="text-emerald-400 hover:text-white flex items-center gap-1 text-[10px] font-black uppercase transition-colors"
                        >
                          {copiedField === 'desc' ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
                          {copiedField === 'desc' ? 'Done' : 'Copy'}
                        </button>
                      </div>
                      <div className="p-4 bg-black/40 border border-emerald-900/30 rounded-xl text-emerald-100 text-xs leading-loose whitespace-pre-wrap shadow-inner h-32 overflow-y-auto">
                        {currentResult.seo.description}
                      </div>
                    </div>

                    <div className="space-y-3">
                      <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">SEO Keywords</label>
                      <div className="flex flex-wrap gap-2">
                        {currentResult.seo.keywords.map((kw, i) => (
                          <div key={i} className="flex items-center gap-1.5 px-3 py-1.5 bg-emerald-900/20 border border-emerald-900/40 rounded-full text-[10px] text-emerald-300 font-black shadow-sm">
                            <Hash className="w-3 h-3 text-emerald-500" />
                            {kw}
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                </section>
              )}
            </div>

            <div className="lg:col-span-5 space-y-8 animate-fade-in" style={{ animationDelay: '0.2s' }}>
              <section className="glass-card rounded-3xl p-6 shadow-2xl sticky top-8 border-emerald-900/10">
                <div className="flex items-center justify-between mb-6">
                  <h2 className="text-lg font-black flex items-center gap-3 text-emerald-400 tracking-tight uppercase">
                    <Play className="w-5 h-5" /> Rendering Live
                  </h2>
                  {(currentResult || settings.customBackgroundUrl) && (
                    <span className="flex h-2.5 w-2.5 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_10px_rgba(16,185,129,0.8)]"></span>
                  )}
                </div>

                <div 
                  className="relative group w-full mx-auto rounded-3xl overflow-hidden shadow-[0_35px_60px_-15px_rgba(0,0,0,0.8)] border-4 border-emerald-900/30 bg-slate-900 transition-all duration-700 flex items-center justify-center scale-[0.98] hover:scale-100"
                  style={{ aspectRatio: settings.aspectRatio.replace(':', '/') }}
                >
                  <canvas 
                    ref={canvasRef} 
                    className="w-full h-full object-contain"
                  />

                  {isRecording && (
                    <div className="absolute inset-0 bg-black/85 flex flex-col items-center justify-center p-8 text-center backdrop-blur-xl">
                      <div className="w-20 h-20 relative mb-8">
                        <div className="absolute inset-0 border-4 border-emerald-900/30 rounded-full"></div>
                        <div className="absolute inset-0 border-4 border-yellow-500 rounded-full border-t-transparent animate-spin shadow-[0_0_20px_rgba(234,179,8,0.3)]"></div>
                      </div>
                      <h3 className="text-xl font-black text-white mb-2 uppercase tracking-[0.2em]">Exporting High-Res</h3>
                      <p className="text-emerald-500 text-sm font-black tracking-[0.3em]">{Math.round(recordProgress)}%</p>
                    </div>
                  )}
                </div>

                <div className="mt-8 space-y-4">
                  <button
                    onClick={playPreview}
                    disabled={!currentResult || isRecording}
                    className="w-full flex items-center justify-center gap-3 p-4 bg-emerald-900/20 text-emerald-400 rounded-2xl hover:bg-emerald-800/30 transition-all font-black disabled:opacity-30 border border-emerald-800/30 uppercase text-xs tracking-widest"
                  >
                    <Volume2 className="w-5 h-5" /> Test Voice Alignment
                  </button>

                  <button
                    onClick={startExport}
                    disabled={!currentResult || isRecording}
                    className="w-full flex items-center justify-center gap-4 p-5 bg-gradient-to-r from-yellow-500 to-orange-500 text-slate-950 rounded-2xl hover:brightness-110 transition-all font-black shadow-2xl shadow-yellow-500/30 disabled:opacity-50 group uppercase tracking-[0.1em]"
                  >
                    <Download className="w-6 h-6 group-hover:-translate-y-1 transition-transform" />
                    Build MP4 Social Video
                  </button>
                </div>
              </section>
            </div>
          </>
        ) : (
          <div className="col-span-12 animate-fade-in" style={{ animationDelay: '0.1s' }}>
            <section className="glass-card rounded-[3rem] p-12 min-h-[70vh] border-emerald-900/10">
