import { AnimationType } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  xOffset: number; // relative to line start
}

/**
 * Robust text wrapping that returns metadata for each word to allow precise centering.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number
): { lines: string[][], words: WordMetadata[] } => {
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  const paragraphs = text.split('\n');
  const wordsMetadata: WordMetadata[] = [];
  const lines: string[][] = [];

  // Calculate character-based relative timings for all words
  const allWordsRaw = text.split(/\s+/).filter(w => w.length > 0);
  const totalChars = allWordsRaw.reduce((sum, w) => sum + w.length, 0);

  if (totalChars === 0) {
    return { lines: [[]], words: [] };
  }

  let charCursor = 0;
  let lineIdx = 0;

  paragraphs.forEach((paragraph) => {
    const trimmed = paragraph.trim();
    if (trimmed === '') {
      lines.push(['']);
      lineIdx++;
      return;
    }

    const words = trimmed.split(/\s+/).filter(w => w.length > 0);
    let currentLineWords: string[] = [];
    let currentLineWidth = 0;

    for (let n = 0; n < words.length; n++) {
      const word = words[n];
      const wordWidth = ctx.measureText(word).width;
      const spaceWidth = ctx.measureText(' ').width;
      const testWidth = currentLineWidth + (currentLineWords.length > 0 ? spaceWidth : 0) + wordWidth;

      if (testWidth > maxWidth && currentLineWords.length > 0) {
        lines.push(currentLineWords);
        lineIdx++;
        currentLineWords = [];
        currentLineWidth = 0;
      }

      const start = charCursor / totalChars;
      charCursor += word.length;
      const end = charCursor / totalChars;

      wordsMetadata.push({
        text: word,
        start,
        end,
        width: wordWidth,
        lineIndex: lineIdx,
        xOffset: currentLineWidth + (currentLineWords.length > 0 ? spaceWidth : 0)
      });

      currentLineWords.push(word);
      currentLineWidth += (currentLineWords.length > 1 ? spaceWidth : 0) + wordWidth;
    }
    if (currentLineWords.length > 0) {
      lines.push(currentLineWords);
      lineIdx++;
    }
  });

  return { lines, words: wordsMetadata };
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  background: HTMLImageElement | HTMLVideoElement | null,
  text: string,
  progress: number,
  animationType: AnimationType = AnimationType.VERTICAL_SCROLL
) => {
  const ctx = canvas.getContext('2d', { alpha: false });
  if (!ctx) return;

  const width = canvas.width;
  const height = canvas.height;

  // 1. Background
  if (background) {
    const bgWidth = background instanceof HTMLVideoElement ? background.videoWidth : background.width;
    const bgHeight = background instanceof HTMLVideoElement ? background.videoHeight : background.height;

    if (bgWidth > 0 && bgHeight > 0) {
      const bgAspect = bgWidth / bgHeight;
      const canvasAspect = width / height;
      let renderWidth, renderHeight, x, y;

      if (bgAspect > canvasAspect) {
        renderHeight = height;
        renderWidth = height * bgAspect;
        x = (width - renderWidth) / 2;
        y = 0;
      } else {
        renderWidth = width;
        renderHeight = width / bgAspect;
        x = 0;
        y = (height - renderHeight) / 2;
      }
      ctx.drawImage(background, x, y, renderWidth, renderHeight);
    }
  } else {
    const grad = ctx.createLinearGradient(0, 0, 0, height);
    grad.addColorStop(0, '#042f2e');
    grad.addColorStop(1, '#020617');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, width, height);
  }

  // 2. Cinematic Overlays
  const vignette = ctx.createRadialGradient(width / 2, height / 2, 0, width / 2, height / 2, height);
  vignette.addColorStop(0, 'rgba(0, 0, 0, 0.2)');
  vignette.addColorStop(0.6, 'rgba(0, 0, 0, 0.5)');
  vignette.addColorStop(1, 'rgba(0, 0, 0, 0.85)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  // 3. Text Synchronization Config
  const baseFontSize = width * 0.085;
  const maxWidth = width * 0.85;
  const lineHeight = baseFontSize * 2.2;

  ctx.direction = 'rtl';
  ctx.textAlign = 'right'; // RTL base alignment
  ctx.textBaseline = 'middle';

  const { lines, words } = getWordMetadata(ctx, text, maxWidth, baseFontSize, lineHeight);

  if (words.length === 0) {
    return; // Nothing to draw
  }

  // Find current active word
  const activeWordIdx = words.findIndex(w => progress >= w.start && progress <= w.end);
  const activeWord = activeWordIdx !== -1 ? words[activeWordIdx] : (progress < 0.5 ? words[0] : words[words.length - 1]);

  if (!activeWord) return;

  ctx.save();

  if (animationType === AnimationType.VERTICAL_SCROLL) {
    // Center the current line vertically
    const targetY = height / 2;
    const currentLineY = activeWord.lineIndex * lineHeight;
    const scrollY = targetY - currentLineY;

    lines.forEach((lineWords, lineIdx) => {
      const lineY = scrollY + lineIdx * lineHeight;
      if (lineY < -lineHeight || lineY > height + lineHeight) return;

      let currentX = (width + maxWidth) / 2; // Right start for RTL

      lineWords.forEach(wordText => {
        if (!wordText.trim()) return;

        const wordMeta = words.find(w => w.text === wordText && w.lineIndex === lineIdx && progress >= w.start - 0.2 && progress <= w.end + 0.2);
        const isActive = wordMeta === activeWord;

        ctx.save();
        if (isActive) {
          ctx.fillStyle = '#fde047'; // Gold for active
          ctx.shadowColor = 'rgba(234, 179, 8, 0.8)';
          ctx.shadowBlur = 20;
          const scale = 1.1 + Math.sin(progress * 50) * 0.02;
          const wordW = ctx.measureText(wordText).width;
          ctx.translate(currentX - wordW/2, lineY);
          ctx.scale(scale, scale);
          ctx.translate(-(currentX - wordW/2), -lineY);
        } else {
          ctx.fillStyle = 'white';
          ctx.globalAlpha = 0.4;
          ctx.shadowColor = 'black';
          ctx.shadowBlur = 10;
        }

        ctx.fillText(wordText, currentX, lineY);
        ctx.restore();

        currentX -= (ctx.measureText(wordText).width + ctx.measureText(' ').width);
      });
    });
  } else {
    // Horizontal movements (Right to Left / Left to Right)
    const targetX = width / 2;
    const lineY = height / 2;
    const lineWords = lines[activeWord.lineIndex];

    if (!lineWords) {
      ctx.restore();
      return;
    }

    // The relative center of the active word within its line (RTL)
    const wordRelativeCenter = activeWord.xOffset + activeWord.width / 2;

    // Shift: targetX should be where wordRelativeCenter is.
    const startX = targetX + wordRelativeCenter;

    let currentX = startX;
    lineWords.forEach(wordText => {
      if (!wordText.trim()) return;

      const wordW = ctx.measureText(wordText).width;
      const spaceW = ctx.measureText(' ').width;

      const isThisActive = words.find(w => w.text === wordText && w.lineIndex === activeWord.lineIndex && Math.abs(w.start - activeWord.start) < 0.001);
      const isActive = isThisActive && isThisActive === activeWord;

      if (currentX > -wordW && currentX < width + wordW) {
        ctx.save();
        if (isActive) {
          ctx.fillStyle = '#fde047';
          ctx.shadowColor = 'rgba(234, 179, 8, 0.9)';
          ctx.shadowBlur = 25;
          const scale = 1.2;
          ctx.translate(currentX - wordW/2, lineY);
          ctx.scale(scale, scale);
          ctx.translate(-(currentX - wordW/2), -lineY);
        } else {
          ctx.fillStyle = 'white';
          ctx.globalAlpha = 0.3;
          ctx.shadowBlur = 5;
        }
        ctx.fillText(wordText, currentX, lineY);
        ctx.restore();
      }

      currentX -= (wordW + spaceW);
    });
  }

  ctx.restore();
};

import { GoogleGenAI, Modality, Type } from "@google/genai";
import { VoiceName, SEOMetadata } from "../types";

const safetySettings = [
  { category: "HARM_CATEGORY_HARASSMENT", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_HATE_SPEECH", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_SEXUALLY_EXPLICIT", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_DANGEROUS_CONTENT", threshold: "BLOCK_NONE" },
];

/**
 * Strips text of characters that might cause the TTS engine to crash or trigger 'OTHER' errors.
 */
const sanitizeForTTS = (text: string, strict = false): string => {
  let sanitized = text
    .replace(/\uFDFA/g, 'صلی اللہ علیہ وسلم') // ﷺ
    .replace(/[\u{1F000}-\u{1F9FF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B50}\u{2B55}]/gu, ''); // Emojis

  if (strict) {
    // Only Urdu alphabet characters and spaces.
    sanitized = sanitized.replace(/[^\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\s]/g, ' ');
  } else {
    // Keep Urdu, common digits, and standard punctuation.
    sanitized = sanitized.replace(/[^\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\s\d.,?!:;]/g, ' ');
  }

  return sanitized.replace(/\s+/g, ' ').trim();
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const generateNarration = async (text: string, voice: VoiceName, retryCount = 0): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Exponentially increase strictness and wait time
  const isStrict = retryCount > 0;
  const cleanText = sanitizeForTTS(text, isStrict);

  if (!cleanText) {
    throw new Error("No valid Urdu text found in script.");
  }

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ 
        parts: [{ 
          text: `Narrate the following Urdu text at a moderate, clear, and natural speaking pace. Ensure a steady rhythm without rushing: ${cleanText}` 
        }] 
      }],
      config: {
        responseModalities: [Modality.AUDIO], 
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voice },
          },
        },
        safetySettings: safetySettings as any,
      },
    });

    if (!response.candidates || response.candidates.length === 0) {
      throw new Error("Technical error: Empty response from AI.");
    }

    const candidate = response.candidates[0];

    // Handle content-specific blocks (RECITATION/OTHER)
    if ((candidate.finishReason === 'OTHER' || candidate.finishReason === 'RECITATION') && retryCount < 3) {
      console.warn(`Sensitivity block (${candidate.finishReason}). Retrying with simplified text...`);
      await delay(1000 * (retryCount + 1));
      return generateNarration(text, voice, retryCount + 1);
    }

    if (candidate.finishReason && candidate.finishReason !== 'STOP') {
      throw new Error(`Content Blocked: The AI cannot narrate this specific text (Reason: ${candidate.finishReason}).`);
    }

    const audioPart = candidate.content?.parts?.find(p => p.inlineData?.data);
    if (audioPart?.inlineData?.data) {
      return audioPart.inlineData.data;
    }

    throw new Error("Technical error: Audio data missing in response.");

  } catch (error: any) {
    const errorMsg = error.message || "";
    console.error(`Narration Error (Attempt ${retryCount + 1}):`, error);

    // Handle Technical RPC / 500 / XHR errors specifically
    const isTechnicalError = 
      errorMsg.includes("500") || 
      errorMsg.includes("INTERNAL") || 
      errorMsg.includes("xhr error") || 
      errorMsg.includes("Rpc failed") ||
      errorMsg.includes("UNKNOWN");

    if (isTechnicalError && retryCount < 3) {
      const waitTime = Math.pow(2, retryCount) * 2000; // 2s, 4s, 8s
      console.warn(`Transient technical error. Retrying in ${waitTime}ms...`);
      await delay(waitTime);
      return generateNarration(text, voice, retryCount + 1);
    }

    // Re-throw if we are out of retries or if it's a specific logical error
    if (isTechnicalError) {
      throw new Error("Connection unstable. The AI service is currently overloaded or failing to respond. Please check your internet and try again in a moment.");
    }

    throw error;
  }
};

