import { AnimationType } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  xOffset: number; // relative to line start
}

/**
 * Robust text wrapping that returns metadata for each word to allow precise centering.
 * Includes weights for spaces and paragraph breaks to better simulate vocal rhythm.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number
): { lines: string[][], words: WordMetadata[] } => {
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  const paragraphs = text.split('\n').map(p => p.trim());
  const wordsMetadata: WordMetadata[] = [];
  const lines: string[][] = [];

  // Calculate total "vocal weight" to map progress accurately
  // Punctuation and breaks take more "time" than just letters
  let totalWeight = 0;
  paragraphs.forEach((p, pIdx) => {
    if (p === '') {
      totalWeight += 2; // Weight for an empty line (pause)
      return;
    }
    const words = p.split(/\s+/).filter(w => w.length > 0);
    words.forEach((w, i) => {
      totalWeight += w.length;
      if (i < words.length - 1) totalWeight += 1; // Weight for space
    });
    if (pIdx < paragraphs.length - 1) totalWeight += 3; // Weight for paragraph break
  });

  if (totalWeight === 0) {
    return { lines: [[]], words: [] };
  }

  let weightCursor = 0;
  let lineIdx = 0;

  paragraphs.forEach((paragraph, pIdx) => {
    if (paragraph === '') {
      lines.push(['']);
      lineIdx++;
      weightCursor += 2;
      return;
    }

    const words = paragraph.split(/\s+/).filter(w => w.length > 0);
    let currentLineWords: string[] = [];
    let currentLineWidth = 0;

    for (let n = 0; n < words.length; n++) {
      const word = words[n];
      const wordWidth = ctx.measureText(word).width;
      const spaceWidth = ctx.measureText(' ').width;
      const testWidth = currentLineWidth + (currentLineWords.length > 0 ? spaceWidth : 0) + wordWidth;

      if (testWidth > maxWidth && currentLineWords.length > 0) {
        lines.push(currentLineWords);
        lineIdx++;
        currentLineWords = [];
        currentLineWidth = 0;
      }

      const start = weightCursor / totalWeight;
      weightCursor += word.length;
      const end = weightCursor / totalWeight;

      // Advance cursor for the space after the word (unless it's the last word of a paragraph)
      if (n < words.length - 1) {
        weightCursor += 1;
      }

      wordsMetadata.push({
        text: word,
        start,
        end,
        width: wordWidth,
        lineIndex: lineIdx,
        xOffset: currentLineWidth + (currentLineWords.length > 0 ? spaceWidth : 0)
      });

      currentLineWords.push(word);
      currentLineWidth += (currentLineWords.length > 1 ? spaceWidth : 0) + wordWidth;
    }

    if (currentLineWords.length > 0) {
      lines.push(currentLineWords);
      lineIdx++;
    }

    // Add weight for the paragraph break itself
    if (pIdx < paragraphs.length - 1) {
      weightCursor += 3;
    }
  });

  return { lines, words: wordsMetadata };
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  background: HTMLImageElement | HTMLVideoElement | null,
  text: string,
  progress: number,
  animationType: AnimationType = AnimationType.VERTICAL_SCROLL
) => {
  const ctx = canvas.getContext('2d', { alpha: false });
  if (!ctx) return;

  const width = canvas.width;
  const height = canvas.height;

  // 1. Background
  if (background) {
    const bgWidth = background instanceof HTMLVideoElement ? background.videoWidth : background.width;
    const bgHeight = background instanceof HTMLVideoElement ? background.videoHeight : background.height;

    if (bgWidth > 0 && bgHeight > 0) {
      const bgAspect = bgWidth / bgHeight;
      const canvasAspect = width / height;
      let renderWidth, renderHeight, x, y;

      if (bgAspect > canvasAspect) {
        renderHeight = height;
        renderWidth = height * bgAspect;
        x = (width - renderWidth) / 2;
        y = 0;
      } else {
        renderWidth = width;
        renderHeight = width / bgAspect;
        x = 0;
        y = (height - renderHeight) / 2;
      }
      ctx.drawImage(background, x, y, renderWidth, renderHeight);
    }
  } else {
    const grad = ctx.createLinearGradient(0, 0, 0, height);
    grad.addColorStop(0, '#042f2e');
    grad.addColorStop(1, '#020617');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, width, height);
  }

  // 2. Cinematic Overlays
  const vignette = ctx.createRadialGradient(width / 2, height / 2, 0, width / 2, height / 2, height);
  vignette.addColorStop(0, 'rgba(0, 0, 0, 0.2)');
  vignette.addColorStop(0.6, 'rgba(0, 0, 0, 0.5)');
  vignette.addColorStop(1, 'rgba(0, 0, 0, 0.85)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  // 3. Text Synchronization Config
  const baseFontSize = width * 0.085;
  const maxWidth = width * 0.85;
  const lineHeight = baseFontSize * 2.2;

  ctx.direction = 'rtl';
  ctx.textAlign = 'right'; 
  ctx.textBaseline = 'middle';

  const { lines, words } = getWordMetadata(ctx, text, maxWidth, baseFontSize, lineHeight);

  if (words.length === 0) {
    return;
  }

  // Find current active word with a slight offset adjustment for TTS breathing
  const activeWordIdx = words.findIndex(w => progress >= w.start && progress <= w.end);
  const activeWord = activeWordIdx !== -1 ? words[activeWordIdx] : (progress < 0.5 ? words[0] : words[words.length - 1]);

  if (!activeWord) return;

  ctx.save();

  if (animationType === AnimationType.VERTICAL_SCROLL) {
    const targetY = height / 2;
    const currentLineY = activeWord.lineIndex * lineHeight;
    const scrollY = targetY - currentLineY;

    lines.forEach((lineWords, lineIdx) => {
      const lineY = scrollY + lineIdx * lineHeight;
      if (lineY < -lineHeight || lineY > height + lineHeight) return;

      let currentX = (width + maxWidth) / 2; 

      lineWords.forEach(wordText => {
        if (!wordText.trim()) return;

        // Find if this specific instance of the word is active
        const wordMeta = words.find(w => w.text === wordText && w.lineIndex === lineIdx && Math.abs(w.start - activeWord.start) < 0.0001);
        const isActive = wordMeta === activeWord;

        ctx.save();
        if (isActive) {
          ctx.fillStyle = '#fde047'; 
          ctx.shadowColor = 'rgba(234, 179, 8, 0.8)';
          ctx.shadowBlur = 20;
          const scale = 1.15;
          const wordW = ctx.measureText(wordText).width;
          ctx.translate(currentX - wordW/2, lineY);
          ctx.scale(scale, scale);
          ctx.translate(-(currentX - wordW/2), -lineY);
        } else {
          ctx.fillStyle = 'white';
          ctx.globalAlpha = 0.35;
          ctx.shadowColor = 'black';
          ctx.shadowBlur = 10;
        }

        ctx.fillText(wordText, currentX, lineY);
        ctx.restore();

        currentX -= (ctx.measureText(wordText).width + ctx.measureText(' ').width);
      });
    });
  } else {
    // Horizontal movements
    const targetX = width / 2;
    const lineY = height / 2;
    const lineWords = lines[activeWord.lineIndex];

    if (!lineWords) {
      ctx.restore();
      return;
    }

    const wordRelativeCenter = activeWord.xOffset + activeWord.width / 2;
    const startX = targetX + wordRelativeCenter;

    let currentX = startX;
    lineWords.forEach(wordText => {
      if (!wordText.trim()) return;

      const wordW = ctx.measureText(wordText).width;
      const spaceW = ctx.measureText(' ').width;

      const isThisActive = words.find(w => w.text === wordText && w.lineIndex === activeWord.lineIndex && Math.abs(w.start - activeWord.start) < 0.0001);
      const isActive = isThisActive && isThisActive === activeWord;

      if (currentX > -wordW && currentX < width + wordW) {
        ctx.save();
        if (isActive) {
          ctx.fillStyle = '#fde047';
          ctx.shadowColor = 'rgba(234, 179, 8, 0.9)';
          ctx.shadowBlur = 25;
          const scale = 1.2;
          ctx.translate(currentX - wordW/2, lineY);
          ctx.scale(scale, scale);
          ctx.translate(-(currentX - wordW/2), -lineY);
        } else {
          ctx.fillStyle = 'white';
          ctx.globalAlpha = 0.25;
          ctx.shadowBlur = 5;
        }
        ctx.fillText(wordText, currentX, lineY);
        ctx.restore();
      }

      currentX -= (wordW + spaceW);
    });
  }

  ctx.restore();
};

import { AnimationType } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  centerX: number; // Center of word relative to line start (RTL)
  centerY: number; // Absolute Y based on line index
}

/**
 * Calculates word metadata with vocal weights and exact spatial coordinates.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number
): { lines: string[][], words: WordMetadata[] } => {
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  const paragraphs = text.split('\n').map(p => p.trim());
  const wordsMetadata: WordMetadata[] = [];
  const lines: string[][] = [];

  let totalWeight = 0;
  paragraphs.forEach((p, pIdx) => {
    if (p === '') {
      totalWeight += 2;
      return;
    }
    const words = p.split(/\s+/).filter(w => w.length > 0);
    words.forEach((w, i) => {
      totalWeight += w.length;
      if (i < words.length - 1) totalWeight += 1;
    });
    if (pIdx < paragraphs.length - 1) totalWeight += 3;
  });

  if (totalWeight === 0) return { lines: [[]], words: [] };

  let weightCursor = 0;
  let lineIdx = 0;

  paragraphs.forEach((paragraph, pIdx) => {
    if (paragraph === '') {
      lines.push(['']);
      lineIdx++;
      weightCursor += 2;
      return;
    }

    const wordsInPara = paragraph.split(/\s+/).filter(w => w.length > 0);
    let currentLineWords: string[] = [];
    let currentLineWidth = 0;

    for (let n = 0; n < wordsInPara.length; n++) {
      const word = wordsInPara[n];
      const wordWidth = ctx.measureText(word).width;
      const spaceWidth = ctx.measureText(' ').width;
      const testWidth = currentLineWidth + (currentLineWords.length > 0 ? spaceWidth : 0) + wordWidth;

      if (testWidth > maxWidth && currentLineWords.length > 0) {
        lines.push(currentLineWords);
        lineIdx++;
        currentLineWords = [];
        currentLineWidth = 0;
      }

      const start = weightCursor / totalWeight;
      weightCursor += word.length;
      const end = weightCursor / totalWeight;

      const xOffsetInLine = currentLineWidth + (currentLineWords.length > 0 ? spaceWidth : 0);

      wordsMetadata.push({
        text: word,
        start,
        end,
        width: wordWidth,
        lineIndex: lineIdx,
        centerX: xOffsetInLine + (wordWidth / 2),
        centerY: lineIdx * lineHeight
      });

      if (n < wordsInPara.length - 1) weightCursor += 1;

      currentLineWords.push(word);
      currentLineWidth += (currentLineWords.length > 1 ? spaceWidth : 0) + wordWidth;
    }

    if (currentLineWords.length > 0) {
      lines.push(currentLineWords);
      lineIdx++;
    }

    if (pIdx < paragraphs.length - 1) weightCursor += 3;
  });

  return { lines, words: wordsMetadata };
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  background: HTMLImageElement | HTMLVideoElement | null,
  text: string,
  progress: number,
  animationType: AnimationType = AnimationType.VERTICAL_SCROLL
) => {
  const ctx = canvas.getContext('2d', { alpha: false });
  if (!ctx) return;

  const width = canvas.width;
  const height = canvas.height;

  // 1. Background Rendering
  if (background) {
    const bgWidth = background instanceof HTMLVideoElement ? background.videoWidth : background.width;
    const bgHeight = background instanceof HTMLVideoElement ? background.videoHeight : background.height;
    if (bgWidth > 0 && bgHeight > 0) {
      const bgAspect = bgWidth / bgHeight;
      const canvasAspect = width / height;
      let rw, rh, rx, ry;
      if (bgAspect > canvasAspect) { rh = height; rw = height * bgAspect; rx = (width - rw) / 2; ry = 0; }
      else { rw = width; rh = width / bgAspect; rx = 0; ry = (height - rh) / 2; }
      ctx.drawImage(background, rx, ry, rw, rh);
    }
  } else {
    ctx.fillStyle = '#020617';
    ctx.fillRect(0, 0, width, height);
  }

  // Cinematic Vignette
  const vignette = ctx.createRadialGradient(width/2, height/2, 0, width/2, height/2, height * 0.8);
  vignette.addColorStop(0, 'rgba(0,0,0,0)');
  vignette.addColorStop(1, 'rgba(0,0,0,0.7)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  // 2. Text Configuration
  const baseFontSize = width * 0.085;
  const maxWidth = width * 0.85;
  const lineHeight = baseFontSize * 2.5;

  ctx.direction = 'rtl';
  ctx.textBaseline = 'middle';

  const { lines, words } = getWordMetadata(ctx, text, maxWidth, baseFontSize, lineHeight);
  if (words.length === 0) return;

  // 3. Smooth Camera Interpolation
  // Find current and next word to interpolate position
  const activeIdx = words.findIndex(w => progress >= w.start && progress <= w.end);
  const currentWord = activeIdx !== -1 ? words[activeIdx] : (progress < words[0].start ? words[0] : words[words.length - 1]);

  // Find next word for smooth transition
  const nextWord = words[activeIdx + 1] || currentWord;

  // Calculate interpolation factor (alpha) within the current word's timeframe
  const wordDuration = currentWord.end - currentWord.start;
  const alpha = wordDuration > 0 ? Math.max(0, Math.min(1, (progress - currentWord.start) / wordDuration)) : 0;

  // Calculate smooth scroll targets
  // In RTL, the "line start" is on the right side of the maxWidth block
  const blockRightX = (width + maxWidth) / 2;

  const smoothCenterY = currentWord.centerY + (nextWord.centerY - currentWord.centerY) * alpha;
  const smoothCenterX = currentWord.centerX + (nextWord.centerX - currentWord.centerX) * alpha;

  ctx.save();

  if (animationType === AnimationType.VERTICAL_SCROLL) {
    const scrollY = (height / 2) - smoothCenterY;

    lines.forEach((lineWords, lineIdx) => {
      const lineY = scrollY + (lineIdx * lineHeight);
      if (lineY < -lineHeight || lineY > height + lineHeight) return;

      let currentX = blockRightX;
      lineWords.forEach(wordText => {
        const wordW = ctx.measureText(wordText).width;
        const spaceW = ctx.measureText(' ').width;

        // Match specific word instance
        const wordMeta = words.find(w => w.text === wordText && w.lineIndex === lineIdx && Math.abs(w.start - currentWord.start) < 0.001);
        const isActive = wordMeta === currentWord;

        ctx.save();
        if (isActive) {
          ctx.fillStyle = '#fde047';
          ctx.shadowColor = 'rgba(234, 179, 8, 0.8)';
          ctx.shadowBlur = 25;
          const scale = 1.1 + (Math.sin(progress * 40) * 0.02);
          ctx.translate(currentX - wordW / 2, lineY);
          ctx.scale(scale, scale);
          ctx.translate(-(currentX - wordW / 2), -lineY);
        } else {
          ctx.fillStyle = 'white';
          ctx.globalAlpha = 0.3;
        }
        ctx.fillText(wordText, currentX, lineY);
        ctx.restore();

        currentX -= (wordW + spaceW);
      });
    });
  } else {
    // Horizontal Centering with Wrapping Support
    // We scroll the entire block horizontally and vertically to keep the active word centered
    const scrollY = (height / 2) - currentWord.centerY;
    const scrollX = (width / 2) + smoothCenterX - blockRightX;

    lines.forEach((lineWords, lineIdx) => {
      const lineY = scrollY + (lineIdx * lineHeight);
      if (lineY < -lineHeight || lineY > height + lineHeight) return;

      let currentX = blockRightX + (scrollX - (width / 2)); // Adjusted start based on scroll

      // In horizontal mode, if we want the word at screen center, we calculate global offset
      // target is width/2. Current word center is at (blockRightX - wordCenterX) + globalOffset.
      const horizontalOffset = (width / 2) - (blockRightX - smoothCenterX);

      let drawX = blockRightX + horizontalOffset;

      lineWords.forEach(wordText => {
        const wordW = ctx.measureText(wordText).width;
        const spaceW = ctx.measureText(' ').width;

        const wordMeta = words.find(w => w.text === wordText && w.lineIndex === lineIdx && Math.abs(w.start - currentWord.start) < 0.001);
        const isActive = wordMeta === currentWord;

        if (drawX > -wordW && drawX < width + wordW) {
          ctx.save();
          if (isActive) {
            ctx.fillStyle = '#fde047';
            ctx.shadowColor = 'rgba(234, 179, 8, 0.8)';
            ctx.shadowBlur = 30;
            const scale = 1.2;
            ctx.translate(drawX - wordW/2, lineY);
            ctx.scale(scale, scale);
            ctx.translate(-(drawX - wordW/2), -lineY);
          } else {
            ctx.fillStyle = 'white';
            ctx.globalAlpha = 0.2;
          }
          ctx.fillText(wordText, drawX, lineY);
          ctx.restore();
        }
        drawX -= (wordW + spaceW);
      });
    });
  }

  ctx.restore();
};

