export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  globalX: number; // Center X coordinate relative to the text block's right edge
  globalY: number; // Center Y coordinate relative to the text block's top
}

/**
 * Maps the text into a spatial coordinate system with precise timing weights.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number
): { lines: string[][], words: WordMetadata[] } => {
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  const paragraphs = text.split('\n').map(p => p.trim());
  const wordsMetadata: WordMetadata[] = [];
  const lines: string[][] = [];

  // Calculate timing weights. Punctuation and breaks get extra "time".
  let totalWeight = 0;
  paragraphs.forEach((p, pIdx) => {
    if (p === '') {
      totalWeight += 4; // Pause for empty lines
      return;
    }
    const words = p.split(/\s+/).filter(w => w.length > 0);
    words.forEach((w, i) => {
      // Weight is based on length + small constant for speaking effort
      totalWeight += w.length + 2; 
      // Extra weight for punctuation
      if (w.match(/[۔؟!،:]/)) totalWeight += 3;
    });
    if (pIdx < paragraphs.length - 1) totalWeight += 6; // Long pause between paragraphs
  });

  if (totalWeight === 0) return { lines: [[]], words: [] };

  let weightCursor = 0;
  let lineIdx = 0;

  paragraphs.forEach((paragraph, pIdx) => {
    if (paragraph === '') {
      lines.push(['']);
      lineIdx++;
      weightCursor += 4;
      return;
    }

    const wordsInPara = paragraph.split(/\s+/).filter(w => w.length > 0);
    let currentLineWords: string[] = [];
    let currentLineWidth = 0;

    for (let n = 0; n < wordsInPara.length; n++) {
      const word = wordsInPara[n];
      const wordWidth = ctx.measureText(word).width;
      const spaceWidth = ctx.measureText(' ').width;
      const testWidth = currentLineWidth + (currentLineWords.length > 0 ? spaceWidth : 0) + wordWidth;

      // Wrap text if it exceeds maxWidth
      if (testWidth > maxWidth && currentLineWords.length > 0) {
        lines.push(currentLineWords);
        lineIdx++;
        currentLineWords = [];
        currentLineWidth = 0;
      }

      const wordWeight = word.length + 2 + (word.match(/[۔؟!،:]/) ? 3 : 0);
      const start = weightCursor / totalWeight;
      weightCursor += wordWeight;
      const end = weightCursor / totalWeight;

      const xOffsetInLine = currentLineWidth + (currentLineWords.length > 0 ? spaceWidth : 0);

      wordsMetadata.push({
        text: word,
        start,
        end,
        width: wordWidth,
        lineIndex: lineIdx,
        globalX: xOffsetInLine + (wordWidth / 2),
        globalY: lineIdx * lineHeight
      });

      currentLineWords.push(word);
      currentLineWidth += (currentLineWords.length > 1 ? spaceWidth : 0) + wordWidth;
    }

    if (currentLineWords.length > 0) {
      lines.push(currentLineWords);
      lineIdx++;
    }

    if (pIdx < paragraphs.length - 1) weightCursor += 6;
  });

  return { lines, words: wordsMetadata };
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  background: HTMLImageElement | HTMLVideoElement | null,
  text: string,
  progress: number,
  animationType: AnimationType = AnimationType.VERTICAL_SCROLL
) => {
  const ctx = canvas.getContext('2d', { alpha: false });
  if (!ctx) return;

  const width = canvas.width;
  const height = canvas.height;

  // 1. Background Layer
  if (background) {
    const bgWidth = background instanceof HTMLVideoElement ? background.videoWidth : background.width;
    const bgHeight = background instanceof HTMLVideoElement ? background.videoHeight : background.height;
    if (bgWidth > 0 && bgHeight > 0) {
      const bgAspect = bgWidth / bgHeight;
      const canvasAspect = width / height;
      let rw, rh, rx, ry;
      if (bgAspect > canvasAspect) { rh = height; rw = height * bgAspect; rx = (width - rw) / 2; ry = 0; }
      else { rw = width; rh = width / bgAspect; rx = 0; ry = (height - rh) / 2; }
      ctx.drawImage(background, rx, ry, rw, rh);
    }
  } else {
    ctx.fillStyle = '#020617';
    ctx.fillRect(0, 0, width, height);
  }

  // Cinematic Gradient Overlays
  const grad = ctx.createLinearGradient(0, 0, 0, height);
  grad.addColorStop(0, 'rgba(2, 6, 23, 0.7)');
  grad.addColorStop(0.3, 'rgba(2, 6, 23, 0)');
  grad.addColorStop(0.7, 'rgba(2, 6, 23, 0)');
  grad.addColorStop(1, 'rgba(2, 6, 23, 0.9)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);

  // 2. Text Logic
  const baseFontSize = width * 0.085;
  const maxWidth = width * 0.85;
  const lineHeight = baseFontSize * 2.6;

  ctx.direction = 'rtl';
  ctx.textBaseline = 'middle';

  const { lines, words } = getWordMetadata(ctx, text, maxWidth, baseFontSize, lineHeight);
  if (words.length === 0) return;

  // 3. Smooth Camera Follow
  // Find current active word
  const activeIdx = words.findIndex(w => progress >= w.start && progress <= w.end);
  const currentWord = activeIdx !== -1 ? words[activeIdx] : (progress < words[0].start ? words[0] : words[words.length - 1]);

  // Find next word for smooth look-ahead interpolation
  const nextWord = words[activeIdx + 1] || currentWord;

  // Interpolation factor between words (0 to 1)
  const wordDuration = currentWord.end - currentWord.start;
  const t = wordDuration > 0 ? Math.max(0, Math.min(1, (progress - currentWord.start) / wordDuration)) : 0;

  // Smooth global coordinates
  const smoothX = currentWord.globalX + (nextWord.globalX - currentWord.globalX) * t;
  const smoothY = currentWord.globalY + (nextWord.globalY - currentWord.globalY) * t;

  // Coordinates of the "Right Wall" of the text block
  const blockRightX = (width + maxWidth) / 2;

  ctx.save();

  // 4. Transform Camera based on Animation Mode
  let cameraOffsetX = 0;
  let cameraOffsetY = (height / 2) - smoothY;

  if (animationType === AnimationType.VERTICAL_SCROLL) {
    // Only scroll Y, keep X static centered
    cameraOffsetX = 0;
  } else if (animationType === AnimationType.RIGHT_TO_LEFT) {
    // Scroll both X and Y to follow word flow exactly at screen center
    cameraOffsetX = (width / 2) - (blockRightX - smoothX);
  } else if (animationType === AnimationType.LEFT_TO_RIGHT) {
    cameraOffsetX = -(width / 2) + (blockRightX - smoothX);
  }

  // 5. Draw all visible lines within the camera viewport
  lines.forEach((lineWords, lineIdx) => {
    const lineY = cameraOffsetY + (lineIdx * lineHeight);

    // Cull lines way off-screen
    if (lineY < -lineHeight * 2 || lineY > height + lineHeight * 2) return;

    // Start drawing from the right (RTL)
    let currentX = blockRightX + cameraOffsetX;

    lineWords.forEach(wordText => {
      const wordW = ctx.measureText(wordText).width;
      const spaceW = ctx.measureText(' ').width;

      // Determine if this specific word is the "Speaking" word
      // We check start time proximity to differentiate identical words on different lines
      const isActuallySpeaking = words.find(w => w.text === wordText && w.lineIndex === lineIdx && Math.abs(w.start - currentWord.start) < 0.0001);
      const isActive = isActuallySpeaking === currentWord;

      ctx.save();
      if (isActive) {
        ctx.fillStyle = '#fde047'; // Vivid Gold
        ctx.shadowColor = 'rgba(234, 179, 8, 0.9)';
        ctx.shadowBlur = 30;

        // Dynamic "Pulse" scale based on word progress
        const scale = 1.15 + (Math.sin(t * Math.PI) * 0.05);
        ctx.translate(currentX - wordW / 2, lineY);
        ctx.scale(scale, scale);
        ctx.translate(-(currentX - wordW / 2), -lineY);
      } else {
        ctx.fillStyle = 'white';
        ctx.globalAlpha = 0.3; // Low contrast for past/future words
        ctx.shadowColor = 'black';
        ctx.shadowBlur = 15;
      }

      ctx.fillText(wordText, currentX, lineY);
      ctx.restore();

      currentX -= (wordW + spaceW);
    });
  });

  ctx.restore();
};

import { GoogleGenAI, Modality, Type } from "@google/genai";
import { VoiceName, SEOMetadata } from "../types";

const safetySettings = [
  { category: "HARM_CATEGORY_HARASSMENT", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_HATE_SPEECH", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_SEXUALLY_EXPLICIT", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_DANGEROUS_CONTENT", threshold: "BLOCK_NONE" },
];

/**
 * Progressively sanitizes Urdu text to bypass strict AI safety/style filters.
 * Stage 0: Basic (Remove emojis)
 * Stage 1: Strict (Remove honorifics, non-Urdu symbols)
 * Stage 2: Super Strict (Remove Diacritics/Aeraab)
 * Stage 3: Extreme (Only letters and spaces)
 */
const sanitizeForTTS = (text: string, level: number = 0): string => {
  let sanitized = text;

  // Level 0: Always remove emojis and non-standard symbols
  sanitized = sanitized.replace(/[\u{1F000}-\u{1F9FF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B50}\u{2B55}]/gu, '');

  if (level >= 1) {
    // Remove common honorifics that trigger 'Recitation' blocks
    sanitized = sanitized
      .replace(/\uFDFA/g, 'صلی اللہ علیہ وسلم') // ﷺ
      .replace(/[\u0610-\u0613]/g, ''); // Small signs like (RA), (AS)
  }

  if (level >= 2) {
    // Remove Urdu Diacritics (Zair, Zabar, Pesh, Tashdeed, etc.) 
    // These often make the AI think the text is a religious recitation.
    sanitized = sanitized.replace(/[\u064B-\u0652\u0670]/g, '');
  }

  if (level >= 3) {
    // Extreme: Keep ONLY Urdu alphabet characters and spaces. 
    // Remove all punctuation (.,?!:;) and digits.
    sanitized = sanitized.replace(/[^\u0600-\u06FF\s]/g, ' ');
  }

  return sanitized.replace(/\s+/g, ' ').trim();
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const generateNarration = async (text: string, voice: VoiceName, retryCount = 0): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Progressively increase sanitization level based on retry attempt
  const cleanText = sanitizeForTTS(text, retryCount);

  if (!cleanText) {
    throw new Error("The text provided is empty after cleaning.");
  }

  console.log(`TTS Attempt ${retryCount + 1}: Sanitization Level ${retryCount}`);

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ 
        parts: [{ 
          text: `Read this Urdu text clearly at a natural pace: ${cleanText}` 
        }] 
      }],
      config: {
        responseModalities: [Modality.AUDIO], 
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voice },
          },
        },
        safetySettings: safetySettings as any,
      },
    });

    if (!response.candidates || response.candidates.length === 0) {
      throw new Error("The AI service returned an empty response.");
    }

    const candidate = response.candidates[0];

    // Handle generic block reasons (OTHER, RECITATION, SAFETY)
    if (candidate.finishReason && candidate.finishReason !== 'STOP') {
      if (retryCount < 3) {
        console.warn(`Block detected (${candidate.finishReason}). Retrying with more aggressive sanitization...`);
        await delay(1500 * (retryCount + 1));
        return generateNarration(text, voice, retryCount + 1);
      }
      throw new Error(`Content Blocked: The AI safety filters are preventing this narration. Try simplifying the wording. (Reason: ${candidate.finishReason})`);
    }

    const audioPart = candidate.content?.parts?.find(p => p.inlineData?.data);
    if (audioPart?.inlineData?.data) {
      return audioPart.inlineData.data;
    }

    throw new Error("Audio data was not returned by the AI.");

  } catch (error: any) {
    const errorMsg = error.message || "";

    // Retry on technical errors
    const isTechnical = errorMsg.includes("500") || errorMsg.includes("INTERNAL") || errorMsg.includes("xhr") || errorMsg.includes("Rpc");
    if (isTechnical && retryCount < 3) {
      await delay(2000 * (retryCount + 1));
      return generateNarration(text, voice, retryCount + 1);
    }

    throw error;
  }
};

