import { AnimationType } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  globalX: number; // Distance from the right edge of the text block
  globalY: number; // Vertical distance from the top of the text block
}

/**
 * Calculates high-precision spatial and temporal metadata for the script.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number
): { lines: string[][], words: WordMetadata[] } => {
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  const paragraphs = text.split('\n').map(p => p.trim());
  const wordsMetadata: WordMetadata[] = [];
  const lines: string[][] = [];

  let totalWeight = 0;
  paragraphs.forEach((p, pIdx) => {
    if (p === '') { totalWeight += 4; return; }
    const words = p.split(/\s+/).filter(w => w.length > 0);
    words.forEach((w) => {
      totalWeight += w.length + 2; 
      if (w.match(/[۔؟!،:]/)) totalWeight += 3;
    });
    if (pIdx < paragraphs.length - 1) totalWeight += 6;
  });

  if (totalWeight === 0) return { lines: [[]], words: [] };

  let weightCursor = 0;
  let lineIdx = 0;

  paragraphs.forEach((paragraph, pIdx) => {
    if (paragraph === '') {
      lines.push(['']);
      lineIdx++;
      weightCursor += 4;
      return;
    }

    const wordsInPara = paragraph.split(/\s+/).filter(w => w.length > 0);
    let currentLineWords: string[] = [];
    let currentLineWidth = 0;

    for (let n = 0; n < wordsInPara.length; n++) {
      const word = wordsInPara[n];
      const wordWidth = ctx.measureText(word).width;
      const spaceWidth = ctx.measureText(' ').width;
      const testWidth = currentLineWidth + (currentLineWords.length > 0 ? spaceWidth : 0) + wordWidth;

      if (testWidth > maxWidth && currentLineWords.length > 0) {
        lines.push(currentLineWords);
        lineIdx++;
        currentLineWords = [];
        currentLineWidth = 0;
      }

      const wordWeight = word.length + 2 + (word.match(/[۔؟!،:]/) ? 3 : 0);
      const start = weightCursor / totalWeight;
      weightCursor += wordWeight;
      const end = weightCursor / totalWeight;

      const xOffsetInLine = currentLineWidth + (currentLineWords.length > 0 ? spaceWidth : 0);

      wordsMetadata.push({
        text: word,
        start,
        end,
        width: wordWidth,
        lineIndex: lineIdx,
        globalX: xOffsetInLine + (wordWidth / 2),
        globalY: lineIdx * lineHeight
      });

      currentLineWords.push(word);
      currentLineWidth += (currentLineWords.length > 1 ? spaceWidth : 0) + wordWidth;
    }

    if (currentLineWords.length > 0) {
      lines.push(currentLineWords);
      lineIdx++;
    }

    if (pIdx < paragraphs.length - 1) weightCursor += 6;
  });

  return { lines, words: wordsMetadata };
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  background: HTMLImageElement | HTMLVideoElement | null,
  text: string,
  progress: number,
  animationType: AnimationType = AnimationType.VERTICAL_SCROLL
) => {
  const ctx = canvas.getContext('2d', { alpha: false });
  if (!ctx) return;

  const width = canvas.width;
  const height = canvas.height;

  // 1. Background Layer
  if (background) {
    const bw = background instanceof HTMLVideoElement ? background.videoWidth : background.width;
    const bh = background instanceof HTMLVideoElement ? background.videoHeight : background.height;
    if (bw > 0 && bh > 0) {
      const ba = bw / bh;
      const ca = width / height;
      let rw, rh, rx, ry;
      if (ba > ca) { rh = height; rw = height * ba; rx = (width - rw) / 2; ry = 0; }
      else { rw = width; rh = width / ba; rx = 0; ry = (height - rh) / 2; }
      ctx.drawImage(background, rx, ry, rw, rh);
    }
  } else {
    ctx.fillStyle = '#020617';
    ctx.fillRect(0, 0, width, height);
  }

  // Atmospheric Overlay
  const vignette = ctx.createRadialGradient(width/2, height/2, 0, width/2, height/2, height * 0.9);
  vignette.addColorStop(0, 'rgba(2, 6, 23, 0.2)');
  vignette.addColorStop(1, 'rgba(2, 6, 23, 0.85)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  // 2. Text Logic
  const baseFontSize = width * 0.08;
  const maxWidth = width * 0.85;
  const lineHeight = baseFontSize * 2.8;

  ctx.direction = 'rtl';
  ctx.textBaseline = 'middle';
  ctx.textAlign = 'center'; // Using center for easier coordinate math

  const { lines, words } = getWordMetadata(ctx, text, maxWidth, baseFontSize, lineHeight);
  if (words.length === 0) return;

  // 3. Precise Camera Target Calculation
  const activeIdx = words.findIndex(w => progress >= w.start && progress <= w.end);
  const currentWord = activeIdx !== -1 ? words[activeIdx] : (progress < words[0].start ? words[0] : words[words.length - 1]);
  const nextWord = words[activeIdx + 1] || currentWord;

  const wordDur = currentWord.end - currentWord.start;
  const t = wordDur > 0 ? Math.max(0, Math.min(1, (progress - currentWord.start) / wordDur)) : 0;

  // Camera uses LERP for buttery-smooth movement
  const smoothX = currentWord.globalX + (nextWord.globalX - currentWord.globalX) * t;
  const smoothY = currentWord.globalY + (nextWord.globalY - currentWord.globalY) * t;

  const blockRightX = (width + maxWidth) / 2;

  // 4. Viewport Transforms
  ctx.save();

  let camX = 0;
  let camY = (height / 2) - smoothY;

  if (animationType === AnimationType.RIGHT_TO_LEFT) {
    camX = (width / 2) - (blockRightX - smoothX);
  } else if (animationType === AnimationType.LEFT_TO_RIGHT) {
    camX = -(width / 2) + (blockRightX - smoothX);
  } else {
    camX = 0; // Standard centering for vertical scroll
  }

  // 5. Render
  lines.forEach((lineWords, lineIdx) => {
    const lineY = camY + (lineIdx * lineHeight);
    if (lineY < -lineHeight * 2 || lineY > height + lineHeight * 2) return;

    let lineXCursor = blockRightX + camX;

    lineWords.forEach(wordText => {
      const wordW = ctx.measureText(wordText).width;
      const spaceW = ctx.measureText(' ').width;

      const drawX = lineXCursor - (wordW / 2);

      const wordMeta = words.find(w => w.text === wordText && w.lineIndex === lineIdx && Math.abs(w.start - currentWord.start) < 0.001);
      const isActive = wordMeta === currentWord;

      ctx.save();
      if (isActive) {
        ctx.fillStyle = '#fde047';
        ctx.shadowColor = 'rgba(234, 179, 8, 0.8)';
        ctx.shadowBlur = 35;
        const scale = 1.15 + (Math.sin(t * Math.PI) * 0.08);
        ctx.translate(drawX, lineY);
        ctx.scale(scale, scale);
        ctx.translate(-drawX, -lineY);
      } else {
        ctx.fillStyle = 'white';
        ctx.globalAlpha = 0.25;
        ctx.shadowColor = 'black';
        ctx.shadowBlur = 10;
      }

      ctx.fillText(wordText, drawX, lineY);
      ctx.restore();

      lineXCursor -= (wordW + spaceW);
    });
  });

  ctx.restore();
};

