  { category: "HARM_CATEGORY_SEXUALLY_EXPLICIT", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_DANGEROUS_CONTENT", threshold: "BLOCK_NONE" },
];

/**
 * Progressively sanitizes Urdu text to bypass strict AI safety/recitation filters.
 */
const sanitizeForTTS = (text: string, level: number = 0): string => {
  let sanitized = text;

  // Level 0: Essential cleaning (Remove emojis and decorative symbols)
  sanitized = sanitized.replace(/[\u{1F000}-\u{1F9FF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B50}\u{2B55}]/gu, '');

  if (level >= 1) {
    // Level 1: Replace/Remove specific honorifics that trigger "Recitation" blocks
    sanitized = sanitized
      .replace(/\uFDFA/g, 'صلی اللہ علیہ وسلم') // ﷺ
      .replace(/[\u0610-\u0613]/g, '') // Arabic small signs
      .replace(/آیت الکرسی/g, 'ایک دعا') // Bypass specific scripture names
      .replace(/صحیح البخاری/g, 'کتاب') // Bypass specific source names
      .replace(/حدیث نمبر/g, 'قول'); 
  }

  if (level >= 2) {
    // Level 2: Strip all Diacritics/Aeraab (Zair, Zabar, etc.)
    // High-resolution diacritics often make the AI detect "scripture" patterns.
    sanitized = sanitized.replace(/[\u064B-\u0652\u0670]/g, '');
  }

  if (level >= 3) {
    // Level 3: Extreme - Remove punctuation and keep only core letters
    sanitized = sanitized.replace(/[^\u0600-\u06FF\s]/g, ' ');
  }

  return sanitized.replace(/\s+/g, ' ').trim();
};

