export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  globalX: number; // Distance from the right edge of the text block
  globalY: number; // Vertical distance from the top of the text block
}

// Cubic easing for smooth movement
const easeInOutCubic = (t: number): number => {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
};

/**
 * Calculates high-precision spatial and temporal metadata for the script.
 * Weights are tuned for Urdu speech patterns.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number
): { lines: string[][], words: WordMetadata[] } => {
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  const paragraphs = text.split('\n').map(p => p.trim());
  const wordsMetadata: WordMetadata[] = [];
  const lines: string[][] = [];

  // 1. Calculate relative timing weights
  let totalWeight = 0;
  paragraphs.forEach((p, pIdx) => {
    if (p === '') { totalWeight += 5; return; } // Pause for line breaks
    const words = p.split(/\s+/).filter(w => w.length > 0);
    words.forEach((w) => {
      // Base weight: character length + speech overhead
      totalWeight += w.length + 3; 
      // Punctuation adds significant pause time
      if (w.match(/[۔؟!،:]/)) totalWeight += 8;
      // Spaces add minor pause
      totalWeight += 1;
    });
    if (pIdx < paragraphs.length - 1) totalWeight += 10; // Paragraph breaks
  });

  if (totalWeight === 0) return { lines: [[]], words: [] };

  // 2. Map words to timing and space
  let weightCursor = 0;
  let lineIdx = 0;

  paragraphs.forEach((paragraph, pIdx) => {
    if (paragraph === '') {
      lines.push(['']);
      lineIdx++;
      weightCursor += 5;
      return;
    }

    const wordsInPara = paragraph.split(/\s+/).filter(w => w.length > 0);
    let currentLineWords: string[] = [];
    let currentLineWidth = 0;

    for (let n = 0; n < wordsInPara.length; n++) {
      const word = wordsInPara[n];
      const wordWidth = ctx.measureText(word).width;
      const spaceWidth = ctx.measureText(' ').width;
      const testWidth = currentLineWidth + (currentLineWords.length > 0 ? spaceWidth : 0) + wordWidth;

      // WRAP: If current line is too long, push to next
      if (testWidth > maxWidth && currentLineWords.length > 0) {
        lines.push(currentLineWords);
        lineIdx++;
        currentLineWords = [];
        currentLineWidth = 0;
      }

      const wordWeight = word.length + 3 + (word.match(/[۔؟!،:]/) ? 8 : 0);
      const start = weightCursor / totalWeight;
      weightCursor += wordWeight;
      const end = weightCursor / totalWeight;

      const xOffsetInLine = currentLineWidth + (currentLineWords.length > 0 ? spaceWidth : 0);

      wordsMetadata.push({
        text: word,
        start,
        end,
        width: wordWidth,
        lineIndex: lineIdx,
        globalX: xOffsetInLine + (wordWidth / 2),
        globalY: lineIdx * lineHeight
      });

      weightCursor += 1; // Account for space weight
      currentLineWords.push(word);
      currentLineWidth += (currentLineWords.length > 1 ? spaceWidth : 0) + wordWidth;
    }

    if (currentLineWords.length > 0) {
      lines.push(currentLineWords);
      lineIdx++;
    }

    if (pIdx < paragraphs.length - 1) weightCursor += 10;
  });

  return { lines, words: wordsMetadata };
};

/**
 * Main rendering loop for a single frame.
 */
export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  background: HTMLImageElement | HTMLVideoElement | null,
  text: string,
  progress: number,
  animationType: AnimationType = AnimationType.VERTICAL_SCROLL
) => {
  const ctx = canvas.getContext('2d', { alpha: false });
  if (!ctx) return;

  const width = canvas.width;
  const height = canvas.height;

  // 1. Background Rendering
  if (background) {
    const bw = background instanceof HTMLVideoElement ? background.videoWidth : background.width;
    const bh = background instanceof HTMLVideoElement ? background.videoHeight : background.height;
    if (bw > 0 && bh > 0) {
      const ba = bw / bh;
      const ca = width / height;
      let rw, rh, rx, ry;
      if (ba > ca) { rh = height; rw = height * ba; rx = (width - rw) / 2; ry = 0; }
      else { rw = width; rh = width / ba; rx = 0; ry = (height - rh) / 2; }
      ctx.drawImage(background, rx, ry, rw, rh);
    }
  } else {
    ctx.fillStyle = '#020617';
    ctx.fillRect(0, 0, width, height);
  }

  // Cinematic Gradient Mask
  const vignette = ctx.createRadialGradient(width/2, height/2, 0, width/2, height/2, height * 0.95);
  vignette.addColorStop(0, 'rgba(2, 6, 23, 0.3)');
  vignette.addColorStop(1, 'rgba(2, 6, 23, 0.9)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  // 2. Text Measurement
  const baseFontSize = width * 0.082;
  const maxWidth = width * 0.88;
  const lineHeight = baseFontSize * 2.9;

  ctx.direction = 'rtl';
  ctx.textBaseline = 'middle';
  ctx.textAlign = 'center';

  const { lines, words } = getWordMetadata(ctx, text, maxWidth, baseFontSize, lineHeight);
  if (words.length === 0) return;

  // 3. Smooth Camera Logic
  const activeIdx = words.findIndex(w => progress >= w.start && progress <= w.end);
  const currentWord = activeIdx !== -1 ? words[activeIdx] : (progress < words[0].start ? words[0] : words[words.length - 1]);

  // Calculate LERP target with cubic easing for word transitions
  const wordDur = currentWord.end - currentWord.start;
  const linearT = wordDur > 0 ? Math.max(0, Math.min(1, (progress - currentWord.start) / wordDur)) : 0;
  const easedT = easeInOutCubic(linearT);

  // Find next word for look-ahead
  const nextWord = words[activeIdx + 1] || currentWord;

  // Interpolate camera target coordinates
  const smoothX = currentWord.globalX + (nextWord.globalX - currentWord.globalX) * easedT;
  const smoothY = currentWord.globalY + (nextWord.globalY - currentWord.globalY) * easedT;

  const blockRightX = (width + maxWidth) / 2;

  // 4. Transform Camera Viewport
  ctx.save();

  let camOffsetX = 0;
  let camOffsetY = (height / 2) - smoothY;

  if (animationType === AnimationType.RIGHT_TO_LEFT) {
    camOffsetX = (width / 2) - (blockRightX - smoothX);
  } else if (animationType === AnimationType.LEFT_TO_RIGHT) {
    camOffsetX = -(width / 2) + (blockRightX - smoothX);
  }

  // 5. Draw Visible Multi-line Text
  lines.forEach((lineWords, lineIdx) => {
    const lineY = camOffsetY + (lineIdx * lineHeight);

    // Performance: Skip rendering lines far off-screen
    if (lineY < -lineHeight || lineY > height + lineHeight) return;

    // Start drawing from the right wall of the block
    let xCursor = blockRightX + camOffsetX;

    lineWords.forEach(wordText => {
      const wordW = ctx.measureText(wordText).width;
      const spaceW = ctx.measureText(' ').width;

      const drawX = xCursor - (wordW / 2);

      // Identify if this instance is currently spoken
      const isSpeaking = words.find(w => w.text === wordText && w.lineIndex === lineIdx && Math.abs(w.start - currentWord.start) < 0.0001);
      const isActive = isSpeaking === currentWord;

      ctx.save();
      if (isActive) {
        // PROFESSIONAL HIGHLIGHT: Vivid Gold with soft glow and subtle scale pulse
        ctx.fillStyle = '#fbbf24';
        ctx.shadowColor = 'rgba(251, 191, 36, 0.8)';
        ctx.shadowBlur = 35;

        // Use non-linear t for pulse emphasis
        const pulseScale = 1.12 + (Math.sin(linearT * Math.PI) * 0.06);
        ctx.translate(drawX, lineY);
        ctx.scale(pulseScale, pulseScale);
        ctx.translate(-drawX, -lineY);
      } else {
        // INACTIVE STYLE: Ghosted white with subtle depth
        ctx.fillStyle = 'white';
        ctx.globalAlpha = 0.28;
        ctx.shadowColor = 'black';
        ctx.shadowBlur = 8;
      }

      ctx.fillText(wordText, drawX, lineY);
      ctx.restore();

      xCursor -= (wordW + spaceW);
    });
  });

  ctx.restore();
};

import { AnimationType } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  globalX: number; // Horizontal center relative to the right edge of the text block
  globalY: number; // Vertical center relative to the top of the text block
}

/**
 * Cubic easing function for smooth interpolation.
 */
const easeInOutCubic = (t: number): number => {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
};

/**
 * Maps the script into a spatial and temporal timeline.
 * Tuning weights for Urdu: syllables are complex, so we use a mix of char length and word frequency.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number
): { lines: string[][], words: WordMetadata[] } => {
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  const paragraphs = text.split('\n').map(p => p.trim());
  const wordsMetadata: WordMetadata[] = [];
  const lines: string[][] = [];

  // Phase 1: Calculate temporal weights for each word/pause
  let totalWeight = 0;
  paragraphs.forEach((p, pIdx) => {
    if (p === '') {
      totalWeight += 10; // Significant pause for line breaks
      return;
    }
    const paragraphWords = p.split(/\s+/).filter(w => w.length > 0);
    paragraphWords.forEach((w) => {
      // Each word takes time proportional to length + base speech overhead
      totalWeight += 5 + (w.length * 1.5);
      // Punctuation adds varying amounts of pause
      if (w.match(/[۔؟!]/)) totalWeight += 25; // Full stop
      else if (w.match(/[،:]/)) totalWeight += 15; // Comma / Colon
    });
    if (pIdx < paragraphs.length - 1) totalWeight += 20; // Paragraph breaks
  });

  if (totalWeight === 0) return { lines: [[]], words: [] };

  // Phase 2: Map spatial positions and timing percentages
  let weightCursor = 0;
  let currentLineIdx = 0;

  paragraphs.forEach((paragraph, pIdx) => {
    if (paragraph === '') {
      lines.push(['']);
      currentLineIdx++;
      weightCursor += 10;
      return;
    }

    const wordsInPara = paragraph.split(/\s+/).filter(w => w.length > 0);
    let currentLineWords: string[] = [];
    let currentLineWidth = 0;

    for (let i = 0; i < wordsInPara.length; i++) {
      const word = wordsInPara[i];
      const wordWidth = ctx.measureText(word).width;
      const spaceWidth = ctx.measureText(' ').width;
      const testWidth = currentLineWidth + (currentLineWords.length > 0 ? spaceWidth : 0) + wordWidth;

      // WRAP LOGIC: If the word exceeds line width, start a new line
      if (testWidth > maxWidth && currentLineWords.length > 0) {
        lines.push(currentLineWords);
        currentLineIdx++;
        currentLineWords = [];
        currentLineWidth = 0;
      }

      const wordWeight = 5 + (word.length * 1.5) + (word.match(/[۔؟!]/) ? 25 : (word.match(/[،:]/) ? 15 : 0));
      const start = weightCursor / totalWeight;
      weightCursor += wordWeight;
      const end = weightCursor / totalWeight;

      const xOffsetInLine = currentLineWidth + (currentLineWords.length > 0 ? spaceWidth : 0);

      wordsMetadata.push({
        text: word,
        start,
        end,
        width: wordWidth,
        lineIndex: currentLineIdx,
        globalX: xOffsetInLine + (wordWidth / 2),
        globalY: currentLineIdx * lineHeight
      });

      weightCursor += 2; // Small pause between every word
      currentLineWords.push(word);
      currentLineWidth += (currentLineWords.length > 1 ? spaceWidth : 0) + wordWidth;
    }

    if (currentLineWords.length > 0) {
      lines.push(currentLineWords);
      currentLineIdx++;
    }

    if (pIdx < paragraphs.length - 1) weightCursor += 20;
  });

  return { lines, words: wordsMetadata };
};

/**
 * Renders the frame for the current progress point.
 */
export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  background: HTMLImageElement | HTMLVideoElement | null,
  text: string,
  progress: number,
  animationType: AnimationType = AnimationType.VERTICAL_SCROLL
) => {
  const ctx = canvas.getContext('2d', { alpha: false });
  if (!ctx) return;

  const width = canvas.width;
  const height = canvas.height;

  // 1. Render Background with Fill-and-Crop logic
  if (background) {
    const bgW = background instanceof HTMLVideoElement ? background.videoWidth : background.width;
    const bgH = background instanceof HTMLVideoElement ? background.videoHeight : background.height;
    if (bgW > 0 && bgH > 0) {
      const bgRatio = bgW / bgH;
      const canvasRatio = width / height;
      let drawW, drawH, drawX, drawY;
      if (bgRatio > canvasRatio) { 
        drawH = height; drawW = height * bgRatio; drawX = (width - drawW) / 2; drawY = 0; 
      } else { 
        drawW = width; drawH = width / bgRatio; drawX = 0; drawY = (height - drawH) / 2; 
      }
      ctx.drawImage(background, drawX, drawY, drawW, drawH);
    }
  } else {
    ctx.fillStyle = '#020617';
    ctx.fillRect(0, 0, width, height);
  }

  // Cinematic Vignette and Darkening
  const grad = ctx.createRadialGradient(width/2, height/2, 0, width/2, height/2, height * 1.1);
  grad.addColorStop(0, 'rgba(2, 6, 23, 0.4)');
  grad.addColorStop(1, 'rgba(2, 6, 23, 0.9)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);

  // 2. Setup Typography
  const baseFontSize = width * 0.08;
  const maxWidth = width * 0.88;
  const lineHeight = baseFontSize * 3.0; // Increased spacing for Urdu Nastaliq

  ctx.direction = 'rtl';
  ctx.textBaseline = 'middle';
  ctx.textAlign = 'center';

  const { lines, words } = getWordMetadata(ctx, text, maxWidth, baseFontSize, lineHeight);
  if (words.length === 0) return;

  // 3. Smooth Camera and Timing Logic
  const activeIdx = words.findIndex(w => progress >= w.start && progress <= w.end);
  const currentWord = activeIdx !== -1 ? words[activeIdx] : (progress < words[0].start ? words[0] : words[words.length - 1]);
  const nextWord = words[activeIdx + 1] || currentWord;

  const wordDuration = currentWord.end - currentWord.start;
  const linearProgress = wordDuration > 0 ? Math.max(0, Math.min(1, (progress - currentWord.start) / wordDuration)) : 0;
  const easedProgress = easeInOutCubic(linearProgress);

  // Interpolate camera coordinates for perfectly smooth follow
  const smoothX = currentWord.globalX + (nextWord.globalX - currentWord.globalX) * easedProgress;
  const smoothY = currentWord.globalY + (nextWord.globalY - currentWord.globalY) * easedProgress;

  const blockRightBoundary = (width + maxWidth) / 2;

  // 4. Viewport Transforms
  ctx.save();

  let viewportX = 0;
  let viewportY = (height / 2) - smoothY;

  if (animationType === AnimationType.RIGHT_TO_LEFT) {
    viewportX = (width / 2) - (blockRightBoundary - smoothX);
  } else if (animationType === AnimationType.LEFT_TO_RIGHT) {
    viewportX = -(width / 2) + (blockRightBoundary - smoothX);
  }

  // 5. Drawing Loop
  lines.forEach((lineWords, lineIdx) => {
    const lineY = viewportY + (lineIdx * lineHeight);

    // Frustum Culling
    if (lineY < -lineHeight * 2 || lineY > height + lineHeight * 2) return;

    let cursorX = blockRightBoundary + viewportX;

    lineWords.forEach(wordText => {
      const wordW = ctx.measureText(wordText).width;
      const spaceW = ctx.measureText(' ').width;

      const drawX = cursorX - (wordW / 2);

      const isSpeaking = words.find(w => w.text === wordText && w.lineIndex === lineIdx && Math.abs(w.start - currentWord.start) < 0.0001);
      const isActive = isSpeaking === currentWord;

      ctx.save();
      if (isActive) {
        // HIGHLIGHT: Warm Amber, soft glow, and cinematic pulse
        ctx.fillStyle = '#fbbf24';
        ctx.shadowColor = 'rgba(251, 191, 36, 0.9)';
        ctx.shadowBlur = 40;

        const scale = 1.15 + (Math.sin(linearProgress * Math.PI) * 0.08);
        ctx.translate(drawX, lineY);
        ctx.scale(scale, scale);
        ctx.translate(-drawX, -lineY);
      } else {
        // NORMAL: Crisp white with low opacity to focus viewer on active text
        ctx.fillStyle = 'white';
        ctx.globalAlpha = progress > (isSpeaking?.end || 0) ? 0.35 : 0.25; 
        ctx.shadowColor = 'black';
        ctx.shadowBlur = 10;
      }

      ctx.fillText(wordText, drawX, lineY);
      ctx.restore();

      cursorX -= (wordW + spaceW);
    });
  });

  ctx.restore();
};

import { GoogleGenAI, Modality, Type } from "@google/genai";
import { VoiceName, SEOMetadata } from "../types";

const safetySettings = [
  { category: "HARM_CATEGORY_HARASSMENT", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_HATE_SPEECH", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_SEXUALLY_EXPLICIT", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_DANGEROUS_CONTENT", threshold: "BLOCK_NONE" },
];

/**
 * Progressively sanitizes text to bypass strict safety and recitation blocks.
 * Level 4 is extreme: it removes all punctuation and potentially sensitive nouns.
 */
const sanitizeForTTS = (text: string, level: number = 0): string => {
  let sanitized = text;

  // Level 0: Essential cleaning
  sanitized = sanitized.replace(/[\u{1F000}-\u{1F9FF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B50}\u{2B55}]/gu, '');

  if (level >= 1) {
    // Level 1: Replace honorifics and specific triggers
    sanitized = sanitized
      .replace(/\uFDFA/g, ' ') 
      .replace(/[\u0610-\u0613]/g, '')
      .replace(/آیت الکرسی/g, 'تحریر') 
      .replace(/صحیح البخاری/g, 'کتاب')
      .replace(/قرآن/g, 'کتاب')
      .replace(/حدیث/g, 'قول')
      .replace(/اللہ/g, 'خدا');
  }

  if (level >= 2) {
    // Level 2: Strip all Diacritics
    sanitized = sanitized.replace(/[\u064B-\u0652\u0670]/g, '');
  }

  if (level >= 3) {
    // Level 3: Keep ONLY base Urdu characters and spaces
    sanitized = sanitized.replace(/[^\u0600-\u06FF\s]/g, ' ');
  }

  return sanitized.replace(/\s+/g, ' ').trim();
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Strict instructional prompt to prevent the AI from generating an "explanation" or "answer".
 */
const getTTSPrompt = (text: string): string => {
  return `Act as a simple Text-to-Speech tool. 
Do not answer the text below. Do not analyze it. 
Your only output must be the audio of you reading this text exactly: 
"${text}"`;
};

export const generateNarration = async (text: string, voice: VoiceName, retryCount = 0): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const cleanText = sanitizeForTTS(text, retryCount);

  if (!cleanText) {
    throw new Error("Text is empty after sanitization.");
  }

  console.log(`TTS Generation Attempt ${retryCount + 1} (Sanitization Level ${retryCount})`);

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ 
        parts: [{ 
          text: getTTSPrompt(cleanText)
        }] 
      }],
      config: {
        responseModalities: [Modality.AUDIO], 
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voice },
          },
        },
        safetySettings: safetySettings as any,
      },
    });

    if (!response.candidates || response.candidates.length === 0) {
      throw new Error("No response candidates from AI.");
    }

    const candidate = response.candidates[0];

    // Check for finishReason issues
    if (candidate.finishReason && candidate.finishReason !== 'STOP') {
      if (retryCount < 3) {
        console.warn(`Content block (${candidate.finishReason}). Retrying with higher sanitization...`);
        await delay(1200 * (retryCount + 1));
        return generateNarration(text, voice, retryCount + 1);
      }
      throw new Error(`Narration restricted: ${candidate.finishReason}. Content may trigger safety or recitation policies.`);
    }

    const audioPart = candidate.content?.parts?.find(p => p.inlineData?.data);
    if (audioPart?.inlineData?.data) {
      return audioPart.inlineData.data;
    }

    throw new Error("Audio data not found in response.");

  } catch (error: any) {
    const errorString = error.message || "";

    // Catch the specific 'non-audio response' or 400 error and trigger a retry
    const isRetryable = errorString.includes("400") || 
                        errorString.includes("non-audio") || 
                        errorString.includes("INVALID_ARGUMENT") ||
                        errorString.includes("Rpc");

    if (isRetryable && retryCount < 3) {
      console.warn(`Caught non-audio/protocol error. Retrying with Sanitization Level ${retryCount + 1}...`);
      await delay(2000);
      return generateNarration(text, voice, retryCount + 1);
    }
    throw error;
  }
};

