import { AnimationType } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  globalX: number; 
  globalY: number; 
}

/**
 * Cubic easing for smooth cinematic transitions.
 */
const easeInOutCubic = (t: number): number => {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
};

/**
 * Calculates temporal and spatial metadata for the script.
 * Finely tuned for Urdu speech rhythm and Nastaliq rendering bounds.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number
): { lines: string[][], words: WordMetadata[] } => {
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  const paragraphs = text.split('\n').map(p => p.trim());
  const wordsMetadata: WordMetadata[] = [];
  const lines: string[][] = [];

  // 1. Precise timing weight calculation
  let totalWeight = 0;
  paragraphs.forEach((p, pIdx) => {
    if (p === '') {
      totalWeight += 15; // Paragraph break pause
      return;
    }
    const wordsInPara = p.split(/\s+/).filter(w => w.length > 0);
    wordsInPara.forEach((w) => {
      // Base speech duration weight
      totalWeight += 7 + (w.length * 2);
      // Extra weight for long Urdu clusters
      if (w.length > 5) totalWeight += 4;

      // Punctuation pause weights
      if (w.match(/[۔؟!]/)) totalWeight += 35; // Major stop
      else if (w.match(/[،:]/)) totalWeight += 22; // Breath pause
    });
    if (pIdx < paragraphs.length - 1) totalWeight += 30; 
  });

  if (totalWeight === 0) return { lines: [[]], words: [] };

  // 2. Spatial and temporal mapping
  let weightCursor = 0;
  let currentLineIdx = 0;

  paragraphs.forEach((paragraph, pIdx) => {
    if (paragraph === '') {
      lines.push(['']);
      currentLineIdx++;
      weightCursor += 15;
      return;
    }

    const wordsInPara = paragraph.split(/\s+/).filter(w => w.length > 0);
    let currentLineWords: string[] = [];
    let currentLineWidth = 0;
    const spaceWidth = ctx.measureText(' ').width;

    for (let i = 0; i < wordsInPara.length; i++) {
      const word = wordsInPara[i];
      const wordWidth = ctx.measureText(word).width;

      if (currentLineWidth + wordWidth > maxWidth && currentLineWords.length > 0) {
        lines.push(currentLineWords);
        currentLineWords = [];
        currentLineWidth = 0;
        currentLineIdx++;
      }

      const wordWeight = 7 + (word.length * 2) + (word.length > 5 ? 4 : 0);
      let pauseWeight = 0;
      if (word.match(/[۔؟!]/)) pauseWeight = 35;
      else if (word.match(/[،:]/)) pauseWeight = 22;

      const startTime = weightCursor / totalWeight;
      weightCursor += wordWeight;
      const midTime = weightCursor / totalWeight;
      weightCursor += pauseWeight;
      const endTime = weightCursor / totalWeight;

      wordsMetadata.push({
        text: word,
        start: startTime,
        end: endTime,
        width: wordWidth,
        lineIndex: currentLineIdx,
        globalX: 0,
        globalY: 0
      });

      currentLineWords.push(word);
      currentLineWidth += wordWidth + spaceWidth;
    }

    if (currentLineWords.length > 0) {
      lines.push(currentLineWords);
      currentLineIdx++;
    }
    weightCursor += 30; // Paragraph end pause
  });

  return { lines, words: wordsMetadata };
};

/**
 * Renders a single frame of the video with animated text and background.
 */
export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  bg: HTMLImageElement | HTMLVideoElement | null,
  text: string,
  progress: number,
  animationType: AnimationType
) => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;

  const { width, height } = canvas;

  // 1. Clear and Draw Background
  ctx.fillStyle = '#020617';
  ctx.fillRect(0, 0, width, height);

  if (bg) {
    let bgWidth = 0;
    let bgHeight = 0;

    if (bg instanceof HTMLVideoElement) {
        bgWidth = bg.videoWidth;
        bgHeight = bg.videoHeight;
    } else {
        bgWidth = bg.width;
        bgHeight = bg.height;
    }

    if (bgWidth > 0 && bgHeight > 0) {
        const scale = Math.max(width / bgWidth, height / bgHeight);
        const x = (width - bgWidth * scale) / 2;
        const y = (height - bgHeight * scale) / 2;

        ctx.globalAlpha = 0.6;
        ctx.drawImage(bg, x, y, bgWidth * scale, bgHeight * scale);
        ctx.globalAlpha = 1.0;
    }
  }

  // Visual overlay for atmospheric depth
  const gradient = ctx.createLinearGradient(0, 0, 0, height);
  gradient.addColorStop(0, 'rgba(2, 6, 23, 0.4)');
  gradient.addColorStop(0.5, 'rgba(2, 6, 23, 0.1)');
  gradient.addColorStop(1, 'rgba(2, 6, 23, 0.7)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, width, height);

  // 2. Setup Text Styling
  const baseFontSize = width * 0.055;
  const lineHeight = baseFontSize * 1.8;
  const maxWidth = width * 0.85;
  const { lines, words } = getWordMetadata(ctx, text, maxWidth, baseFontSize, lineHeight);

  if (lines.length === 0) return;

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.direction = 'rtl';
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // 3. Animation and Positioning Logic
  const totalContentHeight = lines.length * lineHeight;
  const viewportHeight = height * 0.6;
  const startY = height * 0.2;
  let scrollOffset = 0;

  if (animationType === AnimationType.VERTICAL_SCROLL) {
    const scrollRange = Math.max(0, totalContentHeight - viewportHeight);
    scrollOffset = scrollRange * easeInOutCubic(progress);
  }

  // 4. Render each line
  lines.forEach((lineWords, lineIdx) => {
    const lineBaseY = startY + (lineIdx * lineHeight) - scrollOffset;

    // Viewport Culling
    if (lineBaseY < -lineHeight || lineBaseY > height + lineHeight) return;

    let xOffset = 0;
    if (animationType === AnimationType.LEFT_TO_RIGHT) {
        xOffset = (progress * width * 0.4) - (width * 0.2);
    } else if (animationType === AnimationType.RIGHT_TO_LEFT) {
        xOffset = -(progress * width * 0.4) + (width * 0.2);
    }

    const centerX = width / 2 + xOffset;
    const lineText = lineWords.join(' ');

    // Highlight evaluation
    const activeWordsInLine = words.filter(w => w.lineIndex === lineIdx && progress >= w.start && progress <= w.end);
    const isLineActive = activeWordsInLine.length > 0;

    // Draw base text with soft shadow
    ctx.shadowBlur = 15;
    ctx.shadowColor = 'rgba(0, 0, 0, 0.4)';
    ctx.fillStyle = isLineActive ? 'rgba(255, 255, 255, 0.95)' : 'rgba(255, 255, 255, 0.6)';
    ctx.fillText(lineText, centerX, lineBaseY);
    ctx.shadowBlur = 0;

    // If active, add a golden glow effect
    if (isLineActive) {
      ctx.save();
      ctx.translate(centerX, lineBaseY);
      const activeWord = activeWordsInLine[0];
      const p = (progress - activeWord.start) / (activeWord.end - activeWord.start);
      const pulse = 1 + (0.02 * Math.sin(p * Math.PI));
      ctx.scale(pulse, pulse);

      ctx.shadowBlur = 25;
      ctx.shadowColor = 'rgba(234, 179, 8, 0.6)';
      ctx.fillStyle = '#fbbf24'; // text-yellow-400
      ctx.fillText(lineText, 0, 0);
      ctx.restore();
    }
  });

  // Footer Branding
  ctx.font = `bold ${width * 0.015}px Inter, sans-serif`;
  ctx.fillStyle = 'rgba(255, 255, 255, 0.25)';
  ctx.textAlign = 'center';
  ctx.fillText('N O O R   S T U D I O   •   A I   G E N E R A T E D', width / 2, height * 0.96);
};

