      .replace(/صلی اللہ علیہ وآلہ وسلم/g, ' ');
  }

  if (level >= 2) {
    // Level 2: Strip all Diacritics (Aeraab) which often trigger recitation filters
    sanitized = sanitized.replace(/[\u064B-\u0652\u0670]/g, '');
  }

  if (level >= 3) {
    // Level 3: Keep ONLY base Urdu characters and spaces (Remove punctuation)
    sanitized = sanitized.replace(/[^\u0600-\u06FF\s]/g, ' ');
  }

  if (level >= 4) {
    // Level 4: Neutralize any remaining high-sensitivity religious vocabulary
    sanitized = sanitized
      .replace(/شیطان/g, 'برائی')
      .replace(/حفاظت/g, 'امن')
      .replace(/عمل/g, 'کام')
      .replace(/شر/g, 'نقصان');
  }

  return sanitized.replace(/\s+/g, ' ').trim();
};

