  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const cleanText = sanitizeForTTS(text, retryCount);

  if (!cleanText) {
    throw new Error("Text is empty after sanitization.");
  }

  console.log(`TTS Generation Attempt ${retryCount + 1} (Sanitization Level ${retryCount})`);

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ 
        parts: [{ 
          text: getTTSPrompt(cleanText, retryCount)
        }] 
      }],
      config: {
