import { AnimationType } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  globalX: number; // Center of the word relative to the line's right edge
  globalY: number; // Center of the word vertically
}

/**
 * Cubic easing for smooth cinematic transitions.
 */
const easeInOutCubic = (t: number): number => {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
};

/**
 * Calculates temporal and spatial metadata for the script.
 * Finely tuned for Urdu speech rhythm and Nastaliq rendering bounds.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number
): { lines: string[][], words: WordMetadata[] } => {
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  const paragraphs = text.split('\n').map(p => p.trim());
  const wordsMetadata: WordMetadata[] = [];
  const lines: string[][] = [];

  let totalWeight = 0;
  paragraphs.forEach((p) => {
    if (p === '') { totalWeight += 15; return; }
    const wordsInPara = p.split(/\s+/).filter(w => w.length > 0);
    wordsInPara.forEach((w) => {
      totalWeight += 8 + (w.length * 2.2);
      if (w.match(/[۔؟!]/)) totalWeight += 35;
      else if (w.match(/[،:]/)) totalWeight += 22;
    });
    totalWeight += 25; 
  });

  if (totalWeight === 0) return { lines: [[]], words: [] };

  let weightCursor = 0;
  let currentLineIdx = 0;

  paragraphs.forEach((paragraph) => {
    if (paragraph === '') {
      lines.push(['']);
      currentLineIdx++;
      weightCursor += 15;
      return;
    }

    const wordsInPara = paragraph.split(/\s+/).filter(w => w.length > 0);
    let currentLineWords: string[] = [];
    let currentLineWidth = 0;
    const spaceWidth = ctx.measureText(' ').width;

    for (let i = 0; i < wordsInPara.length; i++) {
      const word = wordsInPara[i];
      const wordWidth = ctx.measureText(word).width;

      // Line wrap logic
      if (currentLineWidth + wordWidth > maxWidth && currentLineWords.length > 0) {
        lines.push(currentLineWords);
        currentLineWords = [];
        currentLineWidth = 0;
        currentLineIdx++;
      }

      const wordWeight = 8 + (word.length * 2.2);
      const startTime = weightCursor / totalWeight;
      weightCursor += wordWeight;
      const endTime = weightCursor / totalWeight;

      // Important: globalX is distance from the RIGHT edge of the text block
      const xPosInLine = currentLineWidth + (wordWidth / 2);

      wordsMetadata.push({
        text: word,
        start: startTime,
        end: endTime,
        width: wordWidth,
        lineIndex: currentLineIdx,
        globalX: xPosInLine,
        globalY: currentLineIdx * lineHeight
      });

      // Add punctuation pause to timing
      if (word.match(/[۔؟!]/)) weightCursor += 35;
      else if (word.match(/[،:]/)) weightCursor += 22;

      currentLineWords.push(word);
      currentLineWidth += wordWidth + spaceWidth;
    }

    if (currentLineWords.length > 0) {
      lines.push(currentLineWords);
      currentLineIdx++;
    }
    weightCursor += 25;
  });

  return { lines, words: wordsMetadata };
};

/**
 * Renders a single frame with a word-tracking camera.
 */
export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  bg: HTMLImageElement | HTMLVideoElement | null,
  text: string,
  progress: number,
  animationType: AnimationType
) => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;

  const { width, height } = canvas;

  // 1. Draw Background
  ctx.fillStyle = '#020617';
  ctx.fillRect(0, 0, width, height);

  if (bg) {
    const bgW = bg instanceof HTMLVideoElement ? bg.videoWidth : bg.width;
    const bgH = bg instanceof HTMLVideoElement ? bg.videoHeight : bg.height;
    if (bgW > 0) {
      const scale = Math.max(width / bgW, height / bgH);
      ctx.globalAlpha = 0.5;
      ctx.drawImage(bg, (width - bgW * scale) / 2, (height - bgH * scale) / 2, bgW * scale, bgH * scale);
      ctx.globalAlpha = 1.0;
    }
  }

  // Vignette for focus
  const grad = ctx.createRadialGradient(width/2, height/2, 0, width/2, height/2, height);
  grad.addColorStop(0, 'transparent');
  grad.addColorStop(1, 'rgba(2, 6, 23, 0.8)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);

  // 2. Setup Typography
  const baseFontSize = width * 0.07;
  const lineHeight = baseFontSize * 2.2;
  const maxWidth = width * 0.85;
  const { lines, words } = getWordMetadata(ctx, text, maxWidth, baseFontSize, lineHeight);

  if (words.length === 0) return;

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.direction = 'rtl';
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // 3. Camera Logic: Find the target focus point
  const activeIdx = words.findIndex(w => progress >= w.start && progress <= w.end);
  const currentWord = activeIdx !== -1 ? words[activeIdx] : (progress < words[0].start ? words[0] : words[words.length - 1]);

  // Interpolate camera for ultra-smooth focus transition
  const nextWord = words[activeIdx + 1] || currentWord;
  const wordDuration = currentWord.end - currentWord.start;
  const wordProgress = wordDuration > 0 ? (progress - currentWord.start) / wordDuration : 0;
  const easedInner = easeInOutCubic(Math.min(1, wordProgress * 1.5)); // Faster transition start

  const targetCamX = currentWord.globalX + (nextWord.globalX - currentWord.globalX) * easedInner;
  const targetCamY = currentWord.globalY + (nextWord.globalY - currentWord.globalY) * easedInner;

  // Final viewport calculation based on mode
  let viewportX = width / 2;
  let viewportY = height / 2 - targetCamY;

  if (animationType === AnimationType.RIGHT_TO_LEFT) {
    // In RTL, words start from right. TrackingCam centers them.
    // globalX is from right, so we offset the center by (maxWidth/2 - targetCamX)
    viewportX = (width / 2) + (maxWidth / 2 - targetCamX);
  } else if (animationType === AnimationType.LEFT_TO_RIGHT) {
    viewportX = (width / 2) - (maxWidth / 2 - targetCamX);
  } else {
    // Vertical scroll stays horizontally centered
    viewportX = width / 2;
  }

  // 4. Drawing Loop
  lines.forEach((lineWords, lineIdx) => {
    const lineY = viewportY + (lineIdx * lineHeight);

    // Frustum Culling
    if (lineY < -lineHeight || lineY > height + lineHeight) return;

    // Draw lines relative to current viewport focus
    const lineText = lineWords.join(' ');
    const isLineActive = words.some(w => w.lineIndex === lineIdx && progress >= w.start && progress <= w.end);

    ctx.save();
    if (isLineActive) {
      // Background glow for active line
      ctx.shadowBlur = 30;
      ctx.shadowColor = 'rgba(234, 179, 8, 0.2)';
      ctx.fillStyle = 'white';

      // Highlight the active word specifically within the line
      const activeWord = words.find(w => w.lineIndex === lineIdx && progress >= w.start && progress <= w.end);
      if (activeWord) {
        // Draw the line once normally, then overlay the pulse on the word (simplified for performance)
        ctx.globalAlpha = 0.5;
        ctx.fillText(lineText, viewportX, lineY);
        ctx.globalAlpha = 1.0;
        ctx.fillStyle = '#fbbf24';

        // Dynamic pulse for the active line
        const pulse = 1 + 0.03 * Math.sin(progress * Math.PI * 10);
        ctx.translate(viewportX, lineY);
        ctx.scale(pulse, pulse);
        ctx.fillText(lineText, 0, 0);
      } else {
        ctx.fillText(lineText, viewportX, lineY);
      }
    } else {
      ctx.globalAlpha = 0.25;
      ctx.fillStyle = 'white';
      ctx.fillText(lineText, viewportX, lineY);
    }
    ctx.restore();
  });

  // Footer
  ctx.globalAlpha = 0.3;
  ctx.font = `bold ${width * 0.02}px Inter, sans-serif`;
  ctx.fillStyle = 'white';
  ctx.fillText('NOOR STUDIO AI', width / 2, height * 0.95);
};

