      else if (w.match(/[،:]/)) totalWeight += 22;
    });
    totalWeight += 25; 
  });

  if (totalWeight === 0) return { lines: [[]], words: [] };

  let weightCursor = 0;
  let currentLineIdx = 0;
  const spaceWidth = ctx.measureText(' ').width;

  paragraphs.forEach((paragraph) => {
    if (paragraph === '') {
      lines.push(['']);
      currentLineIdx++;
      weightCursor += 15;
      return;
    }

    const wordsInPara = paragraph.split(/\s+/).filter(w => w.length > 0);
    let currentLineWords: string[] = [];
    let currentLineWidth = 0;
    let lineStartWordIdx = wordsMetadata.length;

    for (let i = 0; i < wordsInPara.length; i++) {
      const word = wordsInPara[i];
      const wordWidth = ctx.measureText(word).width;

      // Line wrap logic
      if (currentLineWidth + wordWidth > maxWidth && currentLineWords.length > 0) {
        // Finalize previous line's relativeX
        finalizeLineOffsets(wordsMetadata, lineStartWordIdx, currentLineWidth - spaceWidth, true);

        lines.push(currentLineWords);
        currentLineWords = [];
        currentLineWidth = 0;
        currentLineIdx++;
        lineStartWordIdx = wordsMetadata.length;
      }

      const wordWeight = 8 + (word.length * 2.2);
      const startTime = weightCursor / totalWeight;
      weightCursor += wordWeight;
      const endTime = weightCursor / totalWeight;

      // Store word with its cumulative width offset for now
      wordsMetadata.push({
        text: word,
        start: startTime,
        end: endTime,
        width: wordWidth,
        lineIndex: currentLineIdx,
        relativeX: currentLineWidth, // Temporary: distance from line start
        globalY: currentLineIdx * lineHeight
      });

      if (word.match(/[۔؟!]/)) weightCursor += 35;
      else if (word.match(/[،:]/)) weightCursor += 22;

      currentLineWords.push(word);
      currentLineWidth += wordWidth + spaceWidth;
    }

    if (currentLineWords.length > 0) {
      finalizeLineOffsets(wordsMetadata, lineStartWordIdx, currentLineWidth - spaceWidth, true);
      lines.push(currentLineWords);
      currentLineIdx++;
    }
    weightCursor += 25;
  });

  return { lines, words: wordsMetadata };
};

/**
 * Converts temporary cumulative width offsets into centered relative coordinates.
 */
function finalizeLineOffsets(words: WordMetadata[], startIdx: number, totalWidth: number, isRTL: boolean) {
  for (let i = startIdx; i < words.length; i++) {
    const word = words[i];
    if (isRTL) {
      // In RTL, first word is on the right. 
      // relativeX = (TotalLineHalf) - (DistFromStart + WordHalf)
      word.relativeX = (totalWidth / 2) - (word.relativeX + word.width / 2);
    } else {
      // In LTR, first word is on the left.
      // relativeX = -(TotalLineHalf) + (DistFromStart + WordHalf)
      word.relativeX = -(totalWidth / 2) + (word.relativeX + word.width / 2);
    }
  }
}

/**
 * Renders a single frame with line-anchoring and per-word highlighting.
 */
export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  bg: HTMLImageElement | HTMLVideoElement | null,
  text: string,
  progress: number,
  animationType: AnimationType
) => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;

  const { width, height } = canvas;

  // 1. Draw Background
  ctx.fillStyle = '#020617';
  ctx.fillRect(0, 0, width, height);

  if (bg) {
    const bgW = bg instanceof HTMLVideoElement ? bg.videoWidth : bg.width;
    const bgH = bg instanceof HTMLVideoElement ? bg.videoHeight : bg.height;
    if (bgW > 0) {
      const scale = Math.max(width / bgW, height / bgH);
      ctx.globalAlpha = 0.5;
      ctx.drawImage(bg, (width - bgW * scale) / 2, (height - bgH * scale) / 2, bgW * scale, bgH * scale);
      ctx.globalAlpha = 1.0;
    }
  }

  // Cinematic Vignette
  const grad = ctx.createRadialGradient(width/2, height/2, 0, width/2, height/2, height);
  grad.addColorStop(0, 'transparent');
  grad.addColorStop(1, 'rgba(2, 6, 23, 0.9)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);

  // 2. Setup Typography
  const baseFontSize = width * 0.075;
  const lineHeight = baseFontSize * 2.2;
  const maxWidth = width * 0.85;
  const { lines, words } = getWordMetadata(ctx, text, maxWidth, baseFontSize, lineHeight);

  if (words.length === 0) return;

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.direction = 'rtl';
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // 3. Camera Positioning
  const activeIdx = words.findIndex(w => progress >= w.start && progress <= w.end);
  const currentWord = activeIdx !== -1 ? words[activeIdx] : (progress < words[0].start ? words[0] : words[words.length - 1]);

  const currentLineIdx = currentWord.lineIndex;
  const lineWordsMetadata = words.filter(w => w.lineIndex === currentLineIdx);
  const lineStartTime = lineWordsMetadata[0].start;
  const lineEndTime = lineWordsMetadata[lineWordsMetadata.length - 1].end;

  const lineDuration = lineEndTime - lineStartTime;
  const timeIntoLine = progress - lineStartTime;

  // Transition window for movement between lines (reduced to 10% for more stability)
  const transitionTime = lineDuration * 0.1;
  let lineEased = 0.5; 

  if (timeIntoLine < transitionTime) {
    lineEased = easeInOutCubic(timeIntoLine / transitionTime) * 0.5;
  } else if (lineEndTime - progress < transitionTime) {
    lineEased = 0.5 + easeInOutCubic(1 - (lineEndTime - progress) / transitionTime) * 0.5;
  } else {
    // LOCK POSITION: The line stays perfectly still while voice is active
    lineEased = 0.5;
  }

  const targetCamY = currentWord.globalY;
  let viewportX = width / 2;
  let viewportY = height / 2 - targetCamY;

  if (animationType === AnimationType.RIGHT_TO_LEFT) {
    const horizontalOffset = (0.5 - lineEased) * (width * 1.5);
    viewportX = (width / 2) + horizontalOffset;
  } else if (animationType === AnimationType.LEFT_TO_RIGHT) {
    const horizontalOffset = (lineEased - 0.5) * (width * 1.5);
    viewportX = (width / 2) + horizontalOffset;
  } else {
    viewportX = width / 2;
  }

  // 4. Render Logic
  lines.forEach((lineTextArray, lineIdx) => {
    const lineY = viewportY + (lineIdx * lineHeight);
    if (lineY < -lineHeight || lineY > height + lineHeight) return;

    const isLineActive = currentLineIdx === lineIdx;

    if (isLineActive) {
      // For active lines, we render word-by-word to allow per-word highlighting
      const activeLineWords = words.filter(w => w.lineIndex === lineIdx);

      activeLineWords.forEach(w => {
        const isWordActive = progress >= w.start && progress <= w.end;

        ctx.save();
        ctx.translate(viewportX + w.relativeX, lineY);

        if (isWordActive) {
          // ACTIVE WORD HIGHLIGHT
          ctx.shadowBlur = 45;
          ctx.shadowColor = 'rgba(251, 191, 36, 0.4)';
          ctx.fillStyle = '#fbbf24'; // Vivid Amber

          // Slight pulse effect only on the active word
          const pulse = 1 + 0.04 * Math.sin(progress * Math.PI * 15);
          ctx.scale(pulse, pulse);
        } else {
          // INACTIVE WORD IN ACTIVE LINE
          ctx.globalAlpha = 0.4;
          ctx.fillStyle = 'white';
        }

        ctx.fillText(w.text, 0, 0);
        ctx.restore();
      });
    } else {
      // For background lines, render as a single string for performance
      ctx.save();
      ctx.globalAlpha = 0.15;
      ctx.fillStyle = 'white';
      ctx.fillText(lineTextArray.join(' '), viewportX, lineY);
      ctx.restore();
    }
  });

  // Footer Branding
  ctx.globalAlpha = 0.2;
  ctx.font = `bold ${width * 0.018}px Inter, sans-serif`;
  ctx.fillStyle = 'white';
  ctx.fillText('NOOR STUDIO AI • CINEMATIC URDU', width / 2, height * 0.96);
};

