      lines.push(currentLineWords);
      currentLineIdx++;
    }
    weightCursor += 30;
  });

  return { lines, words: wordsMetadata };
};

function finalizeLineOffsets(words: WordMetadata[], startIdx: number, totalWidth: number, isRTL: boolean) {
  for (let i = startIdx; i < words.length; i++) {
    const word = words[i];
    if (isRTL) {
      word.relativeX = (totalWidth / 2) - (word.relativeX + word.width / 2);
    } else {
      word.relativeX = -(totalWidth / 2) + (word.relativeX + word.width / 2);
    }
  }
}

/**
 * Renders the video frame with high-stability motion and moving word spotlight.
 */
export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  bg: HTMLImageElement | HTMLVideoElement | null,
  text: string,
  progress: number,
  animationType: AnimationType
) => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;

  const { width, height } = canvas;

  // 1. Background Layer
  ctx.fillStyle = '#020617';
  ctx.fillRect(0, 0, width, height);

  if (bg) {
    const bgW = bg instanceof HTMLVideoElement ? bg.videoWidth : bg.width;
    const bgH = bg instanceof HTMLVideoElement ? bg.videoHeight : bg.height;
    if (bgW > 0) {
      const scale = Math.max(width / bgW, height / bgH);
      ctx.globalAlpha = 0.45;
      ctx.drawImage(bg, (width - bgW * scale) / 2, (height - bgH * scale) / 2, bgW * scale, bgH * scale);
      ctx.globalAlpha = 1.0;
    }
  }

  // Deep shadow overlay for legibility
  const grad = ctx.createRadialGradient(width/2, height/2, 0, width/2, height/2, height * 0.8);
  grad.addColorStop(0, 'rgba(2, 6, 23, 0.1)');
  grad.addColorStop(1, 'rgba(2, 6, 23, 0.95)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);

  // 2. Setup Typography
  const baseFontSize = width * 0.08; 
  const lineHeight = baseFontSize * 2.3;
  const maxWidth = width * 0.88;
  const { lines, words } = getWordMetadata(ctx, text, maxWidth, baseFontSize, lineHeight);

  if (words.length === 0) return;

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.direction = 'rtl';
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // 3. Motion Engine: Calculate Camera Stability
  const activeIdx = words.findIndex(w => progress >= w.start && progress <= w.end);
  const currentWord = activeIdx !== -1 ? words[activeIdx] : (progress < words[0].start ? words[0] : words[words.length - 1]);

  const currentLineIdx = currentWord.lineIndex;
  const lineWords = words.filter(w => w.lineIndex === currentLineIdx);
  const lineStart = lineWords[0].start;
  const lineEnd = lineWords[lineWords.length - 1].end;
  const lineDur = lineEnd - lineStart;

  // Voice stability zone: Motion only happens in 10% entrance and 10% exit
  const transDur = lineDur * 0.1;
  let lineStep = 0.5; // Locked Center

  if (progress < lineStart + transDur) {
    lineStep = easeInOutCubic((progress - lineStart) / transDur) * 0.5;
  } else if (progress > lineEnd - transDur) {
    lineStep = 0.5 + easeInOutCubic((progress - (lineEnd - transDur)) / transDur) * 0.5;
  } else {
    lineStep = 0.5; // LOCKED STILL while being said
  }

  // Vertical Camera Lerp (prevent jumping)
  const targetY = height / 2 - currentWord.globalY;
  const viewportY = targetY; // In high-stability mode, we stick to the line's Y

  let viewportX = width / 2;
  if (animationType === AnimationType.RIGHT_TO_LEFT) {
    const entranceOffset = (0.5 - lineStep) * (width * 1.2);
    viewportX += entranceOffset;
  } else if (animationType === AnimationType.LEFT_TO_RIGHT) {
    const entranceOffset = (lineStep - 0.5) * (width * 1.2);
    viewportX += entranceOffset;
  }

  // 4. Drawing Pass
  lines.forEach((lineTextArray, lineIdx) => {
    const lineY = viewportY + (lineIdx * lineHeight);
    if (lineY < -lineHeight || lineY > height + lineHeight) return;

    const isLineActive = currentLineIdx === lineIdx;

    if (isLineActive) {
      const activeLineWords = words.filter(w => w.lineIndex === lineIdx);

      // Moving Spotlight Logic: The glow travels behind the words
      const spotlightX = viewportX + currentWord.relativeX;

      // Draw a subtle moving bloom behind the active word
      ctx.save();
      const glow = ctx.createRadialGradient(spotlightX, lineY, 0, spotlightX, lineY, baseFontSize * 2);
      glow.addColorStop(0, 'rgba(251, 191, 36, 0.15)');
      glow.addColorStop(1, 'transparent');
      ctx.fillStyle = glow;
      ctx.fillRect(0, 0, width, height);
      ctx.restore();

      activeLineWords.forEach(w => {
        const isWordActive = progress >= w.start && progress <= w.end;
        ctx.save();
        ctx.translate(viewportX + w.relativeX, lineY);

        if (isWordActive) {
          // Dynamic Pulse & Highlight
          ctx.shadowBlur = 35;
          ctx.shadowColor = 'rgba(251, 191, 36, 0.5)';
          ctx.fillStyle = '#fbbf24'; 
          const scale = 1 + 0.03 * Math.sin(progress * Math.PI * 20);
          ctx.scale(scale, scale);
        } else {
          // Dimmed inactive words in focus line
          ctx.globalAlpha = 0.45;
          ctx.fillStyle = 'white';
        }

        ctx.fillText(w.text, 0, 0);
        ctx.restore();
      });
    } else {
      // Inactive background lines
      ctx.save();
      ctx.globalAlpha = 0.12;
      ctx.fillStyle = 'white';
      ctx.fillText(lineTextArray.join(' '), viewportX, lineY);
      ctx.restore();
    }
  });

  // Branding Overlay
  ctx.save();
  ctx.globalAlpha = 0.25;
  ctx.font = `bold ${width * 0.02}px Inter, sans-serif`;
  ctx.fillStyle = 'white';
  ctx.fillText('NOOR STUDIO AI • CINEMATIC NARRATION', width / 2, height * 0.96);
  ctx.restore();
};

import { AnimationType } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  relativeX: number; // Center of the word relative to the line's center
  globalY: number;   // Vertical position relative to the first line
}

/**
 * Smooth cubic easing for high-end cinematic feel.
 */
const easeInOutCubic = (t: number): number => {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
};

/**
 * Calculates precise word timings and spatial coordinates for Nastaliq layout.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number
): { lines: string[][], words: WordMetadata[] } => {
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;
  ctx.direction = 'rtl';

  const paragraphs = text.split('\n').map(p => p.trim());
  const wordsMetadata: WordMetadata[] = [];
  const lines: string[][] = [];

  let totalWeight = 0;
  paragraphs.forEach((p) => {
    if (p === '') { totalWeight += 15; return; }
    const wordsInPara = p.split(/\s+/).filter(w => w.length > 0);
    wordsInPara.forEach((w) => {
      totalWeight += 10 + (w.length * 2.5);
      if (w.match(/[۔؟!]/)) totalWeight += 40;
      else if (w.match(/[،:]/)) totalWeight += 25;
    });
    totalWeight += 30; 
  });

  if (totalWeight === 0) return { lines: [[]], words: [] };

  let weightCursor = 0;
  let currentLineIdx = 0;
  const spaceWidth = ctx.measureText(' ').width;

  paragraphs.forEach((paragraph) => {
    if (paragraph === '') {
      lines.push(['']);
      currentLineIdx++;
      weightCursor += 15;
      return;
    }

    const wordsInPara = paragraph.split(/\s+/).filter(w => w.length > 0);
    let currentLineWords: string[] = [];
    let currentLineWidth = 0;
    let lineStartWordIdx = wordsMetadata.length;

    for (let i = 0; i < wordsInPara.length; i++) {
      const word = wordsInPara[i];
      const wordWidth = ctx.measureText(word).width;

      if (currentLineWidth + wordWidth > maxWidth && currentLineWords.length > 0) {
        finalizeLineOffsets(wordsMetadata, lineStartWordIdx, currentLineWidth - spaceWidth, true);
        lines.push(currentLineWords);
        currentLineWords = [];
        currentLineWidth = 0;
        currentLineIdx++;
        lineStartWordIdx = wordsMetadata.length;
      }

      const wordWeight = 10 + (word.length * 2.5);
      const startTime = weightCursor / totalWeight;
      weightCursor += wordWeight;
      const endTime = weightCursor / totalWeight;

      wordsMetadata.push({
        text: word,
        start: startTime,
        end: endTime,
        width: wordWidth,
        lineIndex: currentLineIdx,
        relativeX: currentLineWidth, 
        globalY: currentLineIdx * lineHeight
      });

      if (word.match(/[۔؟!]/)) weightCursor += 40;
      else if (word.match(/[،:]/)) weightCursor += 25;

      currentLineWords.push(word);
      currentLineWidth += wordWidth + spaceWidth;
    }

    if (currentLineWords.length > 0) {
      finalizeLineOffsets(wordsMetadata, lineStartWordIdx, currentLineWidth - spaceWidth, true);
      lines.push(currentLineWords);
      currentLineIdx++;
    }
    weightCursor += 30;
  });

  return { lines, words: wordsMetadata };
};

function finalizeLineOffsets(words: WordMetadata[], startIdx: number, totalWidth: number, isRTL: boolean) {
  for (let i = startIdx; i < words.length; i++) {
    const word = words[i];
    if (isRTL) {
      word.relativeX = (totalWidth / 2) - (word.relativeX + word.width / 2);
    } else {
      word.relativeX = -(totalWidth / 2) + (word.relativeX + word.width / 2);
    }
  }
}

/**
 * Renders the video frame with high-stability motion and moving word spotlight.
 */
export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  bg: HTMLImageElement | HTMLVideoElement | null,
  text: string,
  progress: number,
  animationType: AnimationType
) => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;

  const { width, height } = canvas;

  // 1. Background Layer
  ctx.fillStyle = '#020617';
  ctx.fillRect(0, 0, width, height);

  if (bg) {
    const bgW = bg instanceof HTMLVideoElement ? bg.videoWidth : bg.width;
    const bgH = bg instanceof HTMLVideoElement ? bg.videoHeight : bg.height;
    if (bgW > 0) {
      const scale = Math.max(width / bgW, height / bgH);
      ctx.globalAlpha = 0.45;
      ctx.drawImage(bg, (width - bgW * scale) / 2, (height - bgH * scale) / 2, bgW * scale, bgH * scale);
      ctx.globalAlpha = 1.0;
    }
  }

  // Deep shadow overlay for legibility
  const grad = ctx.createRadialGradient(width/2, height/2, 0, width/2, height/2, height * 0.8);
  grad.addColorStop(0, 'rgba(2, 6, 23, 0.2)');
  grad.addColorStop(1, 'rgba(2, 6, 23, 0.98)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);

  // 2. Setup Typography
  const baseFontSize = width * 0.082; 
  const lineHeight = baseFontSize * 2.3;
  const maxWidth = width * 0.88;
  const { lines, words } = getWordMetadata(ctx, text, maxWidth, baseFontSize, lineHeight);

  if (words.length === 0) return;

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.direction = 'rtl';
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // 3. Motion Engine: Calculate Camera Stability and Transitions
  // Find current word, but handle edge cases for smooth scroll-in and scroll-out
  const firstWord = words[0];
  const lastWord = words[words.length - 1];

  let currentWord = firstWord;
  let activeIdx = -1;

  if (progress < firstWord.start) {
    currentWord = firstWord;
  } else if (progress > lastWord.end) {
    currentWord = lastWord;
  } else {
    activeIdx = words.findIndex(w => progress >= w.start && progress <= w.end);
    currentWord = activeIdx !== -1 ? words[activeIdx] : firstWord;
  }

  const currentLineIdx = currentWord.lineIndex;
  const lineWords = words.filter(w => w.lineIndex === currentLineIdx);
  const lineStart = lineWords[0].start;
  const lineEnd = lineWords[lineWords.length - 1].end;
  const lineDur = lineEnd - lineStart;

  // Transition window: motion happens in the gaps between line focus
  const transDur = Math.min(lineDur * 0.15, 0.05); // 15% of line or fixed cap

  let lineHStep = 0.5; // Locked Horizontal Center
  let verticalFocusY = currentWord.globalY;

  // Handle Horizontal Movement based on current focus
  if (progress < lineStart) {
     lineHStep = 0.0; // Off-screen to the right (for RTL)
  } else if (progress < lineStart + transDur) {
     lineHStep = easeInOutCubic((progress - lineStart) / transDur) * 0.5;
  } else if (progress > lineEnd - transDur && progress <= lineEnd) {
     lineHStep = 0.5 + easeInOutCubic((progress - (lineEnd - transDur)) / transDur) * 0.5;
  } else if (progress > lineEnd) {
     lineHStep = 1.0; // Off-screen to the left (for RTL)
  } else {
     lineHStep = 0.5; // STABLE CENTER
  }

  // Handle End-of-Video Vertical Exit
  // If we are past the last word, we scroll the viewport further to clear the screen
  const exitDuration = 0.05; // 5% of total time for exit
  const exitProgress = Math.max(0, (progress - lastWord.end) / exitDuration);
  if (exitProgress > 0) {
    verticalFocusY += Math.min(exitProgress, 1.0) * lineHeight;
  }

  // Calculate Final Viewport Coordinates
  const viewportY = height / 2 - verticalFocusY;
  let viewportX = width / 2;

  if (animationType === AnimationType.RIGHT_TO_LEFT) {
    const hOffset = (0.5 - lineHStep) * (width * 1.3);
    viewportX += hOffset;
  } else if (animationType === AnimationType.LEFT_TO_RIGHT) {
    const hOffset = (lineHStep - 0.5) * (width * 1.3);
    viewportX += hOffset;
  }

  // 4. Drawing Pass
  lines.forEach((lineTextArray, lineIdx) => {
    const lineY = viewportY + (lineIdx * lineHeight);

    // Efficient culling
    if (lineY < -lineHeight || lineY > height + lineHeight) return;

    const isLineActive = currentLineIdx === lineIdx;

    if (isLineActive && progress <= lastWord.end + 0.01) {
      const activeLineWords = words.filter(w => w.lineIndex === lineIdx);

      // Moving Spotlight travels with the active word
      const spotlightX = viewportX + currentWord.relativeX;

      ctx.save();
      const bloom = ctx.createRadialGradient(spotlightX, lineY, 0, spotlightX, lineY, baseFontSize * 2.5);
      bloom.addColorStop(0, 'rgba(251, 191, 36, 0.18)');
      bloom.addColorStop(1, 'transparent');
      ctx.fillStyle = bloom;
      ctx.fillRect(0, 0, width, height);
      ctx.restore();

      activeLineWords.forEach(w => {
        const isWordActive = progress >= w.start && progress <= w.end;
        ctx.save();
        ctx.translate(viewportX + w.relativeX, lineY);

        if (isWordActive) {
          ctx.shadowBlur = 40;
          ctx.shadowColor = 'rgba(251, 191, 36, 0.6)';
          ctx.fillStyle = '#fbbf24'; 
          const scale = 1 + 0.04 * Math.sin(progress * Math.PI * 25);
          ctx.scale(scale, scale);
        } else {
          ctx.globalAlpha = 0.5;
          ctx.fillStyle = 'white';
        }

        ctx.fillText(w.text, 0, 0);
        ctx.restore();
      });
    } else {
      // Background and non-active lines
      ctx.save();
      // Fade out based on distance from center for 'depth' feel
      const distFromCenter = Math.abs(lineY - height/2);
      const opacityFactor = Math.max(0, 1 - distFromCenter / (height/2));
      ctx.globalAlpha = 0.12 * opacityFactor;
      ctx.fillStyle = 'white';
      ctx.fillText(lineTextArray.join(' '), viewportX, lineY);
      ctx.restore();
    }
  });

  // Branding Overlay
  ctx.save();
  ctx.globalAlpha = 0.22;
  ctx.font = `bold ${width * 0.022}px Inter, sans-serif`;
  ctx.fillStyle = 'white';
  ctx.fillText('NOOR STUDIO AI • CINEMATIC NARRATION', width / 2, height * 0.96);
  ctx.restore();
};

