  const vignette = ctx.createRadialGradient(width/2, height/2, height * 0.1, width/2, height/2, height * 0.9);
  vignette.addColorStop(0, 'rgba(2, 6, 23, 0.1)');
  vignette.addColorStop(0.5, 'rgba(2, 6, 23, 0.4)');
  vignette.addColorStop(1, 'rgba(2, 6, 23, 0.95)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

