      const spotlightX = viewportX + currentWord.relativeX;
      ctx.save();
      const bloom = ctx.createRadialGradient(spotlightX, lineY, 0, spotlightX, lineY, baseFontSize * 3);
      bloom.addColorStop(0, 'rgba(251, 191, 36, 0.2)');
      bloom.addColorStop(1, 'transparent');
      ctx.fillStyle = bloom;
      ctx.fillRect(0, 0, width, height);
      ctx.restore();

      activeLineWords.forEach(w => {
        const isWordActive = progress >= w.start && progress <= w.end;
        ctx.save();
        ctx.translate(viewportX + w.relativeX, lineY);

        if (isWordActive) {
          ctx.shadowBlur = 50;
          ctx.shadowColor = 'rgba(251, 191, 36, 0.7)';
          ctx.fillStyle = '#fbbf24'; 
          const scale = 1.0 + 0.06 * Math.sin(progress * Math.PI * 18);
          ctx.scale(scale, scale);
        } else {
          const wordProgress = (progress - w.start) / (w.end - w.start);
          const hasBeenSpoken = progress > w.end;

          ctx.globalAlpha = hasBeenSpoken ? 0.4 : 0.6;
          ctx.fillStyle = 'white';
        }

        ctx.fillText(w.text, 0, 0);
        ctx.restore();
      });
    } else {
      // Inactive Background Lines
      ctx.save();
      ctx.globalAlpha = 0.15 * focusFactor;
      ctx.fillStyle = 'white';

      // Slight depth-of-field blur feel for non-focused lines
      if (focusFactor < 0.5) {
        ctx.filter = `blur(${Math.max(0, (0.5 - focusFactor) * 8)}px)`;
      }

      ctx.fillText(lineTextArray.join(' '), viewportX, lineY);
      ctx.restore();
    }
  });

  // 5. Branding & UI
  ctx.save();
  ctx.globalAlpha = 0.3;
  ctx.font = `bold ${width * 0.02}px Inter, sans-serif`;
  ctx.fillStyle = 'white';
  ctx.textAlign = 'center';
  ctx.fillText('NOOR STUDIO AI • CINEMATIC NARRATOR', width / 2, height * 0.95);
  ctx.restore();
};

