import { AnimationType, EditorLayer, LayerType, TextEffect, ImageEffect } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  relativeX: number;
  globalY: number;
}

const easeInOutCubic = (t: number): number => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;

export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number
): { lines: string[][], words: WordMetadata[] } => {
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;
  ctx.direction = 'rtl';

  const paragraphs = text.split('\n').map(p => p.trim());
  const wordsMetadata: WordMetadata[] = [];
  const lines: string[][] = [];

  let totalWeight = 0;
  paragraphs.forEach((p) => {
    if (p === '') { totalWeight += 15; return; }
    const wordsInPara = p.split(/\s+/).filter(w => w.length > 0);
    wordsInPara.forEach((w) => {
      totalWeight += 12 + (w.length * 2.8);
      if (w.match(/[۔؟!]/)) totalWeight += 45;
      else if (w.match(/[،:]/)) totalWeight += 28;
    });
    totalWeight += 35; 
  });

  if (totalWeight === 0) return { lines: [[]], words: [] };

  let weightCursor = 0;
  let currentLineIdx = 0;
  const spaceWidth = ctx.measureText(' ').width;

  paragraphs.forEach((paragraph) => {
    if (paragraph === '') {
      lines.push(['']);
      currentLineIdx++;
      weightCursor += 15;
      return;
    }

    const wordsInPara = paragraph.split(/\s+/).filter(w => w.length > 0);
    let currentLineWords: string[] = [];
    let currentLineWidth = 0;
    let lineStartWordIdx = wordsMetadata.length;

    for (let i = 0; i < wordsInPara.length; i++) {
      const word = wordsInPara[i];
      const wordWidth = ctx.measureText(word).width;

      if (currentLineWidth + wordWidth > maxWidth && currentLineWords.length > 0) {
        finalizeLineOffsets(wordsMetadata, lineStartWordIdx, currentLineWidth - spaceWidth, true);
        lines.push(currentLineWords);
        currentLineWords = [];
        currentLineWidth = 0;
        currentLineIdx++;
        lineStartWordIdx = wordsMetadata.length;
      }

      const wordWeight = 12 + (word.length * 2.8);
      const startTime = weightCursor / totalWeight;
      weightCursor += wordWeight;
      const endTime = weightCursor / totalWeight;

      wordsMetadata.push({
        text: word,
        start: startTime,
        end: endTime,
        width: wordWidth,
        lineIndex: currentLineIdx,
        relativeX: currentLineWidth, 
        globalY: currentLineIdx * lineHeight
      });

      if (word.match(/[۔؟!]/)) weightCursor += 45;
      else if (word.match(/[،:]/)) weightCursor += 28;

      currentLineWords.push(word);
      currentLineWidth += wordWidth + spaceWidth;
    }

    if (currentLineWords.length > 0) {
      finalizeLineOffsets(wordsMetadata, lineStartWordIdx, currentLineWidth - spaceWidth, true);
      lines.push(currentLineWords);
      currentLineIdx++;
    }
    weightCursor += 35;
  });

  return { lines, words: wordsMetadata };
};

function finalizeLineOffsets(words: WordMetadata[], startIdx: number, totalWidth: number, isRTL: boolean) {
  for (let i = startIdx; i < words.length; i++) {
    const word = words[i];
    if (isRTL) {
      word.relativeX = (totalWidth / 2) - (word.relativeX + word.width / 2);
    } else {
      word.relativeX = -(totalWidth / 2) + (word.relativeX + word.width / 2);
    }
  }
}

const renderNarrationLayer = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  layer: any,
  globalProgress: number,
  duration: number
) => {
  const progress = (globalProgress * duration - layer.startTime) / (layer.endTime - layer.startTime);
  if (progress < 0 || progress > 1.05) return;

  const baseFontSize = width * 0.088; 
  const lineHeight = baseFontSize * 2.5;
  const maxWidth = width * 0.9;
  const { lines, words } = getWordMetadata(ctx, layer.text, maxWidth, baseFontSize, lineHeight);

  if (words.length === 0) return;

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.direction = 'rtl';
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  const firstWord = words[0];
  const lastWord = words[words.length - 1];
  let currentWord = words[0];
  let activeIdx = words.findIndex(w => progress >= w.start && progress <= w.end);

  if (activeIdx !== -1) currentWord = words[activeIdx];
  else if (progress > lastWord.end) currentWord = lastWord;

  const totalVerticalRange = lastWord.globalY - firstWord.globalY;
  const exitBuffer = lineHeight * 2;

  // Continuous Vertical Scroll
  const scrollY = firstWord.globalY + (totalVerticalRange + exitBuffer) * progress;
  const viewportY = (height * 0.45) - scrollY;

  lines.forEach((lineTextArray, lineIdx) => {
    const lineY = viewportY + (lineIdx * lineHeight);
    if (lineY < -lineHeight || lineY > height + lineHeight) return;

    const isLineActive = currentWord.lineIndex === lineIdx;
    const distFromFocus = Math.abs(lineY - (height * 0.45));
    const focusFactor = Math.max(0, 1 - distFromFocus / (height * 0.5));

    // Right-to-Left Slide Logic
    let viewportX = width / 2;
    if (layer.animationType !== AnimationType.VERTICAL_SCROLL) {
      const lineWords = words.filter(w => w.lineIndex === lineIdx);
      const lineStart = lineWords[0].start;
      const lineEnd = lineWords[lineWords.length - 1].end;
      const lineProgress = (progress - lineStart) / (lineEnd - lineStart);

      // Magnetic Drift: Text slides in from right and locks at center
      let driftProgress = 0.5; // Locked at center
      if (progress < lineStart) {
        driftProgress = 0; // Way out right
      } else if (progress < lineStart + 0.08) {
        driftProgress = easeInOutCubic((progress - lineStart) / 0.08) * 0.5;
      } else if (progress > lineEnd - 0.08) {
        driftProgress = 0.5 + easeInOutCubic((progress - (lineEnd - 0.08)) / 0.08) * 0.5;
      }

      const dir = layer.animationType === AnimationType.RIGHT_TO_LEFT ? 1 : -1;
      viewportX += (0.5 - driftProgress) * (width * 1.5) * dir;
    }

    if (isLineActive) {
      const activeLineWords = words.filter(w => w.lineIndex === lineIdx);
      const spotlightX = viewportX + currentWord.relativeX;

      ctx.save();
      const bloom = ctx.createRadialGradient(spotlightX, lineY, 0, spotlightX, lineY, baseFontSize * 3.5);
      bloom.addColorStop(0, 'rgba(251, 191, 36, 0.22)');
      bloom.addColorStop(1, 'transparent');
      ctx.fillStyle = bloom;
      ctx.fillRect(0, 0, width, height);
      ctx.restore();

      activeLineWords.forEach(w => {
        const isWordActive = progress >= w.start && progress <= w.end;
        ctx.save();
        ctx.translate(viewportX + w.relativeX, lineY);

        if (isWordActive) {
          ctx.shadowBlur = 60;
          ctx.shadowColor = 'rgba(251, 191, 36, 0.8)';
          ctx.fillStyle = '#fbbf24'; 
          const pulse = 1.0 + 0.06 * Math.sin(progress * Math.PI * 22);
          ctx.scale(pulse, pulse);
        } else {
          ctx.globalAlpha = progress > w.end ? 0.35 : 0.65;
          ctx.fillStyle = 'white';
        }
        ctx.fillText(w.text, 0, 0);
        ctx.restore();
      });
    } else {
      // Inactive / Background Lines
      ctx.save();
      ctx.globalAlpha = 0.18 * focusFactor;
      ctx.fillStyle = 'white';
      if (focusFactor < 0.4) {
        ctx.filter = `blur(${Math.max(0, (0.4 - focusFactor) * 12)}px)`;
      }
      ctx.fillText(lineTextArray.join(' '), viewportX, lineY);
      ctx.restore();
    }
  });
};

const renderTextLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const duration = layer.endTime - layer.startTime;
  const localTime = time - layer.startTime;

  ctx.save();
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `${layer.fontSize}px Inter, sans-serif`;
  ctx.fillStyle = layer.color;

  let alpha = 1;
  let scale = 1;
  let offsetY = 0;

  if (layer.animation === 'fade') {
    if (localTime < 0.5) alpha = localTime / 0.5;
    else if (duration - localTime < 0.5) alpha = (duration - localTime) / 0.5;
  } else if (layer.animation === 'slide') {
    if (localTime < 0.5) offsetY = (1 - (localTime / 0.5)) * 50;
  } else if (layer.animation === 'bounce') {
    scale = 1 + 0.1 * Math.sin(localTime * 10);
  } else if (layer.animation === 'typewriter') {
    const charsToShow = Math.floor(layer.text.length * Math.min(1, localTime / (duration * 0.5)));
    const visibleText = layer.text.substring(0, charsToShow);
    ctx.fillText(visibleText, width * layer.x, height * layer.y + offsetY);
    ctx.restore();
    return;
  }

  ctx.globalAlpha = alpha;
  ctx.translate(width * layer.x, height * layer.y + offsetY);
  ctx.scale(scale, scale);
  ctx.fillText(layer.text, 0, 0);
  ctx.restore();
};

const renderImageLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const localTime = time - layer.startTime;
  const duration = layer.endTime - layer.startTime;

  const img = new Image();
  img.src = layer.url;
  if (!img.complete) return;

  ctx.save();
  let scale = layer.scale;
  let alpha = 1;

  if (layer.animation === 'zoom') scale *= (1 + 0.2 * (localTime / duration));
  else if (layer.animation === 'fade') alpha = Math.min(1, localTime / 0.5) * Math.min(1, (duration - localTime) / 0.5);

  ctx.globalAlpha = alpha;
  const drawW = img.width * scale;
  const drawH = img.height * scale;
  ctx.drawImage(img, width * layer.x - drawW / 2, height * layer.y - drawH / 2, drawW, drawH);
  ctx.restore();
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  bg: HTMLImageElement | HTMLVideoElement | null,
  layers: EditorLayer[],
  currentTime: number,
  totalDuration: number
) => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  const { width, height } = canvas;

  ctx.fillStyle = '#020617';
  ctx.fillRect(0, 0, width, height);

  if (bg) {
    const bgW = bg instanceof HTMLVideoElement ? bg.videoWidth : bg.width;
    const bgH = bg instanceof HTMLVideoElement ? bg.videoHeight : bg.height;
    if (bgW > 0) {
      const scale = Math.max(width / bgW, height / bgH);
      ctx.globalAlpha = 0.55;
      ctx.drawImage(bg, (width - bgW * scale) / 2, (height - bgH * scale) / 2, bgW * scale, bgH * scale);
      ctx.globalAlpha = 1.0;
    }
  }

  const vignette = ctx.createRadialGradient(width/2, height/2, height * 0.1, width/2, height/2, height * 1.0);
  vignette.addColorStop(0, 'rgba(2, 6, 23, 0.15)');
  vignette.addColorStop(0.6, 'rgba(2, 6, 23, 0.5)');
  vignette.addColorStop(1, 'rgba(2, 6, 23, 0.98)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  const sortedLayers = [...layers].sort((a, b) => a.zIndex - b.zIndex);
  const progress = currentTime / totalDuration;

  sortedLayers.forEach(layer => {
    if (!layer.visible) return;
    if (layer.type === LayerType.NARRATION) {
      renderNarrationLayer(ctx, width, height, layer, progress, totalDuration);
    } else if (layer.type === LayerType.TEXT) {
      renderTextLayer(ctx, width, height, layer, currentTime);
    } else if (layer.type === LayerType.IMAGE) {
      renderImageLayer(ctx, width, height, layer, currentTime);
    }
  });

  ctx.save();
  ctx.globalAlpha = 0.25;
  ctx.font = `bold ${width * 0.022}px Inter, sans-serif`;
  ctx.fillStyle = 'white';
  ctx.textAlign = 'center';
  ctx.fillText('NOOR STUDIO AI • CINEMATIC NARRATOR', width / 2, height * 0.96);
  ctx.restore();
};

