          </div>
          <div>
            <h1 className="text-3xl font-bold text-white tracking-tight">Noor Narrator Studio</h1>
            <p className="text-sm text-emerald-500 font-semibold tracking-widest uppercase">AI Voice & Cinematic Video</p>
          </div>
        </div>
        <div className="flex gap-4">
          <button onClick={() => setShowHistory(!showHistory)} className="px-5 py-2.5 glass-card rounded-xl hover:bg-emerald-900/40 transition-all flex items-center gap-2 border border-emerald-900/50">
            {showHistory ? <ArrowLeft className="w-5 h-5" /> : <History className="w-5 h-5" />}
            <span className="hidden sm:inline font-bold">{showHistory ? "Back" : "Archive"}</span>
          </button>
        </div>
      </header>

      {isEditing && currentResult ? (
        <div className="fixed inset-0 z-50 bg-[#020617] flex flex-col p-6 overflow-hidden">
