                          <input type="number" value={(selectedLayer as any).fontSize} onChange={(e) => updateLayer(selectedLayer.id, { fontSize: Number(e.target.value) })} className="w-full bg-black/40 border border-emerald-900/40 rounded-xl p-2 text-white text-sm" />
                        </div>
                        <div className="space-y-2">
                          <label className="text-[10px] font-black text-emerald-600 uppercase">Color</label>
                          <input type="color" value={(selectedLayer as any).color} onChange={(e) => updateLayer(selectedLayer.id, { color: e.target.value })} className="w-full h-10 bg-black/40 border border-emerald-900/40 rounded-xl cursor-pointer" />
                        </div>
                      </div>
                    </>
