                  {selectedLayer.type === LayerType.IMAGE && (
                    <>
                       <div className="space-y-2">
                          <label className="text-[10px] font-black text-emerald-600 uppercase">Scale</label>
                          <input type="range" min="0.1" max="2" step="0.1" value={(selectedLayer as any).scale} onChange={(e) => updateLayer(selectedLayer.id, { scale: Number(e.target.value) })} className="w-full" />
                       </div>
                    </>
                  )}
                  <div className="space-y-4 pt-6 border-t border-emerald-900/20">
                    <div className="flex items-center gap-2 text-[10px] font-black text-emerald-600 uppercase">
                      <Clock className="w-3 h-3" /> Timing (Seconds)
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-1">
                        <label className="text-[8px] font-bold text-slate-500 uppercase">In</label>
                        <input type="number" step="0.1" min="0" value={selectedLayer.startTime} onChange={(e) => updateLayer(selectedLayer.id, { startTime: Number(e.target.value) })} className="w-full bg-black/40 border border-emerald-900/40 rounded-xl p-2 text-white text-xs" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[8px] font-bold text-slate-500 uppercase">Out</label>
                        <input type="number" step="0.1" max={duration} value={selectedLayer.endTime} onChange={(e) => updateLayer(selectedLayer.id, { endTime: Number(e.target.value) })} className="w-full bg-black/40 border border-emerald-900/40 rounded-xl p-2 text-white text-xs" />
                      </div>
                    </div>
                  </div>
