              ) : (
                <div className="h-full flex flex-col items-center justify-center text-slate-700 text-xs font-bold uppercase tracking-widest text-center">
                   Select a layer<br/>to edit properties
                </div>
              )}
            </div>
          </div>

          <div className="h-24 bg-slate-900/50 rounded-2xl p-4 flex items-center border border-emerald-900/20 relative">
             <div className="absolute top-0 bottom-0 w-0.5 bg-emerald-500 shadow-[0_0_10px_#10b981] z-10" style={{ left: `${(pauseOffsetRef.current / duration) * 100}%` }}></div>
             <div className="w-full h-full relative overflow-hidden rounded-lg bg-black/40 flex flex-col justify-center gap-1">
                {layers.map(layer => (
                  <div 
                    key={layer.id} 
                    className={`h-4 absolute rounded-sm border ${selectedLayerId === layer.id ? 'bg-emerald-500/50 border-emerald-400' : 'bg-slate-700/30 border-slate-600'}`}
                    style={{ left: `${(layer.startTime / duration) * 100}%`, width: `${((layer.endTime - layer.startTime) / duration) * 100}%` }}
                  ></div>
                ))}
             </div>
          </div>
        </div>
      ) : null}

      <main className="w-full max-w-6xl grid grid-cols-1 lg:grid-cols-12 gap-10 relative z-10">
        {!showHistory ? (
          <>
            <div className="lg:col-span-7 space-y-6 animate-fade-in">
              <section className="glass-card rounded-3xl p-8 shadow-2xl border-emerald-900/20">
                <div className="flex items-center justify-between mb-6">
                  <h2 className="text-xl font-bold flex items-center gap-3 text-yellow-500">
                    <Mic2 className="w-6 h-6" /> Script Editor
                  </h2>
                </div>
                {errorMsg && (
                  <div className="mb-6 p-4 bg-red-900/20 border border-red-500/30 rounded-2xl flex items-start gap-3">
                    <AlertCircle className="w-5 h-5 text-red-500 mt-0.5 shrink-0" />
                    <div className="text-sm text-red-200"><p className="font-bold mb-1">Attention</p><p>{errorMsg}</p></div>
                  </div>
                )}
                <textarea className="urdu-font w-full h-56 bg-black/40 border border-emerald-900/40 rounded-2xl p-6 text-2xl text-emerald-50 focus:outline-none focus:ring-4 focus:ring-emerald-600/20 transition-all resize-none shadow-inner" placeholder="یہاں اپنا اردو متن لکھیں..." value={settings.text} onChange={(e) => setSettings({ ...settings, text: e.target.value })} dir="rtl" />

                <div className="mt-8 p-6 bg-emerald-950/20 border border-emerald-900/30 rounded-3xl space-y-6">
                  <div className="flex items-center justify-between">
                    <h3 className="text-sm font-black text-emerald-400 uppercase tracking-[0.2em] flex items-center gap-2">
                      <Sparkles className="w-4 h-4" /> Cinematic Pro Tools
                    </h3>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-4">
                      <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Nano Banana Pro (Image)</label>
                      <div className="flex gap-2">
                        {(['1K', '2K', '4K'] as ImageSize[]).map(size => (
                          <button
                            key={size}
                            onClick={() => setSettings({ ...settings, imageSize: size })}
                            className={`flex-1 p-2 text-[10px] font-bold rounded-lg border transition-all ${settings.imageSize === size ? 'bg-emerald-600 border-emerald-400 text-white' : 'bg-black/20 border-emerald-900/40 text-slate-500'}`}
                          >
                            {size}
