import { GoogleGenAI, Modality, Type } from "@google/genai";
import { VoiceName, SEOMetadata, ImageSize, AspectRatio } from "../types";

const safetySettings = [
  { category: "HARM_CATEGORY_HARASSMENT", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_HATE_SPEECH", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_SEXUALLY_EXPLICIT", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_DANGEROUS_CONTENT", threshold: "BLOCK_NONE" },
];

const sanitizeForTTS = (text: string): string => {
  return text
    .replace(/[\u{1F000}-\u{1F9FF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B50}\u{2B55}]/gu, '')
    .replace(/\s+/g, ' ')
    .trim();
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const getTTSPrompt = (text: string): string => {
  return `Recite the following text with professional eloquence. Pay special attention to the correct Tajweed and beautiful pronunciation of Arabic phrases. The tone should be spiritual, calm, and deeply narrative: "${text}"`;
};

/**
 * Ensures a paid API key is selected for Pro/Veo models.
 */
export const ensureProKey = async (): Promise<void> => {
  // @ts-ignore
  if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
    // @ts-ignore
    await window.aistudio.openSelectKey();
  }
};

export const generateNarration = async (text: string, voice: VoiceName, retryCount = 0): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const cleanText = sanitizeForTTS(text);
  if (!cleanText) throw new Error("Text is empty after cleaning.");

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: getTTSPrompt(cleanText) }] }],
      config: {
        responseModalities: [Modality.AUDIO], 
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voice },
          },
        },
        safetySettings: safetySettings as any,
      },
    });

    if (response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data) {
      return response.candidates[0].content.parts[0].inlineData.data;
    }
    throw new Error("Audio data not found.");
  } catch (error: any) {
    if (retryCount < 3) {
      await delay(2000 * (retryCount + 1));
      return generateNarration(text, voice, retryCount + 1);
    }
    throw error;
  }
};

export const generateProImage = async (prompt: string, size: ImageSize = '1K', ratio: AspectRatio = AspectRatio.VERTICAL) => {
  await ensureProKey();
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-image-preview',
    contents: { parts: [{ text: `Cinematic Urdu Atmosphere: ${prompt}. Atmospheric lighting, photorealistic, no text, religious serenity.` }] },
    config: {
      imageConfig: {
        aspectRatio: ratio as any,
        imageSize: size
      }
    }
  });

  const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
  if (part?.inlineData?.data) {
    return `data:image/png;base64,${part.inlineData.data}`;
  }
  throw new Error("Pro image generation failed.");
};

export const generateVeoVideo = async (prompt: string, imageBase64: string, ratio: AspectRatio = AspectRatio.VERTICAL) => {
  await ensureProKey();
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const cleanBase64 = imageBase64.replace(/^data:image\/\w+;base64,/, "");

  let operation = await ai.models.generateVideos({
    model: 'veo-3.1-fast-generate-preview',
    prompt: `Animate this scene gracefully: ${prompt}. Subtle camera push, gentle lighting changes, atmospheric floating particles.`,
    image: {
      imageBytes: cleanBase64,
      mimeType: 'image/png'
    },
    config: {
      numberOfVideos: 1,
      resolution: '1080p',
      aspectRatio: ratio === AspectRatio.LANDSCAPE ? '16:9' : '9:16'
    }
  });

  while (!operation.done) {
    await delay(10000);
    operation = await ai.operations.getVideosOperation({ operation: operation as any });
  }

  const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
  if (!downloadLink) throw new Error("Video generation operation failed.");

  const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
  const blob = await response.blob();
  return URL.createObjectURL(blob);
};

export const generateSEOMetadata = async (script: string): Promise<SEOMetadata> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Provide JSON viral SEO (Title, Description, Keywords) for this script: ${script}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          description: { type: Type.STRING },
          keywords: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["title", "description", "keywords"]
      }
    }
  });
  return JSON.parse(response.text || '{}') as SEOMetadata;
};

export const generateAtmosphereImage = async (prompt: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `Atmosphere: ${prompt}. Cinematic masterpiece, dramatic lighting, 8k resolution, no text, artistic silhouette.` }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData?.data);
    return part ? `data:image/png;base64,${part.inlineData.data}` : null;
  } catch { return null; }
};

import { AnimationType, EditorLayer, LayerType, TextEffect, ImageEffect } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  relativeX: number; // Offset from the line's center
  globalY: number;
}

const easeInOutCubic = (t: number): number => {
  const clampedT = Math.max(0, Math.min(1, t));
  return clampedT < 0.5 ? 4 * clampedT * clampedT * clampedT : 1 - Math.pow(-2 * clampedT + 2, 3) / 2;
};

/**
 * Calculates words and lines with high precision for RTL alignment.
 * Optimized for both Vertical and Landscape displays.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number
): { lines: string[][], words: WordMetadata[] } => {
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;
  ctx.direction = 'rtl';

  const paragraphs = text.split('\n').map(p => p.trim());
  const wordsMetadata: WordMetadata[] = [];
  const lines: string[][] = [];

  // Calculate total weights for timing
  let totalWeight = 0;
  paragraphs.forEach((p) => {
    if (p === '') { totalWeight += 20; return; }
    const wordsInPara = p.split(/\s+/).filter(w => w.length > 0);
    wordsInPara.forEach((w) => {
      totalWeight += 15 + (w.length * 3.2);
      if (w.match(/[۔؟!]/)) totalWeight += 50;
      else if (w.match(/[،:]/)) totalWeight += 30;
    });
    totalWeight += 40; 
  });

  if (totalWeight === 0) return { lines: [[]], words: [] };

  let weightCursor = 0;
  let currentLineIdx = 0;
  const spaceWidth = ctx.measureText(' ').width;

  paragraphs.forEach((paragraph) => {
    if (paragraph === '') {
      lines.push(['']);
      currentLineIdx++;
      weightCursor += 20;
      return;
    }

    const wordsInPara = paragraph.split(/\s+/).filter(w => w.length > 0);
    let currentLineWords: string[] = [];
    let currentLineWidth = 0;
    let lineStartWordIdx = wordsMetadata.length;

    for (let i = 0; i < wordsInPara.length; i++) {
      const word = wordsInPara[i];
      const wordWidth = ctx.measureText(word).width;

      // Strict line wrapping
      if (currentLineWidth + wordWidth > maxWidth && currentLineWords.length > 0) {
        finalizeLineAlignment(ctx, wordsMetadata, lineStartWordIdx, currentLineWords);
        lines.push(currentLineWords);
        currentLineWords = [];
        currentLineWidth = 0;
        currentLineIdx++;
        lineStartWordIdx = wordsMetadata.length;
      }

      const wordWeight = 15 + (word.length * 3.2);
      const startTime = weightCursor / totalWeight;
      weightCursor += wordWeight;
      const endTime = weightCursor / totalWeight;

      wordsMetadata.push({
        text: word,
        start: startTime,
        end: endTime,
        width: wordWidth,
        lineIndex: currentLineIdx,
        relativeX: 0, 
        globalY: currentLineIdx * lineHeight
      });

      if (word.match(/[۔؟!]/)) weightCursor += 50;
      else if (word.match(/[،:]/)) weightCursor += 30;

      currentLineWords.push(word);
      currentLineWidth += wordWidth + spaceWidth;
    }

    if (currentLineWords.length > 0) {
      finalizeLineAlignment(ctx, wordsMetadata, lineStartWordIdx, currentLineWords);
      lines.push(currentLineWords);
      currentLineIdx++;
    }
    weightCursor += 40;
  });

  return { lines, words: wordsMetadata };
};

function finalizeLineAlignment(
  ctx: CanvasRenderingContext2D, 
  allWords: WordMetadata[], 
  startIdx: number, 
  lineStrings: string[]
) {
  const fullLineString = lineStrings.join(' ');
  const totalLineWidth = ctx.measureText(fullLineString).width;
  const lineCenter = totalLineWidth / 2;

  for (let i = 0; i < lineStrings.length; i++) {
    const wordMeta = allWords[startIdx + i];
    const subStr = lineStrings.slice(0, i + 1).join(' ');
    const subStrWidth = ctx.measureText(subStr).width;
    const wordCenterInLine = subStrWidth - (wordMeta.width / 2);
    wordMeta.relativeX = lineCenter - wordCenterInLine;
  }
}

const renderNarrationLayer = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  layer: any,
  globalProgress: number,
  duration: number
) => {
  const currentTotalTime = globalProgress * duration;
  const progress = (currentTotalTime - layer.startTime) / (layer.endTime - layer.startTime);
  if (progress < 0 || progress > 1.05) return;

  const isLandscape = width > height;
  const scaleRef = isLandscape ? height * 1.4 : width; 
  const baseFontSize = scaleRef * 0.085; 
  const lineHeight = baseFontSize * 2.4;
  const maxWidth = width * (isLandscape ? 0.75 : 0.85);

  const { lines, words } = getWordMetadata(ctx, layer.text, maxWidth, baseFontSize, lineHeight);
  if (words.length === 0) return;

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.direction = 'rtl';
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  const lastWord = words[words.length - 1];
  let currentWord = words[0];
  let activeIdx = words.findIndex(w => progress >= w.start && progress <= w.end);

  if (activeIdx !== -1) currentWord = words[activeIdx];
  else if (progress > lastWord.end) currentWord = lastWord;

  const firstWord = words[0];
  const totalVerticalRange = lastWord.globalY - firstWord.globalY;
  const scrollY = firstWord.globalY + (totalVerticalRange + lineHeight * 2) * progress;
  const verticalCenterOffset = isLandscape ? 0.42 : 0.45;
  const viewportY = (height * verticalCenterOffset) - scrollY;

  lines.forEach((lineTextArray, lineIdx) => {
    const lineY = viewportY + (lineIdx * lineHeight);
    if (lineY < -lineHeight || lineY > height + lineHeight) return;

    const isLineActive = currentWord.lineIndex === lineIdx;
    const distFromFocus = Math.abs(lineY - (height * verticalCenterOffset));
    const focusFactor = Math.max(0, 1 - distFromFocus / (height * 0.5));

    let viewportX = width / 2;
    if (layer.animationType !== AnimationType.VERTICAL_SCROLL) {
      const lineWords = words.filter(w => w.lineIndex === lineIdx);
      if (lineWords.length > 0) {
        const lineStartSec = lineWords[0].start * duration;
        const lineEndSec = lineWords[lineWords.length - 1].end * duration;
        const slideTime = 0.5;

        if (isLineActive) {
          viewportX = (width / 2) - currentWord.relativeX;
          if (currentTotalTime < lineStartSec + slideTime) {
            const t = (currentTotalTime - lineStartSec) / slideTime;
            const startX = width * 1.5 * (layer.animationType === AnimationType.RIGHT_TO_LEFT ? 1 : -1);
            viewportX = startX + (viewportX - startX) * easeInOutCubic(t);
          } else if (currentTotalTime > lineEndSec - slideTime) {
            const t = (currentTotalTime - (lineEndSec - slideTime)) / slideTime;
            const endX = -width * 0.5 * (layer.animationType === AnimationType.RIGHT_TO_LEFT ? 1 : -1);
            viewportX = viewportX + (endX - viewportX) * easeInOutCubic(t);
          }
        } else if (progress < lineWords[0].start) {
          viewportX = width * 2 * (layer.animationType === AnimationType.RIGHT_TO_LEFT ? 1 : -1);
        } else {
          viewportX = -width * 1 * (layer.animationType === AnimationType.RIGHT_TO_LEFT ? 1 : -1);
        }
      }
    }

    if (isLineActive) {
      const spotlightX = viewportX + currentWord.relativeX;
      ctx.save();
      const bloom = ctx.createRadialGradient(spotlightX, lineY, 0, spotlightX, lineY, baseFontSize * 5);
      bloom.addColorStop(0, 'rgba(251, 191, 36, 0.35)');
      bloom.addColorStop(1, 'transparent');
      ctx.fillStyle = bloom;
      ctx.fillRect(0, 0, width, height);
      ctx.restore();

      words.filter(w => w.lineIndex === lineIdx).forEach(w => {
        const isWordActive = progress >= w.start && progress <= w.end;
        ctx.save();
        ctx.translate(viewportX + w.relativeX, lineY);
        if (isWordActive) {
          ctx.shadowBlur = 50;
          ctx.shadowColor = 'rgba(251, 191, 36, 0.9)';
          ctx.fillStyle = '#fbbf24'; 
          const pulse = 1.0 + 0.05 * Math.sin(progress * Math.PI * 25);
          ctx.scale(pulse, pulse);
        } else {
          ctx.globalAlpha = progress > w.end ? 0.25 : 0.65;
          ctx.fillStyle = 'white';
        }
        ctx.fillText(w.text, 0, 0);
        ctx.restore();
      });
    } else {
      ctx.save();
      ctx.globalAlpha = 0.12 * focusFactor;
      ctx.fillStyle = 'white';
      if (focusFactor < 0.4) ctx.filter = `blur(${Math.max(0, (0.4 - focusFactor) * 20)}px)`;
      ctx.fillText(lineTextArray.join(' '), viewportX, lineY);
      ctx.restore();
    }
  });
};

const renderTextLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const duration = layer.endTime - layer.startTime;
  const localTime = time - layer.startTime;
  ctx.save();
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `${layer.fontSize}px Inter, sans-serif`;
  ctx.fillStyle = layer.color;
  let alpha = 1; let scale = 1; let offsetY = 0;
  if (layer.animation === 'fade') {
    if (localTime < 0.5) alpha = localTime / 0.5;
    else if (duration - localTime < 0.5) alpha = (duration - localTime) / 0.5;
  } else if (layer.animation === 'slide') {
    if (localTime < 0.5) offsetY = (1 - (localTime / 0.5)) * 50;
  } else if (layer.animation === 'bounce') {
    scale = 1 + 0.1 * Math.sin(localTime * 10);
  } else if (layer.animation === 'typewriter') {
    const charsToShow = Math.floor(layer.text.length * Math.min(1, localTime / (duration * 0.5)));
    ctx.fillText(layer.text.substring(0, charsToShow), width * layer.x, height * layer.y + offsetY);
    ctx.restore(); return;
  }
  ctx.globalAlpha = alpha;
  ctx.translate(width * layer.x, height * layer.y + offsetY);
  ctx.scale(scale, scale);
  ctx.fillText(layer.text, 0, 0);
  ctx.restore();
};

const renderImageLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const localTime = time - layer.startTime;
  const duration = layer.endTime - layer.startTime;
  const img = new Image(); img.src = layer.url;
  if (!img.complete) return;
  ctx.save();
  let scale = layer.scale; let alpha = 1;
  if (layer.animation === 'zoom') scale *= (1 + 0.2 * (localTime / duration));
  else if (layer.animation === 'fade') alpha = Math.min(1, localTime / 0.5) * Math.min(1, (duration - localTime) / 0.5);
  ctx.globalAlpha = alpha;
  const drawW = img.width * scale; const drawH = img.height * scale;
  ctx.drawImage(img, width * layer.x - drawW / 2, height * layer.y - drawH / 2, drawW, drawH);
  ctx.restore();
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  bg: HTMLImageElement | HTMLVideoElement | null,
  layers: EditorLayer[],
  currentTime: number,
  totalDuration: number
) => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  const { width, height } = canvas;
  ctx.fillStyle = '#020617';
  ctx.fillRect(0, 0, width, height);
  if (bg) {
    const bgW = bg instanceof HTMLVideoElement ? bg.videoWidth : bg.width;
    const bgH = bg instanceof HTMLVideoElement ? bg.videoHeight : bg.height;
    if (bgW > 0) {
      const scale = Math.max(width / bgW, height / bgH);
      ctx.globalAlpha = 0.55;
      ctx.drawImage(bg, (width - bgW * scale) / 2, (height - bgH * scale) / 2, bgW * scale, bgH * scale);
      ctx.globalAlpha = 1.0;
    }
  }
  const vignette = ctx.createRadialGradient(width/2, height/2, height * 0.1, width/2, height/2, height * 1.0);
  vignette.addColorStop(0, 'rgba(2, 6, 23, 0.15)');
  vignette.addColorStop(0.6, 'rgba(2, 6, 23, 0.5)');
  vignette.addColorStop(1, 'rgba(2, 6, 23, 0.98)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);
  const progress = currentTime / totalDuration;
  [...layers].sort((a, b) => a.zIndex - b.zIndex).forEach(layer => {
    if (!layer.visible) return;
    if (layer.type === LayerType.NARRATION) renderNarrationLayer(ctx, width, height, layer, progress, totalDuration);
    else if (layer.type === LayerType.TEXT) renderTextLayer(ctx, width, height, layer, currentTime);
    else if (layer.type === LayerType.IMAGE) renderImageLayer(ctx, width, height, layer, currentTime);
  });
  ctx.save(); ctx.globalAlpha = 0.25; ctx.font = `bold ${width * 0.022}px Inter, sans-serif`;
  ctx.fillStyle = 'white'; ctx.textAlign = 'center';
  ctx.fillText('NOOR STUDIO AI • CINEMATIC NARRATOR', width / 2, height * 0.96);
  ctx.restore();
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { 
  Video, Download, Loader2, Play, Pause, RotateCcw, Sparkles, History, Volume2, Mic2, ArrowLeft, 
  Image as ImageIcon, Smartphone, Monitor, Instagram, Facebook, AlertCircle, Edit3, Plus, Trash2, 
  Layers, Settings, Move, Type as TypeIcon, Sliders, X, Check, Save, Clock, Film
} from 'lucide-react';
import { 
  VoiceName, NarrationHistoryItem, GenerationSettings, AnimationType, 
  BackgroundSource, SEOMetadata, AspectRatio, EditorLayer, LayerType, TextEffect, ImageEffect, ImageSize 
} from './types';
import { generateNarration, generateAtmosphereImage, generateSEOMetadata, generateProImage, generateVeoVideo } from './services/geminiService';
import { decode, decodeAudioData } from './utils/audioUtils';
import { drawVideoFrame } from './utils/videoUtils';

const DEFAULT_TEXT = `سکون کی نیند اور اللہ کی حفاظت۔ ✨\nنبی کریم صلی اللہ علیہ وآلہ وسلم کا بتایا ہوا ایک ایسا عمل جو ہمیں رات بھر شیطان کے شر سے محفوظ رکھتا ہے۔ 🌙\nآپ صلی اللہ علیہ وآلہ وسلم نے فرمایا: "جب تم رات کو اپنے بستر پر سونے کے لیے جاؤ تو آیت الکرسی پڑھ لیا کرو۔" 📖\nصحیح البخاری حدیث نمبر 5010۔`;
const STORAGE_KEY = 'noor_last_used_text';

const ASPECT_RATIO_CONFIG = {
  [AspectRatio.VERTICAL]: { width: 1080, height: 1920, label: "Reels / TikTok", icon: Smartphone },
  [AspectRatio.LANDSCAPE]: { width: 1920, height: 1080, label: "YouTube / Desktop", icon: Monitor },
  [AspectRatio.SQUARE]: { width: 1080, height: 1080, label: "Instagram Feed", icon: Instagram },
  [AspectRatio.FEED]: { width: 1080, height: 1350, label: "Facebook / Portrait", icon: Facebook },
};

type PlaybackStatus = 'playing' | 'paused' | 'stopped';

const App: React.FC = () => {
  const [settings, setSettings] = useState<GenerationSettings>(() => {
    const savedText = localStorage.getItem(STORAGE_KEY);
    return {
      text: savedText || DEFAULT_TEXT,
      voice: VoiceName.CHARON,
      generateImage: true,
      style: "Starry night sky over a peaceful mosque silhouette",
      animationType: AnimationType.VERTICAL_SCROLL,
      aspectRatio: AspectRatio.VERTICAL,
      backgroundSource: BackgroundSource.AI,
      imageSize: '1K'
    };
  });

  const [isGenerating, setIsGenerating] = useState(false);
  const [isGeneratingPro, setIsGeneratingPro] = useState(false);
  const [isAnimatingVeo, setIsAnimatingVeo] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordProgress, setRecordProgress] = useState(0);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [playbackStatus, setPlaybackStatus] = useState<PlaybackStatus>('stopped');
  const [isEditing, setIsEditing] = useState(false);

  const [currentResult, setCurrentResult] = useState<{ 
    audioUrl: string; 
    imageUrl?: string; 
    videoUrl?: string;
    audioBuffer?: AudioBuffer;
    base64Audio: string;
    seo?: SEOMetadata;
  } | null>(null);

  const [layers, setLayers] = useState<EditorLayer[]>([]);
  const [selectedLayerId, setSelectedLayerId] = useState<string | null>(null);
  const [history, setHistory] = useState<NarrationHistoryItem[]>([]);
  const [showHistory, setShowHistory] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const recordCanvasRef = useRef<HTMLCanvasElement>(null);
  const backgroundVideoRef = useRef<HTMLVideoElement | null>(null);
  const stopSignalRef = useRef<boolean>(false);
  const previewRequestRef = useRef<number>(0);
  const currentPreviewSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const playbackStartTimeRef = useRef<number>(0);
  const pauseOffsetRef = useRef<number>(0);

  const duration = useMemo(() => currentResult?.audioBuffer?.duration || 10, [currentResult]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, settings.text);
  }, [settings.text]);

  useEffect(() => {
    if (currentResult) {
      setLayers(prev => {
        const existing = prev.find(l => l.id === 'narration-main');
        if (existing) {
          return prev.map(l => l.id === 'narration-main' ? { ...l, text: settings.text, animationType: settings.animationType, endTime: duration } : l) as EditorLayer[];
        }
        return [
          {
            id: 'narration-main',
            type: LayerType.NARRATION,
            startTime: 0,
            endTime: duration,
            visible: true,
            zIndex: 1,
            text: settings.text,
            animationType: settings.animationType
          }
        ];
      });
    }
  }, [currentResult, duration, settings.text, settings.animationType]);

  useEffect(() => {
    const draw = () => {
      if (!canvasRef.current) return;
      const config = ASPECT_RATIO_CONFIG[settings.aspectRatio];
      if (canvasRef.current.width !== config.width || canvasRef.current.height !== config.height) {
        canvasRef.current.width = config.width;
        canvasRef.current.height = config.height;
      }

      let bg: any = null;
      const activeVideoUrl = currentResult?.videoUrl || (settings.customBackgroundType === 'video' ? settings.customBackgroundUrl : null);
      const activeImageUrl = currentResult?.imageUrl || (settings.customBackgroundType === 'image' ? settings.customBackgroundUrl : null);

      if (activeVideoUrl) {
        if (!backgroundVideoRef.current || backgroundVideoRef.current.src !== activeVideoUrl) {
          const v = document.createElement('video');
          v.src = activeVideoUrl;
          v.muted = true; v.loop = true; v.crossOrigin = "anonymous";
          v.play().catch(() => {});
          backgroundVideoRef.current = v;
        }
        bg = backgroundVideoRef.current;
      } else if (activeImageUrl) {
        const img = new Image(); img.crossOrigin = "anonymous"; img.src = activeImageUrl; bg = img;
      }

      let time = 0;
      if (playbackStatus === 'playing' && audioContextRef.current) {
        time = pauseOffsetRef.current + (audioContextRef.current.currentTime - playbackStartTimeRef.current);
      } else if (playbackStatus === 'paused') {
        time = pauseOffsetRef.current;
      }
      drawVideoFrame(canvasRef.current, bg, layers, time % duration, duration);
      previewRequestRef.current = requestAnimationFrame(draw);
    };
    draw();
    return () => cancelAnimationFrame(previewRequestRef.current);
  }, [currentResult, settings, playbackStatus, layers, duration]);

  const handleGenerate = async () => {
    if (!settings.text.trim()) return;
    setIsGenerating(true); setErrorMsg(null); stopSignalRef.current = false;
    setCurrentResult(null); stopPreview();
    try {
      if (!audioContextRef.current) audioContextRef.current = new AudioContext({ sampleRate: 24000 });
      const base64Audio = await generateNarration(settings.text, settings.voice);
      if (stopSignalRef.current) return;
      const audioData = decode(base64Audio);
      const audioBuffer = await decodeAudioData(audioData, audioContextRef.current, 24000, 1);
      const audioUrl = URL.createObjectURL(new Blob([audioData], { type: 'audio/pcm' }));
      const seoPromise = generateSEOMetadata(settings.text);
      const imageUrlPromise = (settings.backgroundSource === BackgroundSource.AI && settings.generateImage) ? generateAtmosphereImage(settings.style) : Promise.resolve(null);
      const [seo, imageUrl] = await Promise.all([seoPromise, imageUrlPromise]);
      if (stopSignalRef.current) return;
      setCurrentResult({ audioUrl, imageUrl: imageUrl || undefined, audioBuffer, base64Audio, seo });
      setHistory(prev => [{ id: Date.now().toString(), text: settings.text, voice: settings.voice, timestamp: Date.now(), audioUrl, imageUrl: imageUrl || undefined, seo, aspectRatio: settings.aspectRatio }, ...prev]);
    } catch (e: any) {
      if (!stopSignalRef.current) setErrorMsg(e.message || "An error occurred.");
    } finally { setIsGenerating(false); }
  };

  const handleGenerateProImage = async () => {
    setIsGeneratingPro(true);
    setErrorMsg(null);
    try {
      const url = await generateProImage(settings.style || settings.text, settings.imageSize, settings.aspectRatio);
      setCurrentResult(prev => prev ? { ...prev, imageUrl: url } : null);
    } catch (e: any) {
      setErrorMsg(e.message || "Pro image generation failed.");
    } finally {
      setIsGeneratingPro(false);
    }
  };

  const handleAnimateVeo = async () => {
    if (!currentResult?.imageUrl) return;
    setIsAnimatingVeo(true);
    setErrorMsg(null);
    try {
      const videoUrl = await generateVeoVideo(settings.style || settings.text, currentResult.imageUrl, settings.aspectRatio);
      setCurrentResult(prev => prev ? { ...prev, videoUrl } : null);
    } catch (e: any) {
      setErrorMsg(e.message || "Veo animation failed.");
    } finally {
      setIsAnimatingVeo(false);
    }
  };

  const playPreview = async () => {
    if (!currentResult?.audioBuffer || !audioContextRef.current) return;
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') await ctx.resume();
    if (pauseOffsetRef.current >= duration) pauseOffsetRef.current = 0;
    const source = ctx.createBufferSource();
    source.buffer = currentResult.audioBuffer;
    source.connect(ctx.destination);
    currentPreviewSourceRef.current = source;
    source.onended = () => { if (currentPreviewSourceRef.current === source) { setPlaybackStatus('stopped'); pauseOffsetRef.current = 0; currentPreviewSourceRef.current = null; } };
    source.start(0, pauseOffsetRef.current);
    playbackStartTimeRef.current = ctx.currentTime;
    setPlaybackStatus('playing');
  };

  const pausePreview = () => {
    if (!currentPreviewSourceRef.current || !audioContextRef.current) return;
    pauseOffsetRef.current += (audioContextRef.current.currentTime - playbackStartTimeRef.current);
    currentPreviewSourceRef.current.stop();
    currentPreviewSourceRef.current = null;
    setPlaybackStatus('paused');
  };

  const stopPreview = () => {
    if (currentPreviewSourceRef.current) { currentPreviewSourceRef.current.stop(); currentPreviewSourceRef.current = null; }
    pauseOffsetRef.current = 0; setPlaybackStatus('stopped');
  };

  const startExport = async () => {
    if (!currentResult?.audioBuffer) return;
    stopPreview(); setIsRecording(true); setRecordProgress(0);
    const config = ASPECT_RATIO_CONFIG[settings.aspectRatio];
    const canvas = recordCanvasRef.current!;
    canvas.width = config.width; canvas.height = config.height;
    const stream = canvas.captureStream(60);
    const audioCtx = audioContextRef.current!;
    const dest = audioCtx.createMediaStreamDestination();
    const recorder = new MediaRecorder(new MediaStream([...stream.getTracks(), ...dest.stream.getTracks()]), { mimeType: 'video/webm;codecs=vp9' });
    const chunks: Blob[] = [];
    recorder.ondataavailable = e => chunks.push(e.data);
    recorder.onstop = () => { const blob = new Blob(chunks, { type: 'video/webm' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `noor-studio-${Date.now()}.webm`; a.click(); setIsRecording(false); };

    let bg: any = null;
    const activeBgUrl = currentResult.videoUrl || currentResult.imageUrl;
    const isVideo = !!currentResult.videoUrl;

    if (isVideo && activeBgUrl) {
      bg = document.createElement('video'); bg.src = activeBgUrl; bg.muted = true; bg.crossOrigin = "anonymous";
      await new Promise(r => bg.onloadeddata = r); bg.play();
    } else if (activeBgUrl) {
      bg = new Image(); bg.crossOrigin = "anonymous"; bg.src = activeBgUrl; await new Promise(r => bg.onload = r);
    }

    const sourceNode = audioCtx.createBufferSource();
    sourceNode.buffer = currentResult.audioBuffer;
    sourceNode.connect(dest); recorder.start(); sourceNode.start();
    const startTime = audioCtx.currentTime;
    const renderLoop = () => {
      const elapsed = audioCtx.currentTime - startTime;
      const progress = Math.min(elapsed / duration, 1);
      if (bg instanceof HTMLVideoElement) bg.currentTime = elapsed % bg.duration;
      drawVideoFrame(canvas, bg, layers, elapsed, duration);
      setRecordProgress(progress * 100);
      if (progress < 1) requestAnimationFrame(renderLoop);
      else setTimeout(() => recorder.stop(), 500);
    };
    renderLoop();
  };

  const addLayer = (type: LayerType) => {
    const id = `layer-${Date.now()}`;
    if (type === LayerType.TEXT) {
      setLayers([...layers, { id, type, text: 'New Text', fontSize: 60, color: '#FFFFFF', animation: 'fade', x: 0.5, y: 0.5, startTime: 0, endTime: duration, visible: true, zIndex: layers.length + 1 }]);
    } else if (type === LayerType.IMAGE) {
      setLayers([...layers, { id, type, url: 'https://images.unsplash.com/photo-1518173946687-a4c8a9833d8e?w=800', animation: 'zoom', x: 0.5, y: 0.5, scale: 0.5, startTime: 0, endTime: duration, visible: true, zIndex: layers.length + 1 }]);
    }
    setSelectedLayerId(id);
  };

  const updateLayer = (id: string, updates: Partial<EditorLayer>) => {
    setLayers(layers.map(l => l.id === id ? { ...l, ...updates } as any : l));
  };

  const deleteLayer = (id: string) => {
    setLayers(layers.filter(l => l.id !== id));
    if (selectedLayerId === id) setSelectedLayerId(null);
  };

  const selectedLayer = layers.find(l => l.id === selectedLayerId);

  return (
    <div className="min-h-screen flex flex-col items-center bg-[#020617] p-4 md:p-8">
      <canvas ref={recordCanvasRef} className="hidden" />

      <header className="w-full max-w-6xl flex justify-between items-center mb-10 relative z-20">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-emerald-800 rounded-2xl shadow-xl shadow-emerald-950/50">
            <Video className="w-8 h-8 text-yellow-400" />
          </div>
          <div>
            <h1 className="text-3xl font-bold text-white tracking-tight">Noor Narrator Studio</h1>
            <p className="text-sm text-emerald-500 font-semibold tracking-widest uppercase">AI Voice & Cinematic Design</p>
          </div>
        </div>
        <div className="flex gap-4">
          <button onClick={() => setShowHistory(!showHistory)} className="px-5 py-2.5 glass-card rounded-xl hover:bg-emerald-900/40 transition-all flex items-center gap-2 border border-emerald-900/50">
            {showHistory ? <ArrowLeft className="w-5 h-5" /> : <History className="w-5 h-5" />}
            <span className="hidden sm:inline font-bold">{showHistory ? "Back" : "Archive"}</span>
          </button>
        </div>
      </header>

      {isEditing && currentResult ? (
        <div className="fixed inset-0 z-50 bg-[#020617] flex flex-col p-6 overflow-hidden">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-2xl font-black text-white flex items-center gap-3">
              <Edit3 className="text-emerald-500" /> Cinematic Editor
            </h2>
            <div className="flex gap-3">
               <button onClick={() => setIsEditing(false)} className="px-6 py-2 bg-slate-800 text-white rounded-xl font-bold flex items-center gap-2 hover:bg-slate-700 transition-colors">
                 <X className="w-5 h-5" /> Close
               </button>
               <button onClick={startExport} className="px-6 py-2 bg-emerald-600 text-white rounded-xl font-bold flex items-center gap-2 hover:bg-emerald-500 transition-colors">
                 <Save className="w-5 h-5" /> Export
               </button>
            </div>
          </div>

          <div className="flex-1 grid grid-cols-12 gap-8 overflow-hidden mb-6">
            <div className="col-span-3 glass-card rounded-3xl p-6 overflow-y-auto custom-scrollbar border-emerald-900/30">
              <div className="flex items-center gap-2 mb-6 text-emerald-400 font-black uppercase tracking-widest text-xs">
                <Layers className="w-4 h-4" /> Timeline Layers
              </div>
              <div className="space-y-3">
                {layers.map(layer => (
                  <button 
                    key={layer.id}
                    onClick={() => setSelectedLayerId(layer.id)}
                    className={`w-full p-4 rounded-2xl flex items-center justify-between border transition-all ${selectedLayerId === layer.id ? 'bg-emerald-600/20 border-emerald-500 text-emerald-200' : 'bg-slate-900/50 border-emerald-900/20 text-slate-400'}`}
                  >
                    <div className="flex items-center gap-3">
                      {layer.type === LayerType.TEXT ? <TypeIcon className="w-4 h-4" /> : layer.type === LayerType.IMAGE ? <ImageIcon className="w-4 h-4" /> : <Mic2 className="w-4 h-4" />}
                      <span className="text-xs font-bold truncate max-w-[120px]">
                        {layer.type === LayerType.TEXT ? (layer as any).text : layer.type === LayerType.IMAGE ? 'Overlay Image' : 'Sync Text'}
                      </span>
                    </div>
                    {layer.type !== LayerType.NARRATION && (
                      <Trash2 onClick={(e) => { e.stopPropagation(); deleteLayer(layer.id); }} className="w-4 h-4 text-red-500 hover:text-red-400" />
                    )}
                  </button>
                ))}
              </div>
            </div>

            <div className="col-span-6 flex flex-col items-center justify-center">
              <div className="relative group rounded-3xl overflow-hidden border-8 border-emerald-900/20 shadow-2xl bg-black" style={{ height: '70vh', aspectRatio: settings.aspectRatio.replace(':', '/') }}>
                <canvas ref={canvasRef} className="w-full h-full object-contain" />
              </div>
            </div>

            <div className="col-span-3 glass-card rounded-3xl p-6 overflow-y-auto custom-scrollbar border-emerald-900/30">
              <div className="flex items-center gap-2 mb-6 text-yellow-500 font-black uppercase tracking-widest text-xs">
                <Sliders className="w-4 h-4" /> Properties
              </div>
              {selectedLayer ? (
                <div className="space-y-6">
                  {selectedLayer.type === LayerType.TEXT && (
                    <div className="space-y-4">
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-emerald-600 uppercase">Text</label>
                        <textarea value={(selectedLayer as any).text} onChange={(e) => updateLayer(selectedLayer.id, { text: e.target.value })} className="w-full bg-black/40 border border-emerald-900/40 rounded-xl p-3 text-white text-sm focus:outline-none" />
                      </div>
                    </div>
                  )}
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                      <label className="text-[8px] font-bold text-slate-500 uppercase">Start</label>
                      <input type="number" step="0.1" value={selectedLayer.startTime} onChange={(e) => updateLayer(selectedLayer.id, { startTime: Number(e.target.value) })} className="w-full bg-black/40 border border-emerald-900/40 rounded-xl p-2 text-white text-xs" />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[8px] font-bold text-slate-500 uppercase">End</label>
                      <input type="number" step="0.1" value={selectedLayer.endTime} onChange={(e) => updateLayer(selectedLayer.id, { endTime: Number(e.target.value) })} className="w-full bg-black/40 border border-emerald-900/40 rounded-xl p-2 text-white text-xs" />
                    </div>
                  </div>
                </div>
              ) : null}
            </div>
          </div>
        </div>
      ) : null}

      <main className="w-full max-w-6xl grid grid-cols-1 lg:grid-cols-12 gap-10 relative z-10">
        {!showHistory ? (
          <>
            <div className="lg:col-span-7 space-y-6 animate-fade-in">
              <section className="glass-card rounded-3xl p-8 shadow-2xl border-emerald-900/20">
                <div className="flex items-center justify-between mb-6">
                  <h2 className="text-xl font-bold flex items-center gap-3 text-yellow-500">
                    <Mic2 className="w-6 h-6" /> Script Editor
                  </h2>
                </div>
                {errorMsg && (
                  <div className="mb-6 p-4 bg-red-900/20 border border-red-500/30 rounded-2xl flex items-start gap-3">
                    <AlertCircle className="w-5 h-5 text-red-500 mt-0.5 shrink-0" />
                    <div className="text-sm text-red-200"><p>{errorMsg}</p></div>
                  </div>
                )}
                <textarea className="urdu-font w-full h-56 bg-black/40 border border-emerald-900/40 rounded-2xl p-6 text-2xl text-emerald-50 focus:outline-none focus:ring-4 focus:ring-emerald-600/20 transition-all resize-none shadow-inner" placeholder="یہاں اپنا اردو متن لکھیں..." value={settings.text} onChange={(e) => setSettings({ ...settings, text: e.target.value })} dir="rtl" />

                <div className="mt-8 p-6 bg-emerald-950/20 border border-emerald-900/30 rounded-3xl space-y-6">
                  <h3 className="text-sm font-black text-emerald-400 uppercase tracking-[0.2em] flex items-center gap-2">
                    <Sparkles className="w-4 h-4" /> Cinematic Pro Tools
                  </h3>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-4">
                      <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Nano Banana Pro (Background)</label>
                      <div className="flex gap-2">
                        {(['1K', '2K', '4K'] as ImageSize[]).map(size => (
                          <button key={size} onClick={() => setSettings({ ...settings, imageSize: size })} className={`flex-1 p-2 text-[10px] font-bold rounded-lg border transition-all ${settings.imageSize === size ? 'bg-emerald-600 border-emerald-400 text-white' : 'bg-black/20 border-emerald-900/40 text-slate-500'}`}>{size}</button>
                        ))}
                      </div>
                      <button onClick={handleGenerateProImage} disabled={isGeneratingPro || !settings.text} className="w-full p-4 bg-yellow-500/10 text-yellow-500 border border-yellow-500/30 rounded-xl hover:bg-yellow-500/20 transition-all font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-2">
                        {isGeneratingPro ? <Loader2 className="w-4 h-4 animate-spin" /> : <ImageIcon className="w-4 h-4" />} High-Res Image
                      </button>
                    </div>

                    <div className="space-y-4">
                      <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Veo 3 (Animation)</label>
                      <button onClick={handleAnimateVeo} disabled={isAnimatingVeo || !currentResult?.imageUrl} className="w-full h-full p-4 bg-emerald-500/10 text-emerald-400 border border-emerald-500/30 rounded-xl hover:bg-emerald-500/20 transition-all font-black uppercase text-[10px] tracking-widest flex flex-col items-center justify-center gap-2">
                        {isAnimatingVeo ? <><Loader2 className="w-6 h-6 animate-spin" /> <span>Animating...</span></> : <><Film className="w-6 h-6" /> <span>Veo Animation</span></>}
                      </button>
                    </div>
                  </div>
                </div>

                <div className="mt-8 grid grid-cols-1 sm:grid-cols-2 gap-6">
                   <div className="space-y-3">
                    <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Narrator</label>
                    <select className="w-full bg-emerald-950/50 border border-emerald-900/40 rounded-xl p-4 text-sm text-emerald-100 focus:outline-none" value={settings.voice} onChange={(e) => setSettings({ ...settings, voice: e.target.value as VoiceName })}>
                      <option value={VoiceName.CHARON}>Charon - Deep & Spiritual</option>
                      <option value={VoiceName.ZEPHYR}>Zephyr - Elegant Female</option>
                    </select>
                  </div>
                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Animation</label>
                    <select className="w-full bg-emerald-950/50 border border-emerald-900/40 rounded-xl p-4 text-sm text-emerald-100 focus:outline-none" value={settings.animationType} onChange={(e) => setSettings({ ...settings, animationType: e.target.value as AnimationType })}>
                      <option value={AnimationType.VERTICAL_SCROLL}>Vertical Read</option>
                      <option value={AnimationType.RIGHT_TO_LEFT}>Horizontal Scroll</option>
                    </select>
                  </div>
                </div>

                <div className="mt-8">
                  <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest block mb-4">Ratio</label>
                  <div className="grid grid-cols-4 gap-4">
                    {Object.entries(ASPECT_RATIO_CONFIG).map(([key, config]) => (
                      <button key={key} onClick={() => setSettings({ ...settings, aspectRatio: key as AspectRatio })} className={`flex flex-col items-center gap-2 p-3 rounded-xl border transition-all ${settings.aspectRatio === key ? 'bg-emerald-600/30 border-emerald-500 text-emerald-200' : 'bg-black/20 border-emerald-900/20 text-slate-500'}`}>
                        <config.icon className="w-5 h-5" />
                        <span className="text-[10px] font-black uppercase text-center">{config.label.split(' ')[0]}</span>
                      </button>
                    ))}
                  </div>
                </div>

                <div className="mt-10">
