import { GoogleGenAI, Modality, Type } from "@google/genai";
import { VoiceName, SEOMetadata, ImageSize, AspectRatio } from "../types";

const safetySettings = [
  { category: "HARM_CATEGORY_HARASSMENT", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_HATE_SPEECH", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_SEXUALLY_EXPLICIT", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_DANGEROUS_CONTENT", threshold: "BLOCK_NONE" },
];

const sanitizeForTTS = (text: string): string => {
  return text
    .replace(/[\u{1F000}-\u{1F9FF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B50}\u{2B55}]/gu, '')
    .replace(/\s+/g, ' ')
    .trim();
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const getTTSPrompt = (text: string): string => {
  return `Recite the following text with professional eloquence. Pay special attention to the correct Tajweed and beautiful pronunciation of Arabic phrases. The tone should be spiritual, calm, and deeply narrative: "${text}"`;
};

/**
 * Ensures a paid API key is selected for Pro/Veo models.
 */
export const ensureProKey = async (): Promise<void> => {
  // @ts-ignore
  if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
    // @ts-ignore
    await window.aistudio.openSelectKey();
  }
};

export const generateNarration = async (text: string, voice: VoiceName, retryCount = 0): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const cleanText = sanitizeForTTS(text);
  if (!cleanText) throw new Error("Text is empty after cleaning.");

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: getTTSPrompt(cleanText) }] }],
      config: {
        responseModalities: [Modality.AUDIO], 
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voice },
          },
        },
        safetySettings: safetySettings as any,
      },
    });

    if (response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data) {
      return response.candidates[0].content.parts[0].inlineData.data;
    }
    throw new Error("Audio data not found.");
  } catch (error: any) {
    if (retryCount < 3) {
      await delay(2000 * (retryCount + 1));
      return generateNarration(text, voice, retryCount + 1);
    }
    throw error;
  }
};

export const generateProImage = async (prompt: string, size: ImageSize = '1K', ratio: AspectRatio = AspectRatio.VERTICAL) => {
  await ensureProKey();
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-image-preview',
    contents: { parts: [{ text: `Cinematic Atmosphere: ${prompt}. Atmospheric lighting, photorealistic, no text, religious serenity.` }] },
    config: {
      imageConfig: {
        aspectRatio: ratio as any,
        imageSize: size
      }
    }
  });

  const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
  if (part?.inlineData?.data) {
    return `data:image/png;base64,${part.inlineData.data}`;
  }
  throw new Error("Pro image generation failed.");
};

export const generateVeoVideo = async (prompt: string, imageBase64: string, ratio: AspectRatio = AspectRatio.VERTICAL) => {
  await ensureProKey();
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const cleanBase64 = imageBase64.replace(/^data:image\/\w+;base64,/, "");

  let operation = await ai.models.generateVideos({
    model: 'veo-3.1-fast-generate-preview',
    prompt: `Animate this scene gracefully: ${prompt}. Subtle camera movement, cinematic atmosphere, floating particles.`,
    image: {
      imageBytes: cleanBase64,
      mimeType: 'image/png'
    },
    config: {
      numberOfVideos: 1,
      resolution: '1080p',
      aspectRatio: ratio === AspectRatio.LANDSCAPE ? '16:9' : '9:16'
    }
  });

  while (!operation.done) {
    await delay(10000);
    operation = await ai.operations.getVideosOperation({ operation: operation as any });
  }

  const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
  if (!downloadLink) throw new Error("Video generation failed.");

  const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
  const blob = await response.blob();
  return URL.createObjectURL(blob);
};

export const generateSEOMetadata = async (script: string): Promise<SEOMetadata> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Provide JSON viral SEO (Title, Description, Keywords) for this script: ${script}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          description: { type: Type.STRING },
          keywords: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["title", "description", "keywords"]
      }
    }
  });
  return JSON.parse(response.text || '{}') as SEOMetadata;
};

export const generateAtmosphereImage = async (prompt: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `Atmosphere: ${prompt}. Cinematic masterpiece, dramatic lighting, 8k resolution, no text, artistic silhouette.` }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData?.data);
