                <button onClick={handleGenerate} disabled={isGenerating || isRecording || !settings.text.trim()} className="mt-10 w-full bg-gradient-to-br from-emerald-500 to-emerald-800 hover:from-emerald-400 hover:to-emerald-700 disabled:opacity-50 text-white font-black py-5 px-8 rounded-2xl shadow-2xl transition-all flex items-center justify-center gap-4 group uppercase tracking-[0.2em] text-sm">
