  ZEPHYR = 'Zephyr'
}

export enum AnimationType {
  VERTICAL_SCROLL = 'Vertical Scroll',
  LEFT_TO_RIGHT = 'Left to Right',
  RIGHT_TO_LEFT = 'Right to Left',
}

export enum BackgroundAnimation {
  NONE = 'None',
  ZOOM_IN = 'Zoom In',
  ZOOM_OUT = 'Zoom Out',
  PAN_LEFT = 'Pan Left',
  PAN_RIGHT = 'Pan Right'
}

export enum AspectRatio {
  VERTICAL = '9:16',
  LANDSCAPE = '16:9',
  SQUARE = '1:1',
  FEED = '4:5'
}

