import { GoogleGenAI, Modality, Type } from "@google/genai";
import { VoiceName, SEOMetadata } from "../types";

const safetySettings = [
  { category: "HARM_CATEGORY_HARASSMENT", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_HATE_SPEECH", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_SEXUALLY_EXPLICIT", threshold: "BLOCK_NONE" },
  { category: "HARM_CATEGORY_DANGEROUS_CONTENT", threshold: "BLOCK_NONE" },
];

/**
 * Sanitizes text by removing non-textual decorative elements while preserving
 * the original sacred and linguistic integrity of Arabic/Urdu content.
 */
const sanitizeForTTS = (text: string): string => {
  // Level 0: Clean Emojis and non-pronounceable decorative symbols only.
  // We strictly preserve names like "Allah", "Ayat-ul-Kursi", and "Bukhari".
  return text
    .replace(/[\u{1F000}-\u{1F9FF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B50}\u{2B55}]/gu, '')
    // CRITICAL FIX: Replace EACH newline with a full stop + space. 
    // This allows multiple newlines to generate longer pauses (e.g. "..\n\n.." -> ". . "), 
    // syncing with the visual engine which adds weight per empty line.
    .replace(/\n/g, '. ')
    .replace(/\s+/g, ' ')
    .trim();
};

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Enhanced prompt for beautiful religious and literary narration.
 */
const getTTSPrompt = (text: string): string => {
  return `Recite the following text with professional eloquence. Pay special attention to the correct Tajweed and beautiful pronunciation of Arabic phrases. The tone should be spiritual, calm, and deeply narrative: "${text}"`;
};

export const generateNarration = async (text: string, voice: VoiceName, retryCount = 0): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const cleanText = sanitizeForTTS(text);

  if (!cleanText) {
    throw new Error("Text is empty after cleaning.");
  }

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ 
        parts: [{ 
          text: getTTSPrompt(cleanText)
        }] 
      }],
      config: {
        responseModalities: [Modality.AUDIO], 
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voice },
          },
        },
        safetySettings: safetySettings as any,
      },
    });

    if (!response.candidates || response.candidates.length === 0) {
      throw new Error("No response candidates from AI.");
    }

    const candidate = response.candidates[0];

    // Handle Finish Reason
    if (candidate.finishReason && candidate.finishReason !== 'STOP') {
       if (retryCount < 3) {
         await delay(1500 * (retryCount + 1));
         return generateNarration(text, voice, retryCount + 1);
       }
       throw new Error(`Narration failed: ${candidate.finishReason}. The content might be too long or restricted.`);
    }

    const audioPart = candidate.content?.parts?.find(p => p.inlineData?.data);
    if (audioPart?.inlineData?.data) {
      return audioPart.inlineData.data;
    }

    throw new Error("Audio data not found in response.");

  } catch (error: any) {
    const errorString = (error.message || "").toLowerCase();

    if (retryCount < 3) {
      console.warn(`Retryable error: ${errorString}. Retrying...`);
      await delay(2000 * (retryCount + 1));
      return generateNarration(text, voice, retryCount + 1);
    }
    throw error;
  }
};

export const generateSEOMetadata = async (script: string): Promise<SEOMetadata> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Analyze this Islamic video script and generate viral SEO metadata in JSON format.

    1. **Title**: Create a high-CTR, trending title that **MUST** combine **Urdu script** and **English text**.
       - This hybrid format is critical for maximizing reach across both Urdu and English speaking audiences.
       - Format examples: 
         - "Urdu Hook | English Hook"
         - "English Title - Urdu Title"
         - "Urdu Phrase (English Translation)"
       - Make it click-worthy and emotional.

    2. **Description**: Write a deeply engaging, spiritual description. Use bullet points and emojis to make it readable.

    3. **Keywords**: Generate a list of 15+ trending tags. Include a mix of:
       - English keywords (e.g., #IslamicStatus, #Hadith)
       - Urdu keywords in Urdu script (e.g., #اسلام, #بیان)
       - Roman Urdu keywords (e.g., #Sukun, #Allah)

    Script: ${script}
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          description: { type: Type.STRING },
          keywords: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["title", "description", "keywords"]
      }
    }
  });
  return JSON.parse(response.text || '{}') as SEOMetadata;
};

/**
 * Generates a concise, artistic image prompt based on the provided script.
 */
export const generateVisualPrompt = async (script: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Read the following Urdu/English script and describe a SINGLE, static, cinematic background image that perfectly matches the mood and content.

    Script: "${script}"

    Rules:
    - Return ONLY the visual description string.
    - Focus on lighting, atmosphere, setting, and color palette.
    - Do NOT include people faces if possible (silhouette is okay).
    - Style: 8k resolution, photorealistic or digital art masterpiece.
    - Keep it under 40 words.`,
  });

  return response.text?.trim() || "A peaceful, starry night sky over a silhouette of a mosque, cinematic lighting.";
};

export const generateAtmosphereImage = async (prompt: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `Atmosphere: ${prompt}. Cinematic masterpiece, dramatic lighting, 8k resolution, no text, artistic silhouette.` }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData?.data);
    return part ? `data:image/png;base64,${part.inlineData.data}` : null;
  } catch { return null; }
};

import { AnimationType, EditorLayer, LayerType, TextEffect, ImageEffect, BackgroundAnimation } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  relativeX: number; // Offset from the line's geometric center
  globalY: number;
}

/**
 * Standard cubic easing for smooth transitions.
 */
const easeInOutCubic = (t: number): number => {
  const clampedT = Math.max(0, Math.min(1, t));
  return clampedT < 0.5 ? 4 * clampedT * clampedT * clampedT : 1 - Math.pow(-2 * clampedT + 2, 3) / 2;
};

/**
 * Calculates words and lines with high precision for RTL alignment.
 * Implements gapless timing to ensure continuous visibility of subtitles.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number
): { lines: string[][], words: WordMetadata[] } => {
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;
  ctx.direction = 'rtl';

  // Note: We split by newlines to preserve paragraph structure
  const paragraphs = text.split('\n');
  const wordsMetadata: WordMetadata[] = [];
  const lines: string[][] = [];

  // Tuning weights for Urdu/English TTS synchronization
  // Significantly increased to prevent visual layer from rushing ahead of audio
  const WEIGHT_START_PAD = 150; // Delay start to account for audio lead-in
  const WEIGHT_BASE = 25;       // Per word base duration
  const WEIGHT_CHAR = 10;       // Per character duration (Urdu chars are dense)
  const WEIGHT_STOP = 200;      // Full stop, question mark (Strong pause)
  const WEIGHT_COMMA = 80;      // Comma, colon (Medium pause)
  const WEIGHT_PARA = 250;      // Pause at end of paragraph content
  const WEIGHT_EMPTY_LINE = 200; // Pause for empty lines (multiple breaks)

  // 1. Calculate total timing weights
  let totalWeight = WEIGHT_START_PAD;
  paragraphs.forEach((p) => {
    const trimmed = p.trim();
    if (trimmed === '') { 
      // Add weight for empty lines to sync with audio silence
      totalWeight += WEIGHT_EMPTY_LINE; 
      return; 
    }
    const wordsInPara = trimmed.split(/\s+/).filter(w => w.length > 0);
    wordsInPara.forEach((w, idx) => {
      let wWeight = WEIGHT_BASE + (w.length * WEIGHT_CHAR);
      // Added ASCII punctuation support (., ?)
      if (w.match(/[۔؟!.\?]/)) wWeight += WEIGHT_STOP;
      else if (w.match(/[،:,]/)) wWeight += WEIGHT_COMMA;

      // Add paragraph pause to the last word of the block
      if (idx === wordsInPara.length - 1) {
        wWeight += WEIGHT_PARA;
      }
      totalWeight += wWeight;
    });
  });

  // Prevent divide by zero
  if (totalWeight === 0) totalWeight = 100;

  let weightCursor = WEIGHT_START_PAD;
  let currentLineIdx = 0;
  const spaceWidth = ctx.measureText(' ').width;

  paragraphs.forEach((paragraph) => {
    const trimmed = paragraph.trim();
    if (trimmed === '') {
      // Just advance the cursor for the silence
      weightCursor += WEIGHT_EMPTY_LINE;

      // Visual spacer line
      lines.push(['']); 
      currentLineIdx++;
      return;
    }

    const wordsInPara = trimmed.split(/\s+/).filter(w => w.length > 0);
    let currentLineWords: string[] = [];
    let currentLineWidth = 0;
    let lineStartWordIdx = wordsMetadata.length;

    for (let i = 0; i < wordsInPara.length; i++) {
      const word = wordsInPara[i];
      const wordWidth = ctx.measureText(word).width;

      const prospectiveWidth = currentLineWidth + (currentLineWords.length > 0 ? spaceWidth : 0) + wordWidth;
      if (prospectiveWidth > maxWidth && currentLineWords.length > 0) {
        finalizeLineAlignment(ctx, wordsMetadata, lineStartWordIdx, currentLineWords);
        lines.push(currentLineWords);
        currentLineWords = [];
        currentLineWidth = 0;
        currentLineIdx++;
        lineStartWordIdx = wordsMetadata.length;
      }

      let wordWeight = WEIGHT_BASE + (word.length * WEIGHT_CHAR);
      // Added ASCII punctuation support
      if (word.match(/[۔؟!.\?]/)) wordWeight += WEIGHT_STOP;
      else if (word.match(/[،:,]/)) wordWeight += WEIGHT_COMMA;

      if (i === wordsInPara.length - 1) {
        wordWeight += WEIGHT_PARA;
      }

      const startTime = weightCursor / totalWeight;
      weightCursor += wordWeight;
      const endTime = weightCursor / totalWeight;

      wordsMetadata.push({
        text: word,
        start: startTime,
        end: endTime,
        width: wordWidth,
        lineIndex: currentLineIdx,
        relativeX: 0,
        globalY: currentLineIdx * lineHeight
      });

      currentLineWords.push(word);
      currentLineWidth += (currentLineWords.length > 1 ? spaceWidth : 0) + wordWidth;
    }

    if (currentLineWords.length > 0) {
      finalizeLineAlignment(ctx, wordsMetadata, lineStartWordIdx, currentLineWords);
      lines.push(currentLineWords);
      currentLineIdx++;
    }
  });

  return { lines, words: wordsMetadata };
};

function finalizeLineAlignment(
  ctx: CanvasRenderingContext2D, 
  allWords: WordMetadata[], 
  startIdx: number, 
  lineStrings: string[]
) {
  const fullLineString = lineStrings.join(' ');
  const totalLineWidth = ctx.measureText(fullLineString).width;
  const lineCenter = totalLineWidth / 2;

  for (let i = 0; i < lineStrings.length; i++) {
    const wordMeta = allWords[startIdx + i];
    const subStr = lineStrings.slice(0, i + 1).join(' ');
    const subStrWidth = ctx.measureText(subStr).width;
    const wordCenterInLine = subStrWidth - (wordMeta.width / 2);
    wordMeta.relativeX = lineCenter - wordCenterInLine;
  }
}

export const renderNarrationLayer = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  layer: any,
  globalProgress: number,
  duration: number
) => {
  const currentTotalTime = globalProgress * duration;
  const progress = (currentTotalTime - layer.startTime) / (layer.endTime - layer.startTime);
  if (progress < 0 || progress > 1.05) return;

  const isLandscape = width > height;
  const isUltraNarrow = (width / height) < 0.55; 

  let scaleRef = isLandscape ? height * 1.45 : width;
  if (isUltraNarrow) scaleRef = width * 1.15;

  const baseFontSize = scaleRef * 0.08; 
  const lineHeight = baseFontSize * 2.5;
  const maxWidth = width * (isLandscape ? 0.65 : 0.82);

  const { lines, words } = getWordMetadata(ctx, layer.text, maxWidth, baseFontSize, lineHeight);
  if (words.length === 0) return;

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.direction = 'rtl';
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // Find active word with robust bounds checking
  let activeIdx = -1;
  for (let i = 0; i < words.length; i++) {
    // Inclusive start, exclusive end (except last word)
    if (progress >= words[i].start && progress < words[i].end) {
      activeIdx = i;
      break;
    }
  }

  // Edge case handling
  if (activeIdx === -1) {
    if (progress >= words[words.length - 1].end) activeIdx = words.length - 1;
    else if (progress < words[0].start) activeIdx = 0;
    else activeIdx = 0; 
  }

  const currentWord = words[activeIdx];
  const nextWord = words[activeIdx + 1] || currentWord;
  const wordDuration = currentWord.end - currentWord.start;
  const wordProgress = wordDuration > 0 ? (progress - currentWord.start) / wordDuration : 1;
  const smoothT = easeInOutCubic(wordProgress);

  // If we are before the first word (due to start padding), don't interpolate to random previous.
  // Just sit at the start of first word.
  let targetScrollY = currentWord.globalY;
  let targetRelativeX = currentWord.relativeX;

  if (activeIdx < words.length - 1) {
      targetScrollY = currentWord.globalY + (nextWord.globalY - currentWord.globalY) * smoothT;
      targetRelativeX = currentWord.relativeX + (nextWord.relativeX - currentWord.relativeX) * smoothT;
  }

  const verticalCenter = height * 0.48;
  const viewportYBase = verticalCenter - targetScrollY;

  lines.forEach((lineTextArray, lineIdx) => {
    const lineY = viewportYBase + (lineIdx * lineHeight);
    if (lineY < -lineHeight * 3 || lineY > height + lineHeight * 3) return;

    const isLineActive = currentWord.lineIndex === lineIdx;
    const distFromFocusY = Math.abs(lineY - verticalCenter);
    const focusFactor = Math.max(0, 1 - distFromFocusY / (height * 0.4));

    let viewportX = width / 2;
    if (layer.animationType !== AnimationType.VERTICAL_SCROLL) {
      const lineWords = words.filter(w => w.lineIndex === lineIdx);
      if (lineWords.length > 0) {
        const lineStartSec = lineWords[0].start * duration;
        const lineEndSec = lineWords[lineWords.length - 1].end * duration;
        const transitionSec = 0.65;

        if (isLineActive) {
          viewportX = (width / 2) - targetRelativeX;
          if (currentTotalTime < lineStartSec + transitionSec) {
            const t = (currentTotalTime - lineStartSec) / transitionSec;
            const startX = width * 1.8 * (layer.animationType === AnimationType.RIGHT_TO_LEFT ? 1 : -1);
            viewportX = startX + (viewportX - startX) * easeInOutCubic(t);
          } else if (currentTotalTime > lineEndSec - transitionSec) {
            const t = (currentTotalTime - (lineEndSec - transitionSec)) / transitionSec;
            const endX = -width * 0.8 * (layer.animationType === AnimationType.RIGHT_TO_LEFT ? 1 : -1);
            viewportX = viewportX + (endX - viewportX) * easeInOutCubic(t);
          }
        } else if (progress < lineWords[0].start) {
          viewportX = width * 2.5 * (layer.animationType === AnimationType.RIGHT_TO_LEFT ? 1 : -1);
        } else {
          viewportX = -width * 1.5 * (layer.animationType === AnimationType.RIGHT_TO_LEFT ? 1 : -1);
        }
      }
    }

    if (isLineActive) {
      const spotlightX = viewportX + targetRelativeX;
      ctx.save();
      const bloom = ctx.createRadialGradient(spotlightX, lineY, 0, spotlightX, lineY, baseFontSize * 5.5);
      bloom.addColorStop(0, 'rgba(251, 191, 36, 0.35)');
      bloom.addColorStop(1, 'transparent');
      ctx.fillStyle = bloom;
      ctx.fillRect(0, 0, width, height);
      ctx.restore();

      words.filter(w => w.lineIndex === lineIdx).forEach((w) => {
        const isLast = (w === words[words.length - 1]);
        const isWordActive = progress >= w.start && (isLast ? progress <= w.end : progress < w.end);

        ctx.save();
        ctx.translate(viewportX + w.relativeX, lineY);
        if (isWordActive) {
          ctx.shadowBlur = 50;
          ctx.shadowColor = 'rgba(251, 191, 36, 1)';
          ctx.fillStyle = '#fbbf24'; // Active word GOLD
          // Enhanced pop animation
          const pulse = 1.25 + 0.1 * Math.sin(progress * Math.PI * 25);
          ctx.scale(pulse, pulse);
        } else {
          ctx.globalAlpha = 1.0; 
          ctx.fillStyle = 'white';
        }
        ctx.fillText(w.text, 0, 0);
        ctx.restore();
      });
    } else {
      ctx.save();
      ctx.globalAlpha = 0.15 * focusFactor;
      ctx.fillStyle = 'white';
      if (focusFactor < 0.5) {
        ctx.filter = `blur(${Math.max(0, (0.5 - focusFactor) * 25)}px)`;
      }
      ctx.fillText(lineTextArray.join(' '), viewportX, lineY);
      ctx.restore();
    }
  });
};

const renderTextLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const duration = layer.endTime - layer.startTime;
  const localTime = time - layer.startTime;
  ctx.save();
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `${layer.fontSize}px Inter, sans-serif`;
  ctx.fillStyle = layer.color;
  let alpha = 1; let scale = 1; let offsetY = 0;
  if (layer.animation === 'fade') {
    if (localTime < 0.5) alpha = localTime / 0.5;
    else if (duration - localTime < 0.5) alpha = (duration - localTime) / 0.5;
  } else if (layer.animation === 'slide') {
    if (localTime < 0.5) offsetY = (1 - (localTime / 0.5)) * 50;
  } else if (layer.animation === 'bounce') {
    scale = 1 + 0.1 * Math.sin(localTime * 10);
  } else if (layer.animation === 'typewriter') {
    const charsToShow = Math.floor(layer.text.length * Math.min(1, localTime / (duration * 0.5)));
    ctx.fillText(layer.text.substring(0, charsToShow), width * layer.x, height * layer.y + offsetY);
    ctx.restore(); return;
  }
  ctx.globalAlpha = alpha;
  ctx.translate(width * layer.x, height * layer.y + offsetY);
  ctx.scale(scale, scale);
  ctx.fillText(layer.text, 0, 0);
  ctx.restore();
};

const renderImageLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const localTime = time - layer.startTime;
  const duration = layer.endTime - layer.startTime;
  const img = new Image();
  img.src = layer.url;
  if (!img.complete) return;
  ctx.save();
  let scale = layer.scale;
  let alpha = 1;
  if (layer.animation === 'zoom') scale *= (1 + 0.2 * (localTime / duration));
  else if (layer.animation === 'fade') alpha = Math.min(1, localTime / 0.5) * Math.min(1, (duration - localTime) / 0.5);
  ctx.globalAlpha = alpha;
  const drawW = img.width * scale;
  const drawH = img.height * scale;
  ctx.drawImage(img, width * layer.x - drawW / 2, height * layer.y - drawH / 2, drawW, drawH);
  ctx.restore();
};

interface LoadedBackgroundAsset {
  element: HTMLImageElement | HTMLVideoElement;
  type: 'image' | 'video';
  id: string;
}

const drawBackgroundSlideshow = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  bgAssets: LoadedBackgroundAsset[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation
) => {
  if (bgAssets.length === 0) return;

  const slideDuration = Math.max(2, totalDuration / bgAssets.length);
  const totalSlides = bgAssets.length;

  // Determine current slide
  let slideIndex = Math.floor(currentTime / slideDuration);
  // Ensure we don't go out of bounds at the very end
  if (slideIndex >= totalSlides) slideIndex = totalSlides - 1;

  const currentAsset = bgAssets[slideIndex];

  // Calculate cross-fade
  const timeInSlide = currentTime - (slideIndex * slideDuration);
  const fadeDuration = 1.0; // 1 second cross-fade
  const remainingTime = slideDuration - timeInSlide;

  let nextAsset: LoadedBackgroundAsset | null = null;
  let crossFadeOpacity = 0;

  if (remainingTime < fadeDuration && slideIndex < totalSlides - 1) {
    nextAsset = bgAssets[slideIndex + 1];
    crossFadeOpacity = 1 - (remainingTime / fadeDuration);
  }

  const drawSingleBg = (asset: LoadedBackgroundAsset, opacity: number, progressForAnim: number) => {
    const bg = asset.element;
    const bgW = bg instanceof HTMLVideoElement ? bg.videoWidth : bg.width;
    const bgH = bg instanceof HTMLVideoElement ? bg.videoHeight : bg.height;

    if (bgW > 0) {
      let baseScale = Math.max(width / bgW, height / bgH);
      let animScale = 1.0;
      let animX = 0;
      let animY = 0;

      // Apply background animation (based on slide progress, not total)
      switch (bgAnim) {
        case BackgroundAnimation.ZOOM_IN:
          animScale = 1.0 + (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.ZOOM_OUT:
          animScale = 1.15 - (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.PAN_LEFT:
          animX = -(progressForAnim * width * 0.1);
          break;
        case BackgroundAnimation.PAN_RIGHT:
          animX = (progressForAnim * width * 0.1) - (width * 0.1);
          break;
      }

      ctx.save();
      ctx.globalAlpha = 0.55 * opacity;
      const finalScale = baseScale * animScale;
      const drawWidth = bgW * finalScale;
      const drawHeight = bgH * finalScale;
      const x = (width - drawWidth) / 2 + animX;
      const y = (height - drawHeight) / 2 + animY;

      ctx.drawImage(bg, x, y, drawWidth, drawHeight);
      ctx.restore();
    }
  };

  // Draw Current
  // Normalized progress 0 to 1 for the current slide duration
  const currentSlideProgress = timeInSlide / slideDuration;
  drawSingleBg(currentAsset, 1, currentSlideProgress);

  // Draw Next (if fading)
  if (nextAsset && crossFadeOpacity > 0) {
    // Start animation for next slide at 0
    drawSingleBg(nextAsset, crossFadeOpacity, 0);
  }
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  bgAssets: LoadedBackgroundAsset[], // Changed to accept array of loaded assets
  layers: EditorLayer[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation = BackgroundAnimation.NONE
) => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  const { width, height } = canvas;
  const progress = totalDuration > 0 ? currentTime / totalDuration : 0;

  ctx.fillStyle = '#020617';
  ctx.fillRect(0, 0, width, height);

  // Draw Background(s)
  drawBackgroundSlideshow(ctx, width, height, bgAssets, currentTime, totalDuration, bgAnim);

  const vignette = ctx.createRadialGradient(width/2, height/2, height * 0.1, width/2, height/2, height * 1.0);
  vignette.addColorStop(0, 'rgba(2, 6, 23, 0.15)');
  vignette.addColorStop(0.6, 'rgba(2, 6, 23, 0.5)');
  vignette.addColorStop(1, 'rgba(2, 6, 23, 0.98)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  const sortedLayers = [...layers].sort((a, b) => a.zIndex - b.zIndex);
  sortedLayers.forEach(layer => {
    if (!layer.visible) return;
    if (layer.type === LayerType.NARRATION) {
      renderNarrationLayer(ctx, width, height, layer, progress, totalDuration);
    } else if (layer.type === LayerType.TEXT) {
      renderTextLayer(ctx, width, height, layer, currentTime);
    } else if (layer.type === LayerType.IMAGE) {
      renderImageLayer(ctx, width, height, layer, currentTime);
    }
  });

  ctx.save();
  ctx.globalAlpha = 0.25;
  ctx.font = `bold ${width * 0.022}px Inter, sans-serif`;
  ctx.fillStyle = 'white';
  ctx.textAlign = 'center';
  ctx.fillText('NOOR STUDIO AI • CINEMATIC NARRATOR', width / 2, height * 0.96);
  ctx.restore();
};

