                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Dynamic Scene Description (Editable)</label>
                      <input className="w-full bg-black/40 border border-emerald-900/40 rounded-xl p-4 text-sm text-white focus:outline-none focus:ring-2 focus:ring-emerald-600 transition-all" placeholder="Scene description will appear here..." value={settings.style} onChange={(e) => setSettings({...settings, style: e.target.value})} />
                    </div>

                    <div className="grid grid-cols-4 sm:grid-cols-6 gap-3 pt-2">
                      {backgrounds.map(bg => {
