import { AnimationType, EditorLayer, LayerType, TextEffect, ImageEffect, BackgroundAnimation } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  relativeX: number; // Offset from the line's geometric center
  globalY: number;
}

/**
 * Standard cubic easing for smooth transitions.
 */
const easeInOutCubic = (t: number): number => {
  const clampedT = Math.max(0, Math.min(1, t));
  return clampedT < 0.5 ? 4 * clampedT * clampedT * clampedT : 1 - Math.pow(-2 * clampedT + 2, 3) / 2;
};

/**
 * Normalizes text to ensure 1:1 mapping between TTS and Visuals.
 * Rules:
 * 1. Remove emojis/decorative symbols that TTS might skip.
 * 2. Collapse ALL whitespace (newlines, tabs, double spaces) into a single space.
 * 3. Trim edges.
 */
export const normalizeText = (text: string): string => {
  return text
    .replace(/[\u{1F000}-\u{1F9FF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B50}\u{2B55}]/gu, '')
    .replace(/\s+/g, ' ')
    .trim();
};

/**
 * Calculates words and lines with high precision for RTL alignment.
 * Implements gapless timing to ensure continuous visibility of subtitles.
 * 
 * NOW uses a strict flow-layout engine that ignores input line breaks
 * and wraps text automatically based on visual width.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number
): { lines: string[][], words: WordMetadata[] } => {
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // Use normalized text to treat input as a single logical flow
  const normalizedText = normalizeText(text);
  const allWords = normalizedText.split(' ').filter(w => w.length > 0);

  const wordsMetadata: WordMetadata[] = [];
  const lines: string[][] = [];

  // Tuning weights for Urdu/English TTS synchronization
  const WEIGHT_START_PAD = 150; 
  const WEIGHT_BASE = 35;       // Increased for distinct word separation
  const WEIGHT_CHAR = 12;       
  const WEIGHT_STOP = 250;      
  const WEIGHT_COMMA = 120;     
  const WEIGHT_PARA = 300;      

  // 1. Calculate total timing weights
  let totalWeight = WEIGHT_START_PAD;

  allWords.forEach((w) => {
    let wWeight = WEIGHT_BASE + (w.length * WEIGHT_CHAR);
    if (w.match(/[۔؟!.\?]/)) wWeight += WEIGHT_STOP;
    else if (w.match(/[،:,]/)) wWeight += WEIGHT_COMMA;
    totalWeight += wWeight;
  });

  // Add end buffer
  totalWeight += WEIGHT_PARA;

  if (totalWeight === 0) totalWeight = 100;

  let weightCursor = WEIGHT_START_PAD;
  let currentLineIdx = 0;
  const spaceWidth = ctx.measureText(' ').width;

  // 2. Layout Engine: Flow words into lines
  let currentLineWords: string[] = [];
  let currentLineWordIndices: number[] = []; // Track indices in allWords
  let currentLineWidth = 0;

  const commitLine = () => {
    if (currentLineWords.length === 0) return;

    // Calculate Explicit RTL Positions
    // In RTL, the first logical word is on the RIGHT.
    // We calculate offsets from the center.
    // StartX (Right Edge) = TotalWidth / 2
    const totalW = currentLineWidth;
    let cursorX = totalW / 2; // Start at rightmost edge relative to center

    currentLineWordIndices.forEach((globalIdx, i) => {
       const word = currentLineWords[i];
       const wWidth = ctx.measureText(word).width;

       // Center of the word at this position
       const wordCenterX = cursorX - (wWidth / 2);

       // Assign to metadata
       wordsMetadata[globalIdx].relativeX = wordCenterX;
       wordsMetadata[globalIdx].lineIndex = currentLineIdx;
       wordsMetadata[globalIdx].globalY = currentLineIdx * lineHeight;

       // Move cursor left
       cursorX -= (wWidth + spaceWidth);
    });

    lines.push([...currentLineWords]);
    currentLineWords = [];
    currentLineWordIndices = [];
    currentLineWidth = 0;
    currentLineIdx++;
  };

  allWords.forEach((word, globalIdx) => {
    const wordWidth = ctx.measureText(word).width;

    // Check wrap
    const prospectiveWidth = currentLineWidth + (currentLineWords.length > 0 ? spaceWidth : 0) + wordWidth;

    if (prospectiveWidth > maxWidth && currentLineWords.length > 0) {
      commitLine();
    }

    // Time Calculation
    let wordWeight = WEIGHT_BASE + (word.length * WEIGHT_CHAR);
    if (word.match(/[۔؟!.\?]/)) wordWeight += WEIGHT_STOP;
    else if (word.match(/[،:,]/)) wordWeight += WEIGHT_COMMA;

    const startTime = weightCursor / totalWeight;
    weightCursor += wordWeight;
    const endTime = weightCursor / totalWeight;

    // Push initial metadata (position will be fixed in commitLine)
    wordsMetadata.push({
      text: word,
      start: startTime,
      end: endTime,
      width: wordWidth,
      lineIndex: 0, 
      relativeX: 0,
      globalY: 0
    });

    currentLineWords.push(word);
    currentLineWordIndices.push(globalIdx);
    currentLineWidth += (currentLineWords.length > 1 ? spaceWidth : 0) + wordWidth;
  });

  // Commit remaining
  commitLine();

  return { lines, words: wordsMetadata };
};

export const renderNarrationLayer = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  layer: any,
  globalProgress: number,
  duration: number
) => {
  const currentTotalTime = globalProgress * duration;
  const progress = (currentTotalTime - layer.startTime) / (layer.endTime - layer.startTime);
  if (progress < 0 || progress > 1.05) return;

  const isLandscape = width > height;
  const isUltraNarrow = (width / height) < 0.55; 

  let scaleRef = isLandscape ? height * 1.45 : width;
  if (isUltraNarrow) scaleRef = width * 1.15;

  const baseFontSize = scaleRef * 0.08; 
  const lineHeight = baseFontSize * 2.5;
  const maxWidth = width * (isLandscape ? 0.65 : 0.82);

  // Note: getWordMetadata now normalizes internally, but layer.text should already be normalized
  const { lines, words } = getWordMetadata(ctx, layer.text, maxWidth, baseFontSize, lineHeight);
  if (words.length === 0) return;

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  // We use LTR drawing because we manually calculated RTL positions
  ctx.direction = 'ltr'; 
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // Find active word
  let activeIdx = -1;
  for (let i = 0; i < words.length; i++) {
    if (progress >= words[i].start && progress < words[i].end) {
      activeIdx = i;
      break;
    }
  }

  if (activeIdx === -1) {
    if (progress >= words[words.length - 1].end) activeIdx = words.length - 1;
    else activeIdx = 0; 
  }

  const currentWord = words[activeIdx];
  const nextWord = words[activeIdx + 1] || currentWord;
  const wordDuration = currentWord.end - currentWord.start;
  const wordProgress = wordDuration > 0 ? (progress - currentWord.start) / wordDuration : 1;
  const smoothT = easeInOutCubic(wordProgress);

  // Auto-Scroll Logic
  let targetScrollY = currentWord.globalY;
  let targetRelativeX = currentWord.relativeX;

  if (activeIdx < words.length - 1) {
      targetScrollY = currentWord.globalY + (nextWord.globalY - currentWord.globalY) * smoothT;
      targetRelativeX = currentWord.relativeX + (nextWord.relativeX - currentWord.relativeX) * smoothT;
  }

  const verticalCenter = height * 0.48;
  const viewportYBase = verticalCenter - targetScrollY;

  lines.forEach((lineTextArray, lineIdx) => {
    const lineY = viewportYBase + (lineIdx * lineHeight);

    // Cull off-screen lines
    if (lineY < -lineHeight * 3 || lineY > height + lineHeight * 3) return;

    const isLineActive = currentWord.lineIndex === lineIdx;
    const distFromFocusY = Math.abs(lineY - verticalCenter);
    const focusFactor = Math.max(0, 1 - distFromFocusY / (height * 0.4));

    let viewportX = width / 2;
    // Animation specific logic...
    if (layer.animationType !== AnimationType.VERTICAL_SCROLL) {
      // (Simplified logic for brevity, keeping existing structure)
      // Note: For side-scroll, we would need different logic, but focus is on Vertical mostly.
      // Keeping existing entrance/exit logic if needed, but centering mostly.
      const lineWords = words.filter(w => w.lineIndex === lineIdx);
      if (lineWords.length > 0 && isLineActive) {
         viewportX = (width / 2) - targetRelativeX;
      }
    }

    if (isLineActive) {
      // Draw words individually for the active line
      const lineWordsMeta = words.filter(w => w.lineIndex === lineIdx);

      lineWordsMeta.forEach((w) => {
        const isLast = (w === words[words.length - 1]);
        const isWordActive = progress >= w.start && (isLast ? progress <= w.end : progress < w.end);

        ctx.save();
        ctx.translate(viewportX + w.relativeX, lineY);

        if (isWordActive) {
          // Precise Highlight: Amber Glow
          ctx.shadowBlur = 20;
          ctx.shadowColor = 'rgba(251, 191, 36, 0.6)';
          ctx.fillStyle = '#fbbf24'; 
          const scale = 1.1; 
          ctx.scale(scale, scale);
        } else {
          // Previously spoken or upcoming words in this line
          // Dim them slightly to let the active word pop
          ctx.globalAlpha = 0.85; 
          ctx.fillStyle = '#f1f5f9'; 
        }

        ctx.fillText(w.text, 0, 0);
        ctx.restore();
      });
    } else {
      // Inactive lines: Draw as full text block (optimization)
      // Since we calculated RTL manually, we can't just draw the array join because browser might re-order.
      // We must draw word by word to match our manual layout, OR trust the browser for inactive lines.
      // For consistency, we draw word by word but with low opacity.

      const lineWordsMeta = words.filter(w => w.lineIndex === lineIdx);

      ctx.save();
      ctx.globalAlpha = 0.15 * focusFactor;
      ctx.fillStyle = 'white';
      if (focusFactor < 0.5) {
        ctx.filter = `blur(${Math.max(0, (0.5 - focusFactor) * 20)}px)`;
      }

      lineWordsMeta.forEach(w => {
         ctx.fillText(w.text, viewportX + w.relativeX, lineY);
      });

      ctx.restore();
    }
  });
};

const renderTextLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const duration = layer.endTime - layer.startTime;
  const localTime = time - layer.startTime;
  ctx.save();
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `${layer.fontSize}px Inter, sans-serif`;
  ctx.fillStyle = layer.color;
  let alpha = 1; let scale = 1; let offsetY = 0;
  if (layer.animation === 'fade') {
    if (localTime < 0.5) alpha = localTime / 0.5;
    else if (duration - localTime < 0.5) alpha = (duration - localTime) / 0.5;
  } else if (layer.animation === 'slide') {
    if (localTime < 0.5) offsetY = (1 - (localTime / 0.5)) * 50;
  } else if (layer.animation === 'bounce') {
    scale = 1 + 0.1 * Math.sin(localTime * 10);
  } else if (layer.animation === 'typewriter') {
    const charsToShow = Math.floor(layer.text.length * Math.min(1, localTime / (duration * 0.5)));
    ctx.fillText(layer.text.substring(0, charsToShow), width * layer.x, height * layer.y + offsetY);
    ctx.restore(); return;
  }
  ctx.globalAlpha = alpha;
  ctx.translate(width * layer.x, height * layer.y + offsetY);
  ctx.scale(scale, scale);
  ctx.fillText(layer.text, 0, 0);
  ctx.restore();
};

const renderImageLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const localTime = time - layer.startTime;
  const duration = layer.endTime - layer.startTime;
  const img = new Image();
  img.src = layer.url;
  if (!img.complete) return;
  ctx.save();
  let scale = layer.scale;
  let alpha = 1;
  if (layer.animation === 'zoom') scale *= (1 + 0.2 * (localTime / duration));
  else if (layer.animation === 'fade') alpha = Math.min(1, localTime / 0.5) * Math.min(1, (duration - localTime) / 0.5);
  ctx.globalAlpha = alpha;
  const drawW = img.width * scale;
  const drawH = img.height * scale;
  ctx.drawImage(img, width * layer.x - drawW / 2, height * layer.y - drawH / 2, drawW, drawH);
  ctx.restore();
};

interface LoadedBackgroundAsset {
  element: HTMLImageElement | HTMLVideoElement;
  type: 'image' | 'video';
  id: string;
}

const drawBackgroundSlideshow = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  bgAssets: LoadedBackgroundAsset[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation
) => {
  if (bgAssets.length === 0) return;

  const slideDuration = Math.max(2, totalDuration / bgAssets.length);
  const totalSlides = bgAssets.length;

  // Determine current slide
  let slideIndex = Math.floor(currentTime / slideDuration);
  // Ensure we don't go out of bounds at the very end
  if (slideIndex >= totalSlides) slideIndex = totalSlides - 1;

  const currentAsset = bgAssets[slideIndex];

  // Calculate cross-fade
  const timeInSlide = currentTime - (slideIndex * slideDuration);
  const fadeDuration = 1.0; // 1 second cross-fade
  const remainingTime = slideDuration - timeInSlide;

  let nextAsset: LoadedBackgroundAsset | null = null;
  let crossFadeOpacity = 0;

  if (remainingTime < fadeDuration && slideIndex < totalSlides - 1) {
    nextAsset = bgAssets[slideIndex + 1];
    crossFadeOpacity = 1 - (remainingTime / fadeDuration);
  }

  const drawSingleBg = (asset: LoadedBackgroundAsset, opacity: number, progressForAnim: number) => {
    const bg = asset.element;
    const bgW = bg instanceof HTMLVideoElement ? bg.videoWidth : bg.width;
    const bgH = bg instanceof HTMLVideoElement ? bg.videoHeight : bg.height;

    if (bgW > 0) {
      let baseScale = Math.max(width / bgW, height / bgH);
      let animScale = 1.0;
      let animX = 0;
      let animY = 0;

      // Apply background animation (based on slide progress, not total)
      switch (bgAnim) {
        case BackgroundAnimation.ZOOM_IN:
          animScale = 1.0 + (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.ZOOM_OUT:
          animScale = 1.15 - (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.PAN_LEFT:
          animX = -(progressForAnim * width * 0.1);
          break;
        case BackgroundAnimation.PAN_RIGHT:
          animX = (progressForAnim * width * 0.1) - (width * 0.1);
          break;
      }

      ctx.save();
      ctx.globalAlpha = 0.55 * opacity;
      const finalScale = baseScale * animScale;
      const drawWidth = bgW * finalScale;
      const drawHeight = bgH * finalScale;
      const x = (width - drawWidth) / 2 + animX;
      const y = (height - drawHeight) / 2 + animY;

      ctx.drawImage(bg, x, y, drawWidth, drawHeight);
      ctx.restore();
    }
  };

  // Draw Current
  // Normalized progress 0 to 1 for the current slide duration
  const currentSlideProgress = timeInSlide / slideDuration;
  drawSingleBg(currentAsset, 1, currentSlideProgress);

  // Draw Next (if fading)
  if (nextAsset && crossFadeOpacity > 0) {
    // Start animation for next slide at 0
    drawSingleBg(nextAsset, crossFadeOpacity, 0);
  }
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  bgAssets: LoadedBackgroundAsset[], // Changed to accept array of loaded assets
  layers: EditorLayer[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation = BackgroundAnimation.NONE
) => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  const { width, height } = canvas;
  const progress = totalDuration > 0 ? currentTime / totalDuration : 0;

  ctx.fillStyle = '#020617';
  ctx.fillRect(0, 0, width, height);

  // Draw Background(s)
  drawBackgroundSlideshow(ctx, width, height, bgAssets, currentTime, totalDuration, bgAnim);

  const vignette = ctx.createRadialGradient(width/2, height/2, height * 0.1, width/2, height/2, height * 1.0);
  vignette.addColorStop(0, 'rgba(2, 6, 23, 0.15)');
  vignette.addColorStop(0.6, 'rgba(2, 6, 23, 0.5)');
  vignette.addColorStop(1, 'rgba(2, 6, 23, 0.98)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  const sortedLayers = [...layers].sort((a, b) => a.zIndex - b.zIndex);
  sortedLayers.forEach(layer => {
    if (!layer.visible) return;
    if (layer.type === LayerType.NARRATION) {
      renderNarrationLayer(ctx, width, height, layer, progress, totalDuration);
    } else if (layer.type === LayerType.TEXT) {
      renderTextLayer(ctx, width, height, layer, currentTime);
    } else if (layer.type === LayerType.IMAGE) {
      renderImageLayer(ctx, width, height, layer, currentTime);
    }
  });

  ctx.save();
  ctx.globalAlpha = 0.25;
  ctx.font = `bold ${width * 0.022}px Inter, sans-serif`;
  ctx.fillStyle = 'white';
  ctx.textAlign = 'center';
  ctx.fillText('NOOR STUDIO AI • CINEMATIC NARRATOR', width / 2, height * 0.96);
  ctx.restore();
};

/**
 * Creates a composite thumbnail image by drawing text over the generated background.
 */
export const createCompositeThumbnail = async (
  imageUrl: string,
  overlayText: string
): Promise<string> => {
  const canvas = document.createElement('canvas');
  // Standard YouTube Thumbnail size
  canvas.width = 1280;
  canvas.height = 720;
  const ctx = canvas.getContext('2d');
  if (!ctx) return imageUrl;

  const img = new Image();
  img.crossOrigin = "anonymous";
  img.src = imageUrl;

  await new Promise((resolve) => {
    if (img.complete) resolve(true);
    img.onload = () => resolve(true);
    img.onerror = () => resolve(false);
  });

  // 1. Draw Background Image (Cover fill)
  const scale = Math.max(canvas.width / img.width, canvas.height / img.height);
  const x = (canvas.width / 2) - (img.width / 2) * scale;
  const y = (canvas.height / 2) - (img.height / 2) * scale;
  ctx.drawImage(img, x, y, img.width * scale, img.height * scale);

  // 2. Draw Vignette / Dark Overlay for readability
  const gradient = ctx.createLinearGradient(0, canvas.height * 0.4, 0, canvas.height);
  gradient.addColorStop(0, 'rgba(0,0,0,0)');
  gradient.addColorStop(0.6, 'rgba(0,0,0,0.7)');
  gradient.addColorStop(1, 'rgba(0,0,0,0.9)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // 3. Draw Text
  if (overlayText) {
    ctx.font = 'bold 80px "Noto Nastaliq Urdu", "Inter", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.direction = 'rtl';

    const words = overlayText.split(' ');
    let lines: string[] = [];
    let currentLine = words[0];

    // Simple greedy wrap for title
    const maxWidth = canvas.width * 0.8;
    for (let i = 1; i < words.length; i++) {
        const word = words[i];
        const width = ctx.measureText(currentLine + " " + word).width;
        if (width < maxWidth) {
            currentLine += " " + word;
        } else {
            lines.push(currentLine);
            currentLine = word;
        }
    }
    lines.push(currentLine);

    // Styling
    const lineHeight = 110;
    let startY = canvas.height - 100 - (lines.length * lineHeight);
    // Push down if single line
    if(lines.length === 1) startY = canvas.height - 160;

    ctx.shadowColor = "rgba(0,0,0,0.8)";
    ctx.shadowBlur = 15;
    ctx.strokeStyle = "black";
    ctx.lineWidth = 12;
    ctx.fillStyle = "#fbbf24"; // Amber/Yellow for high click-through

    lines.forEach((line, i) => {
       const lineY = startY + (i * lineHeight);
       // Stroke
       ctx.strokeText(line, canvas.width / 2, lineY);
       // Fill
       ctx.fillText(line, canvas.width / 2, lineY);
    });
  }

  // 4. Branding
  ctx.font = 'bold 24px "Inter", sans-serif';
  ctx.fillStyle = 'rgba(255,255,255,0.7)';
  ctx.shadowBlur = 0;
  ctx.lineWidth = 0;
  ctx.textAlign = 'right';
  ctx.fillText('NOOR STUDIO AI', canvas.width - 40, 50);

  return canvas.toDataURL('image/png');
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { 
  Video, Download, Loader2, Play, Pause, RotateCcw, Sparkles, History, Volume2, Mic2, ArrowLeft, 
  Image as ImageIcon, Smartphone, Monitor, Instagram, Facebook, AlertCircle, Edit3, Plus, Trash2, 
