import { AnimationType, EditorLayer, LayerType, TextEffect, ImageEffect, BackgroundAnimation } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  relativeX: number; // Offset from the line's geometric center
  globalY: number;
}

/**
 * Standard cubic easing for smooth transitions.
 */
const easeInOutCubic = (t: number): number => {
  const clampedT = Math.max(0, Math.min(1, t));
  return clampedT < 0.5 ? 4 * clampedT * clampedT * clampedT : 1 - Math.pow(-2 * clampedT + 2, 3) / 2;
};

/**
 * Normalizes text to ensure 1:1 mapping between TTS and Visuals.
 * Rules:
 * 1. Remove emojis/decorative symbols that TTS might skip.
 * 2. Collapse ALL whitespace (newlines, tabs, double spaces) into a single space.
 * 3. Trim edges.
 */
export const normalizeText = (text: string): string => {
  return text
    .replace(/[\u{1F000}-\u{1F9FF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B50}\u{2B55}]/gu, '')
    .replace(/\s+/g, ' ')
    .trim();
};

/**
 * Calculates words and lines with high precision for RTL alignment.
 * Implements gapless timing to ensure continuous visibility of subtitles.
 * 
 * NOW uses a strict flow-layout engine that ignores input line breaks
 * and wraps text automatically based on visual width.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number
): { lines: string[][], words: WordMetadata[] } => {
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // Use normalized text to treat input as a single logical flow
  const normalizedText = normalizeText(text);
  const allWords = normalizedText.split(' ').filter(w => w.length > 0);

  const wordsMetadata: WordMetadata[] = [];
  const lines: string[][] = [];

  // Tuning weights for Urdu/English TTS synchronization
  const WEIGHT_START_PAD = 150; 
  const WEIGHT_BASE = 35;       // Increased for distinct word separation
  const WEIGHT_CHAR = 12;       
  const WEIGHT_STOP = 250;      
  const WEIGHT_COMMA = 120;     
  const WEIGHT_PARA = 300;      

  // 1. Calculate total timing weights
  let totalWeight = WEIGHT_START_PAD;

  allWords.forEach((w) => {
    let wWeight = WEIGHT_BASE + (w.length * WEIGHT_CHAR);
    if (w.match(/[۔؟!.\?]/)) wWeight += WEIGHT_STOP;
    else if (w.match(/[،:,]/)) wWeight += WEIGHT_COMMA;
    totalWeight += wWeight;
  });

  // Add end buffer
  totalWeight += WEIGHT_PARA;

  if (totalWeight === 0) totalWeight = 100;

  let weightCursor = WEIGHT_START_PAD;
  let currentLineIdx = 0;
  const spaceWidth = ctx.measureText(' ').width;

  // 2. Layout Engine: Flow words into lines
  let currentLineWords: string[] = [];
  let currentLineWordIndices: number[] = []; // Track indices in allWords
  let currentLineWidth = 0;

  const commitLine = () => {
    if (currentLineWords.length === 0) return;

    // Calculate Explicit RTL Positions
    // In RTL, the first logical word is on the RIGHT.
    // We calculate offsets from the center.
    // StartX (Right Edge) = TotalWidth / 2
    const totalW = currentLineWidth;
    let cursorX = totalW / 2; // Start at rightmost edge relative to center

    currentLineWordIndices.forEach((globalIdx, i) => {
       const word = currentLineWords[i];
       const wWidth = ctx.measureText(word).width;

       // Center of the word at this position
       const wordCenterX = cursorX - (wWidth / 2);

       // Assign to metadata
       wordsMetadata[globalIdx].relativeX = wordCenterX;
       wordsMetadata[globalIdx].lineIndex = currentLineIdx;
       wordsMetadata[globalIdx].globalY = currentLineIdx * lineHeight;

       // Move cursor left
       cursorX -= (wWidth + spaceWidth);
    });

    lines.push([...currentLineWords]);
    currentLineWords = [];
    currentLineWordIndices = [];
    currentLineWidth = 0;
    currentLineIdx++;
  };

  allWords.forEach((word, globalIdx) => {
    const wordWidth = ctx.measureText(word).width;

    // Check wrap
    const prospectiveWidth = currentLineWidth + (currentLineWords.length > 0 ? spaceWidth : 0) + wordWidth;

    if (prospectiveWidth > maxWidth && currentLineWords.length > 0) {
      commitLine();
    }

    // Time Calculation
    let wordWeight = WEIGHT_BASE + (word.length * WEIGHT_CHAR);
    if (word.match(/[۔؟!.\?]/)) wordWeight += WEIGHT_STOP;
    else if (word.match(/[،:,]/)) wordWeight += WEIGHT_COMMA;

    const startTime = weightCursor / totalWeight;
    weightCursor += wordWeight;
    const endTime = weightCursor / totalWeight;

    // Push initial metadata (position will be fixed in commitLine)
    wordsMetadata.push({
      text: word,
      start: startTime,
      end: endTime,
      width: wordWidth,
      lineIndex: 0, 
      relativeX: 0,
      globalY: 0
    });

    currentLineWords.push(word);
    currentLineWordIndices.push(globalIdx);
    currentLineWidth += (currentLineWords.length > 1 ? spaceWidth : 0) + wordWidth;
  });

  // Commit remaining
  commitLine();

  return { lines, words: wordsMetadata };
};

export const renderNarrationLayer = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  layer: any,
  globalProgress: number,
  duration: number
) => {
  const currentTotalTime = globalProgress * duration;
  const progress = (currentTotalTime - layer.startTime) / (layer.endTime - layer.startTime);
  if (progress < 0 || progress > 1.05) return;

  const isLandscape = width > height;
  const isUltraNarrow = (width / height) < 0.55; 

  let scaleRef = isLandscape ? height * 1.45 : width;
  if (isUltraNarrow) scaleRef = width * 1.15;

  const baseFontSize = scaleRef * 0.08; 
  const lineHeight = baseFontSize * 2.5;
  const maxWidth = width * (isLandscape ? 0.65 : 0.82);

  // 1. Get Metadata
  const { lines, words } = getWordMetadata(ctx, layer.text, maxWidth, baseFontSize, lineHeight);
  if (words.length === 0) return;

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.direction = 'ltr'; // We handle RTL manually via relativeX
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // 2. Determine Active Word & Line
  let activeIdx = -1;
  for (let i = 0; i < words.length; i++) {
    if (progress >= words[i].start && progress < words[i].end) {
      activeIdx = i;
      break;
    }
  }

  if (activeIdx === -1) {
    if (progress >= words[words.length - 1].end) activeIdx = words.length - 1;
    else activeIdx = 0; 
  }

  const currentWord = words[activeIdx];
  const wordDuration = currentWord.end - currentWord.start;
  const wordProgress = wordDuration > 0 ? (progress - currentWord.start) / wordDuration : 1;

  // 3. Teleprompter Logic: Calculate Vertical Center
  // Target: The active line should be exactly in the center of the screen.
  // Smooth Scroll: If we are on the LAST word of a line, ease to the next line.

  const currentLineIndex = currentWord.lineIndex;
  const lineWords = words.filter(w => w.lineIndex === currentLineIndex);
  const isLastWordInLine = lineWords[lineWords.length - 1] === currentWord;

  let interpolatedLineIndex = currentLineIndex;

  // Look ahead logic for smooth line transition
  if (isLastWordInLine) {
    // Start sliding to the next line only in the last 60% of the last word's duration
    // This gives user time to read the full line before it moves up.
    if (wordProgress > 0.4) {
       const slideT = (wordProgress - 0.4) / 0.6; // Normalize 0 to 1
       interpolatedLineIndex += easeInOutCubic(slideT);
    }
  }

  const scrollYOffset = interpolatedLineIndex * lineHeight;
  const screenCenterY = height * 0.48; // Optical center (slightly above geometric middle)

  // 4. Render Lines (Active Window: Previous, Current, Next)
  lines.forEach((lineTextArray, lineIdx) => {
    // Calculate where this line sits on screen relative to the "Camera" (interpolated index)
    const lineGlobalY = lineIdx * lineHeight;
    const offsetFromCamera = lineGlobalY - scrollYOffset; 
    const drawY = screenCenterY + offsetFromCamera;

    // Strict 3-Line Visibility Rule
    // We only want to see lines that are roughly within +/- 1.5 lineHeights of the center.
    // This accommodates the partial transition.
    const distLines = Math.abs(lineIdx - interpolatedLineIndex);
    if (distLines > 1.8) return; 

    // Determine visual style based on proximity to center
    // Exact center = 1.0 opacity, scale 1.1
    // Neighbors = 0.5 opacity, scale 0.95

    // We calculate a "Focus Factor" (1.0 = center, 0.0 = far away)
    // Distance in pixels from center
    const distPx = Math.abs(offsetFromCamera);
    const focusFactor = Math.max(0, 1 - (distPx / (lineHeight * 1.2))); // Drop off quickly

    const isCurrentLine = lineIdx === currentLineIndex;

    // Base Opacity/Scale logic
    let lineOpacity = 0.3 + (0.7 * focusFactor); // Min 0.3, Max 1.0
    let lineScale = 0.9 + (0.2 * focusFactor);   // Min 0.9, Max 1.1

    // 5. Draw Words
    const lineWordsMeta = words.filter(w => w.lineIndex === lineIdx);

    ctx.save();
    ctx.translate(width / 2, drawY); // Center horizontally, positioning vertically
    ctx.scale(lineScale, lineScale); // Apply zoom effect to center line

    lineWordsMeta.forEach((w) => {
      // Determine if this specific word is active
      // Logic: strictly based on timestamp
      const isWordActive = progress >= w.start && progress < w.end;
      const isWordPast = progress >= w.end;

      ctx.save();
      ctx.translate(w.relativeX, 0); // RTL positioning relative to center

      if (isCurrentLine && isWordActive) {
        // Active Word Styling: Bright Amber, Glow
        ctx.shadowBlur = 25;
        ctx.shadowColor = 'rgba(251, 191, 36, 0.8)';
        ctx.fillStyle = '#fbbf24'; 
        ctx.globalAlpha = 1;
        // Subtle pop for the word itself
        const wordPop = 1.05 + (0.05 * Math.sin(wordProgress * Math.PI));
        ctx.scale(wordPop, wordPop);
      } else if (isCurrentLine && isWordPast) {
         // Past words in current line: Still visible but slightly dimmed to keep focus on reader
         ctx.fillStyle = '#e2e8f0';
         ctx.globalAlpha = 0.9;
         ctx.shadowBlur = 0;
      } else if (isCurrentLine && !isWordPast) {
         // Future words in current line: Visible
         ctx.fillStyle = '#ffffff';
         ctx.globalAlpha = 1;
         ctx.shadowBlur = 0;
      } else {
         // Context Lines (Previous/Next)
         ctx.fillStyle = '#94a3b8'; // Slate-400
         ctx.globalAlpha = lineOpacity * 0.6; // Apply the distance fade
         ctx.shadowBlur = 0;
      }

      ctx.fillText(w.text, 0, 0);
      ctx.restore();
    });

    ctx.restore();
  });
};

const renderTextLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const duration = layer.endTime - layer.startTime;
  const localTime = time - layer.startTime;
  ctx.save();
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `${layer.fontSize}px Inter, sans-serif`;
  ctx.fillStyle = layer.color;
  let alpha = 1; let scale = 1; let offsetY = 0;
  if (layer.animation === 'fade') {
    if (localTime < 0.5) alpha = localTime / 0.5;
    else if (duration - localTime < 0.5) alpha = (duration - localTime) / 0.5;
  } else if (layer.animation === 'slide') {
    if (localTime < 0.5) offsetY = (1 - (localTime / 0.5)) * 50;
  } else if (layer.animation === 'bounce') {
    scale = 1 + 0.1 * Math.sin(localTime * 10);
  } else if (layer.animation === 'typewriter') {
    const charsToShow = Math.floor(layer.text.length * Math.min(1, localTime / (duration * 0.5)));
    ctx.fillText(layer.text.substring(0, charsToShow), width * layer.x, height * layer.y + offsetY);
    ctx.restore(); return;
  }
  ctx.globalAlpha = alpha;
  ctx.translate(width * layer.x, height * layer.y + offsetY);
  ctx.scale(scale, scale);
  ctx.fillText(layer.text, 0, 0);
  ctx.restore();
};

const renderImageLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const localTime = time - layer.startTime;
  const duration = layer.endTime - layer.startTime;
  const img = new Image();
  img.src = layer.url;
  if (!img.complete) return;
  ctx.save();
  let scale = layer.scale;
  let alpha = 1;
  if (layer.animation === 'zoom') scale *= (1 + 0.2 * (localTime / duration));
  else if (layer.animation === 'fade') alpha = Math.min(1, localTime / 0.5) * Math.min(1, (duration - localTime) / 0.5);
  ctx.globalAlpha = alpha;
  const drawW = img.width * scale;
  const drawH = img.height * scale;
  ctx.drawImage(img, width * layer.x - drawW / 2, height * layer.y - drawH / 2, drawW, drawH);
  ctx.restore();
};

interface LoadedBackgroundAsset {
  element: HTMLImageElement | HTMLVideoElement;
  type: 'image' | 'video';
  id: string;
}

const drawBackgroundSlideshow = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  bgAssets: LoadedBackgroundAsset[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation
) => {
  if (bgAssets.length === 0) return;

  const slideDuration = Math.max(2, totalDuration / bgAssets.length);
  const totalSlides = bgAssets.length;

  // Determine current slide
  let slideIndex = Math.floor(currentTime / slideDuration);
  // Ensure we don't go out of bounds at the very end
  if (slideIndex >= totalSlides) slideIndex = totalSlides - 1;

  const currentAsset = bgAssets[slideIndex];

  // Calculate cross-fade
  const timeInSlide = currentTime - (slideIndex * slideDuration);
  const fadeDuration = 1.0; // 1 second cross-fade
  const remainingTime = slideDuration - timeInSlide;

  let nextAsset: LoadedBackgroundAsset | null = null;
  let crossFadeOpacity = 0;

  if (remainingTime < fadeDuration && slideIndex < totalSlides - 1) {
    nextAsset = bgAssets[slideIndex + 1];
    crossFadeOpacity = 1 - (remainingTime / fadeDuration);
  }

  const drawSingleBg = (asset: LoadedBackgroundAsset, opacity: number, progressForAnim: number) => {
    const bg = asset.element;
    const bgW = bg instanceof HTMLVideoElement ? bg.videoWidth : bg.width;
    const bgH = bg instanceof HTMLVideoElement ? bg.videoHeight : bg.height;

    if (bgW > 0) {
      let baseScale = Math.max(width / bgW, height / bgH);
      let animScale = 1.0;
      let animX = 0;
      let animY = 0;

      // Apply background animation (based on slide progress, not total)
      switch (bgAnim) {
        case BackgroundAnimation.ZOOM_IN:
          animScale = 1.0 + (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.ZOOM_OUT:
          animScale = 1.15 - (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.PAN_LEFT:
          animX = -(progressForAnim * width * 0.1);
          break;
        case BackgroundAnimation.PAN_RIGHT:
          animX = (progressForAnim * width * 0.1) - (width * 0.1);
          break;
      }

      ctx.save();
      ctx.globalAlpha = 0.55 * opacity;
      const finalScale = baseScale * animScale;
      const drawWidth = bgW * finalScale;
      const drawHeight = bgH * finalScale;
      const x = (width - drawWidth) / 2 + animX;
      const y = (height - drawHeight) / 2 + animY;

      ctx.drawImage(bg, x, y, drawWidth, drawHeight);
      ctx.restore();
    }
  };

  // Draw Current
  // Normalized progress 0 to 1 for the current slide duration
  const currentSlideProgress = timeInSlide / slideDuration;
  drawSingleBg(currentAsset, 1, currentSlideProgress);

  // Draw Next (if fading)
  if (nextAsset && crossFadeOpacity > 0) {
    // Start animation for next slide at 0
    drawSingleBg(nextAsset, crossFadeOpacity, 0);
  }
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  bgAssets: LoadedBackgroundAsset[], // Changed to accept array of loaded assets
  layers: EditorLayer[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation = BackgroundAnimation.NONE
) => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  const { width, height } = canvas;
  const progress = totalDuration > 0 ? currentTime / totalDuration : 0;

  ctx.fillStyle = '#020617';
  ctx.fillRect(0, 0, width, height);

  // Draw Background(s)
  drawBackgroundSlideshow(ctx, width, height, bgAssets, currentTime, totalDuration, bgAnim);

  const vignette = ctx.createRadialGradient(width/2, height/2, height * 0.1, width/2, height/2, height * 1.0);
  vignette.addColorStop(0, 'rgba(2, 6, 23, 0.15)');
  vignette.addColorStop(0.6, 'rgba(2, 6, 23, 0.5)');
  vignette.addColorStop(1, 'rgba(2, 6, 23, 0.98)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  const sortedLayers = [...layers].sort((a, b) => a.zIndex - b.zIndex);
  sortedLayers.forEach(layer => {
    if (!layer.visible) return;
    if (layer.type === LayerType.NARRATION) {
      renderNarrationLayer(ctx, width, height, layer, progress, totalDuration);
    } else if (layer.type === LayerType.TEXT) {
      renderTextLayer(ctx, width, height, layer, currentTime);
    } else if (layer.type === LayerType.IMAGE) {
      renderImageLayer(ctx, width, height, layer, currentTime);
    }
  });

  ctx.save();
  ctx.globalAlpha = 0.25;
  ctx.font = `bold ${width * 0.022}px Inter, sans-serif`;
  ctx.fillStyle = 'white';
  ctx.textAlign = 'center';
  ctx.fillText('NOOR STUDIO AI • CINEMATIC NARRATOR', width / 2, height * 0.96);
  ctx.restore();
};

/**
 * Creates a composite thumbnail image by drawing text over the generated background.
 */
export const createCompositeThumbnail = async (
  imageUrl: string,
  overlayText: string
): Promise<string> => {
  const canvas = document.createElement('canvas');
  // Standard YouTube Thumbnail size
  canvas.width = 1280;
  canvas.height = 720;
  const ctx = canvas.getContext('2d');
  if (!ctx) return imageUrl;

  const img = new Image();
  img.crossOrigin = "anonymous";
  img.src = imageUrl;

  await new Promise((resolve) => {
    if (img.complete) resolve(true);
    img.onload = () => resolve(true);
    img.onerror = () => resolve(false);
  });

  // 1. Draw Background Image (Cover fill)
  const scale = Math.max(canvas.width / img.width, canvas.height / img.height);
  const x = (canvas.width / 2) - (img.width / 2) * scale;
  const y = (canvas.height / 2) - (img.height / 2) * scale;
  ctx.drawImage(img, x, y, img.width * scale, img.height * scale);

  // 2. Draw Vignette / Dark Overlay for readability
  const gradient = ctx.createLinearGradient(0, canvas.height * 0.4, 0, canvas.height);
  gradient.addColorStop(0, 'rgba(0,0,0,0)');
  gradient.addColorStop(0.6, 'rgba(0,0,0,0.7)');
  gradient.addColorStop(1, 'rgba(0,0,0,0.9)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // 3. Draw Text
  if (overlayText) {
    ctx.font = 'bold 80px "Noto Nastaliq Urdu", "Inter", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.direction = 'rtl';

    const words = overlayText.split(' ');
    let lines: string[] = [];
    let currentLine = words[0];

    // Simple greedy wrap for title
    const maxWidth = canvas.width * 0.8;
    for (let i = 1; i < words.length; i++) {
        const word = words[i];
        const width = ctx.measureText(currentLine + " " + word).width;
        if (width < maxWidth) {
            currentLine += " " + word;
        } else {
            lines.push(currentLine);
            currentLine = word;
        }
    }
    lines.push(currentLine);

    // Styling
    const lineHeight = 110;
    let startY = canvas.height - 100 - (lines.length * lineHeight);
    // Push down if single line
    if(lines.length === 1) startY = canvas.height - 160;

    ctx.shadowColor = "rgba(0,0,0,0.8)";
    ctx.shadowBlur = 15;
    ctx.strokeStyle = "black";
    ctx.lineWidth = 12;
    ctx.fillStyle = "#fbbf24"; // Amber/Yellow for high click-through

    lines.forEach((line, i) => {
       const lineY = startY + (i * lineHeight);
       // Stroke
       ctx.strokeText(line, canvas.width / 2, lineY);
       // Fill
       ctx.fillText(line, canvas.width / 2, lineY);
    });
  }

  // 4. Branding
  ctx.font = 'bold 24px "Inter", sans-serif';
  ctx.fillStyle = 'rgba(255,255,255,0.7)';
  ctx.shadowBlur = 0;
  ctx.lineWidth = 0;
  ctx.textAlign = 'right';
  ctx.fillText('NOOR STUDIO AI', canvas.width - 40, 50);

  return canvas.toDataURL('image/png');
};

import { AnimationType, EditorLayer, LayerType, TextEffect, ImageEffect, BackgroundAnimation } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  relativeX: number; // Offset from the line's geometric center
  globalY: number;
  index: number;
}

/**
 * Standard cubic easing for smooth transitions.
 */
const easeInOutCubic = (t: number): number => {
  const clampedT = Math.max(0, Math.min(1, t));
  return clampedT < 0.5 ? 4 * clampedT * clampedT * clampedT : 1 - Math.pow(-2 * clampedT + 2, 3) / 2;
};

/**
 * Normalizes text to ensure 1:1 mapping between TTS and Visuals.
 * Rules:
 * 1. Remove emojis/decorative symbols that TTS might skip.
 * 2. Collapse ALL whitespace (newlines, tabs, double spaces) into a single space.
 * 3. Trim edges.
 */
export const normalizeText = (text: string): string => {
  return text
    .replace(/[\u{1F000}-\u{1F9FF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B50}\u{2B55}]/gu, '')
    .replace(/\s+/g, ' ')
    .trim();
};

/**
 * Calculates words and lines with high precision for RTL alignment.
 * Implements gapless timing to ensure continuous visibility of subtitles.
 * 
 * NOW uses a strict flow-layout engine that ignores input line breaks
 * and wraps text automatically based on visual width.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number
): { lines: string[][], words: WordMetadata[] } => {
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // Use normalized text to treat input as a single logical flow
  const normalizedText = normalizeText(text);
  const allWords = normalizedText.split(' ').filter(w => w.length > 0);

  const wordsMetadata: WordMetadata[] = [];
  const lines: string[][] = [];

  // Tuning weights for Urdu/English TTS synchronization
  const WEIGHT_START_PAD = 150; 
  const WEIGHT_BASE = 35;       // Increased for distinct word separation
  const WEIGHT_CHAR = 12;       
  const WEIGHT_STOP = 250;      
  const WEIGHT_COMMA = 120;     
  const WEIGHT_PARA = 300;      

  // 1. Calculate total timing weights
  let totalWeight = WEIGHT_START_PAD;

  allWords.forEach((w) => {
    let wWeight = WEIGHT_BASE + (w.length * WEIGHT_CHAR);
    if (w.match(/[۔؟!.\?]/)) wWeight += WEIGHT_STOP;
    else if (w.match(/[،:,]/)) wWeight += WEIGHT_COMMA;
    totalWeight += wWeight;
  });

  // Add end buffer
  totalWeight += WEIGHT_PARA;

  if (totalWeight === 0) totalWeight = 100;

  let weightCursor = WEIGHT_START_PAD;
  let currentLineIdx = 0;
  const spaceWidth = ctx.measureText(' ').width;

  // 2. Layout Engine: Flow words into lines
  let currentLineWords: string[] = [];
  let currentLineWordIndices: number[] = []; // Track indices in allWords
  let currentLineWidth = 0;

  const commitLine = () => {
    if (currentLineWords.length === 0) return;

    // Calculate Explicit RTL Positions
    // In RTL, the first logical word is on the RIGHT.
    // We calculate offsets from the center.
    // StartX (Right Edge) = TotalWidth / 2
    const totalW = currentLineWidth;
    let cursorX = totalW / 2; // Start at rightmost edge relative to center

    currentLineWordIndices.forEach((globalIdx, i) => {
       const word = currentLineWords[i];
       const wWidth = ctx.measureText(word).width;

       // Center of the word at this position
       const wordCenterX = cursorX - (wWidth / 2);

       // Assign to metadata
       wordsMetadata[globalIdx].relativeX = wordCenterX;
       wordsMetadata[globalIdx].lineIndex = currentLineIdx;
       wordsMetadata[globalIdx].globalY = currentLineIdx * lineHeight;

       // Move cursor left
       cursorX -= (wWidth + spaceWidth);
    });

    lines.push([...currentLineWords]);
    currentLineWords = [];
    currentLineWordIndices = [];
    currentLineWidth = 0;
    currentLineIdx++;
  };

  allWords.forEach((word, globalIdx) => {
    const wordWidth = ctx.measureText(word).width;

    // Check wrap
    const prospectiveWidth = currentLineWidth + (currentLineWords.length > 0 ? spaceWidth : 0) + wordWidth;

    if (prospectiveWidth > maxWidth && currentLineWords.length > 0) {
      commitLine();
    }

    // Time Calculation
    let wordWeight = WEIGHT_BASE + (word.length * WEIGHT_CHAR);
    if (word.match(/[۔؟!.\?]/)) wordWeight += WEIGHT_STOP;
    else if (word.match(/[،:,]/)) wordWeight += WEIGHT_COMMA;

    const startTime = weightCursor / totalWeight;
    weightCursor += wordWeight;
    const endTime = weightCursor / totalWeight;

    // Push initial metadata (position will be fixed in commitLine)
    wordsMetadata.push({
      text: word,
      start: startTime,
      end: endTime,
      width: wordWidth,
      lineIndex: 0, 
      relativeX: 0,
      globalY: 0,
      index: globalIdx
    });

    currentLineWords.push(word);
    currentLineWordIndices.push(globalIdx);
    currentLineWidth += (currentLineWords.length > 1 ? spaceWidth : 0) + wordWidth;
  });

  // Commit remaining
  commitLine();

  return { lines, words: wordsMetadata };
};

export const renderNarrationLayer = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  layer: any,
  globalProgress: number,
  duration: number
) => {
  const currentTotalTime = globalProgress * duration;
  const progress = (currentTotalTime - layer.startTime) / (layer.endTime - layer.startTime);
  if (progress < 0 || progress > 1.05) return;

  const isLandscape = width > height;
  const isUltraNarrow = (width / height) < 0.55; 

  let scaleRef = isLandscape ? height * 1.45 : width;
  if (isUltraNarrow) scaleRef = width * 1.15;

  const baseFontSize = scaleRef * 0.08; 
  const lineHeight = baseFontSize * 2.5;
  const maxWidth = width * (isLandscape ? 0.65 : 0.82);

  // 1. Get Metadata
  const { lines, words } = getWordMetadata(ctx, layer.text, maxWidth, baseFontSize, lineHeight);
  if (words.length === 0) return;

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.direction = 'ltr'; // We handle RTL manually via relativeX
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // 2. Determine Active Word & Line
  let activeIdx = -1;
  for (let i = 0; i < words.length; i++) {
    if (progress >= words[i].start && progress < words[i].end) {
      activeIdx = i;
      break;
    }
  }

  if (activeIdx === -1) {
    if (progress >= words[words.length - 1].end) activeIdx = words.length - 1;
    else activeIdx = 0; 
  }

  const currentWord = words[activeIdx];
  const currentLineIndex = currentWord.lineIndex;

  // 3. Teleprompter Logic: Vertical Scrolling
  // Target: The active line should be exactly in the center of the screen.
  // Smooth Scroll: If we are on the LAST word of a line, ease to the next line.

  let interpolatedLineIndex = currentLineIndex;

  const lineWords = words.filter(w => w.lineIndex === currentLineIndex);
  const isLastWordInLine = lineWords[lineWords.length - 1] === currentWord;

  if (isLastWordInLine) {
    const wordDuration = currentWord.end - currentWord.start;
    const p = (progress - currentWord.start) / wordDuration;
    // Start sliding to the next line only in the last 60% of the last word's duration
    // This gives user time to read the full line before it moves up.
    if (p > 0.4) {
       const slideT = (p - 0.4) / 0.6; // Normalize 0 to 1
       interpolatedLineIndex += easeInOutCubic(slideT);
    }
  }

  const screenCenterY = height * 0.48; // Optical center (slightly above geometric middle)

  // 4. Render Lines (Active Window: Previous, Current, Next)
  // We iterate through all lines but only draw those close to the center index
  lines.forEach((_, lineIdx) => {
    const distFromCenter = lineIdx - interpolatedLineIndex;

    // Strict 3-Line Visibility Rule (plus small buffer for transitions)
    // We only want to see lines that are roughly within +/- 1.8 lineHeights of the center.
    if (Math.abs(distFromCenter) > 2.0) return;

    // Calculate position
    const drawY = screenCenterY + (distFromCenter * lineHeight);

    // Calculate Styling based on proximity to center
    // Center (0) -> Scale 1.1, Opacity 1.0
    // Neighbors (1) -> Scale 0.9, Opacity 0.4
    const absDist = Math.abs(distFromCenter);
    const focusFactor = Math.max(0, 1 - absDist); // 1.0 at center, 0.0 at +/- 1 line distance

    // Visual Parameters
    const scale = 0.95 + (0.15 * focusFactor); // Min 0.95, Max 1.1
    const opacity = 0.3 + (0.7 * focusFactor); // Min 0.3, Max 1.0

    ctx.save();
    ctx.translate(width / 2, drawY);
    ctx.scale(scale, scale);

    const lineWordsMeta = words.filter(w => w.lineIndex === lineIdx);

    lineWordsMeta.forEach((w) => {
      // Precise Timestamp Highlight
      const isWordActive = progress >= w.start && progress < w.end;
      const isWordPast = progress >= w.end;

      ctx.save();
      ctx.translate(w.relativeX, 0); // RTL positioning

      if (isWordActive) {
        // Active Word: Bright Amber, Glow, Pulse
        ctx.shadowBlur = 25;
        ctx.shadowColor = 'rgba(251, 191, 36, 0.8)';
        ctx.fillStyle = '#fbbf24'; 
        ctx.globalAlpha = 1;

        // Subtle Pulse
        const wp = (progress - w.start) / (w.end - w.start);
        const pulse = 1.0 + (0.05 * Math.sin(wp * Math.PI));
        ctx.scale(pulse, pulse);
      } else {
        // Inactive Words
        if (lineIdx < currentLineIndex || (lineIdx === currentLineIndex && isWordPast)) {
             // Past words: Dimmed, Receding
             ctx.fillStyle = '#e2e8f0'; 
             ctx.globalAlpha = opacity * 0.7; 
        } else {
             // Future words: Visible but waiting
             ctx.fillStyle = '#ffffff'; 
             ctx.globalAlpha = opacity;
        }
        ctx.shadowBlur = 0;
      }

      ctx.fillText(w.text, 0, 0);
      ctx.restore();
    });

    ctx.restore();
  });
};

const renderTextLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const duration = layer.endTime - layer.startTime;
  const localTime = time - layer.startTime;
  ctx.save();
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `${layer.fontSize}px Inter, sans-serif`;
  ctx.fillStyle = layer.color;
  let alpha = 1; let scale = 1; let offsetY = 0;
  if (layer.animation === 'fade') {
    if (localTime < 0.5) alpha = localTime / 0.5;
    else if (duration - localTime < 0.5) alpha = (duration - localTime) / 0.5;
  } else if (layer.animation === 'slide') {
    if (localTime < 0.5) offsetY = (1 - (localTime / 0.5)) * 50;
  } else if (layer.animation === 'bounce') {
    scale = 1 + 0.1 * Math.sin(localTime * 10);
  } else if (layer.animation === 'typewriter') {
    const charsToShow = Math.floor(layer.text.length * Math.min(1, localTime / (duration * 0.5)));
    ctx.fillText(layer.text.substring(0, charsToShow), width * layer.x, height * layer.y + offsetY);
    ctx.restore(); return;
  }
  ctx.globalAlpha = alpha;
  ctx.translate(width * layer.x, height * layer.y + offsetY);
  ctx.scale(scale, scale);
  ctx.fillText(layer.text, 0, 0);
  ctx.restore();
};

const renderImageLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const localTime = time - layer.startTime;
  const duration = layer.endTime - layer.startTime;
  const img = new Image();
  img.src = layer.url;
  if (!img.complete) return;
  ctx.save();
  let scale = layer.scale;
  let alpha = 1;
  if (layer.animation === 'zoom') scale *= (1 + 0.2 * (localTime / duration));
  else if (layer.animation === 'fade') alpha = Math.min(1, localTime / 0.5) * Math.min(1, (duration - localTime) / 0.5);
  ctx.globalAlpha = alpha;
  const drawW = img.width * scale;
  const drawH = img.height * scale;
  ctx.drawImage(img, width * layer.x - drawW / 2, height * layer.y - drawH / 2, drawW, drawH);
  ctx.restore();
};

interface LoadedBackgroundAsset {
  element: HTMLImageElement | HTMLVideoElement;
  type: 'image' | 'video';
  id: string;
}

const drawBackgroundSlideshow = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  bgAssets: LoadedBackgroundAsset[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation
) => {
  if (bgAssets.length === 0) return;

  const slideDuration = Math.max(2, totalDuration / bgAssets.length);
  const totalSlides = bgAssets.length;

  // Determine current slide
  let slideIndex = Math.floor(currentTime / slideDuration);
  // Ensure we don't go out of bounds at the very end
  if (slideIndex >= totalSlides) slideIndex = totalSlides - 1;

  const currentAsset = bgAssets[slideIndex];

  // Calculate cross-fade
  const timeInSlide = currentTime - (slideIndex * slideDuration);
  const fadeDuration = 1.0; // 1 second cross-fade
  const remainingTime = slideDuration - timeInSlide;

  let nextAsset: LoadedBackgroundAsset | null = null;
  let crossFadeOpacity = 0;

  if (remainingTime < fadeDuration && slideIndex < totalSlides - 1) {
    nextAsset = bgAssets[slideIndex + 1];
    crossFadeOpacity = 1 - (remainingTime / fadeDuration);
  }

  const drawSingleBg = (asset: LoadedBackgroundAsset, opacity: number, progressForAnim: number) => {
    const bg = asset.element;
    const bgW = bg instanceof HTMLVideoElement ? bg.videoWidth : bg.width;
    const bgH = bg instanceof HTMLVideoElement ? bg.videoHeight : bg.height;

    if (bgW > 0) {
      let baseScale = Math.max(width / bgW, height / bgH);
      let animScale = 1.0;
      let animX = 0;
      let animY = 0;

      // Apply background animation (based on slide progress, not total)
      switch (bgAnim) {
        case BackgroundAnimation.ZOOM_IN:
          animScale = 1.0 + (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.ZOOM_OUT:
          animScale = 1.15 - (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.PAN_LEFT:
          animX = -(progressForAnim * width * 0.1);
          break;
        case BackgroundAnimation.PAN_RIGHT:
          animX = (progressForAnim * width * 0.1) - (width * 0.1);
          break;
      }

      ctx.save();
      ctx.globalAlpha = 0.55 * opacity;
      const finalScale = baseScale * animScale;
      const drawWidth = bgW * finalScale;
      const drawHeight = bgH * finalScale;
      const x = (width - drawWidth) / 2 + animX;
      const y = (height - drawHeight) / 2 + animY;

      ctx.drawImage(bg, x, y, drawWidth, drawHeight);
      ctx.restore();
    }
  };

  // Draw Current
  // Normalized progress 0 to 1 for the current slide duration
  const currentSlideProgress = timeInSlide / slideDuration;
  drawSingleBg(currentAsset, 1, currentSlideProgress);

  // Draw Next (if fading)
  if (nextAsset && crossFadeOpacity > 0) {
    // Start animation for next slide at 0
    drawSingleBg(nextAsset, crossFadeOpacity, 0);
  }
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  bgAssets: LoadedBackgroundAsset[], // Changed to accept array of loaded assets
  layers: EditorLayer[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation = BackgroundAnimation.NONE
) => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  const { width, height } = canvas;
  const progress = totalDuration > 0 ? currentTime / totalDuration : 0;

  ctx.fillStyle = '#020617';
  ctx.fillRect(0, 0, width, height);

  // Draw Background(s)
  drawBackgroundSlideshow(ctx, width, height, bgAssets, currentTime, totalDuration, bgAnim);

  const vignette = ctx.createRadialGradient(width/2, height/2, height * 0.1, width/2, height/2, height * 1.0);
  vignette.addColorStop(0, 'rgba(2, 6, 23, 0.15)');
  vignette.addColorStop(0.6, 'rgba(2, 6, 23, 0.5)');
  vignette.addColorStop(1, 'rgba(2, 6, 23, 0.98)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  const sortedLayers = [...layers].sort((a, b) => a.zIndex - b.zIndex);
  sortedLayers.forEach(layer => {
    if (!layer.visible) return;
    if (layer.type === LayerType.NARRATION) {
      renderNarrationLayer(ctx, width, height, layer, progress, totalDuration);
    } else if (layer.type === LayerType.TEXT) {
      renderTextLayer(ctx, width, height, layer, currentTime);
    } else if (layer.type === LayerType.IMAGE) {
      renderImageLayer(ctx, width, height, layer, currentTime);
    }
  });

  ctx.save();
  ctx.globalAlpha = 0.25;
  ctx.font = `bold ${width * 0.022}px Inter, sans-serif`;
  ctx.fillStyle = 'white';
  ctx.textAlign = 'center';
  ctx.fillText('NOOR STUDIO AI • CINEMATIC NARRATOR', width / 2, height * 0.96);
  ctx.restore();
};

/**
 * Creates a composite thumbnail image by drawing text over the generated background.
 */
export const createCompositeThumbnail = async (
  imageUrl: string,
  overlayText: string
): Promise<string> => {
  const canvas = document.createElement('canvas');
  // Standard YouTube Thumbnail size
  canvas.width = 1280;
  canvas.height = 720;
  const ctx = canvas.getContext('2d');
  if (!ctx) return imageUrl;

  const img = new Image();
  img.crossOrigin = "anonymous";
  img.src = imageUrl;

  await new Promise((resolve) => {
    if (img.complete) resolve(true);
    img.onload = () => resolve(true);
    img.onerror = () => resolve(false);
  });

  // 1. Draw Background Image (Cover fill)
  const scale = Math.max(canvas.width / img.width, canvas.height / img.height);
  const x = (canvas.width / 2) - (img.width / 2) * scale;
  const y = (canvas.height / 2) - (img.height / 2) * scale;
  ctx.drawImage(img, x, y, img.width * scale, img.height * scale);

  // 2. Draw Vignette / Dark Overlay for readability
  const gradient = ctx.createLinearGradient(0, canvas.height * 0.4, 0, canvas.height);
  gradient.addColorStop(0, 'rgba(0,0,0,0)');
  gradient.addColorStop(0.6, 'rgba(0,0,0,0.7)');
  gradient.addColorStop(1, 'rgba(0,0,0,0.9)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // 3. Draw Text
  if (overlayText) {
    ctx.font = 'bold 80px "Noto Nastaliq Urdu", "Inter", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.direction = 'rtl';

    const words = overlayText.split(' ');
    let lines: string[] = [];
    let currentLine = words[0];

    // Simple greedy wrap for title
    const maxWidth = canvas.width * 0.8;
    for (let i = 1; i < words.length; i++) {
        const word = words[i];
        const width = ctx.measureText(currentLine + " " + word).width;
        if (width < maxWidth) {
            currentLine += " " + word;
        } else {
            lines.push(currentLine);
            currentLine = word;
        }
    }
    lines.push(currentLine);

    // Styling
    const lineHeight = 110;
    let startY = canvas.height - 100 - (lines.length * lineHeight);
    // Push down if single line
    if(lines.length === 1) startY = canvas.height - 160;

    ctx.shadowColor = "rgba(0,0,0,0.8)";
    ctx.shadowBlur = 15;
    ctx.strokeStyle = "black";
    ctx.lineWidth = 12;
    ctx.fillStyle = "#fbbf24"; // Amber/Yellow for high click-through

    lines.forEach((line, i) => {
       const lineY = startY + (i * lineHeight);
       // Stroke
       ctx.strokeText(line, canvas.width / 2, lineY);
       // Fill
       ctx.fillText(line, canvas.width / 2, lineY);
    });
  }

  // 4. Branding
  ctx.font = 'bold 24px "Inter", sans-serif';
  ctx.fillStyle = 'rgba(255,255,255,0.7)';
  ctx.shadowBlur = 0;
  ctx.lineWidth = 0;
  ctx.textAlign = 'right';
  ctx.fillText('NOOR STUDIO AI', canvas.width - 40, 50);

  return canvas.toDataURL('image/png');
};

import { AnimationType, EditorLayer, LayerType, TextEffect, ImageEffect, BackgroundAnimation } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  relativeX: number; // Offset from the line's geometric center
  globalY: number;   // Note: This is now the actual Y position including paragraph spacing
  index: number;
}

export interface LineMetadata {
  words: string[];
  y: number;
  height: number;
  isParagraphStart: boolean;
  wordIndices: number[];
}

/**
 * Standard cubic easing for smooth transitions.
 */
const easeInOutCubic = (t: number): number => {
  const clampedT = Math.max(0, Math.min(1, t));
  return clampedT < 0.5 ? 4 * clampedT * clampedT * clampedT : 1 - Math.pow(-2 * clampedT + 2, 3) / 2;
};

/**
 * Normalizes text to ensure 1:1 mapping between TTS and Visuals.
 * Rules:
 * 1. Remove emojis/decorative symbols that TTS might skip.
 * 2. Collapse ALL whitespace (newlines, tabs, double spaces) into a single space.
 * 3. Trim edges.
 */
export const normalizeText = (text: string): string => {
  return text
    .replace(/[\u{1F000}-\u{1F9FF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B50}\u{2B55}]/gu, '')
    .replace(/\s+/g, ' ')
    .trim();
};

/**
 * Checks if a word ends with a sentence-terminating character (Urdu/English).
 */
const isParagraphEnd = (word: string): boolean => {
  return /[۔!?\.\؟]$/.test(word);
};

/**
 * Calculates words and lines with high precision for RTL alignment.
 * Implements gapless timing to ensure continuous visibility of subtitles.
 * 
 * NOW uses a strict flow-layout engine that ignores input line breaks
 * and wraps text automatically based on visual width + semantic punctuation.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number
): { lines: LineMetadata[], words: WordMetadata[] } => {
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // Use normalized text to treat input as a single logical flow
  const normalizedText = normalizeText(text);
  const allWords = normalizedText.split(' ').filter(w => w.length > 0);

  const wordsMetadata: WordMetadata[] = [];
  const lines: LineMetadata[] = [];

  // Tuning weights for Urdu/English TTS synchronization
  const WEIGHT_START_PAD = 150; 
  const WEIGHT_BASE = 35;       
  const WEIGHT_CHAR = 12;       
  const WEIGHT_STOP = 250;      
  const WEIGHT_COMMA = 120;     
  const WEIGHT_PARA = 300;      

  // 1. Calculate total timing weights
  let totalWeight = WEIGHT_START_PAD;

  allWords.forEach((w) => {
    let wWeight = WEIGHT_BASE + (w.length * WEIGHT_CHAR);
    if (w.match(/[۔؟!.\?]/)) wWeight += WEIGHT_STOP;
    else if (w.match(/[،:,]/)) wWeight += WEIGHT_COMMA;
    totalWeight += wWeight;
  });

  // Add end buffer
  totalWeight += WEIGHT_PARA;

  if (totalWeight === 0) totalWeight = 100;

  let weightCursor = WEIGHT_START_PAD;
  const spaceWidth = ctx.measureText(' ').width;
  const PARAGRAPH_SPACING = lineHeight * 0.6; // Visual gap for paragraphs

  // 2. Layout Engine State
  let currentLineWords: string[] = [];
  let currentLineWordIndices: number[] = []; 
  let currentLineWidth = 0;
  let currentLineY = 0;
  let currentLineIdx = 0;

  // Flags for semantic wrapping
  let pendingParagraphBreak = false; 

  const commitLine = () => {
    if (currentLineWords.length === 0) return;

    // Calculate Explicit RTL Positions
    // In RTL, the first logical word is on the RIGHT.
    const totalW = currentLineWidth;
    let cursorX = totalW / 2; // Start at rightmost edge relative to center

    currentLineWordIndices.forEach((globalIdx, i) => {
       const word = currentLineWords[i];
       const wWidth = ctx.measureText(word).width;

       // Center of the word at this position
       const wordCenterX = cursorX - (wWidth / 2);

       // Assign to metadata
       // NOTE: We update the WordMetadata entry we created earlier
       wordsMetadata[globalIdx].relativeX = wordCenterX;
       wordsMetadata[globalIdx].lineIndex = currentLineIdx;
       wordsMetadata[globalIdx].globalY = currentLineY;

       // Move cursor left
       cursorX -= (wWidth + spaceWidth);
    });

    lines.push({
      words: [...currentLineWords],
      wordIndices: [...currentLineWordIndices],
      y: currentLineY,
      height: lineHeight,
      isParagraphStart: pendingParagraphBreak // This line STARTED a paragraph (conceptually)
    });

    currentLineWords = [];
    currentLineWordIndices = [];
    currentLineWidth = 0;
    currentLineIdx++;
  };

  // 3. Flow words
  allWords.forEach((word, globalIdx) => {
    const wordWidth = ctx.measureText(word).width;

    // Check if we need to start a new line BEFORE adding this word
    // Conditions:
    // A. pendingParagraphBreak is true (previous word was 'end of sentence' strong punctuation)
    // B. Word doesn't fit visually

    const fits = (currentLineWidth + (currentLineWords.length ? spaceWidth : 0) + wordWidth) <= maxWidth;

    // NOTE: We only break for paragraph if there is already content in the current line.
    // If current line is empty, we just start there.
    // Actually, if pendingParagraphBreak is true, we want to force the PREVIOUS line to end,
    // and start THIS word on a NEW line.

    if (currentLineWords.length > 0 && (pendingParagraphBreak || !fits)) {
         commitLine();

         // Advance Y Position for the NEW line
         currentLineY += lineHeight;

         if (pendingParagraphBreak) {
             currentLineY += PARAGRAPH_SPACING;
             // Reset the flag, we have consumed the break by creating a gap
             pendingParagraphBreak = false; 
         }
    }

    // Time Calculation
    let wordWeight = WEIGHT_BASE + (word.length * WEIGHT_CHAR);
    if (word.match(/[۔؟!.\?]/)) wordWeight += WEIGHT_STOP;
    else if (word.match(/[،:,]/)) wordWeight += WEIGHT_COMMA;

    const startTime = weightCursor / totalWeight;
    weightCursor += wordWeight;
    const endTime = weightCursor / totalWeight;

    // Push placeholder metadata (positions fixed in commitLine)
    wordsMetadata.push({
      text: word,
      start: startTime,
      end: endTime,
      width: wordWidth,
      lineIndex: 0, // updated in commit
      relativeX: 0, // updated in commit
      globalY: 0,   // updated in commit
      index: globalIdx
    });

    currentLineWords.push(word);
    currentLineWordIndices.push(globalIdx);
    currentLineWidth += (currentLineWords.length > 1 ? spaceWidth : 0) + wordWidth;

    // Check if THIS word triggers a break for the NEXT word
    if (isParagraphEnd(word)) {
        pendingParagraphBreak = true;
    }
  });

  // Commit remaining
  commitLine();

  return { lines, words: wordsMetadata };
};

export const renderNarrationLayer = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  layer: any,
  globalProgress: number,
  duration: number
) => {
  const currentTotalTime = globalProgress * duration;
  const progress = (currentTotalTime - layer.startTime) / (layer.endTime - layer.startTime);
  if (progress < 0 || progress > 1.05) return;

  const isLandscape = width > height;
  const isUltraNarrow = (width / height) < 0.55; 

  let scaleRef = isLandscape ? height * 1.45 : width;
  if (isUltraNarrow) scaleRef = width * 1.15;

  const baseFontSize = scaleRef * 0.08; 
  const lineHeight = baseFontSize * 2.5;
  const maxWidth = width * (isLandscape ? 0.65 : 0.82);

  // 1. Get Metadata (With Paragraph Spacing support)
  const { lines, words } = getWordMetadata(ctx, layer.text, maxWidth, baseFontSize, lineHeight);
  if (words.length === 0) return;

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.direction = 'ltr'; 
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // 2. Determine Active Word & Line
  let activeIdx = -1;
  for (let i = 0; i < words.length; i++) {
    if (progress >= words[i].start && progress < words[i].end) {
      activeIdx = i;
      break;
    }
  }

  if (activeIdx === -1) {
    if (progress >= words[words.length - 1].end) activeIdx = words.length - 1;
    else activeIdx = 0; 
  }

  const currentWord = words[activeIdx];
  const currentLineIndex = currentWord.lineIndex;

  // 3. Teleprompter Logic: Camera Position
  // We want the active line to be in the center.
  // The "Camera Y" is the Y position that should be rendered at screenCenterY.

  let cameraY = lines[currentLineIndex].y;

  // Smooth Scroll Logic
  const lineWords = words.filter(w => w.lineIndex === currentLineIndex);
  const isLastWordInLine = lineWords[lineWords.length - 1] === currentWord;

  if (isLastWordInLine && currentLineIndex < lines.length - 1) {
    const wordDuration = currentWord.end - currentWord.start;
    const p = (progress - currentWord.start) / wordDuration;

    // Slide to next line in the last 60% of the word
    if (p > 0.4) {
       const slideT = (p - 0.4) / 0.6; 
       const nextLineY = lines[currentLineIndex + 1].y;
       const diff = nextLineY - cameraY;
       cameraY += diff * easeInOutCubic(slideT);
    }
  }

  const screenCenterY = height * 0.48; 

  // 4. Render Lines (Active Window: Previous, Current, Next)
  // We iterate through all lines but only draw those visually close to the cameraY
  // We use pixels for culling now because line spacing is variable

  const VISUAL_WINDOW_HEIGHT = lineHeight * 2.5; // Roughly +/- 1.5 lines of visibility

  lines.forEach((lineMeta, lineIdx) => {
    const relativeY = lineMeta.y - cameraY;

    // Culling
    if (Math.abs(relativeY) > VISUAL_WINDOW_HEIGHT) return;

    const drawY = screenCenterY + relativeY;

    // Calculate Focus Factor based on pixel distance from center
    // 0 distance = 1.0 focus
    // lineHeight distance = 0.0 focus (starts fading out)

    const distRatio = Math.abs(relativeY) / (lineHeight * 1.2);
    const focusFactor = Math.max(0, 1 - distRatio); 

    // Visual Parameters
    const scale = 0.95 + (0.15 * focusFactor); // Min 0.95, Max 1.1
    const opacity = 0.25 + (0.75 * focusFactor); // Min 0.25, Max 1.0

    ctx.save();
    ctx.translate(width / 2, drawY);
    ctx.scale(scale, scale);

    const lineWordsMeta = words.filter(w => w.lineIndex === lineIdx);

    lineWordsMeta.forEach((w) => {
      // Precise Timestamp Highlight
      const isWordActive = progress >= w.start && progress < w.end;
      const isWordPast = progress >= w.end;

      ctx.save();
      ctx.translate(w.relativeX, 0); // RTL positioning

      if (isWordActive) {
        // Active Word: Bright Amber, Glow, Pulse
        ctx.shadowBlur = 25;
        ctx.shadowColor = 'rgba(251, 191, 36, 0.8)';
        ctx.fillStyle = '#fbbf24'; 
        ctx.globalAlpha = 1;

        const wp = (progress - w.start) / (w.end - w.start);
        const pulse = 1.0 + (0.05 * Math.sin(wp * Math.PI));
        ctx.scale(pulse, pulse);
      } else {
        // Inactive Words
        // If it's the current active line, past words are slightly dimmer
        if (lineIdx === currentLineIndex) {
            if (isWordPast) {
                 ctx.fillStyle = '#cbd5e1'; // Slate-300
                 ctx.globalAlpha = 0.8;
            } else {
                 ctx.fillStyle = '#ffffff'; 
                 ctx.globalAlpha = 1.0;
            }
        } else {
             // Context lines (Previous/Next) are controlled by the line opacity
             ctx.fillStyle = '#94a3b8'; // Slate-400
             ctx.globalAlpha = opacity * 0.8; 
        }
        ctx.shadowBlur = 0;
      }

      ctx.fillText(w.text, 0, 0);
      ctx.restore();
    });

    ctx.restore();
  });
};

const renderTextLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const duration = layer.endTime - layer.startTime;
  const localTime = time - layer.startTime;
  ctx.save();
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `${layer.fontSize}px Inter, sans-serif`;
  ctx.fillStyle = layer.color;
  let alpha = 1; let scale = 1; let offsetY = 0;
  if (layer.animation === 'fade') {
    if (localTime < 0.5) alpha = localTime / 0.5;
    else if (duration - localTime < 0.5) alpha = (duration - localTime) / 0.5;
  } else if (layer.animation === 'slide') {
    if (localTime < 0.5) offsetY = (1 - (localTime / 0.5)) * 50;
  } else if (layer.animation === 'bounce') {
    scale = 1 + 0.1 * Math.sin(localTime * 10);
  } else if (layer.animation === 'typewriter') {
    const charsToShow = Math.floor(layer.text.length * Math.min(1, localTime / (duration * 0.5)));
    ctx.fillText(layer.text.substring(0, charsToShow), width * layer.x, height * layer.y + offsetY);
    ctx.restore(); return;
  }
  ctx.globalAlpha = alpha;
  ctx.translate(width * layer.x, height * layer.y + offsetY);
  ctx.scale(scale, scale);
  ctx.fillText(layer.text, 0, 0);
  ctx.restore();
};

const renderImageLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const localTime = time - layer.startTime;
  const duration = layer.endTime - layer.startTime;
  const img = new Image();
  img.src = layer.url;
  if (!img.complete) return;
  ctx.save();
  let scale = layer.scale;
  let alpha = 1;
  if (layer.animation === 'zoom') scale *= (1 + 0.2 * (localTime / duration));
  else if (layer.animation === 'fade') alpha = Math.min(1, localTime / 0.5) * Math.min(1, (duration - localTime) / 0.5);
  ctx.globalAlpha = alpha;
  const drawW = img.width * scale;
  const drawH = img.height * scale;
  ctx.drawImage(img, width * layer.x - drawW / 2, height * layer.y - drawH / 2, drawW, drawH);
  ctx.restore();
};

interface LoadedBackgroundAsset {
  element: HTMLImageElement | HTMLVideoElement;
  type: 'image' | 'video';
  id: string;
}

const drawBackgroundSlideshow = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  bgAssets: LoadedBackgroundAsset[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation
) => {
  if (bgAssets.length === 0) return;

  const slideDuration = Math.max(2, totalDuration / bgAssets.length);
  const totalSlides = bgAssets.length;

  // Determine current slide
  let slideIndex = Math.floor(currentTime / slideDuration);
  // Ensure we don't go out of bounds at the very end
  if (slideIndex >= totalSlides) slideIndex = totalSlides - 1;

  const currentAsset = bgAssets[slideIndex];

  // Calculate cross-fade
  const timeInSlide = currentTime - (slideIndex * slideDuration);
  const fadeDuration = 1.0; // 1 second cross-fade
  const remainingTime = slideDuration - timeInSlide;

  let nextAsset: LoadedBackgroundAsset | null = null;
  let crossFadeOpacity = 0;

  if (remainingTime < fadeDuration && slideIndex < totalSlides - 1) {
    nextAsset = bgAssets[slideIndex + 1];
    crossFadeOpacity = 1 - (remainingTime / fadeDuration);
  }

  const drawSingleBg = (asset: LoadedBackgroundAsset, opacity: number, progressForAnim: number) => {
    const bg = asset.element;
    const bgW = bg instanceof HTMLVideoElement ? bg.videoWidth : bg.width;
    const bgH = bg instanceof HTMLVideoElement ? bg.videoHeight : bg.height;

    if (bgW > 0) {
      let baseScale = Math.max(width / bgW, height / bgH);
      let animScale = 1.0;
      let animX = 0;
      let animY = 0;

      // Apply background animation (based on slide progress, not total)
      switch (bgAnim) {
        case BackgroundAnimation.ZOOM_IN:
          animScale = 1.0 + (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.ZOOM_OUT:
          animScale = 1.15 - (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.PAN_LEFT:
          animX = -(progressForAnim * width * 0.1);
          break;
        case BackgroundAnimation.PAN_RIGHT:
          animX = (progressForAnim * width * 0.1) - (width * 0.1);
          break;
      }

      ctx.save();
      ctx.globalAlpha = 0.55 * opacity;
      const finalScale = baseScale * animScale;
      const drawWidth = bgW * finalScale;
      const drawHeight = bgH * finalScale;
      const x = (width - drawWidth) / 2 + animX;
      const y = (height - drawHeight) / 2 + animY;

      ctx.drawImage(bg, x, y, drawWidth, drawHeight);
      ctx.restore();
    }
  };

  // Draw Current
  // Normalized progress 0 to 1 for the current slide duration
  const currentSlideProgress = timeInSlide / slideDuration;
  drawSingleBg(currentAsset, 1, currentSlideProgress);

  // Draw Next (if fading)
  if (nextAsset && crossFadeOpacity > 0) {
    // Start animation for next slide at 0
    drawSingleBg(nextAsset, crossFadeOpacity, 0);
  }
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  bgAssets: LoadedBackgroundAsset[], // Changed to accept array of loaded assets
  layers: EditorLayer[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation = BackgroundAnimation.NONE
) => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  const { width, height } = canvas;
  const progress = totalDuration > 0 ? currentTime / totalDuration : 0;

  ctx.fillStyle = '#020617';
  ctx.fillRect(0, 0, width, height);

  // Draw Background(s)
  drawBackgroundSlideshow(ctx, width, height, bgAssets, currentTime, totalDuration, bgAnim);

  const vignette = ctx.createRadialGradient(width/2, height/2, height * 0.1, width/2, height/2, height * 1.0);
  vignette.addColorStop(0, 'rgba(2, 6, 23, 0.15)');
  vignette.addColorStop(0.6, 'rgba(2, 6, 23, 0.5)');
  vignette.addColorStop(1, 'rgba(2, 6, 23, 0.98)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  const sortedLayers = [...layers].sort((a, b) => a.zIndex - b.zIndex);
  sortedLayers.forEach(layer => {
    if (!layer.visible) return;
    if (layer.type === LayerType.NARRATION) {
      renderNarrationLayer(ctx, width, height, layer, progress, totalDuration);
    } else if (layer.type === LayerType.TEXT) {
      renderTextLayer(ctx, width, height, layer, currentTime);
    } else if (layer.type === LayerType.IMAGE) {
      renderImageLayer(ctx, width, height, layer, currentTime);
    }
  });

  ctx.save();
  ctx.globalAlpha = 0.25;
  ctx.font = `bold ${width * 0.022}px Inter, sans-serif`;
  ctx.fillStyle = 'white';
  ctx.textAlign = 'center';
  ctx.fillText('NOOR STUDIO AI • CINEMATIC NARRATOR', width / 2, height * 0.96);
  ctx.restore();
};

/**
 * Creates a composite thumbnail image by drawing text over the generated background.
 */
export const createCompositeThumbnail = async (
  imageUrl: string,
  overlayText: string
): Promise<string> => {
  const canvas = document.createElement('canvas');
  // Standard YouTube Thumbnail size
  canvas.width = 1280;
  canvas.height = 720;
  const ctx = canvas.getContext('2d');
  if (!ctx) return imageUrl;

  const img = new Image();
  img.crossOrigin = "anonymous";
  img.src = imageUrl;

  await new Promise((resolve) => {
    if (img.complete) resolve(true);
    img.onload = () => resolve(true);
    img.onerror = () => resolve(false);
  });

  // 1. Draw Background Image (Cover fill)
  const scale = Math.max(canvas.width / img.width, canvas.height / img.height);
  const x = (canvas.width / 2) - (img.width / 2) * scale;
  const y = (canvas.height / 2) - (img.height / 2) * scale;
  ctx.drawImage(img, x, y, img.width * scale, img.height * scale);

  // 2. Draw Vignette / Dark Overlay for readability
  const gradient = ctx.createLinearGradient(0, canvas.height * 0.4, 0, canvas.height);
  gradient.addColorStop(0, 'rgba(0,0,0,0)');
  gradient.addColorStop(0.6, 'rgba(0,0,0,0.7)');
  gradient.addColorStop(1, 'rgba(0,0,0,0.9)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // 3. Draw Text
  if (overlayText) {
    ctx.font = 'bold 80px "Noto Nastaliq Urdu", "Inter", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.direction = 'rtl';

    const words = overlayText.split(' ');
    let lines: string[] = [];
    let currentLine = words[0];

    // Simple greedy wrap for title
    const maxWidth = canvas.width * 0.8;
    for (let i = 1; i < words.length; i++) {
        const word = words[i];
        const width = ctx.measureText(currentLine + " " + word).width;
        if (width < maxWidth) {
            currentLine += " " + word;
        } else {
            lines.push(currentLine);
            currentLine = word;
        }
    }
    lines.push(currentLine);

    // Styling
    const lineHeight = 110;
    let startY = canvas.height - 100 - (lines.length * lineHeight);
    // Push down if single line
    if(lines.length === 1) startY = canvas.height - 160;

    ctx.shadowColor = "rgba(0,0,0,0.8)";
    ctx.shadowBlur = 15;
    ctx.strokeStyle = "black";
    ctx.lineWidth = 12;
    ctx.fillStyle = "#fbbf24"; // Amber/Yellow for high click-through

    lines.forEach((line, i) => {
       const lineY = startY + (i * lineHeight);
       // Stroke
       ctx.strokeText(line, canvas.width / 2, lineY);
       // Fill
       ctx.fillText(line, canvas.width / 2, lineY);
    });
  }

  // 4. Branding
  ctx.font = 'bold 24px "Inter", sans-serif';
  ctx.fillStyle = 'rgba(255,255,255,0.7)';
  ctx.shadowBlur = 0;
  ctx.lineWidth = 0;
  ctx.textAlign = 'right';
  ctx.fillText('NOOR STUDIO AI', canvas.width - 40, 50);

  return canvas.toDataURL('image/png');
};

import { AnimationType, EditorLayer, LayerType, TextEffect, ImageEffect, BackgroundAnimation } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  relativeX: number; // Offset from the line's geometric center
  globalY: number;   // Note: This is now the actual Y position including paragraph spacing
  index: number;
}

export interface LineMetadata {
  words: string[];
  y: number;
  height: number;
  isParagraphStart: boolean;
  wordIndices: number[];
}

/**
 * Standard cubic easing for smooth transitions.
 */
const easeInOutCubic = (t: number): number => {
  const clampedT = Math.max(0, Math.min(1, t));
  return clampedT < 0.5 ? 4 * clampedT * clampedT * clampedT : 1 - Math.pow(-2 * clampedT + 2, 3) / 2;
};

/**
 * Normalizes text to ensure 1:1 mapping between TTS and Visuals.
 * Rules:
 * 1. Remove emojis/decorative symbols that TTS might skip.
 * 2. Collapse ALL whitespace (newlines, tabs, double spaces) into a single space.
 * 3. Trim edges.
 */
export const normalizeText = (text: string): string => {
  return text
    .replace(/[\u{1F000}-\u{1F9FF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B50}\u{2B55}]/gu, '')
    .replace(/\s+/g, ' ')
    .trim();
};

/**
 * Checks if a word ends with a sentence-terminating character (Urdu/English).
 */
const isParagraphEnd = (word: string): boolean => {
  return /[۔!?\.\؟]$/.test(word);
};

/**
 * Calculates words and lines with high precision for RTL alignment.
 * Implements gapless timing to ensure continuous visibility of subtitles.
 * 
 * NOW uses a strict flow-layout engine that ignores input line breaks
 * and wraps text automatically based on visual width + semantic punctuation.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number
): { lines: LineMetadata[], words: WordMetadata[] } => {
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // Use normalized text to treat input as a single logical flow
  const normalizedText = normalizeText(text);
  const allWords = normalizedText.split(' ').filter(w => w.length > 0);

  const wordsMetadata: WordMetadata[] = [];
  const lines: LineMetadata[] = [];

  // Tuning weights for Urdu/English TTS synchronization
  const WEIGHT_START_PAD = 150; 
  const WEIGHT_BASE = 35;       
  const WEIGHT_CHAR = 12;       
  const WEIGHT_STOP = 250;      
  const WEIGHT_COMMA = 120;     
  const WEIGHT_PARA = 300;      

  // 1. Calculate total timing weights
  let totalWeight = WEIGHT_START_PAD;

  allWords.forEach((w) => {
    let wWeight = WEIGHT_BASE + (w.length * WEIGHT_CHAR);
    if (w.match(/[۔؟!.\?]/)) wWeight += WEIGHT_STOP;
    else if (w.match(/[،:,]/)) wWeight += WEIGHT_COMMA;
    totalWeight += wWeight;
  });

  // Add end buffer
  totalWeight += WEIGHT_PARA;

  if (totalWeight === 0) totalWeight = 100;

  let weightCursor = WEIGHT_START_PAD;
  const spaceWidth = ctx.measureText(' ').width;
  const PARAGRAPH_SPACING = lineHeight * 0.6; // Visual gap for paragraphs

  // 2. Layout Engine State
  let currentLineWords: string[] = [];
  let currentLineWordIndices: number[] = []; 
  let currentLineWidth = 0;
  let currentLineY = 0;
  let currentLineIdx = 0;

  // Flags for semantic wrapping
  let pendingParagraphBreak = false; 

  const commitLine = () => {
    if (currentLineWords.length === 0) return;

    // Calculate Explicit RTL Positions
    // In RTL, the first logical word is on the RIGHT.
    const totalW = currentLineWidth;
    let cursorX = totalW / 2; // Start at rightmost edge relative to center

    currentLineWordIndices.forEach((globalIdx, i) => {
       const word = currentLineWords[i];
       const wWidth = ctx.measureText(word).width;

       // Center of the word at this position
       const wordCenterX = cursorX - (wWidth / 2);

       // Assign to metadata
       // NOTE: We update the WordMetadata entry we created earlier
       wordsMetadata[globalIdx].relativeX = wordCenterX;
       wordsMetadata[globalIdx].lineIndex = currentLineIdx;
       wordsMetadata[globalIdx].globalY = currentLineY;

       // Move cursor left
       cursorX -= (wWidth + spaceWidth);
    });

    lines.push({
      words: [...currentLineWords],
      wordIndices: [...currentLineWordIndices],
      y: currentLineY,
      height: lineHeight,
      isParagraphStart: pendingParagraphBreak // This line STARTED a paragraph (conceptually)
    });

    currentLineWords = [];
    currentLineWordIndices = [];
    currentLineWidth = 0;
    currentLineIdx++;
  };

  // 3. Flow words
  allWords.forEach((word, globalIdx) => {
    const wordWidth = ctx.measureText(word).width;

    // Check if we need to start a new line BEFORE adding this word
    // Conditions:
    // A. pendingParagraphBreak is true (previous word was 'end of sentence' strong punctuation)
    // B. Word doesn't fit visually

    const fits = (currentLineWidth + (currentLineWords.length ? spaceWidth : 0) + wordWidth) <= maxWidth;

    // NOTE: We only break for paragraph if there is already content in the current line.
    // If current line is empty, we just start there.
    // Actually, if pendingParagraphBreak is true, we want to force the PREVIOUS line to end,
    // and start THIS word on a NEW line.

    if (currentLineWords.length > 0 && (pendingParagraphBreak || !fits)) {
         commitLine();

         // Advance Y Position for the NEW line
         currentLineY += lineHeight;

         if (pendingParagraphBreak) {
             currentLineY += PARAGRAPH_SPACING;
             // Reset the flag, we have consumed the break by creating a gap
             pendingParagraphBreak = false; 
         }
    }

    // Time Calculation
    let wordWeight = WEIGHT_BASE + (word.length * WEIGHT_CHAR);
    if (word.match(/[۔؟!.\?]/)) wordWeight += WEIGHT_STOP;
    else if (word.match(/[،:,]/)) wordWeight += WEIGHT_COMMA;

    const startTime = weightCursor / totalWeight;
    weightCursor += wordWeight;
    const endTime = weightCursor / totalWeight;

    // Push placeholder metadata (positions fixed in commitLine)
    wordsMetadata.push({
      text: word,
      start: startTime,
      end: endTime,
      width: wordWidth,
      lineIndex: 0, // updated in commit
      relativeX: 0, // updated in commit
      globalY: 0,   // updated in commit
      index: globalIdx
    });

    currentLineWords.push(word);
    currentLineWordIndices.push(globalIdx);
    currentLineWidth += (currentLineWords.length > 1 ? spaceWidth : 0) + wordWidth;

    // Check if THIS word triggers a break for the NEXT word
    if (isParagraphEnd(word)) {
        pendingParagraphBreak = true;
    }
  });

  // Commit remaining
  commitLine();

  return { lines, words: wordsMetadata };
};

export const renderNarrationLayer = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  layer: any,
  globalProgress: number,
  duration: number
) => {
  const currentTotalTime = globalProgress * duration;
  const progress = (currentTotalTime - layer.startTime) / (layer.endTime - layer.startTime);
  if (progress < 0 || progress > 1.05) return;

  const isLandscape = width > height;
  const isUltraNarrow = (width / height) < 0.55; 

  let scaleRef = isLandscape ? height * 1.45 : width;
  if (isUltraNarrow) scaleRef = width * 1.15;

  // Reduced font size slightly to accommodate 4 lines comfortably
  const baseFontSize = scaleRef * 0.07; 
  const lineHeight = baseFontSize * 2.5;
  const maxWidth = width * (isLandscape ? 0.65 : 0.82);

  // 1. Get Metadata (With Paragraph Spacing support)
  const { lines, words } = getWordMetadata(ctx, layer.text, maxWidth, baseFontSize, lineHeight);
  if (words.length === 0) return;

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.direction = 'ltr'; 
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // 2. Determine Active Word & Line
  let activeIdx = -1;
  for (let i = 0; i < words.length; i++) {
    if (progress >= words[i].start && progress < words[i].end) {
      activeIdx = i;
      break;
    }
  }

  if (activeIdx === -1) {
    if (progress >= words[words.length - 1].end) activeIdx = words.length - 1;
    else activeIdx = 0; 
  }

  const currentWord = words[activeIdx];
  const currentLineIndex = currentWord.lineIndex;

  // 3. Teleprompter Logic: Camera Position
  // Target: The active line is visually centered.

  let cameraY = lines[currentLineIndex].y;

  // Smooth Scroll Logic
  const lineWords = words.filter(w => w.lineIndex === currentLineIndex);
  const isLastWordInLine = lineWords[lineWords.length - 1] === currentWord;

  if (isLastWordInLine && currentLineIndex < lines.length - 1) {
    const wordDuration = currentWord.end - currentWord.start;
    const p = (progress - currentWord.start) / wordDuration;

    // Slide to next line in the last 60% of the word
    if (p > 0.4) {
       const slideT = (p - 0.4) / 0.6; 
       const nextLineY = lines[currentLineIndex + 1].y;
       const diff = nextLineY - cameraY;
       cameraY += diff * easeInOutCubic(slideT);
    }
  }

  const screenCenterY = height * 0.48; 

  // 4. Render Lines (Active Window: 2 Previous, 1 Current, 1 Upcoming)
  // We extend the visual window to cover roughly -2.5 to +2.5 lines to ensure smooth entry/exit
  const VISUAL_WINDOW_HEIGHT = lineHeight * 3.5; 

  lines.forEach((lineMeta, lineIdx) => {
    const relativeY = lineMeta.y - cameraY;

    // Culling
    if (Math.abs(relativeY) > VISUAL_WINDOW_HEIGHT) return;

    const drawY = screenCenterY + relativeY;

    // Calculate Focus Factor
    // Broader focus curve to keep +/- 1 lines more visible
    // 0 distance = 1.0 focus
    // 1.0 lineHeight distance = ~0.66 focus
    // 2.0 lineHeight distance = ~0.33 focus

    const distRatio = Math.abs(relativeY) / (lineHeight * 3.0);
    const focusFactor = Math.max(0, 1 - distRatio); 

    // Visual Parameters
    // Center line (dist 0): Scale 1.1, Opacity 1.0
    // Neighbors (dist 1): Scale ~0.95, Opacity ~0.75
    // Context (dist 2): Scale ~0.9, Opacity ~0.5

    const scale = 0.9 + (0.2 * focusFactor); // Min 0.9, Max 1.1
    const opacity = 0.2 + (0.8 * focusFactor); // Min 0.2, Max 1.0

    ctx.save();
    ctx.translate(width / 2, drawY);
    ctx.scale(scale, scale);

    const lineWordsMeta = words.filter(w => w.lineIndex === lineIdx);

    lineWordsMeta.forEach((w) => {
      // Precise Timestamp Highlight
      const isWordActive = progress >= w.start && progress < w.end;
      const isWordPast = progress >= w.end;

      ctx.save();
      ctx.translate(w.relativeX, 0); // RTL positioning

      if (isWordActive) {
        // Active Word: Bright Amber, Glow, Pulse
        ctx.shadowBlur = 25;
        ctx.shadowColor = 'rgba(251, 191, 36, 0.8)';
        ctx.fillStyle = '#fbbf24'; 
        ctx.globalAlpha = 1;

        const wp = (progress - w.start) / (w.end - w.start);
        const pulse = 1.0 + (0.05 * Math.sin(wp * Math.PI));
        ctx.scale(pulse, pulse);
      } else {
        // Inactive Words
        if (lineIdx === currentLineIndex) {
            // Current Line Inactive Words
            if (isWordPast) {
                 ctx.fillStyle = '#cbd5e1'; 
                 ctx.globalAlpha = 0.85;
            } else {
                 ctx.fillStyle = '#ffffff'; 
                 ctx.globalAlpha = 1.0;
            }
        } else {
             // Context lines
             ctx.fillStyle = '#94a3b8'; // Slate-400
             ctx.globalAlpha = opacity * 0.7; 
        }
        ctx.shadowBlur = 0;
      }

      ctx.fillText(w.text, 0, 0);
      ctx.restore();
    });

    ctx.restore();
  });
};

const renderTextLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const duration = layer.endTime - layer.startTime;
  const localTime = time - layer.startTime;
  ctx.save();
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `${layer.fontSize}px Inter, sans-serif`;
  ctx.fillStyle = layer.color;
  let alpha = 1; let scale = 1; let offsetY = 0;
  if (layer.animation === 'fade') {
    if (localTime < 0.5) alpha = localTime / 0.5;
    else if (duration - localTime < 0.5) alpha = (duration - localTime) / 0.5;
  } else if (layer.animation === 'slide') {
    if (localTime < 0.5) offsetY = (1 - (localTime / 0.5)) * 50;
  } else if (layer.animation === 'bounce') {
    scale = 1 + 0.1 * Math.sin(localTime * 10);
  } else if (layer.animation === 'typewriter') {
    const charsToShow = Math.floor(layer.text.length * Math.min(1, localTime / (duration * 0.5)));
    ctx.fillText(layer.text.substring(0, charsToShow), width * layer.x, height * layer.y + offsetY);
    ctx.restore(); return;
  }
  ctx.globalAlpha = alpha;
  ctx.translate(width * layer.x, height * layer.y + offsetY);
  ctx.scale(scale, scale);
  ctx.fillText(layer.text, 0, 0);
  ctx.restore();
};

const renderImageLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const localTime = time - layer.startTime;
  const duration = layer.endTime - layer.startTime;
  const img = new Image();
  img.src = layer.url;
  if (!img.complete) return;
  ctx.save();
  let scale = layer.scale;
  let alpha = 1;
  if (layer.animation === 'zoom') scale *= (1 + 0.2 * (localTime / duration));
  else if (layer.animation === 'fade') alpha = Math.min(1, localTime / 0.5) * Math.min(1, (duration - localTime) / 0.5);
  ctx.globalAlpha = alpha;
  const drawW = img.width * scale;
  const drawH = img.height * scale;
  ctx.drawImage(img, width * layer.x - drawW / 2, height * layer.y - drawH / 2, drawW, drawH);
  ctx.restore();
};

interface LoadedBackgroundAsset {
  element: HTMLImageElement | HTMLVideoElement;
  type: 'image' | 'video';
  id: string;
}

const drawBackgroundSlideshow = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  bgAssets: LoadedBackgroundAsset[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation
) => {
  if (bgAssets.length === 0) return;

  const slideDuration = Math.max(2, totalDuration / bgAssets.length);
  const totalSlides = bgAssets.length;

  // Determine current slide
  let slideIndex = Math.floor(currentTime / slideDuration);
  // Ensure we don't go out of bounds at the very end
  if (slideIndex >= totalSlides) slideIndex = totalSlides - 1;

  const currentAsset = bgAssets[slideIndex];

  // Calculate cross-fade
  const timeInSlide = currentTime - (slideIndex * slideDuration);
  const fadeDuration = 1.0; // 1 second cross-fade
  const remainingTime = slideDuration - timeInSlide;

  let nextAsset: LoadedBackgroundAsset | null = null;
  let crossFadeOpacity = 0;

  if (remainingTime < fadeDuration && slideIndex < totalSlides - 1) {
    nextAsset = bgAssets[slideIndex + 1];
    crossFadeOpacity = 1 - (remainingTime / fadeDuration);
  }

  const drawSingleBg = (asset: LoadedBackgroundAsset, opacity: number, progressForAnim: number) => {
    const bg = asset.element;
    const bgW = bg instanceof HTMLVideoElement ? bg.videoWidth : bg.width;
    const bgH = bg instanceof HTMLVideoElement ? bg.videoHeight : bg.height;

    if (bgW > 0) {
      let baseScale = Math.max(width / bgW, height / bgH);
      let animScale = 1.0;
      let animX = 0;
      let animY = 0;

      // Apply background animation (based on slide progress, not total)
      switch (bgAnim) {
        case BackgroundAnimation.ZOOM_IN:
          animScale = 1.0 + (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.ZOOM_OUT:
          animScale = 1.15 - (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.PAN_LEFT:
          animX = -(progressForAnim * width * 0.1);
          break;
        case BackgroundAnimation.PAN_RIGHT:
          animX = (progressForAnim * width * 0.1) - (width * 0.1);
          break;
      }

      ctx.save();
      ctx.globalAlpha = 0.55 * opacity;
      const finalScale = baseScale * animScale;
      const drawWidth = bgW * finalScale;
      const drawHeight = bgH * finalScale;
      const x = (width - drawWidth) / 2 + animX;
      const y = (height - drawHeight) / 2 + animY;

      ctx.drawImage(bg, x, y, drawWidth, drawHeight);
      ctx.restore();
    }
  };

  // Draw Current
  // Normalized progress 0 to 1 for the current slide duration
  const currentSlideProgress = timeInSlide / slideDuration;
  drawSingleBg(currentAsset, 1, currentSlideProgress);

  // Draw Next (if fading)
  if (nextAsset && crossFadeOpacity > 0) {
    // Start animation for next slide at 0
    drawSingleBg(nextAsset, crossFadeOpacity, 0);
  }
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  bgAssets: LoadedBackgroundAsset[], // Changed to accept array of loaded assets
  layers: EditorLayer[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation = BackgroundAnimation.NONE
) => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  const { width, height } = canvas;
  const progress = totalDuration > 0 ? currentTime / totalDuration : 0;

  ctx.fillStyle = '#020617';
  ctx.fillRect(0, 0, width, height);

  // Draw Background(s)
  drawBackgroundSlideshow(ctx, width, height, bgAssets, currentTime, totalDuration, bgAnim);

  const vignette = ctx.createRadialGradient(width/2, height/2, height * 0.1, width/2, height/2, height * 1.0);
  vignette.addColorStop(0, 'rgba(2, 6, 23, 0.15)');
  vignette.addColorStop(0.6, 'rgba(2, 6, 23, 0.5)');
  vignette.addColorStop(1, 'rgba(2, 6, 23, 0.98)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  const sortedLayers = [...layers].sort((a, b) => a.zIndex - b.zIndex);
  sortedLayers.forEach(layer => {
    if (!layer.visible) return;
    if (layer.type === LayerType.NARRATION) {
      renderNarrationLayer(ctx, width, height, layer, progress, totalDuration);
    } else if (layer.type === LayerType.TEXT) {
      renderTextLayer(ctx, width, height, layer, currentTime);
    } else if (layer.type === LayerType.IMAGE) {
      renderImageLayer(ctx, width, height, layer, currentTime);
    }
  });

  ctx.save();
  ctx.globalAlpha = 0.25;
  ctx.font = `bold ${width * 0.022}px Inter, sans-serif`;
  ctx.fillStyle = 'white';
  ctx.textAlign = 'center';
  ctx.fillText('NOOR STUDIO AI • CINEMATIC NARRATOR', width / 2, height * 0.96);
  ctx.restore();
};

/**
 * Creates a composite thumbnail image by drawing text over the generated background.
 * Now supports dynamic canvas sizing for adaptive thumbnails (TikTok/YouTube/etc).
 */
export const createCompositeThumbnail = async (
  imageUrl: string,
  overlayText: string,
  targetWidth: number,
  targetHeight: number
): Promise<string> => {
  const canvas = document.createElement('canvas');
  // Use target dimensions passed from configuration
  canvas.width = targetWidth;
  canvas.height = targetHeight;
  const ctx = canvas.getContext('2d');
  if (!ctx) return imageUrl;

  const img = new Image();
  img.crossOrigin = "anonymous";
  img.src = imageUrl;

  await new Promise((resolve) => {
    if (img.complete) resolve(true);
    img.onload = () => resolve(true);
    img.onerror = () => resolve(false);
  });

  // 1. Draw Background Image (Cover fill)
  const scale = Math.max(canvas.width / img.width, canvas.height / img.height);
  const x = (canvas.width / 2) - (img.width / 2) * scale;
  const y = (canvas.height / 2) - (img.height / 2) * scale;
  ctx.drawImage(img, x, y, img.width * scale, img.height * scale);

  // 2. Draw Vignette / Dark Overlay for readability
  const gradient = ctx.createLinearGradient(0, canvas.height * 0.4, 0, canvas.height);
  gradient.addColorStop(0, 'rgba(0,0,0,0)');
  gradient.addColorStop(0.6, 'rgba(0,0,0,0.7)');
  gradient.addColorStop(1, 'rgba(0,0,0,0.9)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // 3. Draw Text
  if (overlayText) {
    // Dynamic font size based on width (approx 10% of width)
    const fontSize = Math.floor(canvas.width * 0.08); 
    ctx.font = `bold ${fontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.direction = 'rtl';

    const words = overlayText.split(' ');
    let lines: string[] = [];
    let currentLine = words[0];

    // Simple greedy wrap for title
    const maxWidth = canvas.width * 0.8;
    for (let i = 1; i < words.length; i++) {
        const word = words[i];
        const width = ctx.measureText(currentLine + " " + word).width;
        if (width < maxWidth) {
            currentLine += " " + word;
        } else {
            lines.push(currentLine);
            currentLine = word;
        }
    }
    lines.push(currentLine);

    // Styling
    const lineHeight = fontSize * 1.4;
    // Position text in lower third
    let startY = canvas.height - (canvas.height * 0.15) - (lines.length * lineHeight);

    ctx.shadowColor = "rgba(0,0,0,0.8)";
    ctx.shadowBlur = 15;
    ctx.strokeStyle = "black";
    ctx.lineWidth = fontSize * 0.15;
    ctx.fillStyle = "#fbbf24"; // Amber/Yellow for high click-through

    lines.forEach((line, i) => {
       const lineY = startY + (i * lineHeight);
       // Stroke
       ctx.strokeText(line, canvas.width / 2, lineY);
       // Fill
       ctx.fillText(line, canvas.width / 2, lineY);
    });
  }

  // 4. Branding
  const brandSize = Math.max(16, canvas.width * 0.03);
  ctx.font = `bold ${brandSize}px "Inter", sans-serif`;
  ctx.fillStyle = 'rgba(255,255,255,0.7)';
  ctx.shadowBlur = 0;
  ctx.lineWidth = 0;
  ctx.textAlign = 'right';
  ctx.fillText('NOOR STUDIO AI', canvas.width - (brandSize * 1.5), brandSize * 2);

  return canvas.toDataURL('image/png');
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { 
  Video, Download, Loader2, Play, Pause, RotateCcw, Sparkles, History, Volume2, Mic2, ArrowLeft, 
  Image as ImageIcon, Smartphone, Monitor, Instagram, Facebook, AlertCircle, Edit3, Plus, Trash2, 
  Layers, Settings, Move, Type as TypeIcon, Sliders, X, Check, Save, Clock, Copy, Upload, CheckCircle2
} from 'lucide-react';
import { 
  VoiceName, NarrationHistoryItem, GenerationSettings, AnimationType, 
  BackgroundSource, SEOMetadata, AspectRatio, EditorLayer, LayerType, TextEffect, ImageEffect, BackgroundAnimation, BackgroundAsset 
} from './types';
import { generateNarration, generateAtmosphereImage, generateSEOMetadata, generateVisualPrompt, generateThumbnailData } from './services/geminiService';
import { decode, decodeAudioData } from './utils/audioUtils';
import { drawVideoFrame, normalizeText, createCompositeThumbnail } from './utils/videoUtils';

const DEFAULT_TEXT = ``;
const STORAGE_KEY = 'noor_last_used_text';

const ASPECT_RATIO_CONFIG = {
  [AspectRatio.VERTICAL]: { width: 1080, height: 1920, label: "Reels / TikTok", icon: Smartphone },
  [AspectRatio.LANDSCAPE]: { width: 1920, height: 1080, label: "YouTube / Desktop", icon: Monitor },
  [AspectRatio.SQUARE]: { width: 1080, height: 1080, label: "Instagram Feed", icon: Instagram },
  [AspectRatio.FEED]: { width: 1080, height: 1350, label: "Facebook / Portrait", icon: Facebook },
};

const getGeminiAspectRatio = (ratio: AspectRatio): string => {
  switch (ratio) {
    case AspectRatio.VERTICAL: return "9:16";
    case AspectRatio.SQUARE: return "1:1";
    case AspectRatio.FEED: return "3:4";
    default: return "16:9";
  }
};

type PlaybackStatus = 'playing' | 'paused' | 'stopped';

const App: React.FC = () => {
  const [settings, setSettings] = useState<GenerationSettings>(() => {
    const savedText = localStorage.getItem(STORAGE_KEY);
    return {
      text: savedText || DEFAULT_TEXT,
      voice: VoiceName.CHARON,
      generateImage: true,
      style: "Starry night sky over a peaceful mosque silhouette",
      animationType: AnimationType.VERTICAL_SCROLL,
      backgroundAnimation: BackgroundAnimation.ZOOM_IN,
      aspectRatio: AspectRatio.VERTICAL,
      backgroundSource: BackgroundSource.AI,
      selectedBackgroundIds: [] // Initialized as empty array
    };
  });

  const [backgrounds, setBackgrounds] = useState<BackgroundAsset[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isGeneratingBG, setIsGeneratingBG] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordProgress, setRecordProgress] = useState(0);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [playbackStatus, setPlaybackStatus] = useState<PlaybackStatus>('stopped');
  const [isEditing, setIsEditing] = useState(false);

  const [currentResult, setCurrentResult] = useState<{ 
    audioUrl: string; 
    audioBuffer?: AudioBuffer;
    base64Audio: string;
    seo?: SEOMetadata;
    thumbnailUrl?: string;
  } | null>(null);

  const [layers, setLayers] = useState<EditorLayer[]>([]);
  const [selectedLayerId, setSelectedLayerId] = useState<string | null>(null);
  const [history, setHistory] = useState<NarrationHistoryItem[]>([]);
  const [showHistory, setShowHistory] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const recordCanvasRef = useRef<HTMLCanvasElement>(null);

  // Cache for loaded background elements (Images/Videos)
  const loadedAssetsRef = useRef<Map<string, HTMLImageElement | HTMLVideoElement>>(new Map());

  const stopSignalRef = useRef<boolean>(false);
  const previewRequestRef = useRef<number>(0);
  const currentPreviewSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const playbackStartTimeRef = useRef<number>(0);
  const pauseOffsetRef = useRef<number>(0);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const duration = useMemo(() => currentResult?.audioBuffer?.duration || 10, [currentResult]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, settings.text);
  }, [settings.text]);

  useEffect(() => {
    if (currentResult) {
      // NOTE: We used the normalized text for generation, so we use it for the layer too.
      // But for initial load from history/state we might need to re-normalize if we want consistency?
      // Actually, we set this layer right after generation where we have the normalized text.
      // For now, let's assume currentResult implies a fresh generation or we reconstruct.
      // Ideally we store normalized text in currentResult.

      const normalized = normalizeText(settings.text);

      setLayers([
        {
          id: 'narration-main',
          type: LayerType.NARRATION,
          startTime: 0,
          endTime: duration,
          visible: true,
          zIndex: 1,
          text: normalized, // Use normalized text for layer to match audio
          animationType: settings.animationType
        }
      ]);
    }
  }, [currentResult, duration, settings.text, settings.animationType]);

  // Order active backgrounds based on the SELECTION array order
  const activeBgs = useMemo(() => {
    return settings.selectedBackgroundIds
      .map(id => backgrounds.find(bg => bg.id === id))
      .filter((bg): bg is BackgroundAsset => !!bg);
  }, [backgrounds, settings.selectedBackgroundIds]);

  useEffect(() => {
    const loadAssets = async () => {
       const newLoaded = new Map(loadedAssetsRef.current);

       for (const bg of activeBgs) {
         if (!newLoaded.has(bg.id)) {
           if (bg.type === 'video') {
             const v = document.createElement('video');
             v.src = bg.url;
             v.muted = true; v.loop = true; v.crossOrigin = "anonymous";
             v.play().catch(() => {});
             newLoaded.set(bg.id, v);
           } else {
             const img = new Image();
             img.crossOrigin = "anonymous";
             img.src = bg.url;
             await new Promise((resolve) => {
                if (img.complete) resolve(true);
                else img.onload = () => resolve(true);
             });
             newLoaded.set(bg.id, img);
           }
         }
       }
       loadedAssetsRef.current = newLoaded;
    };
    loadAssets();
  }, [activeBgs]);

  useEffect(() => {
    const draw = () => {
      if (!canvasRef.current) return;
      const config = ASPECT_RATIO_CONFIG[settings.aspectRatio];
      if (canvasRef.current.width !== config.width || canvasRef.current.height !== config.height) {
        canvasRef.current.width = config.width;
        canvasRef.current.height = config.height;
      }

      // Prepare assets list for the drawer - ensure strictly following activeBgs order
      const assetsToDraw = activeBgs.map(bg => ({
        id: bg.id,
        type: bg.type,
        element: loadedAssetsRef.current.get(bg.id)
      })).filter(a => a.element) as { element: HTMLImageElement | HTMLVideoElement, type: 'image' | 'video', id: string }[];

      let time = 0;
      if (playbackStatus === 'playing' && audioContextRef.current) {
        time = pauseOffsetRef.current + (audioContextRef.current.currentTime - playbackStartTimeRef.current);
      } else if (playbackStatus === 'paused') {
        time = pauseOffsetRef.current;
      }

      drawVideoFrame(canvasRef.current, assetsToDraw, layers, time % duration, duration, settings.backgroundAnimation);
      previewRequestRef.current = requestAnimationFrame(draw);
    };
    draw();
    return () => cancelAnimationFrame(previewRequestRef.current);
  }, [currentResult, settings, playbackStatus, layers, duration, activeBgs]);

  const handleGenerate = async () => {
    if (!settings.text.trim()) return;
    setIsGenerating(true); setErrorMsg(null); stopSignalRef.current = false;
    setCurrentResult(null); stopPreview();
    try {
      if (!audioContextRef.current) audioContextRef.current = new AudioContext({ sampleRate: 24000 });

      // CRITICAL STEP: Normalize text BEFORE generation.
      // This ensures the text sent to TTS is byte-for-byte identical to what we render.
      const normalizedScript = normalizeText(settings.text);

      // 1. Generate Narration
      const base64Audio = await generateNarration(normalizedScript, settings.voice);
      if (stopSignalRef.current) return;
      const audioData = decode(base64Audio);
      const audioBuffer = await decodeAudioData(audioData, audioContextRef.current, 24000, 1);
      const audioUrl = URL.createObjectURL(new Blob([audioData], { type: 'audio/pcm' }));

      // 2. Dynamic Visual Prompt
      const dynamicPrompt = await generateVisualPrompt(normalizedScript);
      setSettings(s => ({ ...s, style: dynamicPrompt })); // Update UI with new prompt

      // 3. SEO & Image & Thumbnail Data
      const seoPromise = generateSEOMetadata(normalizedScript);
      const thumbDataPromise = generateThumbnailData(normalizedScript);

      let newBg: BackgroundAsset | null = null;
      let bgPromise: Promise<string | null> = Promise.resolve(null);

      // Get target Aspect Ratio string (e.g., "9:16")
      const targetRatio = getGeminiAspectRatio(settings.aspectRatio);

      if (settings.generateImage) {
        // Smart Aspect Ratio: Generate background in the target ratio
        bgPromise = generateAtmosphereImage(dynamicPrompt, targetRatio);
      }

      const [seo, thumbData, bgUrl] = await Promise.all([seoPromise, thumbDataPromise, bgPromise]);

      // Process Background
      if (bgUrl) {
          newBg = { id: Date.now().toString(), url: bgUrl, source: BackgroundSource.AI, type: 'image' };
          setBackgrounds(prev => [...prev, newBg!]);
          setSettings(s => ({ ...s, selectedBackgroundIds: [newBg!.id] }));
      }

      // Generate Raw Thumbnail Image
      let rawThumbnailUrl: string | null = null;
      let finalThumbnailUrl: string | null = null;

      if (thumbData) {
          // Generate thumbnail base image using the CORRECT aspect ratio of the platform
          rawThumbnailUrl = await generateAtmosphereImage(thumbData.visualPrompt, targetRatio);

          if (rawThumbnailUrl) {
              // Get actual dimensions
              const dims = ASPECT_RATIO_CONFIG[settings.aspectRatio];
              // COMPOSITE STEP: Draw text over image with correct dimensions
              finalThumbnailUrl = await createCompositeThumbnail(
                  rawThumbnailUrl, 
                  thumbData.overlayText, 
                  dims.width, 
                  dims.height
              );
          }
      }

      if (stopSignalRef.current) return;
      setCurrentResult({ audioUrl, audioBuffer, base64Audio, seo, thumbnailUrl: finalThumbnailUrl || undefined });

      setHistory(prev => [{ 
        id: Date.now().toString(), 
        text: settings.text, // Keep original text for history display 
        voice: settings.voice, 
        timestamp: Date.now(), 
        audioUrl, 
        imageUrl: newBg?.url || activeBgs[0]?.url, 
        thumbnailUrl: finalThumbnailUrl || undefined,
        seo, 
        aspectRatio: settings.aspectRatio 
      }, ...prev]);
    } catch (e: any) {
      if (!stopSignalRef.current) setErrorMsg(e.message || "An error occurred.");
    } finally { setIsGenerating(false); }
  };

  const generateAdditionalBG = async () => {
    setIsGeneratingBG(true);
    try {
      const targetRatio = getGeminiAspectRatio(settings.aspectRatio);
      const imageUrl = await generateAtmosphereImage(settings.style, targetRatio);
      if (imageUrl) {
        const newBg: BackgroundAsset = { id: Date.now().toString(), url: imageUrl, source: BackgroundSource.AI, type: 'image' };
        setBackgrounds(prev => [...prev, newBg]);
        setSettings(s => ({ ...s, selectedBackgroundIds: [...s.selectedBackgroundIds, newBg.id] }));
      }
    } catch (e: any) {
      setErrorMsg("Failed to generate background.");
    } finally {
      setIsGeneratingBG(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const url = event.target?.result as string;
        const newBg: BackgroundAsset = { 
          id: Date.now().toString(), 
          url, 
          source: BackgroundSource.CUSTOM, 
          type: file.type.startsWith('video') ? 'video' : 'image' 
        };
        setBackgrounds(prev => [...prev, newBg]);
        setSettings(s => ({ ...s, selectedBackgroundIds: [...s.selectedBackgroundIds, newBg.id] }));
