type PlaybackStatus = 'playing' | 'paused' | 'stopped';

const App: React.FC = () => {
  const [settings, setSettings] = useState<GenerationSettings>(() => {
    const savedText = localStorage.getItem(STORAGE_KEY);
    return {
      text: savedText || DEFAULT_TEXT,
      voice: VoiceName.CHARON,
      generateImage: true,
      style: "Starry night sky over a peaceful mosque silhouette",
      animationType: AnimationType.VERTICAL_SCROLL,
      backgroundAnimation: BackgroundAnimation.ZOOM_IN,
      aspectRatio: AspectRatio.VERTICAL,
      backgroundSource: BackgroundSource.AI,
      selectedBackgroundIds: [] // Initialized as empty array
    };
  });

  const [backgrounds, setBackgrounds] = useState<BackgroundAsset[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isGeneratingBG, setIsGeneratingBG] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordProgress, setRecordProgress] = useState(0);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [playbackStatus, setPlaybackStatus] = useState<PlaybackStatus>('stopped');
  const [isEditing, setIsEditing] = useState(false);

  const [currentResult, setCurrentResult] = useState<{ 
    audioUrl: string; 
    audioBuffer?: AudioBuffer;
    base64Audio: string;
    seo?: SEOMetadata;
    thumbnailUrl?: string;
  } | null>(null);

  const [layers, setLayers] = useState<EditorLayer[]>([]);
  const [selectedLayerId, setSelectedLayerId] = useState<string | null>(null);
  const [history, setHistory] = useState<NarrationHistoryItem[]>([]);
  const [showHistory, setShowHistory] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const recordCanvasRef = useRef<HTMLCanvasElement>(null);

  // Cache for loaded background elements (Images/Videos)
  const loadedAssetsRef = useRef<Map<string, HTMLImageElement | HTMLVideoElement>>(new Map());
  const layoutCache = useRef<LayoutCache>(new Map());

  const stopSignalRef = useRef<boolean>(false);
  const previewRequestRef = useRef<number>(0);
  const currentPreviewSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const playbackStartTimeRef = useRef<number>(0);
  const pauseOffsetRef = useRef<number>(0);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const duration = useMemo(() => currentResult?.audioBuffer?.duration || 10, [currentResult]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, settings.text);
    // Invalidate cache when text changes
    layoutCache.current.clear();
  }, [settings.text]);

  // Invalidate cache when aspect ratio or voice changes
  useEffect(() => {
    layoutCache.current.clear();
  }, [settings.aspectRatio, settings.voice]);

  useEffect(() => {
    if (currentResult) {
      const normalized = normalizeText(settings.text);
      setLayers([
        {
          id: 'narration-main',
          type: LayerType.NARRATION,
          startTime: 0,
          endTime: duration,
          visible: true,
          zIndex: 1,
          text: normalized, // Use normalized text for layer to match audio
          animationType: settings.animationType
        }
      ]);
    }
  }, [currentResult, duration, settings.text, settings.animationType]);

  // Order active backgrounds based on the SELECTION array order
  const activeBgs = useMemo(() => {
    return settings.selectedBackgroundIds
      .map(id => backgrounds.find(bg => bg.id === id))
      .filter((bg): bg is BackgroundAsset => !!bg);
  }, [backgrounds, settings.selectedBackgroundIds]);

  useEffect(() => {
    const loadAssets = async () => {
       const newLoaded = new Map(loadedAssetsRef.current);

       for (const bg of activeBgs) {
         if (!newLoaded.has(bg.id)) {
           if (bg.type === 'video') {
             const v = document.createElement('video');
             v.src = bg.url;
             v.muted = true; v.loop = true; v.crossOrigin = "anonymous";
             v.play().catch(() => {});
             newLoaded.set(bg.id, v);
           } else {
             const img = new Image();
             img.crossOrigin = "anonymous";
             img.src = bg.url;
             await new Promise((resolve) => {
                if (img.complete) resolve(true);
                else img.onload = () => resolve(true);
             });
             newLoaded.set(bg.id, img);
           }
         }
       }
       loadedAssetsRef.current = newLoaded;
    };
    loadAssets();
  }, [activeBgs]);

  useEffect(() => {
    const draw = () => {
      if (!canvasRef.current) return;
      const config = ASPECT_RATIO_CONFIG[settings.aspectRatio];
      if (canvasRef.current.width !== config.width || canvasRef.current.height !== config.height) {
        canvasRef.current.width = config.width;
        canvasRef.current.height = config.height;
      }

      // Prepare assets list for the drawer - ensure strictly following activeBgs order
      const assetsToDraw = activeBgs.map(bg => ({
        id: bg.id,
        type: bg.type,
        element: loadedAssetsRef.current.get(bg.id)
      })).filter(a => a.element) as { element: HTMLImageElement | HTMLVideoElement, type: 'image' | 'video', id: string }[];

      let time = 0;
      if (playbackStatus === 'playing' && audioContextRef.current) {
        time = pauseOffsetRef.current + (audioContextRef.current.currentTime - playbackStartTimeRef.current);
      } else if (playbackStatus === 'paused') {
        time = pauseOffsetRef.current;
      }

      drawVideoFrame(canvasRef.current, assetsToDraw, layers, time % duration, duration, settings.backgroundAnimation, layoutCache.current);
      previewRequestRef.current = requestAnimationFrame(draw);
    };
    draw();
    return () => cancelAnimationFrame(previewRequestRef.current);
  }, [currentResult, settings, playbackStatus, layers, duration, activeBgs]);

  const handleGenerate = async () => {
    if (!settings.text.trim()) return;
    setIsGenerating(true); setErrorMsg(null); stopSignalRef.current = false;
    setCurrentResult(null); stopPreview();
    layoutCache.current.clear(); // Clear cache on new generation

    try {
      if (!audioContextRef.current) audioContextRef.current = new AudioContext({ sampleRate: 24000 });

      const normalizedScript = normalizeText(settings.text);

      // 1. Generate Narration
      const base64Audio = await generateNarration(normalizedScript, settings.voice);
      if (stopSignalRef.current) return;
      const audioData = decode(base64Audio);
      const audioBuffer = await decodeAudioData(audioData, audioContextRef.current, 24000, 1);
      const audioUrl = URL.createObjectURL(new Blob([audioData], { type: 'audio/pcm' }));

      // 2. Dynamic Visual Prompt
      const dynamicPrompt = await generateVisualPrompt(normalizedScript);
      setSettings(s => ({ ...s, style: dynamicPrompt })); // Update UI with new prompt

      // 3. SEO & Image & Thumbnail Data
      const seoPromise = generateSEOMetadata(normalizedScript);
      const thumbDataPromise = generateThumbnailData(normalizedScript);

      let newBg: BackgroundAsset | null = null;
      let bgPromise: Promise<string | null> = Promise.resolve(null);

      const targetRatio = getGeminiAspectRatio(settings.aspectRatio);

      if (settings.generateImage) {
        bgPromise = generateAtmosphereImage(dynamicPrompt, targetRatio);
      }

      const [seo, thumbData, bgUrl] = await Promise.all([seoPromise, thumbDataPromise, bgPromise]);

      if (bgUrl) {
          newBg = { id: Date.now().toString(), url: bgUrl, source: BackgroundSource.AI, type: 'image' };
          setBackgrounds(prev => [...prev, newBg!]);
          setSettings(s => ({ ...s, selectedBackgroundIds: [newBg!.id] }));
      }

      let rawThumbnailUrl: string | null = null;
      let finalThumbnailUrl: string | null = null;

      if (thumbData) {
          rawThumbnailUrl = await generateAtmosphereImage(thumbData.visualPrompt, targetRatio);
          if (rawThumbnailUrl) {
              const dims = ASPECT_RATIO_CONFIG[settings.aspectRatio];
              finalThumbnailUrl = await createCompositeThumbnail(
                  rawThumbnailUrl, 
                  thumbData.overlayText, 
                  dims.width, 
                  dims.height
              );
          }
      }

      if (stopSignalRef.current) return;
      setCurrentResult({ audioUrl, audioBuffer, base64Audio, seo, thumbnailUrl: finalThumbnailUrl || undefined });

      setHistory(prev => [{ 
        id: Date.now().toString(), 
        text: settings.text, 
        voice: settings.voice, 
        timestamp: Date.now(), 
        audioUrl, 
        imageUrl: newBg?.url || activeBgs[0]?.url, 
        thumbnailUrl: finalThumbnailUrl || undefined,
        seo, 
        aspectRatio: settings.aspectRatio 
      }, ...prev]);
    } catch (e: any) {
      if (!stopSignalRef.current) setErrorMsg(e.message || "An error occurred.");
    } finally { setIsGenerating(false); }
  };

  const generateAdditionalBG = async () => {
    setIsGeneratingBG(true);
    try {
      const targetRatio = getGeminiAspectRatio(settings.aspectRatio);
      const imageUrl = await generateAtmosphereImage(settings.style, targetRatio);
      if (imageUrl) {
        const newBg: BackgroundAsset = { id: Date.now().toString(), url: imageUrl, source: BackgroundSource.AI, type: 'image' };
        setBackgrounds(prev => [...prev, newBg]);
        setSettings(s => ({ ...s, selectedBackgroundIds: [...s.selectedBackgroundIds, newBg.id] }));
      }
    } catch (e: any) {
      setErrorMsg("Failed to generate background.");
    } finally {
      setIsGeneratingBG(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const url = event.target?.result as string;
        const newBg: BackgroundAsset = { 
          id: Date.now().toString(), 
          url, 
          source: BackgroundSource.CUSTOM, 
          type: file.type.startsWith('video') ? 'video' : 'image' 
        };
        setBackgrounds(prev => [...prev, newBg]);
        setSettings(s => ({ ...s, selectedBackgroundIds: [...s.selectedBackgroundIds, newBg.id] }));
      };
      reader.readAsDataURL(file);
    }
  };

  const toggleBackgroundSelection = (id: string) => {
    setSettings(prev => {
      const exists = prev.selectedBackgroundIds.includes(id);
      if (exists) {
        return { ...prev, selectedBackgroundIds: prev.selectedBackgroundIds.filter(bid => bid !== id) };
      } else {
        return { ...prev, selectedBackgroundIds: [...prev.selectedBackgroundIds, id] };
      }
    });
  };

  const playPreview = async () => {
    if (!currentResult?.audioBuffer || !audioContextRef.current) return;
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') await ctx.resume();
    if (pauseOffsetRef.current >= duration) pauseOffsetRef.current = 0;
    const source = ctx.createBufferSource();
    source.buffer = currentResult.audioBuffer;
    source.connect(ctx.destination);
    currentPreviewSourceRef.current = source;
    source.onended = () => { if (currentPreviewSourceRef.current === source) { setPlaybackStatus('stopped'); pauseOffsetRef.current = 0; currentPreviewSourceRef.current = null; } };
    source.start(0, pauseOffsetRef.current);
    playbackStartTimeRef.current = ctx.currentTime;
    setPlaybackStatus('playing');
  };

  const pausePreview = () => {
    if (!currentPreviewSourceRef.current || !audioContextRef.current) return;
    pauseOffsetRef.current += (audioContextRef.current.currentTime - playbackStartTimeRef.current);
    currentPreviewSourceRef.current.stop();
    currentPreviewSourceRef.current = null;
    setPlaybackStatus('paused');
  };

  const stopPreview = () => {
    if (currentPreviewSourceRef.current) { currentPreviewSourceRef.current.stop(); currentPreviewSourceRef.current = null; }
    pauseOffsetRef.current = 0; setPlaybackStatus('stopped');
  };

  const startExport = async () => {
    if (!currentResult?.audioBuffer) return;
    stopPreview(); setIsRecording(true); setRecordProgress(0);
    const config = ASPECT_RATIO_CONFIG[settings.aspectRatio];
    const canvas = recordCanvasRef.current!;
    canvas.width = config.width; canvas.height = config.height;

    // Fixed 30 FPS Capture Stream for reliability
    const stream = canvas.captureStream(30);
    const audioCtx = audioContextRef.current!;
    const dest = audioCtx.createMediaStreamDestination();

    // Use high bitrate for quality
    const recorder = new MediaRecorder(new MediaStream([...stream.getTracks(), ...dest.stream.getTracks()]), { 
        mimeType: 'video/webm;codecs=vp9', 
        videoBitsPerSecond: 8000000 
    });

    const chunks: Blob[] = [];
    recorder.ondataavailable = e => chunks.push(e.data);
    recorder.onstop = () => { const blob = new Blob(chunks, { type: 'video/webm' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `noor-studio-${Date.now()}.webm`; a.click(); setIsRecording(false); };

    // Pre-load assets for export synchronously logic-wise (already loaded in ref)
    const exportAssets = activeBgs.map(bg => ({
        id: bg.id,
        type: bg.type,
        element: loadedAssetsRef.current.get(bg.id)
    })).filter(a => a.element) as { element: HTMLImageElement | HTMLVideoElement, type: 'image' | 'video', id: string }[];

    // Ensure videos are playing
    exportAssets.forEach(a => { if (a.element instanceof HTMLVideoElement) a.element.play(); });

    const sourceNode = audioCtx.createBufferSource();
    sourceNode.buffer = currentResult.audioBuffer;
    sourceNode.connect(dest); recorder.start(); sourceNode.start();
    const startTime = audioCtx.currentTime;

    const renderLoop = () => {
      const elapsed = audioCtx.currentTime - startTime;
      const progress = Math.min(elapsed / duration, 1);

      // Update videos time
      exportAssets.forEach(a => {
        if (a.element instanceof HTMLVideoElement) {
           a.element.currentTime = elapsed % a.element.duration;
        }
      });

      // Pass the layoutCache to ensure high performance
      drawVideoFrame(canvas, exportAssets, layers, elapsed, duration, settings.backgroundAnimation, layoutCache.current);
      setRecordProgress(progress * 100);
      if (progress < 1) requestAnimationFrame(renderLoop);
      else setTimeout(() => recorder.stop(), 500);
    };
    renderLoop();
  };

  const copyToClipboard = (text: string, field: string) => {
    navigator.clipboard.writeText(text);
    setCopiedField(field);
    setTimeout(() => setCopiedField(null), 2000);
  };

  return (
    <div className="min-h-screen flex flex-col items-center bg-[#020617] p-4 md:p-8">
      <canvas ref={recordCanvasRef} className="hidden" />
      <input type="file" ref={fileInputRef} className="hidden" accept="image/*,video/*" onChange={handleFileUpload} />

      <header className="w-full max-w-6xl flex justify-between items-center mb-10 relative z-20">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-emerald-800 rounded-2xl shadow-xl shadow-emerald-950/50">
            <Video className="w-8 h-8 text-yellow-400" />
          </div>
          <div>
            <h1 className="text-3xl font-bold text-white tracking-tight">Noor Narrator Studio</h1>
            <p className="text-sm text-emerald-500 font-semibold tracking-widest uppercase">AI Voice & Video Sync</p>
          </div>
        </div>
        <div className="flex gap-4">
          <button onClick={() => setShowHistory(!showHistory)} className="px-5 py-2.5 glass-card rounded-xl hover:bg-emerald-900/40 transition-all flex items-center gap-2 border border-emerald-900/50">
            {showHistory ? <ArrowLeft className="w-5 h-5" /> : <History className="w-5 h-5" />}
            <span className="hidden sm:inline font-bold">{showHistory ? "Back" : "Archive"}</span>
          </button>
        </div>
      </header>

      {isEditing && currentResult ? (
        <div className="fixed inset-0 z-50 bg-[#020617] flex flex-col p-6 overflow-hidden">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-2xl font-black text-white flex items-center gap-3">
              <Edit3 className="text-emerald-500" /> Professional Editor
            </h2>
            <div className="flex gap-3">
               <button onClick={() => setIsEditing(false)} className="px-6 py-2 bg-slate-800 text-white rounded-xl font-bold flex items-center gap-2 hover:bg-slate-700 transition-colors">
                 <X className="w-5 h-5" /> Close Editor
               </button>
               <button onClick={startExport} className="px-6 py-2 bg-emerald-600 text-white rounded-xl font-bold flex items-center gap-2 hover:bg-emerald-500 transition-colors">
                 <Save className="w-5 h-5" /> Export Changes
               </button>
            </div>
          </div>

          <div className="flex-1 grid grid-cols-12 gap-8 overflow-hidden mb-6">
            <div className="col-span-3 glass-card rounded-3xl p-6 overflow-y-auto custom-scrollbar border-emerald-900/30">
              <div className="flex items-center gap-2 mb-6 text-emerald-400 font-black uppercase tracking-widest text-xs">
                <Layers className="w-4 h-4" /> Timeline Layers
              </div>
              <div className="space-y-3">
                {layers.map(layer => (
                  <button 
                    key={layer.id}
                    onClick={() => setSelectedLayerId(layer.id)}
                    className={`w-full p-4 rounded-2xl flex items-center justify-between border transition-all ${selectedLayerId === layer.id ? 'bg-emerald-600/20 border-emerald-500 text-emerald-200' : 'bg-slate-900/50 border-emerald-900/20 text-slate-400'}`}
                  >
                    <div className="flex items-center gap-3">
                      {layer.type === LayerType.TEXT ? <TypeIcon className="w-4 h-4" /> : layer.type === LayerType.IMAGE ? <ImageIcon className="w-4 h-4" /> : <Mic2 className="w-4 h-4" />}
                      <span className="text-xs font-bold truncate max-w-[120px]">
                        {layer.type === LayerType.TEXT ? (layer as any).text : layer.type === LayerType.IMAGE ? 'Image Layer' : 'AI Narration'}
                      </span>
                    </div>
                  </button>
                ))}
              </div>
            </div>

            <div className="col-span-6 flex flex-col items-center justify-center">
              <div className="relative group rounded-3xl overflow-hidden border-8 border-emerald-900/20 shadow-2xl bg-black" style={{ height: '70vh', aspectRatio: settings.aspectRatio.replace(':', '/') }}>
                <canvas ref={canvasRef} className="w-full h-full object-contain" />
              </div>
            </div>

            <div className="col-span-3 glass-card rounded-3xl p-6 overflow-y-auto custom-scrollbar border-emerald-900/30">
              <div className="flex items-center gap-2 mb-6 text-yellow-500 font-black uppercase tracking-widest text-xs">
                <Sliders className="w-4 h-4" /> Properties
              </div>
              <div className="h-full flex flex-col items-center justify-center text-slate-700 text-xs font-bold uppercase tracking-widest text-center">
                   Restoring Editor Features...
              </div>
            </div>
          </div>
        </div>
      ) : null}

      <main className="w-full max-w-6xl grid grid-cols-1 lg:grid-cols-12 gap-10 relative z-10">
        {!showHistory ? (
          <>
            <div className="lg:col-span-7 space-y-6 animate-fade-in">
              <section className="glass-card rounded-3xl p-8 shadow-2xl border-emerald-900/20">
                <div className="flex items-center justify-between mb-6">
                  <h2 className="text-xl font-bold flex items-center gap-3 text-yellow-500">
                    <Mic2 className="w-6 h-6" /> Script Editor
                  </h2>
                </div>
                {errorMsg && (
                  <div className="mb-6 p-4 bg-red-900/20 border border-red-500/30 rounded-2xl flex items-start gap-3">
                    <AlertCircle className="w-5 h-5 text-red-500 mt-0.5 shrink-0" />
                    <div className="text-sm text-red-200"><p className="font-bold mb-1">Attention</p><p>{errorMsg}</p></div>
                  </div>
                )}
                <textarea className="urdu-font w-full h-56 bg-black/40 border border-emerald-900/40 rounded-2xl p-6 text-2xl text-emerald-50 focus:outline-none focus:ring-4 focus:ring-emerald-600/20 transition-all resize-none shadow-inner" placeholder="یہاں اپنا اردو متن لکھیں..." value={settings.text} onChange={(e) => setSettings({ ...settings, text: e.target.value })} dir="rtl" />

                <div className="mt-8 space-y-6">
                  <div className="p-6 bg-emerald-950/20 border border-emerald-900/30 rounded-3xl space-y-4">
                    <div className="flex items-center justify-between">
                      <h3 className="text-xs font-black text-emerald-400 uppercase tracking-widest flex items-center gap-2">
                        <ImageIcon className="w-4 h-4" /> Background Gallery (Slideshow)
                      </h3>
                      <div className="flex gap-2">
                        <button onClick={() => fileInputRef.current?.click()} className="p-2 bg-emerald-800/40 hover:bg-emerald-800/60 text-emerald-100 rounded-lg transition-all flex items-center gap-2 text-[10px] font-bold uppercase tracking-wider">
                          <Upload className="w-3 h-3" /> Upload
                        </button>
                        <button onClick={generateAdditionalBG} disabled={isGeneratingBG || !settings.style} className="p-2 bg-yellow-600/20 hover:bg-yellow-600/40 text-yellow-400 rounded-lg transition-all flex items-center gap-2 text-[10px] font-bold uppercase tracking-wider">
                          {isGeneratingBG ? <Loader2 className="w-3 h-3 animate-spin" /> : <Sparkles className="w-3 h-3" />} Generate AI
                        </button>
                      </div>
                    </div>

                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Dynamic Scene Description (Editable)</label>
                      <input className="w-full bg-black/40 border border-emerald-900/40 rounded-xl p-4 text-sm text-white focus:outline-none focus:ring-2 focus:ring-emerald-600 transition-all" placeholder="Scene description will appear here..." value={settings.style} onChange={(e) => setSettings({...settings, style: e.target.value})} />
                    </div>

                    <div className="grid grid-cols-4 sm:grid-cols-6 gap-3 pt-2">
                      {backgrounds.map(bg => {
                        const isSelected = settings.selectedBackgroundIds.includes(bg.id);
                        const selectionOrder = settings.selectedBackgroundIds.indexOf(bg.id) + 1;
                        return (
                          <button 
                            key={bg.id} 
                            onClick={() => toggleBackgroundSelection(bg.id)}
                            className={`relative aspect-video rounded-lg overflow-hidden border-2 transition-all group ${isSelected ? 'border-yellow-400 shadow-lg shadow-yellow-400/20' : 'border-emerald-900/40 opacity-60 hover:opacity-100'}`}
                          >
                            {bg.type === 'video' ? (
                              <div className="w-full h-full bg-slate-800 flex items-center justify-center">
                                <Video className="w-4 h-4 text-slate-500" />
                              </div>
                            ) : (
                              <img src={bg.url} className="w-full h-full object-cover" alt="Background" />
                            )}

                            {/* Source Indicator */}
                            <div className={`absolute top-1 right-1 p-0.5 rounded-full ${bg.source === BackgroundSource.AI ? 'bg-yellow-500' : 'bg-emerald-500'}`}>
                              {bg.source === BackgroundSource.AI ? <Sparkles className="w-2 h-2 text-white" /> : <Upload className="w-2 h-2 text-white" />}
                            </div>

                            {/* Selection Indicator */}
                            {isSelected && (
                              <div className="absolute inset-0 bg-yellow-500/20 flex items-center justify-center">
                                <div className="bg-yellow-500 text-black font-bold text-xs w-5 h-5 rounded-full flex items-center justify-center shadow-md">
                                  {selectionOrder}
                                </div>
                              </div>
                            )}
                          </button>
                        );
                      })}
                      {backgrounds.length === 0 && (
                        <div className="col-span-full py-8 text-center border-2 border-dashed border-emerald-900/20 rounded-xl">
                          <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">No Backgrounds Loaded</p>
                        </div>
                      )}
                    </div>
                    {backgrounds.length > 0 && (
                      <p className="text-[10px] text-slate-400 text-center uppercase tracking-wider">
                        Select multiple images to create a slideshow.
                      </p>
                    )}
                  </div>

                  <div className="p-6 bg-emerald-950/10 border border-emerald-900/20 rounded-3xl space-y-4">
                    <h3 className="text-xs font-black text-emerald-400 uppercase tracking-widest flex items-center gap-2">
                      <Monitor className="w-4 h-4" /> Cinematic Settings
                    </h3>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                      <div className="space-y-3">
                        <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Narrator Voice</label>
                        <select className="w-full bg-emerald-950/50 border border-emerald-900/40 rounded-xl p-4 text-sm text-emerald-100 focus:outline-none transition-all" value={settings.voice} onChange={(e) => setSettings({ ...settings, voice: e.target.value as VoiceName })}>
                          <option value={VoiceName.CHARON}>Charon - Deep & Spiritual</option>
                          <option value={VoiceName.KORE}>Kore - Clear Classic</option>
                          <option value={VoiceName.PUCK}>Puck - Gentle Narrative</option>
                          <option value={VoiceName.FENRIR}>Fenrir - Strong Male</option>
                          <option value={VoiceName.ZEPHYR}>Zephyr - Elegant Female</option>
                        </select>
                      </div>
                      <div className="space-y-3">
                        <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Background Animation</label>
