import { AnimationType, EditorLayer, LayerType, TextEffect, ImageEffect, BackgroundAnimation } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  relativeX: number; // Offset from the line's geometric center
  globalY: number;   // Note: This is now the actual Y position including paragraph spacing
  index: number;
}

export interface LineMetadata {
  words: string[];
  y: number;
  height: number;
  isParagraphStart: boolean;
  wordIndices: number[];
}

export type LayoutCache = Map<string, { lines: LineMetadata[], words: WordMetadata[] }>;

/**
 * Standard cubic easing for smooth transitions.
 */
const easeInOutCubic = (t: number): number => {
  const clampedT = Math.max(0, Math.min(1, t));
  return clampedT < 0.5 ? 4 * clampedT * clampedT * clampedT : 1 - Math.pow(-2 * clampedT + 2, 3) / 2;
};

/**
 * Normalizes text to ensure 1:1 mapping between TTS and Visuals.
 * Rules:
 * 1. Remove emojis/decorative symbols that TTS might skip.
 * 2. Collapse ALL whitespace (newlines, tabs, double spaces) into a single space.
 * 3. Trim edges.
 */
export const normalizeText = (text: string): string => {
  return text
    .replace(/[\u{1F000}-\u{1F9FF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B50}\u{2B55}]/gu, '')
    .replace(/\s+/g, ' ')
    .trim();
};

/**
 * Checks if a word ends with a sentence-terminating character (Urdu/English).
 * Used to trigger visual paragraph breaks without altering text content.
 */
const isParagraphEnd = (word: string): boolean => {
  // Matches: Urdu Full Stop, Exclamation, Question Marks (Eng/Urdu), Period
  return /[۔!?\.\؟]$/.test(word);
};

/**
 * Calculates words and lines with high precision for RTL alignment.
 * Uses Caching to prevent frame drops during video export.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number,
  cache?: LayoutCache
): { lines: LineMetadata[], words: WordMetadata[] } => {
  // 1. Check Cache
  const normalizedText = normalizeText(text);
  const cacheKey = `${normalizedText}_${maxWidth.toFixed(2)}_${baseFontSize.toFixed(2)}`;

  if (cache && cache.has(cacheKey)) {
    return cache.get(cacheKey)!;
  }

  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  const allWords = normalizedText.split(' ').filter(w => w.length > 0);

  const wordsMetadata: WordMetadata[] = [];
  const lines: LineMetadata[] = [];

  // Tuning weights for Urdu/English TTS synchronization
  const WEIGHT_START_PAD = 150; 
  const WEIGHT_BASE = 35;       
  const WEIGHT_CHAR = 12;       
  const WEIGHT_STOP = 250;      
  const WEIGHT_COMMA = 120;     
  const WEIGHT_PARA = 300;      

  // Calculate total timing weights
  let totalWeight = WEIGHT_START_PAD;

  allWords.forEach((w) => {
    let wWeight = WEIGHT_BASE + (w.length * WEIGHT_CHAR);
    if (w.match(/[۔؟!.\?]/)) wWeight += WEIGHT_STOP;
    else if (w.match(/[،:,]/)) wWeight += WEIGHT_COMMA;
    totalWeight += wWeight;
  });

  // Add end buffer
  totalWeight += WEIGHT_PARA;

  if (totalWeight === 0) totalWeight = 100;

  let weightCursor = WEIGHT_START_PAD;
  const spaceWidth = ctx.measureText(' ').width;

  // Visual gap for paragraphs - increased for better separation
  const PARAGRAPH_SPACING = lineHeight * 0.85; 

  // Layout Engine State
  let currentLineWords: string[] = [];
  let currentLineWordIndices: number[] = []; 
  let currentLineWidth = 0;
  let currentLineY = 0;
  let currentLineIdx = 0;

  // Flags for semantic wrapping
  let pendingParagraphBreak = false; 

  const commitLine = () => {
    if (currentLineWords.length === 0) return;

    // Calculate Explicit RTL Positions
    // In RTL, the first logical word is on the RIGHT.
    const totalW = currentLineWidth;
    let cursorX = totalW / 2; // Start at rightmost edge relative to center

    currentLineWordIndices.forEach((globalIdx, i) => {
       const word = currentLineWords[i];
       const wWidth = ctx.measureText(word).width;

       // Center of the word at this position
       const wordCenterX = cursorX - (wWidth / 2);

       // Assign to metadata
       // NOTE: We update the WordMetadata entry we created earlier
       wordsMetadata[globalIdx].relativeX = wordCenterX;
       wordsMetadata[globalIdx].lineIndex = currentLineIdx;
       wordsMetadata[globalIdx].globalY = currentLineY;

       // Move cursor left
       cursorX -= (wWidth + spaceWidth);
    });

    lines.push({
      words: [...currentLineWords],
      wordIndices: [...currentLineWordIndices],
      y: currentLineY,
      height: lineHeight,
      isParagraphStart: pendingParagraphBreak 
    });

    currentLineWords = [];
    currentLineWordIndices = [];
    currentLineWidth = 0;
    currentLineIdx++;
  };

  // Flow words
  allWords.forEach((word, globalIdx) => {
    const wordWidth = ctx.measureText(word).width;

    // Auto-wrap if width exceeded OR if a paragraph break was pending
    const fits = (currentLineWidth + (currentLineWords.length ? spaceWidth : 0) + wordWidth) <= maxWidth;

    // We force a new line if:
    // 1. We have pending words AND (it doesn't fit OR we have a semantic break)
    // 2. Note: pendingParagraphBreak means the PREVIOUS word ended a sentence. 
    //    So THIS word should start on a new line.

    if (currentLineWords.length > 0 && (pendingParagraphBreak || !fits)) {
         commitLine();

         // Advance Y Position for the NEW line
         currentLineY += lineHeight;

         if (pendingParagraphBreak) {
             // Add extra visual spacing for the paragraph break
             currentLineY += PARAGRAPH_SPACING;
             pendingParagraphBreak = false; 
         }
    }

    // Time Calculation
    let wordWeight = WEIGHT_BASE + (word.length * WEIGHT_CHAR);
    if (word.match(/[۔؟!.\?]/)) wordWeight += WEIGHT_STOP;
    else if (word.match(/[،:,]/)) wordWeight += WEIGHT_COMMA;

    const startTime = weightCursor / totalWeight;
    weightCursor += wordWeight;
    const endTime = weightCursor / totalWeight;

    // Push placeholder metadata (positions fixed in commitLine)
    wordsMetadata.push({
      text: word,
      start: startTime,
      end: endTime,
      width: wordWidth,
      lineIndex: 0, // updated in commit
      relativeX: 0, // updated in commit
      globalY: 0,   // updated in commit
      index: globalIdx
    });

    currentLineWords.push(word);
    currentLineWordIndices.push(globalIdx);
    currentLineWidth += (currentLineWords.length > 1 ? spaceWidth : 0) + wordWidth;

    // Check if THIS word triggers a break for the NEXT word
    if (isParagraphEnd(word)) {
        pendingParagraphBreak = true;
    }
  });

  // Commit remaining
  commitLine();

  const result = { lines, words: wordsMetadata };

  // 3. Write to Cache
  if (cache) {
    cache.set(cacheKey, result);
  }

  return result;
};

export const renderNarrationLayer = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  layer: any,
  globalProgress: number,
  duration: number,
  cache?: LayoutCache
) => {
  const currentTotalTime = globalProgress * duration;
  const progress = (currentTotalTime - layer.startTime) / (layer.endTime - layer.startTime);
  if (progress < 0 || progress > 1.05) return;

  const isLandscape = width > height;
  const isUltraNarrow = (width / height) < 0.55; 

  let scaleRef = isLandscape ? height * 1.45 : width;
  if (isUltraNarrow) scaleRef = width * 1.15;

  // Font size tuned for 4-line display
  const baseFontSize = scaleRef * 0.07; 
  const lineHeight = baseFontSize * 2.4;
  const maxWidth = width * (isLandscape ? 0.65 : 0.82);

  // 1. Get Metadata (With Paragraph Spacing support & Caching)
  const { lines, words } = getWordMetadata(ctx, layer.text, maxWidth, baseFontSize, lineHeight, cache);
  if (words.length === 0) return;

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.direction = 'ltr'; 
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // 2. Determine Active Word & Line
  let activeIdx = -1;
  for (let i = 0; i < words.length; i++) {
    if (progress >= words[i].start && progress < words[i].end) {
      activeIdx = i;
      break;
    }
  }

  if (activeIdx === -1) {
    if (progress >= words[words.length - 1].end) activeIdx = words.length - 1;
    else activeIdx = 0; 
  }

  const currentWord = words[activeIdx];
  const currentLineIndex = currentWord.lineIndex;

  // 3. Teleprompter Logic: Camera Position
  // Camera centers on the active line.
  let cameraY = lines[currentLineIndex].y;

  // Smooth Scroll Logic
  const lineWords = words.filter(w => w.lineIndex === currentLineIndex);
  const isLastWordInLine = lineWords[lineWords.length - 1] === currentWord;

  if (isLastWordInLine && currentLineIndex < lines.length - 1) {
    const wordDuration = currentWord.end - currentWord.start;
    const p = (progress - currentWord.start) / wordDuration;

    // Slide to next line in the last 60% of the word
    if (p > 0.4) {
       const slideT = (p - 0.4) / 0.6; 
       const nextLineY = lines[currentLineIndex + 1].y;
       const diff = nextLineY - cameraY;
       cameraY += diff * easeInOutCubic(slideT);
    }
  }

  const screenCenterY = height * 0.48; 

  // 4. Render Lines (Active Window: 2 Previous, 1 Current, 1 Upcoming)
  // Window logic: We need visibility for approx 2.5 lines ABOVE and 1.5 lines BELOW.
  // This ensures the 4 lines (2 prev, 1 cur, 1 next) are well covered.
  const VISUAL_WINDOW_HEIGHT = lineHeight * 3.5; 

  lines.forEach((lineMeta, lineIdx) => {
    const relativeY = lineMeta.y - cameraY;

    // Culling
    if (Math.abs(relativeY) > VISUAL_WINDOW_HEIGHT) return;

    const drawY = screenCenterY + relativeY;

    // Focus Factor Calculation
    // We want the center line to be 100%.
    // Lines +/- 1 LH away to be ~65%.
    // Lines +/- 2 LH away to be ~35%.
    const distRatio = Math.abs(relativeY) / (lineHeight * 3.0);
    const focusFactor = Math.max(0, 1 - distRatio); 

    // Visual Parameters
    // Scale: 1.1 at center, drops to 0.9 at edges.
    const scale = 0.9 + (0.2 * focusFactor); 

    // Opacity: 1.0 at center, drops to 0.2 at edges.
    const opacity = 0.2 + (0.8 * focusFactor); 

    ctx.save();
    ctx.translate(width / 2, drawY);
    ctx.scale(scale, scale);

    const lineWordsMeta = words.filter(w => w.lineIndex === lineIdx);

    lineWordsMeta.forEach((w) => {
      // Precise Timestamp Highlight
      const isWordActive = progress >= w.start && progress < w.end;
      const isWordPast = progress >= w.end;

      ctx.save();
      ctx.translate(w.relativeX, 0); // RTL positioning

      if (isWordActive) {
        // Active Word: Bright Amber, Glow, Pulse
        ctx.shadowBlur = 30;
        ctx.shadowColor = 'rgba(251, 191, 36, 0.9)'; // Amber glow
        ctx.fillStyle = '#fbbf24'; 
        ctx.globalAlpha = 1;

        const wp = (progress - w.start) / (w.end - w.start);
        const pulse = 1.0 + (0.05 * Math.sin(wp * Math.PI));
        ctx.scale(pulse, pulse);
      } else {
        // Inactive Words
        if (lineIdx === currentLineIndex) {
            // Current line, but not active word
            if (isWordPast) {
                 ctx.fillStyle = '#cbd5e1'; // Light Slate
                 ctx.globalAlpha = 0.9;
            } else {
                 ctx.fillStyle = '#ffffff'; // White
                 ctx.globalAlpha = 1.0;
            }
        } else {
             // Context lines (Previous/Next)
             // Use subdued slate color and opacity based on distance
             ctx.fillStyle = '#94a3b8'; // Slate-400
             ctx.globalAlpha = opacity * 0.7; 
        }
        ctx.shadowBlur = 0;
      }

      ctx.fillText(w.text, 0, 0);
      ctx.restore();
    });

    ctx.restore();
  });
};

const renderTextLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const duration = layer.endTime - layer.startTime;
  const localTime = time - layer.startTime;
  ctx.save();
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `${layer.fontSize}px Inter, sans-serif`;
  ctx.fillStyle = layer.color;
  let alpha = 1; let scale = 1; let offsetY = 0;
  if (layer.animation === 'fade') {
    if (localTime < 0.5) alpha = localTime / 0.5;
    else if (duration - localTime < 0.5) alpha = (duration - localTime) / 0.5;
  } else if (layer.animation === 'slide') {
    if (localTime < 0.5) offsetY = (1 - (localTime / 0.5)) * 50;
  } else if (layer.animation === 'bounce') {
    scale = 1 + 0.1 * Math.sin(localTime * 10);
  } else if (layer.animation === 'typewriter') {
    const charsToShow = Math.floor(layer.text.length * Math.min(1, localTime / (duration * 0.5)));
    ctx.fillText(layer.text.substring(0, charsToShow), width * layer.x, height * layer.y + offsetY);
    ctx.restore(); return;
  }
  ctx.globalAlpha = alpha;
  ctx.translate(width * layer.x, height * layer.y + offsetY);
  ctx.scale(scale, scale);
  ctx.fillText(layer.text, 0, 0);
  ctx.restore();
};

const renderImageLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const localTime = time - layer.startTime;
  const duration = layer.endTime - layer.startTime;
  const img = new Image();
  img.src = layer.url;
  if (!img.complete) return;
  ctx.save();
  let scale = layer.scale;
  let alpha = 1;
  if (layer.animation === 'zoom') scale *= (1 + 0.2 * (localTime / duration));
  else if (layer.animation === 'fade') alpha = Math.min(1, localTime / 0.5) * Math.min(1, (duration - localTime) / 0.5);
  ctx.globalAlpha = alpha;
  const drawW = img.width * scale;
  const drawH = img.height * scale;
  ctx.drawImage(img, width * layer.x - drawW / 2, height * layer.y - drawH / 2, drawW, drawH);
  ctx.restore();
};

interface LoadedBackgroundAsset {
  element: HTMLImageElement | HTMLVideoElement;
  type: 'image' | 'video';
  id: string;
}

const drawBackgroundSlideshow = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  bgAssets: LoadedBackgroundAsset[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation
) => {
  if (bgAssets.length === 0) return;

  const slideDuration = Math.max(2, totalDuration / bgAssets.length);
  const totalSlides = bgAssets.length;

  let slideIndex = Math.floor(currentTime / slideDuration);
  if (slideIndex >= totalSlides) slideIndex = totalSlides - 1;

  const currentAsset = bgAssets[slideIndex];
  const timeInSlide = currentTime - (slideIndex * slideDuration);
  const fadeDuration = 1.0; 
  const remainingTime = slideDuration - timeInSlide;

  let nextAsset: LoadedBackgroundAsset | null = null;
  let crossFadeOpacity = 0;

  if (remainingTime < fadeDuration && slideIndex < totalSlides - 1) {
    nextAsset = bgAssets[slideIndex + 1];
    crossFadeOpacity = 1 - (remainingTime / fadeDuration);
  }

  const drawSingleBg = (asset: LoadedBackgroundAsset, opacity: number, progressForAnim: number) => {
    const bg = asset.element;
    const bgW = bg instanceof HTMLVideoElement ? bg.videoWidth : bg.width;
    const bgH = bg instanceof HTMLVideoElement ? bg.videoHeight : bg.height;

    if (bgW > 0) {
      let baseScale = Math.max(width / bgW, height / bgH);
      let animScale = 1.0;
      let animX = 0;
      let animY = 0;

      switch (bgAnim) {
        case BackgroundAnimation.ZOOM_IN:
          animScale = 1.0 + (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.ZOOM_OUT:
          animScale = 1.15 - (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.PAN_LEFT:
          animX = -(progressForAnim * width * 0.1);
          break;
        case BackgroundAnimation.PAN_RIGHT:
          animX = (progressForAnim * width * 0.1) - (width * 0.1);
          break;
      }

      ctx.save();
      ctx.globalAlpha = 0.55 * opacity;
      const finalScale = baseScale * animScale;
      const drawWidth = bgW * finalScale;
      const drawHeight = bgH * finalScale;
      const x = (width - drawWidth) / 2 + animX;
      const y = (height - drawHeight) / 2 + animY;

      ctx.drawImage(bg, x, y, drawWidth, drawHeight);
      ctx.restore();
    }
  };

  const currentSlideProgress = timeInSlide / slideDuration;
  drawSingleBg(currentAsset, 1, currentSlideProgress);

  if (nextAsset && crossFadeOpacity > 0) {
    drawSingleBg(nextAsset, crossFadeOpacity, 0);
  }
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  bgAssets: LoadedBackgroundAsset[], 
  layers: EditorLayer[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation = BackgroundAnimation.NONE,
  layoutCache?: LayoutCache
) => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  const { width, height } = canvas;
  const progress = totalDuration > 0 ? currentTime / totalDuration : 0;

  ctx.fillStyle = '#020617';
  ctx.fillRect(0, 0, width, height);

  drawBackgroundSlideshow(ctx, width, height, bgAssets, currentTime, totalDuration, bgAnim);

  const vignette = ctx.createRadialGradient(width/2, height/2, height * 0.1, width/2, height/2, height * 1.0);
  vignette.addColorStop(0, 'rgba(2, 6, 23, 0.15)');
  vignette.addColorStop(0.6, 'rgba(2, 6, 23, 0.5)');
  vignette.addColorStop(1, 'rgba(2, 6, 23, 0.98)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  const sortedLayers = [...layers].sort((a, b) => a.zIndex - b.zIndex);
  sortedLayers.forEach(layer => {
    if (!layer.visible) return;
    if (layer.type === LayerType.NARRATION) {
      renderNarrationLayer(ctx, width, height, layer, progress, totalDuration, layoutCache);
    } else if (layer.type === LayerType.TEXT) {
      renderTextLayer(ctx, width, height, layer, currentTime);
    } else if (layer.type === LayerType.IMAGE) {
      renderImageLayer(ctx, width, height, layer, currentTime);
    }
  });

  ctx.save();
  ctx.globalAlpha = 0.25;
  ctx.font = `bold ${width * 0.022}px Inter, sans-serif`;
  ctx.fillStyle = 'white';
  ctx.textAlign = 'center';
  ctx.fillText('NOOR STUDIO AI • CINEMATIC NARRATOR', width / 2, height * 0.96);
  ctx.restore();
};

export const createCompositeThumbnail = async (
  imageUrl: string,
  overlayText: string,
  targetWidth: number,
  targetHeight: number
): Promise<string> => {
  const canvas = document.createElement('canvas');
  canvas.width = targetWidth;
  canvas.height = targetHeight;
  const ctx = canvas.getContext('2d');
  if (!ctx) return imageUrl;

  const img = new Image();
  img.crossOrigin = "anonymous";
  img.src = imageUrl;

  await new Promise((resolve) => {
    if (img.complete) resolve(true);
    img.onload = () => resolve(true);
    img.onerror = () => resolve(false);
  });

  const scale = Math.max(canvas.width / img.width, canvas.height / img.height);
  const x = (canvas.width / 2) - (img.width / 2) * scale;
  const y = (canvas.height / 2) - (img.height / 2) * scale;
  ctx.drawImage(img, x, y, img.width * scale, img.height * scale);

  const gradient = ctx.createLinearGradient(0, canvas.height * 0.4, 0, canvas.height);
  gradient.addColorStop(0, 'rgba(0,0,0,0)');
  gradient.addColorStop(0.6, 'rgba(0,0,0,0.7)');
  gradient.addColorStop(1, 'rgba(0,0,0,0.9)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  if (overlayText) {
    const fontSize = Math.floor(canvas.width * 0.08); 
    ctx.font = `bold ${fontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.direction = 'rtl';

    const words = overlayText.split(' ');
    let lines: string[] = [];
    let currentLine = words[0];

    const maxWidth = canvas.width * 0.8;
    for (let i = 1; i < words.length; i++) {
        const word = words[i];
        const width = ctx.measureText(currentLine + " " + word).width;
        if (width < maxWidth) {
            currentLine += " " + word;
        } else {
            lines.push(currentLine);
            currentLine = word;
        }
    }
    lines.push(currentLine);

    const lineHeight = fontSize * 1.4;
    let startY = canvas.height - (canvas.height * 0.15) - (lines.length * lineHeight);

    ctx.shadowColor = "rgba(0,0,0,0.8)";
    ctx.shadowBlur = 15;
    ctx.strokeStyle = "black";
    ctx.lineWidth = fontSize * 0.15;
    ctx.fillStyle = "#fbbf24"; 

    lines.forEach((line, i) => {
       const lineY = startY + (i * lineHeight);
       ctx.strokeText(line, canvas.width / 2, lineY);
       ctx.fillText(line, canvas.width / 2, lineY);
    });
  }

  const brandSize = Math.max(16, canvas.width * 0.03);
  ctx.font = `bold ${brandSize}px "Inter", sans-serif`;
  ctx.fillStyle = 'rgba(255,255,255,0.7)';
  ctx.shadowBlur = 0;
  ctx.lineWidth = 0;
  ctx.textAlign = 'right';
  ctx.fillText('NOOR STUDIO AI', canvas.width - (brandSize * 1.5), brandSize * 2);

  return canvas.toDataURL('image/png');
};

import { AnimationType, EditorLayer, LayerType, TextEffect, ImageEffect, BackgroundAnimation } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  relativeX: number; // Offset from the line's geometric center
  globalY: number;   // Note: This is now the actual Y position including paragraph spacing
  index: number;
}

export interface LineMetadata {
  words: string[];
  y: number;
  height: number;
  isParagraphStart: boolean;
  wordIndices: number[]; // Store indices for O(1) lookup
}

export type LayoutCache = Map<string, { lines: LineMetadata[], words: WordMetadata[] }>;

/**
 * Standard cubic easing for smooth transitions.
 */
const easeInOutCubic = (t: number): number => {
  const clampedT = Math.max(0, Math.min(1, t));
  return clampedT < 0.5 ? 4 * clampedT * clampedT * clampedT : 1 - Math.pow(-2 * clampedT + 2, 3) / 2;
};

/**
 * Normalizes text to ensure 1:1 mapping between TTS and Visuals.
 */
export const normalizeText = (text: string): string => {
  return text
    .replace(/[\u{1F000}-\u{1F9FF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B50}\u{2B55}]/gu, '')
    .replace(/\s+/g, ' ')
    .trim();
};

/**
 * Checks if a word ends with a sentence-terminating character (Urdu/English).
 */
const isParagraphEnd = (word: string): boolean => {
  return /[۔!?\.\؟]$/.test(word);
};

// Tuning weights for Urdu/English TTS synchronization
// Adjusted to prevent drift on long texts
const WEIGHT_START_PAD = 100; 
const WEIGHT_BASE = 30;       
const WEIGHT_CHAR = 10;       
const WEIGHT_STOP = 180; // Reduced from 250 to prevent lag accumulation
const WEIGHT_COMMA = 80; // Reduced from 120
const WEIGHT_PARA = 200;      

const getWordWeight = (word: string): number => {
  let wWeight = WEIGHT_BASE + (word.length * WEIGHT_CHAR);
  if (word.match(/[۔؟!.\?]/)) wWeight += WEIGHT_STOP;
  else if (word.match(/[،:,]/)) wWeight += WEIGHT_COMMA;
  return wWeight;
};

/**
 * Calculates words and lines with high precision for RTL alignment.
 * Uses Caching to prevent frame drops during video export.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number,
  cache?: LayoutCache
): { lines: LineMetadata[], words: WordMetadata[] } => {
  // 1. Check Cache
  const normalizedText = normalizeText(text);
  const cacheKey = `${normalizedText}_${maxWidth.toFixed(2)}_${baseFontSize.toFixed(2)}`;

  if (cache && cache.has(cacheKey)) {
    return cache.get(cacheKey)!;
  }

  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  const allWords = normalizedText.split(' ').filter(w => w.length > 0);

  const wordsMetadata: WordMetadata[] = [];
  const lines: LineMetadata[] = [];

  // Calculate total timing weights using helper to ensure consistency
  let totalWeight = WEIGHT_START_PAD;
  allWords.forEach((w) => {
    totalWeight += getWordWeight(w);
  });
  totalWeight += WEIGHT_PARA;

  if (totalWeight === 0) totalWeight = 100;

  let weightCursor = WEIGHT_START_PAD;
  const spaceWidth = ctx.measureText(' ').width;

  // Visual gap for paragraphs
  const PARAGRAPH_SPACING = lineHeight * 0.85; 

  // Layout Engine State
  let currentLineWords: string[] = [];
  let currentLineWordIndices: number[] = []; 
  let currentLineWidth = 0;
  let currentLineY = 0;
  let currentLineIdx = 0;

  let pendingParagraphBreak = false; 

  const commitLine = () => {
    if (currentLineWords.length === 0) return;

    // Calculate Explicit RTL Positions
    const totalW = currentLineWidth;
    let cursorX = totalW / 2; 

    currentLineWordIndices.forEach((globalIdx, i) => {
       const word = currentLineWords[i];
       const wWidth = ctx.measureText(word).width;
       const wordCenterX = cursorX - (wWidth / 2);

       wordsMetadata[globalIdx].relativeX = wordCenterX;
       wordsMetadata[globalIdx].lineIndex = currentLineIdx;
       wordsMetadata[globalIdx].globalY = currentLineY;

       cursorX -= (wWidth + spaceWidth);
    });

    lines.push({
      words: [...currentLineWords],
      wordIndices: [...currentLineWordIndices],
      y: currentLineY,
      height: lineHeight,
      isParagraphStart: pendingParagraphBreak 
    });

    currentLineWords = [];
    currentLineWordIndices = [];
    currentLineWidth = 0;
    currentLineIdx++;
  };

  // Flow words
  allWords.forEach((word, globalIdx) => {
    const wordWidth = ctx.measureText(word).width;
    const fits = (currentLineWidth + (currentLineWords.length ? spaceWidth : 0) + wordWidth) <= maxWidth;

    if (currentLineWords.length > 0 && (pendingParagraphBreak || !fits)) {
         commitLine();
         currentLineY += lineHeight;
         if (pendingParagraphBreak) {
             currentLineY += PARAGRAPH_SPACING;
             pendingParagraphBreak = false; 
         }
    }

    // Time Calculation
    const wordWeight = getWordWeight(word);
    const startTime = weightCursor / totalWeight;
    weightCursor += wordWeight;
    const endTime = weightCursor / totalWeight;

    wordsMetadata.push({
      text: word,
      start: startTime,
      end: endTime,
      width: wordWidth,
      lineIndex: 0, // updated in commit
      relativeX: 0, // updated in commit
      globalY: 0,   // updated in commit
      index: globalIdx
    });

    currentLineWords.push(word);
    currentLineWordIndices.push(globalIdx);
    currentLineWidth += (currentLineWords.length > 1 ? spaceWidth : 0) + wordWidth;

    if (isParagraphEnd(word)) {
        pendingParagraphBreak = true;
    }
  });

  commitLine();

  const result = { lines, words: wordsMetadata };

  if (cache) {
    cache.set(cacheKey, result);
  }

  return result;
};

export const renderNarrationLayer = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  layer: any,
  globalProgress: number,
  duration: number,
  cache?: LayoutCache
) => {
  const currentTotalTime = globalProgress * duration;
  const progress = (currentTotalTime - layer.startTime) / (layer.endTime - layer.startTime);
  if (progress < 0 || progress > 1.05) return;

  const isLandscape = width > height;
  const isUltraNarrow = (width / height) < 0.55; 

  let scaleRef = isLandscape ? height * 1.45 : width;
  if (isUltraNarrow) scaleRef = width * 1.15;

  const baseFontSize = scaleRef * 0.07; 
  const lineHeight = baseFontSize * 2.4;
  const maxWidth = width * (isLandscape ? 0.65 : 0.82);

  const { lines, words } = getWordMetadata(ctx, layer.text, maxWidth, baseFontSize, lineHeight, cache);
  if (words.length === 0) return;

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.direction = 'ltr'; 
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // 2. Determine Active Word & Line
  let activeIdx = -1;
  // Performance optimization: Start search from expected position based on progress
  const guessIdx = Math.floor(progress * words.length);
  const startSearch = Math.max(0, Math.min(guessIdx - 20, words.length - 1));

  for (let i = startSearch; i < words.length; i++) {
    if (progress >= words[i].start && progress < words[i].end) {
      activeIdx = i;
      break;
    }
  }
  // Fallback if not found in forward search (should imply earlier or not found)
  if (activeIdx === -1) {
     for (let i = 0; i < startSearch; i++) {
        if (progress >= words[i].start && progress < words[i].end) {
            activeIdx = i;
            break;
        }
     }
  }

  if (activeIdx === -1) {
    if (progress >= words[words.length - 1].end) activeIdx = words.length - 1;
    else activeIdx = 0; 
  }

  const currentWord = words[activeIdx];
  const currentLineIndex = currentWord.lineIndex;

  // 3. Teleprompter Logic: Camera Position
  let cameraY = lines[currentLineIndex].y;

  // Smooth Scroll Logic using INDICES from LineMetadata instead of filter()
  const currentLineMeta = lines[currentLineIndex];
  // The last word of the current line is the one at the last index of wordIndices
  const lastWordIdx = currentLineMeta.wordIndices[currentLineMeta.wordIndices.length - 1];
  const isLastWordInLine = (activeIdx === lastWordIdx);

  if (isLastWordInLine && currentLineIndex < lines.length - 1) {
    const wordDuration = currentWord.end - currentWord.start;
    const p = (progress - currentWord.start) / wordDuration;

    if (p > 0.4) {
       const slideT = (p - 0.4) / 0.6; 
       const nextLineY = lines[currentLineIndex + 1].y;
       const diff = nextLineY - cameraY;
       cameraY += diff * easeInOutCubic(slideT);
    }
  }

  const screenCenterY = height * 0.48; 
  const VISUAL_WINDOW_HEIGHT = lineHeight * 3.5; 

  lines.forEach((lineMeta, lineIdx) => {
    const relativeY = lineMeta.y - cameraY;

    // Culling
    if (Math.abs(relativeY) > VISUAL_WINDOW_HEIGHT) return;

    const drawY = screenCenterY + relativeY;
    const distRatio = Math.abs(relativeY) / (lineHeight * 3.0);
    const focusFactor = Math.max(0, 1 - distRatio); 

    const scale = 0.9 + (0.2 * focusFactor); 
    const opacity = 0.2 + (0.8 * focusFactor); 

    ctx.save();
    ctx.translate(width / 2, drawY);
    ctx.scale(scale, scale);

    // Use pre-calculated indices for rendering loop (O(1) access instead of filter)
    lineMeta.wordIndices.forEach((wIdx) => {
      const w = words[wIdx];
      const isWordActive = activeIdx === wIdx; // Fast comparison
      const isWordPast = activeIdx > wIdx;

      ctx.save();
      ctx.translate(w.relativeX, 0); 

      if (isWordActive) {
        ctx.shadowBlur = 30;
        ctx.shadowColor = 'rgba(251, 191, 36, 0.9)'; 
        ctx.fillStyle = '#fbbf24'; 
        ctx.globalAlpha = 1;

        const wp = (progress - w.start) / (w.end - w.start);
        const pulse = 1.0 + (0.05 * Math.sin(wp * Math.PI));
        ctx.scale(pulse, pulse);
      } else {
        if (lineIdx === currentLineIndex) {
            if (isWordPast) {
                 ctx.fillStyle = '#cbd5e1'; 
                 ctx.globalAlpha = 0.9;
            } else {
                 ctx.fillStyle = '#ffffff'; 
                 ctx.globalAlpha = 1.0;
            }
        } else {
             ctx.fillStyle = '#94a3b8'; 
             ctx.globalAlpha = opacity * 0.7; 
        }
        ctx.shadowBlur = 0;
      }

      ctx.fillText(w.text, 0, 0);
      ctx.restore();
    });

    ctx.restore();
  });
};

const renderTextLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const duration = layer.endTime - layer.startTime;
  const localTime = time - layer.startTime;
  ctx.save();
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `${layer.fontSize}px Inter, sans-serif`;
  ctx.fillStyle = layer.color;
  let alpha = 1; let scale = 1; let offsetY = 0;
  if (layer.animation === 'fade') {
    if (localTime < 0.5) alpha = localTime / 0.5;
    else if (duration - localTime < 0.5) alpha = (duration - localTime) / 0.5;
  } else if (layer.animation === 'slide') {
    if (localTime < 0.5) offsetY = (1 - (localTime / 0.5)) * 50;
  } else if (layer.animation === 'bounce') {
    scale = 1 + 0.1 * Math.sin(localTime * 10);
  } else if (layer.animation === 'typewriter') {
    const charsToShow = Math.floor(layer.text.length * Math.min(1, localTime / (duration * 0.5)));
    ctx.fillText(layer.text.substring(0, charsToShow), width * layer.x, height * layer.y + offsetY);
    ctx.restore(); return;
  }
  ctx.globalAlpha = alpha;
  ctx.translate(width * layer.x, height * layer.y + offsetY);
  ctx.scale(scale, scale);
  ctx.fillText(layer.text, 0, 0);
  ctx.restore();
};

const renderImageLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const localTime = time - layer.startTime;
  const duration = layer.endTime - layer.startTime;
  const img = new Image();
  img.src = layer.url;
  if (!img.complete) return;
  ctx.save();
  let scale = layer.scale;
  let alpha = 1;
  if (layer.animation === 'zoom') scale *= (1 + 0.2 * (localTime / duration));
  else if (layer.animation === 'fade') alpha = Math.min(1, localTime / 0.5) * Math.min(1, (duration - localTime) / 0.5);
  ctx.globalAlpha = alpha;
  const drawW = img.width * scale;
  const drawH = img.height * scale;
  ctx.drawImage(img, width * layer.x - drawW / 2, height * layer.y - drawH / 2, drawW, drawH);
  ctx.restore();
};

interface LoadedBackgroundAsset {
  element: HTMLImageElement | HTMLVideoElement;
  type: 'image' | 'video';
  id: string;
}

const drawBackgroundSlideshow = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  bgAssets: LoadedBackgroundAsset[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation
) => {
  if (bgAssets.length === 0) return;

  const slideDuration = Math.max(2, totalDuration / bgAssets.length);
  const totalSlides = bgAssets.length;

  let slideIndex = Math.floor(currentTime / slideDuration);
  if (slideIndex >= totalSlides) slideIndex = totalSlides - 1;

  const currentAsset = bgAssets[slideIndex];
  const timeInSlide = currentTime - (slideIndex * slideDuration);
  const fadeDuration = 1.0; 
  const remainingTime = slideDuration - timeInSlide;

  let nextAsset: LoadedBackgroundAsset | null = null;
  let crossFadeOpacity = 0;

  if (remainingTime < fadeDuration && slideIndex < totalSlides - 1) {
    nextAsset = bgAssets[slideIndex + 1];
    crossFadeOpacity = 1 - (remainingTime / fadeDuration);
  }

  const drawSingleBg = (asset: LoadedBackgroundAsset, opacity: number, progressForAnim: number) => {
    const bg = asset.element;
    const bgW = bg instanceof HTMLVideoElement ? bg.videoWidth : bg.width;
    const bgH = bg instanceof HTMLVideoElement ? bg.videoHeight : bg.height;

    if (bgW > 0) {
      let baseScale = Math.max(width / bgW, height / bgH);
      let animScale = 1.0;
      let animX = 0;
      let animY = 0;

      switch (bgAnim) {
        case BackgroundAnimation.ZOOM_IN:
          animScale = 1.0 + (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.ZOOM_OUT:
          animScale = 1.15 - (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.PAN_LEFT:
          animX = -(progressForAnim * width * 0.1);
          break;
        case BackgroundAnimation.PAN_RIGHT:
          animX = (progressForAnim * width * 0.1) - (width * 0.1);
          break;
      }

      ctx.save();
      ctx.globalAlpha = 0.55 * opacity;
      const finalScale = baseScale * animScale;
      const drawWidth = bgW * finalScale;
      const drawHeight = bgH * finalScale;
      const x = (width - drawWidth) / 2 + animX;
      const y = (height - drawHeight) / 2 + animY;

      ctx.drawImage(bg, x, y, drawWidth, drawHeight);
      ctx.restore();
    }
  };

  const currentSlideProgress = timeInSlide / slideDuration;
  drawSingleBg(currentAsset, 1, currentSlideProgress);

  if (nextAsset && crossFadeOpacity > 0) {
    drawSingleBg(nextAsset, crossFadeOpacity, 0);
  }
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  bgAssets: LoadedBackgroundAsset[], 
  layers: EditorLayer[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation = BackgroundAnimation.NONE,
  layoutCache?: LayoutCache
) => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  const { width, height } = canvas;
  const progress = totalDuration > 0 ? currentTime / totalDuration : 0;

  ctx.fillStyle = '#020617';
  ctx.fillRect(0, 0, width, height);

  drawBackgroundSlideshow(ctx, width, height, bgAssets, currentTime, totalDuration, bgAnim);

  const vignette = ctx.createRadialGradient(width/2, height/2, height * 0.1, width/2, height/2, height * 1.0);
  vignette.addColorStop(0, 'rgba(2, 6, 23, 0.15)');
  vignette.addColorStop(0.6, 'rgba(2, 6, 23, 0.5)');
  vignette.addColorStop(1, 'rgba(2, 6, 23, 0.98)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  const sortedLayers = [...layers].sort((a, b) => a.zIndex - b.zIndex);
  sortedLayers.forEach(layer => {
    if (!layer.visible) return;
    if (layer.type === LayerType.NARRATION) {
      renderNarrationLayer(ctx, width, height, layer, progress, totalDuration, layoutCache);
    } else if (layer.type === LayerType.TEXT) {
      renderTextLayer(ctx, width, height, layer, currentTime);
    } else if (layer.type === LayerType.IMAGE) {
      renderImageLayer(ctx, width, height, layer, currentTime);
    }
  });

  ctx.save();
  ctx.globalAlpha = 0.25;
  ctx.font = `bold ${width * 0.022}px Inter, sans-serif`;
  ctx.fillStyle = 'white';
  ctx.textAlign = 'center';
  ctx.fillText('NOOR STUDIO AI • CINEMATIC NARRATOR', width / 2, height * 0.96);
  ctx.restore();
};

export const createCompositeThumbnail = async (
  imageUrl: string,
  overlayText: string,
  targetWidth: number,
  targetHeight: number
): Promise<string> => {
  const canvas = document.createElement('canvas');
  canvas.width = targetWidth;
  canvas.height = targetHeight;
  const ctx = canvas.getContext('2d');
  if (!ctx) return imageUrl;

  const img = new Image();
  img.crossOrigin = "anonymous";
  img.src = imageUrl;

  await new Promise((resolve) => {
    if (img.complete) resolve(true);
    img.onload = () => resolve(true);
    img.onerror = () => resolve(false);
  });

  const scale = Math.max(canvas.width / img.width, canvas.height / img.height);
  const x = (canvas.width / 2) - (img.width / 2) * scale;
  const y = (canvas.height / 2) - (img.height / 2) * scale;
  ctx.drawImage(img, x, y, img.width * scale, img.height * scale);

  const gradient = ctx.createLinearGradient(0, canvas.height * 0.4, 0, canvas.height);
  gradient.addColorStop(0, 'rgba(0,0,0,0)');
  gradient.addColorStop(0.6, 'rgba(0,0,0,0.7)');
  gradient.addColorStop(1, 'rgba(0,0,0,0.9)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  if (overlayText) {
    const fontSize = Math.floor(canvas.width * 0.08); 
    ctx.font = `bold ${fontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.direction = 'rtl';

    const words = overlayText.split(' ');
    let lines: string[] = [];
    let currentLine = words[0];

    const maxWidth = canvas.width * 0.8;
    for (let i = 1; i < words.length; i++) {
        const word = words[i];
        const width = ctx.measureText(currentLine + " " + word).width;
        if (width < maxWidth) {
            currentLine += " " + word;
        } else {
            lines.push(currentLine);
            currentLine = word;
        }
    }
    lines.push(currentLine);

    const lineHeight = fontSize * 1.4;
    let startY = canvas.height - (canvas.height * 0.15) - (lines.length * lineHeight);

    ctx.shadowColor = "rgba(0,0,0,0.8)";
    ctx.shadowBlur = 15;
    ctx.strokeStyle = "black";
    ctx.lineWidth = fontSize * 0.15;
    ctx.fillStyle = "#fbbf24"; 

    lines.forEach((line, i) => {
       const lineY = startY + (i * lineHeight);
       ctx.strokeText(line, canvas.width / 2, lineY);
       ctx.fillText(line, canvas.width / 2, lineY);
    });
  }

  const brandSize = Math.max(16, canvas.width * 0.03);
  ctx.font = `bold ${brandSize}px "Inter", sans-serif`;
  ctx.fillStyle = 'rgba(255,255,255,0.7)';
  ctx.shadowBlur = 0;
  ctx.lineWidth = 0;
  ctx.textAlign = 'right';
  ctx.fillText('NOOR STUDIO AI', canvas.width - (brandSize * 1.5), brandSize * 2);

  return canvas.toDataURL('image/png');
};

import { AnimationType, EditorLayer, LayerType, TextEffect, ImageEffect, BackgroundAnimation } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  relativeX: number; // Offset from the line's geometric center
  globalY: number;   // Note: This is now the actual Y position including paragraph spacing
  index: number;
}

export interface LineMetadata {
  words: string[];
  y: number;
  height: number;
  isParagraphStart: boolean;
  wordIndices: number[]; // Store indices for O(1) lookup
}

export type LayoutCache = Map<string, { lines: LineMetadata[], words: WordMetadata[] }>;

/**
 * Standard cubic easing for smooth transitions.
 */
const easeInOutCubic = (t: number): number => {
  const clampedT = Math.max(0, Math.min(1, t));
  return clampedT < 0.5 ? 4 * clampedT * clampedT * clampedT : 1 - Math.pow(-2 * clampedT + 2, 3) / 2;
};

/**
 * Normalizes text to ensure 1:1 mapping between TTS and Visuals.
 */
export const normalizeText = (text: string): string => {
  return text
    .replace(/[\u{1F000}-\u{1F9FF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B50}\u{2B55}]/gu, '')
    .replace(/\s+/g, ' ')
    .trim();
};

/**
 * Checks if a word ends with a sentence-terminating character (Urdu/English).
 */
const isParagraphEnd = (word: string): boolean => {
  return /[۔!?\.\؟]$/.test(word);
};

// Tuning weights for Urdu/English TTS synchronization
// Adjusted to prevent drift on long texts by correcting for diacritics and flow
const WEIGHT_START_PAD = 50;  // Reduced padding at start
const WEIGHT_BASE = 25;       // Base cost per word
const WEIGHT_CHAR = 8;        // Cost per character (stripped)
const WEIGHT_STOP = 160;      // Full stops/Paragraph breaks
const WEIGHT_COMMA = 60;      // Commas/Pauses
const WEIGHT_PARA = 150;      // End of stream buffer

const getWordWeight = (word: string): number => {
  // CRITICAL FIX: Strip Urdu/Arabic diacritics (Harakat) for length calculation.
  // These chars exist in string but take 0 time to speak as they modify vowels.
  // Range includes: Fathatan, Dammatan, Kasratan, Fatha, Damma, Kasra, Shadda, Sukun, Superscript Alef
  const cleanWord = word.replace(/[\u064B-\u065F\u0670]/g, "");

  let wWeight = WEIGHT_BASE + (cleanWord.length * WEIGHT_CHAR);

  // Add weight for punctuation that induces pauses
  if (word.match(/[۔؟!.\?]/)) {
      wWeight += WEIGHT_STOP; 
  } else if (word.match(/[،:,]/)) {
      wWeight += WEIGHT_COMMA;
  }
  return wWeight;
};

/**
 * Calculates words and lines with high precision for RTL alignment.
 * Uses Caching to prevent frame drops during video export.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number,
  cache?: LayoutCache
): { lines: LineMetadata[], words: WordMetadata[] } => {
  // 1. Check Cache
  const normalizedText = normalizeText(text);
  const cacheKey = `${normalizedText}_${maxWidth.toFixed(2)}_${baseFontSize.toFixed(2)}`;

  if (cache && cache.has(cacheKey)) {
    return cache.get(cacheKey)!;
  }

  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  const allWords = normalizedText.split(' ').filter(w => w.length > 0);

  const wordsMetadata: WordMetadata[] = [];
  const lines: LineMetadata[] = [];

  // Calculate total timing weights using helper to ensure consistency
  let totalWeight = WEIGHT_START_PAD;
  allWords.forEach((w) => {
    totalWeight += getWordWeight(w);
  });
  totalWeight += WEIGHT_PARA;

  if (totalWeight === 0) totalWeight = 100;

  let weightCursor = WEIGHT_START_PAD;
  const spaceWidth = ctx.measureText(' ').width;

  // Visual gap for paragraphs (Purely visual, does not add time weight)
  const PARAGRAPH_SPACING = lineHeight * 1.0; 

  // Layout Engine State
  let currentLineWords: string[] = [];
  let currentLineWordIndices: number[] = []; 
  let currentLineWidth = 0;
  let currentLineY = 0;
  let currentLineIdx = 0;

  let pendingParagraphBreak = false; 

  const commitLine = () => {
    if (currentLineWords.length === 0) return;

    // Calculate Explicit RTL Positions
    const totalW = currentLineWidth;
    let cursorX = totalW / 2; 

    currentLineWordIndices.forEach((globalIdx, i) => {
       const word = currentLineWords[i];
       const wWidth = ctx.measureText(word).width;
       const wordCenterX = cursorX - (wWidth / 2);

       wordsMetadata[globalIdx].relativeX = wordCenterX;
       wordsMetadata[globalIdx].lineIndex = currentLineIdx;
       wordsMetadata[globalIdx].globalY = currentLineY;

       cursorX -= (wWidth + spaceWidth);
    });

    lines.push({
      words: [...currentLineWords],
      wordIndices: [...currentLineWordIndices],
      y: currentLineY,
      height: lineHeight,
      isParagraphStart: pendingParagraphBreak 
    });

    currentLineWords = [];
    currentLineWordIndices = [];
    currentLineWidth = 0;
    currentLineIdx++;
  };

  // Flow words
  allWords.forEach((word, globalIdx) => {
    const wordWidth = ctx.measureText(word).width;
    const fits = (currentLineWidth + (currentLineWords.length ? spaceWidth : 0) + wordWidth) <= maxWidth;

    // Line break conditions:
    // 1. Doesn't fit width
    // 2. Pending paragraph break (previous word ended a sentence)
    if (currentLineWords.length > 0 && (pendingParagraphBreak || !fits)) {
         commitLine();
         currentLineY += lineHeight;

         // Apply visual spacing if it's a paragraph break
         if (pendingParagraphBreak) {
             currentLineY += PARAGRAPH_SPACING;
             pendingParagraphBreak = false; 
         }
    }

    // Time Calculation
    const wordWeight = getWordWeight(word);
    const startTime = weightCursor / totalWeight;
    weightCursor += wordWeight;
    const endTime = weightCursor / totalWeight;

    wordsMetadata.push({
      text: word,
      start: startTime,
      end: endTime,
      width: wordWidth,
      lineIndex: 0, // updated in commit
      relativeX: 0, // updated in commit
      globalY: 0,   // updated in commit
      index: globalIdx
    });

    currentLineWords.push(word);
    currentLineWordIndices.push(globalIdx);
    currentLineWidth += (currentLineWords.length > 1 ? spaceWidth : 0) + wordWidth;

    // Check if THIS word triggers a break for the NEXT word
    if (isParagraphEnd(word)) {
        pendingParagraphBreak = true;
    }
  });

  commitLine();

  const result = { lines, words: wordsMetadata };

  if (cache) {
    cache.set(cacheKey, result);
  }

  return result;
};

export const renderNarrationLayer = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  layer: any,
  globalProgress: number,
  duration: number,
  cache?: LayoutCache
) => {
  const currentTotalTime = globalProgress * duration;
  const progress = (currentTotalTime - layer.startTime) / (layer.endTime - layer.startTime);
  if (progress < 0 || progress > 1.05) return;

  const isLandscape = width > height;
  const isUltraNarrow = (width / height) < 0.55; 

  let scaleRef = isLandscape ? height * 1.45 : width;
  if (isUltraNarrow) scaleRef = width * 1.15;

  const baseFontSize = scaleRef * 0.07; 
  const lineHeight = baseFontSize * 2.4;
  const maxWidth = width * (isLandscape ? 0.65 : 0.82);

  const { lines, words } = getWordMetadata(ctx, layer.text, maxWidth, baseFontSize, lineHeight, cache);
  if (words.length === 0) return;

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.direction = 'ltr'; 
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // 2. Determine Active Word & Line
  let activeIdx = -1;
  // Performance optimization: Start search from expected position based on progress
  const guessIdx = Math.floor(progress * words.length);
  const startSearch = Math.max(0, Math.min(guessIdx - 20, words.length - 1));

  for (let i = startSearch; i < words.length; i++) {
    if (progress >= words[i].start && progress < words[i].end) {
      activeIdx = i;
      break;
    }
  }
  // Fallback if not found in forward search
  if (activeIdx === -1) {
     for (let i = 0; i < startSearch; i++) {
        if (progress >= words[i].start && progress < words[i].end) {
            activeIdx = i;
            break;
        }
     }
  }

  if (activeIdx === -1) {
    if (progress >= words[words.length - 1].end) activeIdx = words.length - 1;
    else activeIdx = 0; 
  }

  const currentWord = words[activeIdx];
  const currentLineIndex = currentWord.lineIndex;

  // 3. Teleprompter Logic: Camera Position
  let cameraY = lines[currentLineIndex].y;

  // Smooth Scroll Logic
  const currentLineMeta = lines[currentLineIndex];
  const lastWordIdx = currentLineMeta.wordIndices[currentLineMeta.wordIndices.length - 1];
  const isLastWordInLine = (activeIdx === lastWordIdx);

  if (isLastWordInLine && currentLineIndex < lines.length - 1) {
    const wordDuration = currentWord.end - currentWord.start;
    const p = (progress - currentWord.start) / wordDuration;

    // Start scrolling earlier (at 40%) to handle potential large visual jumps (paragraph breaks) smoothly
    if (p > 0.4) {
       const slideT = (p - 0.4) / 0.6; 
       const nextLineY = lines[currentLineIndex + 1].y;
       const diff = nextLineY - cameraY;
       cameraY += diff * easeInOutCubic(slideT);
    }
  }

  const screenCenterY = height * 0.48; 
  const VISUAL_WINDOW_HEIGHT = lineHeight * 3.8; // Slightly larger window to catch paragraph breaks

  lines.forEach((lineMeta, lineIdx) => {
    const relativeY = lineMeta.y - cameraY;

    // Culling
    if (Math.abs(relativeY) > VISUAL_WINDOW_HEIGHT) return;

    const drawY = screenCenterY + relativeY;
    const distRatio = Math.abs(relativeY) / (lineHeight * 3.0);
    const focusFactor = Math.max(0, 1 - distRatio); 

    const scale = 0.9 + (0.2 * focusFactor); 
    const opacity = 0.2 + (0.8 * focusFactor); 

    ctx.save();
    ctx.translate(width / 2, drawY);
    ctx.scale(scale, scale);

    // Render words in line
    lineMeta.wordIndices.forEach((wIdx) => {
      const w = words[wIdx];
      const isWordActive = activeIdx === wIdx; 
      const isWordPast = activeIdx > wIdx;

      ctx.save();
      ctx.translate(w.relativeX, 0); 

      if (isWordActive) {
        ctx.shadowBlur = 30;
        ctx.shadowColor = 'rgba(251, 191, 36, 0.9)'; 
        ctx.fillStyle = '#fbbf24'; 
        ctx.globalAlpha = 1;

        const wp = (progress - w.start) / (w.end - w.start);
        const pulse = 1.0 + (0.05 * Math.sin(wp * Math.PI));
        ctx.scale(pulse, pulse);
      } else {
        if (lineIdx === currentLineIndex) {
            if (isWordPast) {
                 ctx.fillStyle = '#cbd5e1'; 
                 ctx.globalAlpha = 0.9;
            } else {
                 ctx.fillStyle = '#ffffff'; 
                 ctx.globalAlpha = 1.0;
            }
        } else {
             ctx.fillStyle = '#94a3b8'; 
             ctx.globalAlpha = opacity * 0.6; 
        }
        ctx.shadowBlur = 0;
      }

      ctx.fillText(w.text, 0, 0);
      ctx.restore();
    });

    ctx.restore();
  });
};

const renderTextLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const duration = layer.endTime - layer.startTime;
  const localTime = time - layer.startTime;
  ctx.save();
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `${layer.fontSize}px Inter, sans-serif`;
  ctx.fillStyle = layer.color;
  let alpha = 1; let scale = 1; let offsetY = 0;
  if (layer.animation === 'fade') {
    if (localTime < 0.5) alpha = localTime / 0.5;
    else if (duration - localTime < 0.5) alpha = (duration - localTime) / 0.5;
  } else if (layer.animation === 'slide') {
    if (localTime < 0.5) offsetY = (1 - (localTime / 0.5)) * 50;
  } else if (layer.animation === 'bounce') {
    scale = 1 + 0.1 * Math.sin(localTime * 10);
  } else if (layer.animation === 'typewriter') {
    const charsToShow = Math.floor(layer.text.length * Math.min(1, localTime / (duration * 0.5)));
    ctx.fillText(layer.text.substring(0, charsToShow), width * layer.x, height * layer.y + offsetY);
    ctx.restore(); return;
  }
  ctx.globalAlpha = alpha;
  ctx.translate(width * layer.x, height * layer.y + offsetY);
  ctx.scale(scale, scale);
  ctx.fillText(layer.text, 0, 0);
  ctx.restore();
};

const renderImageLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const localTime = time - layer.startTime;
  const duration = layer.endTime - layer.startTime;
  const img = new Image();
  img.src = layer.url;
  if (!img.complete) return;
  ctx.save();
  let scale = layer.scale;
  let alpha = 1;
  if (layer.animation === 'zoom') scale *= (1 + 0.2 * (localTime / duration));
  else if (layer.animation === 'fade') alpha = Math.min(1, localTime / 0.5) * Math.min(1, (duration - localTime) / 0.5);
  ctx.globalAlpha = alpha;
  const drawW = img.width * scale;
  const drawH = img.height * scale;
  ctx.drawImage(img, width * layer.x - drawW / 2, height * layer.y - drawH / 2, drawW, drawH);
  ctx.restore();
};

interface LoadedBackgroundAsset {
  element: HTMLImageElement | HTMLVideoElement;
  type: 'image' | 'video';
  id: string;
}

const drawBackgroundSlideshow = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  bgAssets: LoadedBackgroundAsset[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation
) => {
  if (bgAssets.length === 0) return;

  const slideDuration = Math.max(2, totalDuration / bgAssets.length);
  const totalSlides = bgAssets.length;

  let slideIndex = Math.floor(currentTime / slideDuration);
  if (slideIndex >= totalSlides) slideIndex = totalSlides - 1;

  const currentAsset = bgAssets[slideIndex];
  const timeInSlide = currentTime - (slideIndex * slideDuration);
  const fadeDuration = 1.0; 
  const remainingTime = slideDuration - timeInSlide;

  let nextAsset: LoadedBackgroundAsset | null = null;
  let crossFadeOpacity = 0;

  if (remainingTime < fadeDuration && slideIndex < totalSlides - 1) {
    nextAsset = bgAssets[slideIndex + 1];
    crossFadeOpacity = 1 - (remainingTime / fadeDuration);
  }

  const drawSingleBg = (asset: LoadedBackgroundAsset, opacity: number, progressForAnim: number) => {
    const bg = asset.element;
    const bgW = bg instanceof HTMLVideoElement ? bg.videoWidth : bg.width;
    const bgH = bg instanceof HTMLVideoElement ? bg.videoHeight : bg.height;

    if (bgW > 0) {
      let baseScale = Math.max(width / bgW, height / bgH);
      let animScale = 1.0;
      let animX = 0;
      let animY = 0;

      switch (bgAnim) {
        case BackgroundAnimation.ZOOM_IN:
          animScale = 1.0 + (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.ZOOM_OUT:
          animScale = 1.15 - (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.PAN_LEFT:
          animX = -(progressForAnim * width * 0.1);
          break;
        case BackgroundAnimation.PAN_RIGHT:
          animX = (progressForAnim * width * 0.1) - (width * 0.1);
          break;
      }

      ctx.save();
      ctx.globalAlpha = 0.55 * opacity;
      const finalScale = baseScale * animScale;
      const drawWidth = bgW * finalScale;
      const drawHeight = bgH * finalScale;
      const x = (width - drawWidth) / 2 + animX;
      const y = (height - drawHeight) / 2 + animY;

      ctx.drawImage(bg, x, y, drawWidth, drawHeight);
      ctx.restore();
    }
  };

  const currentSlideProgress = timeInSlide / slideDuration;
  drawSingleBg(currentAsset, 1, currentSlideProgress);

  if (nextAsset && crossFadeOpacity > 0) {
    drawSingleBg(nextAsset, crossFadeOpacity, 0);
  }
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  bgAssets: LoadedBackgroundAsset[], 
  layers: EditorLayer[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation = BackgroundAnimation.NONE,
  layoutCache?: LayoutCache
) => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  const { width, height } = canvas;
  const progress = totalDuration > 0 ? currentTime / totalDuration : 0;

  ctx.fillStyle = '#020617';
  ctx.fillRect(0, 0, width, height);

  drawBackgroundSlideshow(ctx, width, height, bgAssets, currentTime, totalDuration, bgAnim);

  const vignette = ctx.createRadialGradient(width/2, height/2, height * 0.1, width/2, height/2, height * 1.0);
  vignette.addColorStop(0, 'rgba(2, 6, 23, 0.15)');
  vignette.addColorStop(0.6, 'rgba(2, 6, 23, 0.5)');
  vignette.addColorStop(1, 'rgba(2, 6, 23, 0.98)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  const sortedLayers = [...layers].sort((a, b) => a.zIndex - b.zIndex);
  sortedLayers.forEach(layer => {
    if (!layer.visible) return;
    if (layer.type === LayerType.NARRATION) {
      renderNarrationLayer(ctx, width, height, layer, progress, totalDuration, layoutCache);
    } else if (layer.type === LayerType.TEXT) {
      renderTextLayer(ctx, width, height, layer, currentTime);
    } else if (layer.type === LayerType.IMAGE) {
      renderImageLayer(ctx, width, height, layer, currentTime);
    }
  });

  ctx.save();
  ctx.globalAlpha = 0.25;
  ctx.font = `bold ${width * 0.022}px Inter, sans-serif`;
  ctx.fillStyle = 'white';
  ctx.textAlign = 'center';
  ctx.fillText('NOOR STUDIO AI • CINEMATIC NARRATOR', width / 2, height * 0.96);
  ctx.restore();
};

export const createCompositeThumbnail = async (
  imageUrl: string,
  overlayText: string,
  targetWidth: number,
  targetHeight: number
): Promise<string> => {
  const canvas = document.createElement('canvas');
  canvas.width = targetWidth;
  canvas.height = targetHeight;
  const ctx = canvas.getContext('2d');
  if (!ctx) return imageUrl;

  const img = new Image();
  img.crossOrigin = "anonymous";
  img.src = imageUrl;

  await new Promise((resolve) => {
    if (img.complete) resolve(true);
    img.onload = () => resolve(true);
    img.onerror = () => resolve(false);
  });

  const scale = Math.max(canvas.width / img.width, canvas.height / img.height);
  const x = (canvas.width / 2) - (img.width / 2) * scale;
  const y = (canvas.height / 2) - (img.height / 2) * scale;
  ctx.drawImage(img, x, y, img.width * scale, img.height * scale);

  const gradient = ctx.createLinearGradient(0, canvas.height * 0.4, 0, canvas.height);
  gradient.addColorStop(0, 'rgba(0,0,0,0)');
  gradient.addColorStop(0.6, 'rgba(0,0,0,0.7)');
  gradient.addColorStop(1, 'rgba(0,0,0,0.9)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  if (overlayText) {
    const fontSize = Math.floor(canvas.width * 0.08); 
    ctx.font = `bold ${fontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.direction = 'rtl';

    const words = overlayText.split(' ');
    let lines: string[] = [];
    let currentLine = words[0];

    const maxWidth = canvas.width * 0.8;
    for (let i = 1; i < words.length; i++) {
        const word = words[i];
        const width = ctx.measureText(currentLine + " " + word).width;
        if (width < maxWidth) {
            currentLine += " " + word;
        } else {
            lines.push(currentLine);
            currentLine = word;
        }
    }
    lines.push(currentLine);

    const lineHeight = fontSize * 1.4;
    let startY = canvas.height - (canvas.height * 0.15) - (lines.length * lineHeight);

    ctx.shadowColor = "rgba(0,0,0,0.8)";
    ctx.shadowBlur = 15;
    ctx.strokeStyle = "black";
    ctx.lineWidth = fontSize * 0.15;
    ctx.fillStyle = "#fbbf24"; 

    lines.forEach((line, i) => {
       const lineY = startY + (i * lineHeight);
       ctx.strokeText(line, canvas.width / 2, lineY);
       ctx.fillText(line, canvas.width / 2, lineY);
    });
  }

  const brandSize = Math.max(16, canvas.width * 0.03);
  ctx.font = `bold ${brandSize}px "Inter", sans-serif`;
  ctx.fillStyle = 'rgba(255,255,255,0.7)';
  ctx.shadowBlur = 0;
  ctx.lineWidth = 0;
  ctx.textAlign = 'right';
  ctx.fillText('NOOR STUDIO AI', canvas.width - (brandSize * 1.5), brandSize * 2);

  return canvas.toDataURL('image/png');
};

import { AnimationType, EditorLayer, LayerType, TextEffect, ImageEffect, BackgroundAnimation } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  relativeX: number; // Offset from the line's geometric center
  globalY: number;   // Note: This is now the actual Y position including paragraph spacing
  index: number;
}

export interface LineMetadata {
  words: string[];
  y: number;
  height: number;
  isParagraphStart: boolean;
  wordIndices: number[]; // Store indices for O(1) lookup
}

export type LayoutCache = Map<string, { lines: LineMetadata[], words: WordMetadata[] }>;

/**
 * Standard cubic easing for smooth transitions.
 */
const easeInOutCubic = (t: number): number => {
  const clampedT = Math.max(0, Math.min(1, t));
  return clampedT < 0.5 ? 4 * clampedT * clampedT * clampedT : 1 - Math.pow(-2 * clampedT + 2, 3) / 2;
};

/**
 * Normalizes text to ensure 1:1 mapping between TTS and Visuals.
 */
export const normalizeText = (text: string): string => {
  return text
    .replace(/[\u{1F000}-\u{1F9FF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B50}\u{2B55}]/gu, '')
    .replace(/\s+/g, ' ')
    .trim();
};

/**
 * Merges standalone punctuation with the previous word to prevent "ghost" timing blocks.
 * e.g., ["Hello", "world", "."] -> ["Hello", "world."]
 */
const mergePunctuation = (words: string[]): string[] => {
  const merged: string[] = [];
  const punctPattern = /^[۔!?\.\؟,،:;]+$/;

  for (const w of words) {
    if (merged.length > 0 && punctPattern.test(w)) {
      merged[merged.length - 1] += w;
    } else {
      merged.push(w);
    }
  }
  return merged;
};

/**
 * Checks if a word ends with a sentence-terminating character (Urdu/English).
 */
const isParagraphEnd = (word: string): boolean => {
  return /[۔!?\.\؟]$/.test(word);
};

// Tuning weights for Urdu/English TTS synchronization
// Optimized for "Gemini Flash TTS" cadence
const WEIGHT_START_PAD = 40;  
const WEIGHT_BASE = 12;       // Lower base to reduce lag on short words
const WEIGHT_CHAR = 4;        // Reduced character weight (relying more on word count)
const WEIGHT_DIGIT = 15;      // Extra weight per digit (numbers take longer to say)
const WEIGHT_STOP = 90;       // Reduced stop penalty (pauses are rarely >1s)
const WEIGHT_COMMA = 30;      // Short breath pause
const WEIGHT_PARA = 100;      // End buffer

const getWordWeight = (word: string): number => {
  // 1. Clean for length count: Remove diacritics AND punctuation
  // We want to measure the "speakable" mass of the word.
  const cleanWord = word
    .replace(/[\u064B-\u065F\u0670]/g, "") // Urdu/Arabic Diacritics
    .replace(/[۔!?\.\؟,،:;"]/g, "");       // Punctuation

  let wWeight = WEIGHT_BASE + (cleanWord.length * WEIGHT_CHAR);

  // 2. Digit Handling: Numbers (1992) take much longer to say than they look
  const digitCount = (word.match(/\d/g) || []).length;
  if (digitCount > 0) {
      wWeight += (digitCount * WEIGHT_DIGIT);
  }

  // 3. Punctuation Timing
  if (word.match(/[۔؟!.\?]/)) {
      wWeight += WEIGHT_STOP; 
  } else if (word.match(/[،:,]/)) {
      wWeight += WEIGHT_COMMA;
  }
  return wWeight;
};

/**
 * Calculates words and lines with high precision for RTL alignment.
 * Uses Caching to prevent frame drops during video export.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number,
  cache?: LayoutCache
): { lines: LineMetadata[], words: WordMetadata[] } => {
  // 1. Check Cache
  const normalizedText = normalizeText(text);
  const cacheKey = `${normalizedText}_${maxWidth.toFixed(2)}_${baseFontSize.toFixed(2)}`;

  if (cache && cache.has(cacheKey)) {
    return cache.get(cacheKey)!;
  }

  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // 2. Pre-process words: Split & Merge Punctuation
  const rawWords = normalizedText.split(' ').filter(w => w.length > 0);
  const allWords = mergePunctuation(rawWords);

  const wordsMetadata: WordMetadata[] = [];
  const lines: LineMetadata[] = [];

  // Calculate total timing weights
  let totalWeight = WEIGHT_START_PAD;
  allWords.forEach((w) => {
    totalWeight += getWordWeight(w);
  });
  totalWeight += WEIGHT_PARA;

  if (totalWeight === 0) totalWeight = 100;

  let weightCursor = WEIGHT_START_PAD;
  const spaceWidth = ctx.measureText(' ').width;

  // Visual gap for paragraphs
  const PARAGRAPH_SPACING = lineHeight * 1.0; 

  // Layout Engine State
  let currentLineWords: string[] = [];
  let currentLineWordIndices: number[] = []; 
  let currentLineWidth = 0;
  let currentLineY = 0;
  let currentLineIdx = 0;

  let pendingParagraphBreak = false; 

  const commitLine = () => {
    if (currentLineWords.length === 0) return;

    // Calculate Explicit RTL Positions (Center Alignment Logic)
    // For proper Urdu centering, we calculate offsets from the center.
    const totalW = currentLineWidth;
    let cursorX = totalW / 2; // Start from right edge of the block (since we draw relative to center)

    // RTL: First word in array is right-most visually? 
    // Actually, in Canvas LTR drawing with RTL text, we usually draw usually.
    // Here we manually position.
    // For Urdu: Word 0 is rightmost.
    // Let's stick to the previous working logic: standard iteration with centering.

    currentLineWordIndices.forEach((globalIdx, i) => {
       const word = currentLineWords[i];
       const wWidth = ctx.measureText(word).width;
       const wordCenterX = cursorX - (wWidth / 2);

       wordsMetadata[globalIdx].relativeX = wordCenterX;
       wordsMetadata[globalIdx].lineIndex = currentLineIdx;
       wordsMetadata[globalIdx].globalY = currentLineY;

       cursorX -= (wWidth + spaceWidth);
    });

    lines.push({
      words: [...currentLineWords],
      wordIndices: [...currentLineWordIndices],
      y: currentLineY,
      height: lineHeight,
      isParagraphStart: pendingParagraphBreak 
    });

    currentLineWords = [];
    currentLineWordIndices = [];
    currentLineWidth = 0;
    currentLineIdx++;
  };

  // Flow words
  allWords.forEach((word, globalIdx) => {
    const wordWidth = ctx.measureText(word).width;
    const fits = (currentLineWidth + (currentLineWords.length ? spaceWidth : 0) + wordWidth) <= maxWidth;

    // Line break triggers
    if (currentLineWords.length > 0 && (pendingParagraphBreak || !fits)) {
         commitLine();
         currentLineY += lineHeight;

         if (pendingParagraphBreak) {
             currentLineY += PARAGRAPH_SPACING;
             pendingParagraphBreak = false; 
         }
    }

    // Time Calculation
    const wordWeight = getWordWeight(word);
    const startTime = weightCursor / totalWeight;
    weightCursor += wordWeight;
    const endTime = weightCursor / totalWeight;

    wordsMetadata.push({
      text: word,
      start: startTime,
      end: endTime,
      width: wordWidth,
      lineIndex: 0, // updated in commit
      relativeX: 0, // updated in commit
      globalY: 0,   // updated in commit
      index: globalIdx
    });

    currentLineWords.push(word);
    currentLineWordIndices.push(globalIdx);
    currentLineWidth += (currentLineWords.length > 1 ? spaceWidth : 0) + wordWidth;

    if (isParagraphEnd(word)) {
        pendingParagraphBreak = true;
    }
  });

  commitLine();

  const result = { lines, words: wordsMetadata };

  if (cache) {
    cache.set(cacheKey, result);
  }

  return result;
};

export const renderNarrationLayer = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  layer: any,
  globalProgress: number,
  duration: number,
  cache?: LayoutCache
) => {
  const currentTotalTime = globalProgress * duration;
  const progress = (currentTotalTime - layer.startTime) / (layer.endTime - layer.startTime);
  if (progress < 0 || progress > 1.05) return;

  const isLandscape = width > height;
  const isUltraNarrow = (width / height) < 0.55; 

  let scaleRef = isLandscape ? height * 1.45 : width;
  if (isUltraNarrow) scaleRef = width * 1.15;

  const baseFontSize = scaleRef * 0.07; 
  const lineHeight = baseFontSize * 2.4;
  const maxWidth = width * (isLandscape ? 0.65 : 0.82);

  const { lines, words } = getWordMetadata(ctx, layer.text, maxWidth, baseFontSize, lineHeight, cache);
  if (words.length === 0) return;

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.direction = 'ltr'; 
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // 2. Determine Active Word & Line
  let activeIdx = -1;
  const guessIdx = Math.floor(progress * words.length);
  const startSearch = Math.max(0, Math.min(guessIdx - 20, words.length - 1));

  for (let i = startSearch; i < words.length; i++) {
    if (progress >= words[i].start && progress < words[i].end) {
      activeIdx = i;
      break;
    }
  }
  if (activeIdx === -1) {
     for (let i = 0; i < startSearch; i++) {
        if (progress >= words[i].start && progress < words[i].end) {
            activeIdx = i;
            break;
        }
     }
  }

  if (activeIdx === -1) {
    if (progress >= words[words.length - 1].end) activeIdx = words.length - 1;
    else activeIdx = 0; 
  }

  const currentWord = words[activeIdx];
  const currentLineIndex = currentWord.lineIndex;

  // 3. Teleprompter Logic: Camera Position
  let cameraY = lines[currentLineIndex].y;

  // Smooth Scroll Logic
  const currentLineMeta = lines[currentLineIndex];
  const lastWordIdx = currentLineMeta.wordIndices[currentLineMeta.wordIndices.length - 1];
  const isLastWordInLine = (activeIdx === lastWordIdx);

  // Only scroll if we are not on the last line
  if (isLastWordInLine && currentLineIndex < lines.length - 1) {
    const wordDuration = currentWord.end - currentWord.start;
    const p = (progress - currentWord.start) / wordDuration;

    // Scroll during the last 60% of the word's duration (which often includes the pause)
    if (p > 0.4) {
       const slideT = (p - 0.4) / 0.6; 
       const nextLineY = lines[currentLineIndex + 1].y;
       const diff = nextLineY - cameraY;
       cameraY += diff * easeInOutCubic(slideT);
    }
  }

  const screenCenterY = height * 0.48; 
  const VISUAL_WINDOW_HEIGHT = lineHeight * 3.8; 

  lines.forEach((lineMeta, lineIdx) => {
    const relativeY = lineMeta.y - cameraY;

    // Culling
    if (Math.abs(relativeY) > VISUAL_WINDOW_HEIGHT) return;

    const drawY = screenCenterY + relativeY;
    const distRatio = Math.abs(relativeY) / (lineHeight * 3.0);
    const focusFactor = Math.max(0, 1 - distRatio); 

    const scale = 0.9 + (0.2 * focusFactor); 
    const opacity = 0.2 + (0.8 * focusFactor); 

    ctx.save();
    ctx.translate(width / 2, drawY);
    ctx.scale(scale, scale);

    // Render words in line
    lineMeta.wordIndices.forEach((wIdx) => {
      const w = words[wIdx];
      const isWordActive = activeIdx === wIdx; 
      const isWordPast = activeIdx > wIdx;

      ctx.save();
      ctx.translate(w.relativeX, 0); 

      if (isWordActive) {
        ctx.shadowBlur = 30;
        ctx.shadowColor = 'rgba(251, 191, 36, 0.9)'; 
        ctx.fillStyle = '#fbbf24'; 
        ctx.globalAlpha = 1;

        const wp = (progress - w.start) / (w.end - w.start);
        const pulse = 1.0 + (0.05 * Math.sin(wp * Math.PI));
        ctx.scale(pulse, pulse);
      } else {
        if (lineIdx === currentLineIndex) {
            if (isWordPast) {
                 ctx.fillStyle = '#cbd5e1'; 
                 ctx.globalAlpha = 0.9;
            } else {
                 ctx.fillStyle = '#ffffff'; 
                 ctx.globalAlpha = 1.0;
            }
        } else {
             ctx.fillStyle = '#94a3b8'; 
             ctx.globalAlpha = opacity * 0.6; 
        }
        ctx.shadowBlur = 0;
      }

      ctx.fillText(w.text, 0, 0);
      ctx.restore();
    });

    ctx.restore();
  });
};

const renderTextLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const duration = layer.endTime - layer.startTime;
  const localTime = time - layer.startTime;
  ctx.save();
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `${layer.fontSize}px Inter, sans-serif`;
  ctx.fillStyle = layer.color;
  let alpha = 1; let scale = 1; let offsetY = 0;
  if (layer.animation === 'fade') {
    if (localTime < 0.5) alpha = localTime / 0.5;
    else if (duration - localTime < 0.5) alpha = (duration - localTime) / 0.5;
  } else if (layer.animation === 'slide') {
    if (localTime < 0.5) offsetY = (1 - (localTime / 0.5)) * 50;
  } else if (layer.animation === 'bounce') {
    scale = 1 + 0.1 * Math.sin(localTime * 10);
  } else if (layer.animation === 'typewriter') {
    const charsToShow = Math.floor(layer.text.length * Math.min(1, localTime / (duration * 0.5)));
    ctx.fillText(layer.text.substring(0, charsToShow), width * layer.x, height * layer.y + offsetY);
    ctx.restore(); return;
  }
  ctx.globalAlpha = alpha;
  ctx.translate(width * layer.x, height * layer.y + offsetY);
  ctx.scale(scale, scale);
  ctx.fillText(layer.text, 0, 0);
  ctx.restore();
};

const renderImageLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const localTime = time - layer.startTime;
  const duration = layer.endTime - layer.startTime;
  const img = new Image();
  img.src = layer.url;
  if (!img.complete) return;
  ctx.save();
  let scale = layer.scale;
  let alpha = 1;
  if (layer.animation === 'zoom') scale *= (1 + 0.2 * (localTime / duration));
  else if (layer.animation === 'fade') alpha = Math.min(1, localTime / 0.5) * Math.min(1, (duration - localTime) / 0.5);
  ctx.globalAlpha = alpha;
  const drawW = img.width * scale;
  const drawH = img.height * scale;
  ctx.drawImage(img, width * layer.x - drawW / 2, height * layer.y - drawH / 2, drawW, drawH);
  ctx.restore();
};

interface LoadedBackgroundAsset {
  element: HTMLImageElement | HTMLVideoElement;
  type: 'image' | 'video';
  id: string;
}

const drawBackgroundSlideshow = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  bgAssets: LoadedBackgroundAsset[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation
) => {
  if (bgAssets.length === 0) return;

  const slideDuration = Math.max(2, totalDuration / bgAssets.length);
  const totalSlides = bgAssets.length;

  let slideIndex = Math.floor(currentTime / slideDuration);
  if (slideIndex >= totalSlides) slideIndex = totalSlides - 1;

  const currentAsset = bgAssets[slideIndex];
  const timeInSlide = currentTime - (slideIndex * slideDuration);
  const fadeDuration = 1.0; 
  const remainingTime = slideDuration - timeInSlide;

  let nextAsset: LoadedBackgroundAsset | null = null;
  let crossFadeOpacity = 0;

  if (remainingTime < fadeDuration && slideIndex < totalSlides - 1) {
    nextAsset = bgAssets[slideIndex + 1];
    crossFadeOpacity = 1 - (remainingTime / fadeDuration);
  }

  const drawSingleBg = (asset: LoadedBackgroundAsset, opacity: number, progressForAnim: number) => {
    const bg = asset.element;
    const bgW = bg instanceof HTMLVideoElement ? bg.videoWidth : bg.width;
    const bgH = bg instanceof HTMLVideoElement ? bg.videoHeight : bg.height;

    if (bgW > 0) {
      let baseScale = Math.max(width / bgW, height / bgH);
      let animScale = 1.0;
      let animX = 0;
      let animY = 0;

      switch (bgAnim) {
        case BackgroundAnimation.ZOOM_IN:
          animScale = 1.0 + (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.ZOOM_OUT:
          animScale = 1.15 - (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.PAN_LEFT:
          animX = -(progressForAnim * width * 0.1);
          break;
        case BackgroundAnimation.PAN_RIGHT:
          animX = (progressForAnim * width * 0.1) - (width * 0.1);
          break;
      }

      ctx.save();
      ctx.globalAlpha = 0.55 * opacity;
      const finalScale = baseScale * animScale;
      const drawWidth = bgW * finalScale;
      const drawHeight = bgH * finalScale;
      const x = (width - drawWidth) / 2 + animX;
      const y = (height - drawHeight) / 2 + animY;

      ctx.drawImage(bg, x, y, drawWidth, drawHeight);
      ctx.restore();
    }
  };

  const currentSlideProgress = timeInSlide / slideDuration;
  drawSingleBg(currentAsset, 1, currentSlideProgress);

  if (nextAsset && crossFadeOpacity > 0) {
    drawSingleBg(nextAsset, crossFadeOpacity, 0);
  }
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  bgAssets: LoadedBackgroundAsset[], 
  layers: EditorLayer[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation = BackgroundAnimation.NONE,
  layoutCache?: LayoutCache
) => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  const { width, height } = canvas;
  const progress = totalDuration > 0 ? currentTime / totalDuration : 0;

  ctx.fillStyle = '#020617';
  ctx.fillRect(0, 0, width, height);

  drawBackgroundSlideshow(ctx, width, height, bgAssets, currentTime, totalDuration, bgAnim);

  const vignette = ctx.createRadialGradient(width/2, height/2, height * 0.1, width/2, height/2, height * 1.0);
  vignette.addColorStop(0, 'rgba(2, 6, 23, 0.15)');
  vignette.addColorStop(0.6, 'rgba(2, 6, 23, 0.5)');
  vignette.addColorStop(1, 'rgba(2, 6, 23, 0.98)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  const sortedLayers = [...layers].sort((a, b) => a.zIndex - b.zIndex);
  sortedLayers.forEach(layer => {
    if (!layer.visible) return;
    if (layer.type === LayerType.NARRATION) {
      renderNarrationLayer(ctx, width, height, layer, progress, totalDuration, layoutCache);
    } else if (layer.type === LayerType.TEXT) {
      renderTextLayer(ctx, width, height, layer, currentTime);
    } else if (layer.type === LayerType.IMAGE) {
      renderImageLayer(ctx, width, height, layer, currentTime);
    }
  });

  ctx.save();
  ctx.globalAlpha = 0.25;
  ctx.font = `bold ${width * 0.022}px Inter, sans-serif`;
  ctx.fillStyle = 'white';
  ctx.textAlign = 'center';
  ctx.fillText('NOOR STUDIO AI • CINEMATIC NARRATOR', width / 2, height * 0.96);
  ctx.restore();
};

export const createCompositeThumbnail = async (
  imageUrl: string,
  overlayText: string,
  targetWidth: number,
  targetHeight: number
): Promise<string> => {
  const canvas = document.createElement('canvas');
  canvas.width = targetWidth;
  canvas.height = targetHeight;
  const ctx = canvas.getContext('2d');
  if (!ctx) return imageUrl;

  const img = new Image();
  img.crossOrigin = "anonymous";
  img.src = imageUrl;

  await new Promise((resolve) => {
    if (img.complete) resolve(true);
    img.onload = () => resolve(true);
    img.onerror = () => resolve(false);
  });

  const scale = Math.max(canvas.width / img.width, canvas.height / img.height);
  const x = (canvas.width / 2) - (img.width / 2) * scale;
  const y = (canvas.height / 2) - (img.height / 2) * scale;
  ctx.drawImage(img, x, y, img.width * scale, img.height * scale);

  const gradient = ctx.createLinearGradient(0, canvas.height * 0.4, 0, canvas.height);
  gradient.addColorStop(0, 'rgba(0,0,0,0)');
  gradient.addColorStop(0.6, 'rgba(0,0,0,0.7)');
  gradient.addColorStop(1, 'rgba(0,0,0,0.9)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  if (overlayText) {
    const fontSize = Math.floor(canvas.width * 0.08); 
    ctx.font = `bold ${fontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.direction = 'rtl';

    const words = overlayText.split(' ');
    let lines: string[] = [];
    let currentLine = words[0];

    const maxWidth = canvas.width * 0.8;
    for (let i = 1; i < words.length; i++) {
        const word = words[i];
        const width = ctx.measureText(currentLine + " " + word).width;
        if (width < maxWidth) {
            currentLine += " " + word;
        } else {
            lines.push(currentLine);
            currentLine = word;
        }
    }
    lines.push(currentLine);

    const lineHeight = fontSize * 1.4;
    let startY = canvas.height - (canvas.height * 0.15) - (lines.length * lineHeight);

    ctx.shadowColor = "rgba(0,0,0,0.8)";
    ctx.shadowBlur = 15;
    ctx.strokeStyle = "black";
    ctx.lineWidth = fontSize * 0.15;
    ctx.fillStyle = "#fbbf24"; 

    lines.forEach((line, i) => {
       const lineY = startY + (i * lineHeight);
       ctx.strokeText(line, canvas.width / 2, lineY);
       ctx.fillText(line, canvas.width / 2, lineY);
    });
  }

  const brandSize = Math.max(16, canvas.width * 0.03);
  ctx.font = `bold ${brandSize}px "Inter", sans-serif`;
  ctx.fillStyle = 'rgba(255,255,255,0.7)';
  ctx.shadowBlur = 0;
  ctx.lineWidth = 0;
  ctx.textAlign = 'right';
  ctx.fillText('NOOR STUDIO AI', canvas.width - (brandSize * 1.5), brandSize * 2);

  return canvas.toDataURL('image/png');
};

