import { AnimationType, EditorLayer, LayerType, TextEffect, ImageEffect, BackgroundAnimation } from "../types";

export interface WordMetadata {
  text: string;
  start: number;
  end: number;
  width: number;
  lineIndex: number;
  relativeX: number; // Offset from the line's geometric center
  globalY: number;   // Note: This is now the actual Y position including paragraph spacing
  index: number;
}

export interface LineMetadata {
  words: string[];
  y: number;
  height: number;
  isParagraphStart: boolean;
  wordIndices: number[]; // Store indices for O(1) lookup
}

export type LayoutCache = Map<string, { lines: LineMetadata[], words: WordMetadata[] }>;

const LINE_BREAK_TOKEN = "||LB||";

/**
 * Standard cubic easing for smooth transitions.
 */
const easeInOutCubic = (t: number): number => {
  const clampedT = Math.max(0, Math.min(1, t));
  return clampedT < 0.5 ? 4 * clampedT * clampedT * clampedT : 1 - Math.pow(-2 * clampedT + 2, 3) / 2;
};

/**
 * Normalizes text to ensure 1:1 mapping between TTS and Visuals.
 * Smartly handles brackets, newlines, and punctuation spacing.
 */
export const normalizeText = (text: string): string => {
  return text
    // Remove emojis and symbols
    .replace(/[\u{1F000}-\u{1F9FF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B50}\u{2B55}]/gu, '')
    // Remove zero-width characters
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    // Encode Newlines as distinct tokens before collapsing space. 
    // This allows the user to manually control pauses via the Enter key.
    .replace(/\n+/g, ` ${LINE_BREAK_TOKEN} `)
    // Remove space before suffix punctuation (stops, commas, closing brackets)
    .replace(/\s+([۔!?\.\؟,،:;»”’)\}\]])/g, '$1')
    // Remove space after prefix punctuation (opening brackets, quotes)
    .replace(/([«“‘\(\{\[])\s+/g, '$1')
    // Collapse remaining whitespace
    .replace(/\s+/g, ' ')
    .trim();
};

/**
 * Checks if a word ends with a sentence-terminating character (Urdu/English).
 */
const isParagraphEnd = (word: string): boolean => {
  return /[۔!?\.\؟]['"”’)\}\]]*$/.test(word);
};

// --- SYNCHRONIZATION TUNING ---
// These weights determine how "long" a word takes visually relative to others.
// Adjusted for "Gemini Flash TTS" cadence.
const WEIGHT_START_PAD = 10;  
const WEIGHT_BASE = 15;       
const WEIGHT_CHAR = 5;        // Urdu words are dense, keep char weight moderate
const WEIGHT_DIGIT = 20;      
// CRITICAL: High weights for punctuation to force the visual highlighter to PAUSE.
const WEIGHT_STOP = 180;      // ~1.5s relative pause for full stops
const WEIGHT_COMMA = 80;      // ~0.6s relative pause for commas
const WEIGHT_PARA = 100;      // End buffer
const WEIGHT_BREAK = 150;     // Explicit line break (Enter key) pause

const getWordWeight = (word: string): number => {
  // 1. Clean for length count
  const cleanWord = word
    .replace(/[\u064B-\u065F\u0670]/g, "") // Remove Diacritics
    .replace(/[۔!?\.\؟,،:;""''«»\(\)\[\]\{\}]/g, ""); // Remove Punctuation

  let wWeight = WEIGHT_BASE + (cleanWord.length * WEIGHT_CHAR);

  // 2. Digit Handling
  const digitCount = (word.match(/\d/g) || []).length;
  if (digitCount > 0) {
      wWeight += (digitCount * WEIGHT_DIGIT);
  }

  // 3. Punctuation Timing (Pause detection)
  if (/[۔؟!.\?]/.test(word)) {
      wWeight += WEIGHT_STOP; 
  } else if (/[،:,]/.test(word)) {
      wWeight += WEIGHT_COMMA;
  }
  return wWeight;
};

/**
 * Calculates words and lines with high precision for RTL alignment.
 */
export const getWordMetadata = (
  ctx: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  baseFontSize: number,
  lineHeight: number,
  cache?: LayoutCache
): { lines: LineMetadata[], words: WordMetadata[] } => {
  // 1. Check Cache
  const normalizedText = normalizeText(text);
  const cacheKey = `${normalizedText}_${maxWidth.toFixed(2)}_${baseFontSize.toFixed(2)}`;

  if (cache && cache.has(cacheKey)) {
    return cache.get(cacheKey)!;
  }

  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  const rawWords = normalizedText.split(' ').filter(w => w.length > 0);

  const wordsMetadata: WordMetadata[] = [];
  const lines: LineMetadata[] = [];

  // Pass 1: Calculate Total Weight (Time Duration)
  let totalWeight = WEIGHT_START_PAD;
  rawWords.forEach((w) => {
    if (w === LINE_BREAK_TOKEN) {
        totalWeight += WEIGHT_BREAK; // Add time for the silent pause
    } else {
        totalWeight += getWordWeight(w);
    }
  });
  totalWeight += WEIGHT_PARA;

  if (totalWeight === 0) totalWeight = 100;

  // Pass 2: Layout & Timing Allocation
  let weightCursor = WEIGHT_START_PAD;
  const spaceWidth = ctx.measureText(' ').width;
  const PARAGRAPH_SPACING = lineHeight * 0.8; 

  let currentLineWords: string[] = [];
  let currentLineWordIndices: number[] = []; 
  let currentLineWidth = 0;
  let currentLineY = 0;
  let currentLineIdx = 0;
  let pendingParagraphBreak = false; 

  const commitLine = () => {
    if (currentLineWords.length === 0) return;

    // Center alignment calculation
    const totalW = currentLineWidth;
    let cursorX = totalW / 2; 

    currentLineWordIndices.forEach((globalIdx, i) => {
       const word = currentLineWords[i];
       const wWidth = ctx.measureText(word).width;
       const wordCenterX = cursorX - (wWidth / 2);

       wordsMetadata[globalIdx].relativeX = wordCenterX;
       wordsMetadata[globalIdx].lineIndex = currentLineIdx;
       wordsMetadata[globalIdx].globalY = currentLineY;

       cursorX -= (wWidth + spaceWidth);
    });

    lines.push({
      words: [...currentLineWords],
      wordIndices: [...currentLineWordIndices],
      y: currentLineY,
      height: lineHeight,
      isParagraphStart: pendingParagraphBreak 
    });

    currentLineWords = [];
    currentLineWordIndices = [];
    currentLineWidth = 0;
    currentLineIdx++;
  };

  let visualWordIndex = 0; // Index for displayable words (skips tokens)

  rawWords.forEach((word) => {
    if (word === LINE_BREAK_TOKEN) {
        // Force Line Break visual commit
        commitLine();
        currentLineY += lineHeight + PARAGRAPH_SPACING;
        pendingParagraphBreak = true;

        // Add time to the cursor so the highlighter "waits" during this break
        weightCursor += WEIGHT_BREAK;
        return;
    }

    const wordWidth = ctx.measureText(word).width;
    const fits = (currentLineWidth + (currentLineWords.length ? spaceWidth : 0) + wordWidth) <= maxWidth;

    if (currentLineWords.length > 0 && (pendingParagraphBreak || !fits)) {
         commitLine();
         currentLineY += lineHeight;
         if (pendingParagraphBreak) {
             currentLineY += PARAGRAPH_SPACING;
             pendingParagraphBreak = false; 
         }
    }

    const wordWeight = getWordWeight(word);

    // Assign time slots
    const startTime = weightCursor / totalWeight;
    weightCursor += wordWeight;
    const endTime = weightCursor / totalWeight;

    wordsMetadata.push({
      text: word,
      start: startTime,
      end: endTime,
      width: wordWidth,
      lineIndex: 0, // Placeholder, set in commitLine
      relativeX: 0, // Placeholder
      globalY: 0,   // Placeholder
      index: visualWordIndex
    });

    currentLineWords.push(word);
    currentLineWordIndices.push(visualWordIndex);
    currentLineWidth += (currentLineWords.length > 1 ? spaceWidth : 0) + wordWidth;

    if (isParagraphEnd(word)) {
        pendingParagraphBreak = true;
    }

    visualWordIndex++;
  });

  commitLine(); // Commit final line

  const result = { lines, words: wordsMetadata };
  if (cache) cache.set(cacheKey, result);
  return result;
};

export const renderNarrationLayer = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  layer: any,
  globalProgress: number,
  duration: number,
  cache?: LayoutCache
) => {
  // Convert global video time to layer local time (0.0 to 1.0)
  const currentTotalTime = globalProgress * duration;
  const progress = (currentTotalTime - layer.startTime) / (layer.endTime - layer.startTime);

  // Allow slight buffer (1.05) to keep text visible at very end
  if (progress < 0 || progress > 1.05) return;

  const isLandscape = width > height;
  const isUltraNarrow = (width / height) < 0.55; 

  // Dynamic font sizing
  let scaleRef = isLandscape ? height * 1.45 : width;
  if (isUltraNarrow) scaleRef = width * 1.15;

  const baseFontSize = isLandscape ? scaleRef * 0.05 : scaleRef * 0.07; 
  const lineHeight = baseFontSize * 2.2;
  const maxWidth = width * (isLandscape ? 0.8 : 0.82);

  const { lines, words } = getWordMetadata(ctx, layer.text, maxWidth, baseFontSize, lineHeight, cache);
  if (words.length === 0) return;

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.direction = 'ltr'; // Canvas draws LTR even for RTL text if we calculate offsets manually
  ctx.font = `bold ${baseFontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;

  // --- ROBUST ACTIVE INDEX FINDER ---
  // Fixes bug where gaps (silence/pauses) caused index to reset to 0
  let activeIdx = -1;

  for (let i = 0; i < words.length; i++) {
    // If we have passed the start of this word, it is potentially the active one
    if (progress >= words[i].start) {
      activeIdx = i;
    } else {
      // We reached a word that starts in the future.
      // Therefore, the PREVIOUS word (activeIdx) is the one we are currently "holding"
      // or we are in the gap after it.
      break; 
    }
  }

  // Default to first word if at very start
  if (activeIdx === -1) activeIdx = 0;

  const currentWord = words[activeIdx];
  const currentLineIndex = currentWord.lineIndex;

  // --- FORMAL LANDSCAPE RENDERER (Youtube Style) ---
  if (isLandscape) {
    const currentLine = lines[currentLineIndex];
    if (!currentLine) return;

    // Fixed Position: Bottom 20%
    const yPos = height * 0.8; 

    ctx.save();
    ctx.translate(width / 2, yPos);

    // Draw only the CURRENT line
    currentLine.wordIndices.forEach(idx => {
       const w = words[idx];
       const isActive = idx === activeIdx;

       ctx.save();
       ctx.translate(w.relativeX, 0);

       if (isActive) {
           ctx.fillStyle = '#fbbf24'; // Gold for active word
           ctx.shadowColor = 'rgba(251, 191, 36, 0.8)';
           ctx.shadowBlur = 15;
           // Slight pop effect
           const scale = 1.05;
           ctx.scale(scale, scale);
       } else {
           ctx.fillStyle = '#ffffff';
           ctx.globalAlpha = 1.0; 
           ctx.shadowColor = 'rgba(0,0,0,0.8)';
           ctx.shadowBlur = 4;
       }

       ctx.fillText(w.text, 0, 0);
       ctx.restore();
    });
    ctx.restore();
    return; // Exit early for landscape
  }

  // --- PORTRAIT TELEPROMPTER RENDERER (Original Vertical Scroll) ---

  let cameraY = lines[currentLineIndex].y;
  const currentLineMeta = lines[currentLineIndex];
  const lastWordIdx = currentLineMeta.wordIndices[currentLineMeta.wordIndices.length - 1];
  const isLastWordInLine = (activeIdx === lastWordIdx);

  // Smooth scroll logic
  if (isLastWordInLine && currentLineIndex < lines.length - 1) {
    const wordDuration = currentWord.end - currentWord.start;
    const p = (progress - currentWord.start) / wordDuration;
    // Start scrolling when word is 40% done
    if (p > 0.4) {
       const slideT = (p - 0.4) / 0.6; 
       const nextLineY = lines[currentLineIndex + 1].y;
       const diff = nextLineY - cameraY;
       cameraY += diff * easeInOutCubic(slideT);
    }
  }

  const screenCenterY = height * 0.48; 
  const VISUAL_WINDOW_HEIGHT = lineHeight * 4.5; 

  lines.forEach((lineMeta, lineIdx) => {
    const relativeY = lineMeta.y - cameraY;
    // Optimization: Don't draw off-screen lines
    if (Math.abs(relativeY) > VISUAL_WINDOW_HEIGHT) return;

    const drawY = screenCenterY + relativeY;
    const distRatio = Math.abs(relativeY) / (lineHeight * 4.5);
    const focusFactor = Math.max(0, 1 - distRatio); 
    const scale = 0.9 + (0.2 * focusFactor); 
    const opacity = 0.3 + (0.7 * focusFactor); 

    ctx.save();
    ctx.translate(width / 2, drawY);
    ctx.scale(scale, scale);

    lineMeta.wordIndices.forEach((wIdx) => {
      const w = words[wIdx];
      const isWordActive = activeIdx === wIdx; 
      const isWordPast = activeIdx > wIdx;

      ctx.save();
      ctx.translate(w.relativeX, 0); 

      if (isWordActive) {
        ctx.shadowBlur = 30;
        ctx.shadowColor = 'rgba(251, 191, 36, 0.9)'; 
        ctx.fillStyle = '#fbbf24'; 
        ctx.globalAlpha = 1;
        const wp = (progress - w.start) / (w.end - w.start);
        const pulse = 1.0 + (0.05 * Math.sin(wp * Math.PI));
        ctx.scale(pulse, pulse);
      } else {
        if (lineIdx === currentLineIndex) {
            // Current line inactive words
            if (isWordPast) {
                 ctx.fillStyle = '#cbd5e1'; 
                 ctx.globalAlpha = 0.95;
            } else {
                 ctx.fillStyle = '#ffffff'; 
                 ctx.globalAlpha = 1.0;
            }
        } else {
             // Other lines
             ctx.fillStyle = '#94a3b8'; 
             const isNeighbor = Math.abs(relativeY) < (lineHeight * 1.5);
             ctx.globalAlpha = isNeighbor ? Math.min(1, opacity + 0.2) : opacity; 
        }
        ctx.shadowBlur = 0;
      }
      ctx.fillText(w.text, 0, 0);
      ctx.restore();
    });
    ctx.restore();
  });
};

const renderTextLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const duration = layer.endTime - layer.startTime;
  const localTime = time - layer.startTime;
  ctx.save();
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `${layer.fontSize}px Inter, sans-serif`;
  ctx.fillStyle = layer.color;
  let alpha = 1; let scale = 1; let offsetY = 0;
  if (layer.animation === 'fade') {
    if (localTime < 0.5) alpha = localTime / 0.5;
    else if (duration - localTime < 0.5) alpha = (duration - localTime) / 0.5;
  } else if (layer.animation === 'slide') {
    if (localTime < 0.5) offsetY = (1 - (localTime / 0.5)) * 50;
  } else if (layer.animation === 'bounce') {
    scale = 1 + 0.1 * Math.sin(localTime * 10);
  } else if (layer.animation === 'typewriter') {
    const charsToShow = Math.floor(layer.text.length * Math.min(1, localTime / (duration * 0.5)));
    ctx.fillText(layer.text.substring(0, charsToShow), width * layer.x, height * layer.y + offsetY);
    ctx.restore(); return;
  }
  ctx.globalAlpha = alpha;
  ctx.translate(width * layer.x, height * layer.y + offsetY);
  ctx.scale(scale, scale);
  ctx.fillText(layer.text, 0, 0);
  ctx.restore();
};

const renderImageLayer = (ctx: CanvasRenderingContext2D, width: number, height: number, layer: any, time: number) => {
  if (time < layer.startTime || time > layer.endTime) return;
  const localTime = time - layer.startTime;
  const duration = layer.endTime - layer.startTime;
  const img = new Image();
  img.src = layer.url;
  if (!img.complete) return;
  ctx.save();
  let scale = layer.scale;
  let alpha = 1;
  if (layer.animation === 'zoom') scale *= (1 + 0.2 * (localTime / duration));
  else if (layer.animation === 'fade') alpha = Math.min(1, localTime / 0.5) * Math.min(1, (duration - localTime) / 0.5);
  ctx.globalAlpha = alpha;
  const drawW = img.width * scale;
  const drawH = img.height * scale;
  ctx.drawImage(img, width * layer.x - drawW / 2, height * layer.y - drawH / 2, drawW, drawH);
  ctx.restore();
};

interface LoadedBackgroundAsset {
  element: HTMLImageElement | HTMLVideoElement;
  type: 'image' | 'video';
  id: string;
}

const drawBackgroundSlideshow = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  bgAssets: LoadedBackgroundAsset[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation
) => {
  if (bgAssets.length === 0) return;

  const slideDuration = Math.max(2, totalDuration / bgAssets.length);
  const totalSlides = bgAssets.length;

  let slideIndex = Math.floor(currentTime / slideDuration);
  if (slideIndex >= totalSlides) slideIndex = totalSlides - 1;

  const currentAsset = bgAssets[slideIndex];
  const timeInSlide = currentTime - (slideIndex * slideDuration);
  const fadeDuration = 1.0; 
  const remainingTime = slideDuration - timeInSlide;

  let nextAsset: LoadedBackgroundAsset | null = null;
  let crossFadeOpacity = 0;

  if (remainingTime < fadeDuration && slideIndex < totalSlides - 1) {
    nextAsset = bgAssets[slideIndex + 1];
    crossFadeOpacity = 1 - (remainingTime / fadeDuration);
  }

  const drawSingleBg = (asset: LoadedBackgroundAsset, opacity: number, progressForAnim: number) => {
    const bg = asset.element;
    const bgW = bg instanceof HTMLVideoElement ? bg.videoWidth : bg.width;
    const bgH = bg instanceof HTMLVideoElement ? bg.videoHeight : bg.height;

    if (bgW > 0) {
      // --- WATER FLOW ANIMATION ---
      if (bgAnim === BackgroundAnimation.WATER_FLOW) {
         const numSlices = 80; 
         const sliceHeight = height / numSlices;

         const scale = Math.max(width / bgW, height / bgH) * 1.15; // Zoom in to allow movement
         const drawW = bgW * scale;
         const drawH = bgH * scale;
         const startX = (width - drawW) / 2;
         const startY = (height - drawH) / 2;

         const amplitude = width * 0.01; // Strength of wave
         const frequency = 0.05; // Tightness of wave
         const speed = 2.0; // Speed of wave

         ctx.save();
         ctx.globalAlpha = 0.65 * opacity;

         for (let i = 0; i < numSlices; i++) {
             // Calculate sine wave X-offset based on Y-position and Time
             const offset = Math.sin((i * frequency) + (currentTime * speed)) * amplitude;

             // Define horizontal slice on Canvas
             const dy = i * sliceHeight;
             const dh = sliceHeight + 1.5; // Slight overlap to fix sub-pixel gaps

             // Map canvas slice back to Source Image coordinates
             // Relative Y in the drawn image
             const relativeY = dy - startY;
             const sy = (relativeY / scale);
             const sh = (dh / scale);

             // Safety check for source bounds
             if (sy >= 0 && (sy + sh) <= bgH) {
                 ctx.drawImage(
                   bg, 
                   0, sy, bgW, sh, // Source: Full width strip
                   startX + offset, dy, drawW, dh // Dest: Shifted X
                 );
             }
         }
         ctx.restore();
         return;
      }

      // --- STANDARD ANIMATIONS ---
      let baseScale = Math.max(width / bgW, height / bgH);
      let animScale = 1.0;
      let animX = 0;
      let animY = 0;

      switch (bgAnim) {
        case BackgroundAnimation.ZOOM_IN:
          animScale = 1.0 + (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.ZOOM_OUT:
          animScale = 1.15 - (progressForAnim * 0.15);
          break;
        case BackgroundAnimation.PAN_LEFT:
          animX = -(progressForAnim * width * 0.1);
          break;
        case BackgroundAnimation.PAN_RIGHT:
          animX = (progressForAnim * width * 0.1) - (width * 0.1);
          break;
      }

      ctx.save();
      ctx.globalAlpha = 0.55 * opacity;
      const finalScale = baseScale * animScale;
      const drawWidth = bgW * finalScale;
      const drawHeight = bgH * finalScale;
      const x = (width - drawWidth) / 2 + animX;
      const y = (height - drawHeight) / 2 + animY;

      ctx.drawImage(bg, x, y, drawWidth, drawHeight);
      ctx.restore();
    }
  };

  const currentSlideProgress = timeInSlide / slideDuration;
  drawSingleBg(currentAsset, 1, currentSlideProgress);

  if (nextAsset && crossFadeOpacity > 0) {
    drawSingleBg(nextAsset, crossFadeOpacity, 0);
  }
};

export const drawVideoFrame = (
  canvas: HTMLCanvasElement,
  bgAssets: LoadedBackgroundAsset[], 
  layers: EditorLayer[],
  currentTime: number,
  totalDuration: number,
  bgAnim: BackgroundAnimation = BackgroundAnimation.NONE,
  layoutCache?: LayoutCache,
  thumbnailUrl?: string 
) => {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  const { width, height } = canvas;

  // Thumbnail Intro Logic
  const INTRO_DURATION = thumbnailUrl ? 2.0 : 0;

  if (currentTime < INTRO_DURATION && thumbnailUrl) {
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, width, height);

    const img = new Image();
    img.src = thumbnailUrl;
    if (img.complete) {
       const scale = Math.max(width / img.width, height / img.height);
       const animScale = 1.0 + (currentTime / INTRO_DURATION) * 0.1;
       const finalScale = scale * animScale;
       const x = (width - (img.width * finalScale)) / 2;
       const y = (height - (img.height * finalScale)) / 2;

       ctx.save();
       ctx.drawImage(img, x, y, img.width * finalScale, img.height * finalScale);

       // Fade out to black at the end of intro
       if (currentTime > INTRO_DURATION - 0.5) {
         ctx.fillStyle = `rgba(0,0,0,${(currentTime - (INTRO_DURATION - 0.5)) / 0.5})`;
         ctx.fillRect(0,0,width,height);
       }
       ctx.restore();
    }
    return;
  }

  // Main Content Rendering
  const contentTime = currentTime - INTRO_DURATION;
  const contentDuration = Math.max(0.1, totalDuration - INTRO_DURATION);

  ctx.fillStyle = '#020617';
  ctx.fillRect(0, 0, width, height);

  drawBackgroundSlideshow(ctx, width, height, bgAssets, contentTime, contentDuration, bgAnim);

  // Vignette for Cinematic Effect
  const vignette = ctx.createRadialGradient(width/2, height/2, height * 0.1, width/2, height/2, height * 1.0);
  vignette.addColorStop(0, 'rgba(2, 6, 23, 0.15)');
  vignette.addColorStop(0.6, 'rgba(2, 6, 23, 0.5)');
  vignette.addColorStop(1, 'rgba(2, 6, 23, 0.98)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  const sortedLayers = [...layers].sort((a, b) => a.zIndex - b.zIndex);
  sortedLayers.forEach(layer => {
    if (!layer.visible) return;
    if (layer.type === LayerType.NARRATION) {
      renderNarrationLayer(ctx, width, height, layer, currentTime / totalDuration, totalDuration, layoutCache);
    } else if (layer.type === LayerType.TEXT) {
      renderTextLayer(ctx, width, height, layer, currentTime);
    } else if (layer.type === LayerType.IMAGE) {
      renderImageLayer(ctx, width, height, layer, currentTime);
    }
  });

  // Branding Watermark
  ctx.save();
  ctx.globalAlpha = 0.25;
  ctx.font = `bold ${width * 0.022}px Inter, sans-serif`;
  ctx.fillStyle = 'white';
  ctx.textAlign = 'center';
  ctx.fillText('NOOR STUDIO AI • CINEMATIC NARRATOR', width / 2, height * 0.96);
  ctx.restore();
};

export const createCompositeThumbnail = async (
  imageUrl: string,
  overlayText: string,
  targetWidth: number,
  targetHeight: number
): Promise<string> => {
  const canvas = document.createElement('canvas');
  canvas.width = targetWidth;
  canvas.height = targetHeight;
  const ctx = canvas.getContext('2d');
  if (!ctx) return imageUrl;

  const img = new Image();
  img.crossOrigin = "anonymous";
  img.src = imageUrl;

  await new Promise((resolve) => {
    if (img.complete) resolve(true);
    img.onload = () => resolve(true);
    img.onerror = () => resolve(false);
  });

  const scale = Math.max(canvas.width / img.width, canvas.height / img.height);
  const x = (canvas.width / 2) - (img.width / 2) * scale;
  const y = (canvas.height / 2) - (img.height / 2) * scale;
  ctx.drawImage(img, x, y, img.width * scale, img.height * scale);

  const gradient = ctx.createLinearGradient(0, canvas.height * 0.4, 0, canvas.height);
  gradient.addColorStop(0, 'rgba(0,0,0,0)');
  gradient.addColorStop(0.6, 'rgba(0,0,0,0.7)');
  gradient.addColorStop(1, 'rgba(0,0,0,0.9)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  if (overlayText) {
    const fontSize = Math.floor(canvas.width * 0.08); 
    ctx.font = `bold ${fontSize}px "Noto Nastaliq Urdu", "Inter", sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.direction = 'rtl';

    const words = overlayText.split(' ');
    let lines: string[] = [];
    let currentLine = words[0];

    const maxWidth = canvas.width * 0.8;
    for (let i = 1; i < words.length; i++) {
        const word = words[i];
        const width = ctx.measureText(currentLine + " " + word).width;
        if (width < maxWidth) {
            currentLine += " " + word;
        } else {
            lines.push(currentLine);
            currentLine = word;
        }
    }
    lines.push(currentLine);

    const lineHeight = fontSize * 1.4;
    let startY = canvas.height - (canvas.height * 0.15) - (lines.length * lineHeight);

    ctx.shadowColor = "rgba(0,0,0,0.8)";
    ctx.shadowBlur = 15;
    ctx.strokeStyle = "black";
    ctx.lineWidth = fontSize * 0.15;
    ctx.fillStyle = "#fbbf24"; 

    lines.forEach((line, i) => {
       const lineY = startY + (i * lineHeight);
       ctx.strokeText(line, canvas.width / 2, lineY);
       ctx.fillText(line, canvas.width / 2, lineY);
    });
  }

  const brandSize = Math.max(16, canvas.width * 0.03);
  ctx.font = `bold ${brandSize}px "Inter", sans-serif`;
  ctx.fillStyle = 'rgba(255,255,255,0.7)';
  ctx.shadowBlur = 0;
  ctx.lineWidth = 0;
  ctx.textAlign = 'right';
  ctx.fillText('NOOR STUDIO AI', canvas.width - (brandSize * 1.5), brandSize * 2);

  return canvas.toDataURL('image/png');
};
